/// Standard MCP hints describing a tool's operational behavior.
package struct MCPToolAnnotations: Equatable, Sendable {
  package let readOnlyHint: Bool?
  package let destructiveHint: Bool?
  package let idempotentHint: Bool?
  package let openWorldHint: Bool?

  package init(
    readOnlyHint: Bool? = nil,
    destructiveHint: Bool? = nil,
    idempotentHint: Bool? = nil,
    openWorldHint: Bool? = nil
  ) {
    self.readOnlyHint = readOnlyHint
    self.destructiveHint = destructiveHint
    self.idempotentHint = idempotentHint
    self.openWorldHint = openWorldHint
  }

  package var json: JSONValue {
    var object: [String: JSONValue] = [:]
    if let readOnlyHint {
      object["readOnlyHint"] = .bool(readOnlyHint)
    }
    if let destructiveHint {
      object["destructiveHint"] = .bool(destructiveHint)
    }
    if let idempotentHint {
      object["idempotentHint"] = .bool(idempotentHint)
    }
    if let openWorldHint {
      object["openWorldHint"] = .bool(openWorldHint)
    }
    return .object(object)
  }
}

/// MCP tool definition exposed by `tools/list`.
package struct MCPTool: Equatable, Sendable {
  /// Stable MCP tool name.
  package let name: String

  /// Human-readable display title.
  package let title: String

  /// Reader-facing tool description.
  package let description: String

  /// JSON Schema input schema.
  package let inputSchema: JSONValue

  /// JSON Schema for structured tool results.
  package let outputSchema: JSONValue?

  /// Standard MCP operational hints.
  package let annotations: MCPToolAnnotations?

  /// Optional MCP tool metadata.
  package let meta: JSONValue?

  /// Creates an MCP tool definition.
  package init(
    name: String,
    title: String? = nil,
    description: String,
    inputSchema: JSONValue,
    outputSchema: JSONValue? = MCPTool.resultEnvelopeSchema,
    annotations: MCPToolAnnotations? = nil,
    meta: JSONValue? = nil
  ) {
    self.name = name
    self.title = title ?? MCPTool.defaultTitle(for: name)
    self.description = description
    self.inputSchema = inputSchema
    self.outputSchema = outputSchema
    self.annotations = annotations
    self.meta = meta
  }

  /// JSON representation used in MCP `tools/list` responses.
  package var json: JSONValue {
    var object: [String: JSONValue] = [
      "name": .string(name),
      "title": .string(title),
      "description": .string(description),
      "inputSchema": inputSchema,
    ]
    if let outputSchema {
      object["outputSchema"] = outputSchema
    }
    if let annotations {
      object["annotations"] = annotations.json
    }
    if let meta {
      object["_meta"] = meta
    }
    return .object(object)
  }

  internal func prefixed(_ prefix: String) -> MCPTool {
    MCPTool(
      name: "\(prefix).\(name)",
      title: title,
      description: description,
      inputSchema: inputSchema,
      outputSchema: outputSchema,
      annotations: annotations,
      meta: meta
    )
  }

  internal func withAnnotations(_ annotations: MCPToolAnnotations) -> MCPTool {
    MCPTool(
      name: name,
      title: title,
      description: description,
      inputSchema: inputSchema,
      outputSchema: outputSchema,
      annotations: annotations,
      meta: meta
    )
  }

  internal static let resultEnvelopeSchema: JSONValue = .object([
    "type": .string("object"),
    "properties": .object([
      "result": .object([:])
    ]),
    "required": .array([.string("result")]),
    "additionalProperties": .bool(false),
  ])

  private static func defaultTitle(for name: String) -> String {
    name
      .split(whereSeparator: { $0 == "." || $0 == "_" || $0 == "-" })
      .map { part in
        guard let first = part.first else {
          return ""
        }
        return String(first).uppercased() + part.dropFirst()
      }
      .joined(separator: " ")
  }
}

/// Errors thrown while validating or executing registered gateway tools.
internal enum GatewayToolError: Error, LocalizedError, Equatable {
  case unknownTool(String)
  case unknownCLI(String)
  case unknownMCPServer(String)
  case invalidArguments(String)
  case disabled(String)
  case executionFailed(String)

  internal var errorDescription: String? {
    switch self {
    case .unknownTool(let name):
      return "Unknown tool: \(name)"
    case .unknownCLI(let id):
      return "Unknown CLI command id: \(id)"
    case .unknownMCPServer(let id):
      return "Unknown MCP server id: \(id)"
    case .invalidArguments(let message), .disabled(let message), .executionFailed(let message):
      return message
    }
  }
}

internal protocol DownstreamMCPClient: Sendable {
  func listTools(server: MCPServerConfig) throws -> [MCPTool]
  func callTool(server: MCPServerConfig, name: String, arguments: JSONValue) throws -> JSONValue
  func callTool(
    server: MCPServerConfig,
    name: String,
    arguments: JSONValue,
    requestID: String?
  ) throws -> JSONValue
  func startToolCall(
    server: MCPServerConfig,
    name: String,
    arguments: JSONValue,
    requestID: String
  ) throws -> JSONValue
  func listResources(server: MCPServerConfig, cursor: String?) throws -> JSONValue
  func listResourceTemplates(server: MCPServerConfig, cursor: String?) throws -> JSONValue
  func readResource(server: MCPServerConfig, uri: String) throws -> JSONValue
  func listPrompts(server: MCPServerConfig, cursor: String?) throws -> JSONValue
  func getPrompt(server: MCPServerConfig, name: String, arguments: [String: String]?) throws
    -> JSONValue
  func connectionStatus(server: MCPServerConfig) throws -> JSONValue
  func readEvents(server: MCPServerConfig, afterCursor: Int, maxResults: Int) throws -> JSONValue
  func activeRequests(server: MCPServerConfig) throws -> JSONValue
  func cancelRequest(server: MCPServerConfig, requestID: String, reason: String?) throws
    -> JSONValue
}

extension DownstreamMCPClient {
  internal func callTool(
    server: MCPServerConfig,
    name: String,
    arguments: JSONValue,
    requestID: String?
  ) throws -> JSONValue {
    try callTool(server: server, name: name, arguments: arguments)
  }

  internal func connectionStatus(server: MCPServerConfig) throws -> JSONValue {
    .object([
      "state": .string("not_observed"),
      "persistent_session": .bool(false),
    ])
  }

  internal func startToolCall(
    server: MCPServerConfig,
    name: String,
    arguments: JSONValue,
    requestID: String
  ) throws -> JSONValue {
    throw GatewayToolError.disabled(
      "Downstream MCP client does not support asynchronously started tool calls."
    )
  }

  internal func readEvents(
    server: MCPServerConfig,
    afterCursor: Int,
    maxResults: Int
  ) throws -> JSONValue {
    .object([
      "server": .string(server.id),
      "after_cursor": .number(Double(afterCursor)),
      "next_cursor": .number(Double(afterCursor)),
      "events": .array([]),
      "missed_events": .number(0),
      "persistent_session": .bool(false),
    ])
  }

  internal func activeRequests(server: MCPServerConfig) throws -> JSONValue {
    .object([
      "server": .string(server.id),
      "requests": .array([]),
      "persistent_session": .bool(false),
    ])
  }

  internal func cancelRequest(
    server: MCPServerConfig,
    requestID: String,
    reason: String?
  ) throws -> JSONValue {
    throw GatewayToolError.disabled(
      "Downstream MCP client does not support request cancellation."
    )
  }
}

private enum DecodedTOMLValue: Decodable {
  case string(String)
  case integer(Int64)
  case float(Double)
  case bool(Bool)
  case offsetDateTime(Date)
  case localDateTime(LocalDateTime)
  case localDate(LocalDate)
  case localTime(LocalTime)
  case array([DecodedTOMLValue])
  case table([String: DecodedTOMLValue])

  init(from decoder: any Decoder) throws {
    if let keyed = try? decoder.container(keyedBy: DynamicCodingKey.self) {
      var table: [String: DecodedTOMLValue] = [:]
      for key in keyed.allKeys {
        table[key.stringValue] = try keyed.decode(DecodedTOMLValue.self, forKey: key)
      }
      self = .table(table)
      return
    }

    if var unkeyed = try? decoder.unkeyedContainer() {
      var array: [DecodedTOMLValue] = []
      while !unkeyed.isAtEnd {
        array.append(try unkeyed.decode(DecodedTOMLValue.self))
      }
      self = .array(array)
      return
    }

    let single = try decoder.singleValueContainer()
    if let value = try? single.decode(Bool.self) {
      self = .bool(value)
    } else if let value = try? single.decode(Int64.self) {
      self = .integer(value)
    } else if let value = try? single.decode(Double.self) {
      self = .float(value)
    } else if let value = try? single.decode(LocalDateTime.self) {
      self = .localDateTime(value)
    } else if let value = try? single.decode(LocalDate.self) {
      self = .localDate(value)
    } else if let value = try? single.decode(LocalTime.self) {
      self = .localTime(value)
    } else if let value = try? single.decode(Date.self) {
      self = .offsetDateTime(value)
    } else if let value = try? single.decode(String.self) {
      self = .string(value)
    } else {
      throw DecodingError.typeMismatch(
        DecodedTOMLValue.self,
        DecodingError.Context(
          codingPath: decoder.codingPath,
          debugDescription: "Unsupported TOML value"
        )
      )
    }
  }
}

private struct DynamicCodingKey: CodingKey {
  var stringValue: String
  var intValue: Int?

  init?(stringValue: String) {
    self.stringValue = stringValue
    intValue = nil
  }

  init?(intValue: Int) {
    stringValue = "\(intValue)"
    self.intValue = intValue
  }
}

