  private func skillResourceSummaries(skill: SkillInfo, files: [SkillFileInfo])
    -> [SkillResourceSummary]
  {
    let knownKinds = ["agents", "references", "scripts", "assets"]
    var summaries = Dictionary(
      uniqueKeysWithValues: knownKinds.map {
        ($0, SkillResourceSummary(kind: $0, path: $0, skill: skill))
      })
    var other = SkillResourceSummary(kind: "other", path: nil, skill: skill)

    for file in files where file.path != "SKILL.md" {
      let kind = skillResourceKind(for: file.path)
      if knownKinds.contains(kind) {
        summaries[kind]?.add(file)
      } else {
        other.add(file)
      }
    }

    var ordered = knownKinds.compactMap { summaries[$0] }
    if other.exists || other.fileCount > 0 || other.directoryCount > 0 || other.symlinkCount > 0
      || other.otherCount > 0
    {
      ordered.append(other)
    }
    return ordered
  }

  private func skillResourceKind(for path: String) -> String {
    let first = path.split(separator: "/", maxSplits: 1, omittingEmptySubsequences: true).first
    switch first {
    case "agents":
      return "agents"
    case "references":
      return "references"
    case "scripts":
      return "scripts"
    case "assets":
      return "assets"
    default:
      return "other"
    }
  }

  private func skillPackageReadOrder(_ lhs: SkillFileInfo, _ rhs: SkillFileInfo) -> Bool {
    let lhsPriority = skillPackageReadPriority(lhs.path)
    let rhsPriority = skillPackageReadPriority(rhs.path)
    if lhsPriority != rhsPriority {
      return lhsPriority < rhsPriority
    }
    return lhs.path.localizedStandardCompare(rhs.path) == .orderedAscending
  }

  private func skillPackageReadPriority(_ path: String) -> Int {
    if path == "SKILL.md" {
      return 0
    }
    if path == "agents/openai.yaml" {
      return 1
    }
    if path.hasPrefix("references/") {
      return 2
    }
    if path.hasPrefix("agents/") {
      return 3
    }
    if path.hasPrefix("scripts/") {
      return 4
    }
    if path.hasPrefix("assets/") {
      return 5
    }
    return 6
  }

  private func skillFrontmatterStatus(_ content: String?) -> SkillFrontmatterStatus {
    guard let content else {
      return SkillFrontmatterStatus(
        hasOpening: false,
        closed: false,
        name: nil,
        description: nil,
        lineCount: nil
      )
    }
    let block = skillFrontmatterBlock(content)
    let decoded = block.raw.map(decodeSkillFrontmatterYAML)

    return SkillFrontmatterStatus(
      hasOpening: block.hasOpening,
      closed: block.closed,
      name: decoded?.metadata.name,
      description: decoded?.metadata.description,
      lineCount: block.lineCount,
      parseError: decoded?.parseError
    )
  }

  private func isCanonicalSkillName(_ name: String) -> Bool {
    guard !name.isEmpty else {
      return false
    }
    return name.unicodeScalars.allSatisfy { scalar in
      let value = scalar.value
      return (value >= 48 && value <= 57)
        || (value >= 97 && value <= 122)
        || value == 45
    }
  }

  private func skillFrontmatterBlock(_ text: String) -> (
    hasOpening: Bool, closed: Bool, raw: String?, lineCount: Int
  ) {
    let lines = text.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    guard lines.first?.trimmingCharacters(in: .whitespacesAndNewlines) == "---" else {
      return (false, false, nil, lines.count)
    }
    guard
      let closingOffset = lines.dropFirst().enumerated().first(where: { _, line in
        line.trimmingCharacters(in: .whitespacesAndNewlines) == "---"
      })?.offset
    else {
      return (true, false, nil, lines.count)
    }
    let closingLineIndex = closingOffset + 1
    let rawLines = closingLineIndex > 1 ? Array(lines[1..<closingLineIndex]) : []
    return (true, true, rawLines.joined(separator: "\n"), lines.count)
  }

  private func decodeSkillFrontmatterYAML(_ raw: String) -> DecodedSkillFrontmatter {
    do {
      let document = try parseStructuredValue(
        data: Data(raw.utf8),
        format: "yaml",
        path: "SKILL.md",
        maxBytes: max(raw.utf8.count, 1),
        maxDocuments: 1,
        maxDepth: 128
      )
      guard let object = document.value.objectValue else {
        return DecodedSkillFrontmatter(
          metadata: SkillFrontmatter(),
          document: nil,
          parseError: "YAML frontmatter root must be an object."
        )
      }
      return DecodedSkillFrontmatter(
        metadata: SkillFrontmatter(
          name: object["name"]?.stringValue,
          description: object["description"]?.stringValue
        ),
        document: document,
        parseError: nil
      )
    } catch {
      return DecodedSkillFrontmatter(
        metadata: SkillFrontmatter(),
        document: nil,
        parseError: error.localizedDescription
      )
    }
  }

  private func skillMatchedFields(
    _ skill: SkillInfo,
    query: String,
    caseSensitive: Bool
  ) -> [String] {
    let fields: [(String, String)] = [
      ("name", skill.name),
      ("directory_name", skill.directoryName),
      ("description", skill.description ?? ""),
      ("root_id", skill.root.id),
      ("path", skill.fileURL.path),
    ]
    return fields.compactMap { field, value in
      string(value, contains: query, caseSensitive: caseSensitive) ? field : nil
    }
  }

  private func skillContentLineMatches(
    _ content: String,
    query: String,
    caseSensitive: Bool,
    maxMatches: Int
  ) -> [SkillContentLineMatch] {
    var matches: [SkillContentLineMatch] = []
    for (index, line) in content.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .enumerated()
    where string(line, contains: query, caseSensitive: caseSensitive) {
      matches.append(
        SkillContentLineMatch(line: index + 1, text: String(line.prefix(240)))
      )
      if matches.count >= maxMatches {
        break
      }
    }
    return matches
  }

  private func string(_ value: String, contains query: String, caseSensitive: Bool) -> Bool {
    if caseSensitive {
      return value.contains(query)
    }
    return value.range(of: query, options: [.caseInsensitive, .diacriticInsensitive]) != nil
  }

  private func cliList() -> JSONValue {
    .array(
      configuration.cli.commands.map { command in
        .object([
          "id": .string(command.id),
          "executable": .string(command.executable),
          "description": .string(command.description ?? ""),
          "risk": .string(command.risk ?? "unspecified"),
          "discovery": .array(command.discovery.map { .string($0) }),
          "has_interface": .bool(command.interface != nil),
        ])
      })
  }

  private func cliDescribe(arguments object: [String: JSONValue]) throws -> JSONValue {
    let id = try requiredString("id", in: object)
    let command = try registeredCLICommand(id)
    return cliDescription(command)
  }

  private func cliStatus(arguments object: [String: JSONValue]) throws -> JSONValue {
    let id = try optionalString("id", in: object)
    let commands: [CLICommandConfig]
    if let id {
      commands = [try registeredCLICommand(id)]
    } else {
      commands = configuration.cli.commands
    }

    return .object([
      "commands": .array(commands.map { cliExecutableStatus($0) })
    ])
  }

  private func runCLIHelp(arguments object: [String: JSONValue]) throws -> JSONValue {
    guard object["args"] == nil else {
      throw GatewayToolError.invalidArguments("Unknown argument 'args'; use 'path'.")
    }
    let id = try requiredString("id", in: object)
    let command = try registeredCLICommand(id)
    let path = try optionalStringArray("path", in: object)
    var helpArgv = path
    if helpArgv.last != "--help" && helpArgv.last != "-h" {
      helpArgv.append("--help")
    }

    let result = try runRegisteredCLI(
      command: command,
      args: helpArgv,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: false
    )
    return .object([
      "id": .string(command.id),
      "path": .array(path.map { .string($0) }),
      "help_argv": .array(helpArgv.map { .string($0) }),
      "exec_context": .object([
        "tool": .string("cli.exec"),
        "id": .string(command.id),
        "argv_prefix": .array(path.map { .string($0) }),
      ]),
      "interface": command.interface?.json ?? .null,
      "stdout": .string(result.stdout),
      "stderr": .string(result.stderr),
      "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
    ])
  }

  private func runCLIExec(arguments object: [String: JSONValue]) throws -> JSONValue {
    let id = try requiredString("id", in: object)
    let args = try requiredStringArray("argv", in: object)
    let command = try registeredCLICommand(id)
    return try runRegisteredCLI(
      command: command,
      args: args,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: true
    )
    .json
  }

  private func registeredCLICommand(_ id: String) throws -> CLICommandConfig {
    guard let command = configuration.cli.commands.first(where: { $0.id == id }) else {
      throw GatewayToolError.unknownCLI(id)
    }
    return command
  }

  private func runRegisteredCLI(
    command: CLICommandConfig,
    args: [String],
    timeout: Int?,
    requireArbitraryArgs: Bool
  ) throws -> CommandResult {
    if requireArbitraryArgs && !command.allowAnyArgs {
      throw GatewayToolError.disabled(
        "CLI command '\(command.id)' does not allow arbitrary args.")
    }

    return try commandRunner.run(
      executable: command.executable,
      arguments: args,
      workingDirectory: command.resolvedWorkingDirectory(base: configuration.workspaceDirectory),
      environment: command.env,
      timeoutMilliseconds: timeout ?? command.defaultTimeoutMs
        ?? configuration.policy.defaultTimeoutMs,
      maxOutputBytes: configuration.policy.maxOutputBytes
    )
  }

  private func cliDescription(_ command: CLICommandConfig) -> JSONValue {
    .object([
      "id": .string(command.id),
      "executable": .string(command.executable),
      "description": .string(command.description ?? ""),
      "cwd": command.cwd.map(JSONValue.string) ?? .null,
      "allow_any_args": .bool(command.allowAnyArgs),
      "risk": .string(command.risk ?? "unspecified"),
      "discovery": .array(command.discovery.map { .string($0) }),
      "has_interface": .bool(command.interface != nil),
      "interface": command.interface?.json ?? .null,
    ])
  }

  private func mcpServerList() -> JSONValue {
    .array(
      configuration.mcp.servers.map { server in
        .object([
