  private func downstreamMCPPromptJSON(_ prompt: JSONValue, serverID: String) -> JSONValue {
    guard var object = prompt.objectValue else {
      return prompt
    }
    if let name = object["name"]?.stringValue {
      object["get_context"] = .object([
        "tool": .string("mcp.prompts.get"),
        "arguments": .object([
          "server": .string(serverID),
          "name": .string(name),
          "arguments": .object([:]),
        ]),
      ])
    }
    return .object(object)
  }

  private func optionalStringMap(_ name: String, in object: [String: JSONValue]) throws
    -> [String: String]?
  {
    guard let value = object[name] else {
      return nil
    }
    guard let dictionary = value.objectValue else {
      throw GatewayToolError.invalidArguments("\(name) must be an object.")
    }
    var result: [String: String] = [:]
    for key in dictionary.keys.sorted() {
      guard let string = dictionary[key]?.stringValue else {
        throw GatewayToolError.invalidArguments("\(name).\(key) must be a string.")
      }
      result[key] = string
    }
    return result
  }

  private func jsonObject(_ dictionary: [String: String]) -> JSONValue {
    .object(dictionary.mapValues(JSONValue.string))
  }

  private func spawnProcess(arguments object: [String: JSONValue]) throws -> JSONValue {
    guard object["args"] == nil else {
      throw GatewayToolError.invalidArguments("Unknown argument 'args'; use 'argv'.")
    }
    let id = try requiredString("id", in: object)
    guard let command = configuration.cli.commands.first(where: { $0.id == id }) else {
      throw GatewayToolError.unknownCLI(id)
    }
    guard command.allowAnyArgs else {
      throw GatewayToolError.disabled(
        "CLI command '\(command.id)' does not allow arbitrary args.")
    }
    guard object["argv"] != nil else {
      throw GatewayToolError.invalidArguments("Missing required 'argv'.")
    }
    let args = try optionalStringArray("argv", in: object)
    let processID = try processManager.spawn(
      executable: command.executable,
      arguments: args,
      workingDirectory: command.resolvedWorkingDirectory(base: configuration.workspaceDirectory),
      environment: command.env,
      maxOutputBytes: configuration.policy.maxOutputBytes
    )
    return .object(["process_id": .string(processID)])
  }

  private func listProcesses() throws -> JSONValue {
    .object([
      "processes": .array(try processManager.list().map(\.json))
    ])
  }

  private func readProcess(arguments object: [String: JSONValue]) throws -> JSONValue {
    let id = try requiredString("process_id", in: object)
    return try processManager.read(processID: id).json
  }

  private func cancelProcess(arguments object: [String: JSONValue]) throws -> JSONValue {
    let id = try requiredString("process_id", in: object)
    return try processManager.cancel(processID: id).json
  }

  private func runShell(arguments object: [String: JSONValue]) throws -> JSONValue {
    let timeout = optionalInt("timeout_ms", in: object) ?? configuration.policy.defaultTimeoutMs
    guard timeout > 0 else {
      throw GatewayToolError.invalidArguments("timeout_ms must be greater than zero.")
    }
    return try shellManager.run(
      request: shellLaunchRequest(arguments: object),
      defaultShell: configuration.policy.shellExecutable,
      defaultWorkingDirectory: configuration.workspaceDirectory,
      standardInput: try shellStandardInput(arguments: object),
      timeoutMilliseconds: timeout,
      maxOutputBytes: configuration.policy.maxOutputBytes,
      maxSessions: configuration.policy.maxShellSessions,
      terminationGraceMilliseconds: configuration.policy.shellTerminationGraceMs
    ).json
  }

  private func spawnShell(arguments object: [String: JSONValue]) throws -> JSONValue {
    let timeout = optionalInt("timeout_ms", in: object)
    if let timeout, timeout <= 0 {
      throw GatewayToolError.invalidArguments("timeout_ms must be greater than zero when set.")
    }
    let id = try shellManager.spawn(
      request: shellLaunchRequest(arguments: object),
      defaultShell: configuration.policy.shellExecutable,
      defaultWorkingDirectory: configuration.workspaceDirectory,
      timeoutMilliseconds: timeout,
      maxOutputBytes: configuration.policy.maxOutputBytes,
      maxSessions: configuration.policy.maxShellSessions,
      terminationGraceMilliseconds: configuration.policy.shellTerminationGraceMs
    )
    return .object(["session_id": .string(id)])
  }

  private func listShellSessions(arguments object: [String: JSONValue]) throws -> JSONValue {
    let maxBytes = optionalInt("max_bytes", in: object) ?? 0
    guard maxBytes >= 0 && maxBytes <= configuration.policy.maxOutputBytes else {
      throw GatewayToolError.invalidArguments(
        "max_bytes must be between 0 and policy.max_output_bytes."
      )
    }
    return .object([
      "sessions": .array(
        try shellManager.list(
          maxReadBytes: maxBytes,
          encoding: try shellEncoding(arguments: object)
        ).map(\.json)
      )
    ])
  }

  private func readShellSession(arguments object: [String: JSONValue]) throws -> JSONValue {
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    guard maxBytes >= 0 && maxBytes <= configuration.policy.maxOutputBytes else {
      throw GatewayToolError.invalidArguments(
        "max_bytes must be between 0 and policy.max_output_bytes."
      )
    }
    return try shellManager.read(
      sessionID: requiredString("session_id", in: object),
      stdoutCursor: Int64(optionalInt("stdout_cursor", in: object) ?? 0),
      stderrCursor: Int64(optionalInt("stderr_cursor", in: object) ?? 0),
      maxReadBytes: maxBytes,
      encoding: shellEncoding(arguments: object)
    ).json
  }

  private func writeShellSession(arguments object: [String: JSONValue]) throws -> JSONValue {
    let text = object["text"]?.stringValue
    let base64 = object["base64"]?.stringValue
    guard text == nil || base64 == nil else {
      throw GatewayToolError.invalidArguments("Provide only one of text or base64.")
    }
    let data: Data
    if let text {
      data = Data(text.utf8)
    } else if let base64 {
      guard let decoded = Data(base64Encoded: base64) else {
        throw GatewayToolError.invalidArguments("base64 is not valid Base64 data.")
      }
      data = decoded
    } else {
      data = Data()
    }
    guard data.count <= configuration.policy.maxShellInputBytes else {
      throw GatewayToolError.invalidArguments(
        "Shell input exceeds policy.max_shell_input_bytes."
      )
    }
    return try shellManager.write(
      sessionID: requiredString("session_id", in: object),
      data: data,
      close: object["close"]?.boolValue ?? false
    ).json
  }

  private func cancelShellSession(arguments object: [String: JSONValue]) throws -> JSONValue {
    try shellManager.cancel(
      sessionID: requiredString("session_id", in: object)
    ).json
  }

  private func shellLaunchRequest(arguments object: [String: JSONValue]) throws
    -> ShellLaunchRequest
  {
    let modeValue = object["mode"]?.stringValue ?? ShellLaunchMode.shell.rawValue
    guard let mode = ShellLaunchMode(rawValue: modeValue) else {
      throw GatewayToolError.invalidArguments("mode must be shell or argv.")
    }
    return ShellLaunchRequest(
      mode: mode,
      command: object["command"]?.stringValue,
      executable: object["executable"]?.stringValue,
      argv: try optionalStringArray("argv", in: object),
      shell: object["shell"]?.stringValue,
      workingDirectory: object["cwd"]?.stringValue,
      environment: try optionalStringMap("env", in: object) ?? [:]
    )
  }

  private func shellEncoding(arguments object: [String: JSONValue]) throws -> ShellStreamEncoding {
    let value = object["encoding"]?.stringValue ?? ShellStreamEncoding.utf8.rawValue
    guard let encoding = ShellStreamEncoding(rawValue: value) else {
      throw GatewayToolError.invalidArguments("encoding must be utf8 or base64.")
    }
    return encoding
  }

  private func shellStandardInput(arguments object: [String: JSONValue]) throws -> Data {
    let text = object["stdin_text"]?.stringValue
    let base64 = object["stdin_base64"]?.stringValue
    guard text == nil || base64 == nil else {
      throw GatewayToolError.invalidArguments(
        "Provide only one of stdin_text or stdin_base64."
      )
    }
    let data: Data
    if let text {
      data = Data(text.utf8)
    } else if let base64 {
      guard let decoded = Data(base64Encoded: base64) else {
        throw GatewayToolError.invalidArguments("stdin_base64 is not valid Base64 data.")
      }
      data = decoded
    } else {
      data = Data()
    }
    guard data.count <= configuration.policy.maxShellInputBytes else {
      throw GatewayToolError.invalidArguments(
        "Shell input exceeds policy.max_shell_input_bytes."
      )
    }
    return data
  }

  private func requireShellEnabled() throws {
    guard configuration.policy.shellEnabled else {
      throw GatewayToolError.disabled("Shell is disabled by policy.")
    }
  }

  private func workspaceInfo() throws -> JSONValue {
    .object([
      "server": .object([
        "name": .string(configuration.server.name),
        "http": .object([
          "host": .string(configuration.server.http.host),
          "port": .number(Double(configuration.server.http.port)),
          "path": .string(configuration.server.http.path),
          "health_path": .string(configuration.server.http.healthPath),
          "public_base_url": configuration.server.http.publicBaseURL.map(JSONValue.string) ?? .null,
          "auth": .string(httpAuthMode()),
          "access_token_env": configuration.server.http.accessTokenEnv.map(JSONValue.string)
            ?? .null,
        ]),
      ]),
      "workspace": .object([
        "root": .string(configuration.workspaceDirectory.standardizedFileURL.path)
      ]),
      "policy": .object([
        "default_timeout_ms": .number(Double(configuration.policy.defaultTimeoutMs)),
        "max_output_bytes": .number(Double(configuration.policy.maxOutputBytes)),
        "shell_enabled": .bool(configuration.policy.shellEnabled),
      ]),
      "builtin": .object([
        "enabled": .array(configuration.builtin.enabled.sorted().map { .string($0) })
      ]),
      "cli": .object([
