      "scan_truncated": .bool(scanTruncated),
      "result_truncated": .bool(resultTruncated),
      "truncated": .bool(
        scanTruncated || resultTruncated || envFiles.contains { $0.keysTruncated }),
      "values_redacted": .bool(true),
      "env_files": .array(envFiles.map(\.json)),
    ])
  }

