  private func networkTCPCheck(arguments object: [String: JSONValue]) throws -> JSONValue {
    let host = try requiredString("host", in: object)
    guard let port = optionalInt("port", in: object) else {
      throw GatewayToolError.invalidArguments("Missing required integer argument: port")
    }
    let connectTimeoutSeconds = optionalInt("connect_timeout_seconds", in: object) ?? 5
    let timeout = optionalInt("timeout_ms", in: object) ?? 30_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateNetworkHost(host)
    try validateNetworkPort(port)
    try validateBoundedPositive(
      connectTimeoutSeconds, name: "connect_timeout_seconds", upperBound: 60)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let arguments = ["-G", "\(connectTimeoutSeconds)", "-zv", host, "\(port)"]
    let result = try commandRunner.run(
      executable: "/usr/bin/nc",
      arguments: arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    return .object([
      "operation": .string("network.tcp_check"),
      "host": .string(host),
      "port": .number(Double(port)),
      "connect_timeout_seconds": .number(Double(connectTimeoutSeconds)),
      "argv": .array(arguments.map(JSONValue.string)),
      "max_output_bytes": .number(Double(maxOutputBytes)),
      "result": result.json,
    ])
  }

  private func networkHTTPCheck(arguments object: [String: JSONValue]) throws -> JSONValue {
    let url = try requiredString("url", in: object)
    let method = (try optionalString("method", in: object) ?? "HEAD").uppercased()
    let includeBody = try optionalBool("include_body", in: object) ?? false
    let followRedirects = try optionalBool("follow_redirects", in: object) ?? false
    let maxRedirects = optionalInt("max_redirects", in: object) ?? 5
    let connectTimeoutSeconds = optionalInt("connect_timeout_seconds", in: object) ?? 5
    let timeout = optionalInt("timeout_ms", in: object) ?? 30_000
    let maxBodyBytes = optionalInt("max_body_bytes", in: object) ?? 4_096
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? min(configuration.policy.maxOutputBytes, maxBodyBytes + 16_384)
    let validatedURL = try validateHTTPCheckURL(url)
    guard method == "HEAD" || method == "GET" else {
      throw GatewayToolError.invalidArguments("method must be HEAD or GET.")
    }
    try validateBoundedPositive(maxRedirects, name: "max_redirects", upperBound: 20)
    try validateBoundedPositive(
      connectTimeoutSeconds, name: "connect_timeout_seconds", upperBound: 60)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxBodyBytes, name: "max_body_bytes", upperBound: 1_048_576)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let marker = "__COMPUTER_MCP_HTTP_CHECK_META__"
    var arguments = [
      "--silent",
      "--show-error",
      "--max-time",
      "\(max(1, timeout / 1000))",
      "--connect-timeout",
      "\(connectTimeoutSeconds)",
    ]
    if followRedirects {
      arguments += ["--location", "--max-redirs", "\(maxRedirects)"]
    }
    if method == "HEAD" {
      arguments.append("--head")
    } else {
      arguments += ["--request", "GET"]
    }
    if includeBody, method == "GET" {
      arguments += ["--range", "0-\(maxBodyBytes - 1)", "--output", "-"]
    } else {
      arguments += ["--output", "/dev/null"]
    }
    arguments += [
      "--write-out",
      "\n\(marker)\nhttp_code=%{http_code}\nurl_effective=%{url_effective}\ncontent_type=%{content_type}\nredirect_url=%{redirect_url}\ntime_total=%{time_total}\nsize_download=%{size_download}\n",
      validatedURL.absoluteString,
    ]

    let result = try commandRunner.run(
      executable: "/usr/bin/curl",
      arguments: arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    let parsed = parseHTTPCheckOutput(
      result.stdout,
      marker: marker,
      includeBody: includeBody && method == "GET",
      maxBodyBytes: maxBodyBytes,
      stdoutTruncated: result.stdoutTruncated
    )

    return .object([
      "operation": .string("network.http_check"),
      "url": .string(validatedURL.absoluteString),
      "scheme": .string(validatedURL.scheme ?? ""),
      "host": .string(validatedURL.host ?? ""),
      "method": .string(method),
      "include_body": .bool(includeBody && method == "GET"),
      "follow_redirects": .bool(followRedirects),
      "max_redirects": .number(Double(maxRedirects)),
      "connect_timeout_seconds": .number(Double(connectTimeoutSeconds)),
      "timeout_ms": .number(Double(timeout)),
      "max_body_bytes": .number(Double(maxBodyBytes)),
      "max_output_bytes": .number(Double(maxOutputBytes)),
      "argv": .array(arguments.map(JSONValue.string)),
      "http_code": parsed.httpCode.map { .number(Double($0)) } ?? .null,
      "url_effective": parsed.urlEffective.map(JSONValue.string) ?? .null,
      "content_type": parsed.contentType.map(JSONValue.string) ?? .null,
      "redirect_url": parsed.redirectURL.map(JSONValue.string) ?? .null,
      "time_total_seconds": parsed.timeTotal.map { .number($0) } ?? .null,
      "size_download_bytes": parsed.sizeDownload.map { .number($0) } ?? .null,
      "body": parsed.body.map(JSONValue.string) ?? .null,
      "body_bytes": parsed.body.map { .number(Double($0.utf8.count)) } ?? .null,
      "body_truncated": .bool(parsed.bodyTruncated),
      "meta_found": .bool(parsed.metaFound),
      "result": networkCommandSummary(result),
    ])
  }

  private func parseHTTPCheckOutput(
    _ stdout: String,
    marker: String,
    includeBody: Bool,
    maxBodyBytes: Int,
    stdoutTruncated: Bool
  ) -> HTTPCheckOutput {
    guard let markerRange = stdout.range(of: "\n\(marker)\n", options: .backwards) else {
      let body = includeBody && !stdout.isEmpty ? String(stdout.prefix(maxBodyBytes)) : nil
      return HTTPCheckOutput(
        metaFound: false,
        httpCode: nil,
        urlEffective: nil,
        contentType: nil,
        redirectURL: nil,
        timeTotal: nil,
        sizeDownload: nil,
        body: body,
        bodyTruncated: includeBody && (stdoutTruncated || stdout.utf8.count > maxBodyBytes)
      )
    }

    let bodyText = String(stdout[..<markerRange.lowerBound])
    let metaText = String(stdout[markerRange.upperBound...])
    let meta = Dictionary(
      uniqueKeysWithValues: metaText.split(separator: "\n").compactMap {
        line -> (String, String)? in
        guard let separator = line.firstIndex(of: "=") else {
          return nil
        }
        let key = String(line[..<separator])
        let value = String(line[line.index(after: separator)...])
        return (key, value)
      })

    let body: String?
    let bodyTruncated: Bool
    if includeBody {
      let limitedBody =
        bodyText.utf8.count > maxBodyBytes ? String(bodyText.prefix(maxBodyBytes)) : bodyText
      body = limitedBody
      bodyTruncated =
        stdoutTruncated || bodyText.utf8.count > maxBodyBytes
        || (Double(meta["size_download"] ?? "") ?? 0) > Double(maxBodyBytes)
    } else {
      body = nil
      bodyTruncated = false
    }

    return HTTPCheckOutput(
      metaFound: true,
      httpCode: Int(meta["http_code"] ?? ""),
      urlEffective: emptyStringAsNil(meta["url_effective"]),
      contentType: emptyStringAsNil(meta["content_type"]),
      redirectURL: emptyStringAsNil(meta["redirect_url"]),
      timeTotal: Double(meta["time_total"] ?? ""),
      sizeDownload: Double(meta["size_download"] ?? ""),
      body: body,
      bodyTruncated: bodyTruncated
    )
  }

  private func networkListeners(arguments object: [String: JSONValue]) throws -> JSONValue {
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let arguments = ["-nP", "-iTCP", "-sTCP:LISTEN"]
    let result = try commandRunner.run(
      executable: "/usr/sbin/lsof",
      arguments: arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    return .object([
      "operation": .string("network.listeners"),
      "argv": .array(arguments.map(JSONValue.string)),
      "max_output_bytes": .number(Double(maxOutputBytes)),
      "result": result.json,
    ])
  }

  private func macOSUserDirectories(arguments object: [String: JSONValue]) throws -> JSONValue {
    let includeMissing = try optionalBool("include_missing", in: object) ?? true
    let includeSystem = try optionalBool("include_system", in: object) ?? true
    let includeTemporary = try optionalBool("include_temporary", in: object) ?? true

    let directories = macOSUserDirectoryCatalog(
      includeSystem: includeSystem,
      includeTemporary: includeTemporary
    )
    let rows = directories.compactMap { entry -> MacOSUserDirectoryInfo? in
      let info = macOSUserDirectoryInfo(entry)
      if !includeMissing && !info.exists {
        return nil
      }
      return info
    }

    return .object([
      "operation": .string("macos.user_directories"),
      "include_missing": .bool(includeMissing),
      "include_system": .bool(includeSystem),
      "include_temporary": .bool(includeTemporary),
      "directory_count": .number(Double(rows.count)),
      "directories": .array(rows.map(\.json)),
    ])
  }

  private func macOSUserDirectoryCatalog(
    includeSystem: Bool,
    includeTemporary: Bool
  ) -> [MacOSUserDirectoryEntry] {
    let fileManager = FileManager.default
    let home = URL(fileURLWithPath: NSHomeDirectory(), isDirectory: true)
    var entries: [MacOSUserDirectoryEntry] = [
      MacOSUserDirectoryEntry(
        id: "home",
        category: "home",
        path: home.path,
        description: "Current user's home directory."
      ),
      MacOSUserDirectoryEntry(
        id: "desktop",
        category: "user_content",
        path: fileManager.urls(for: .desktopDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Desktop", isDirectory: true).path,
        description: "Current user's Desktop directory."
      ),
      MacOSUserDirectoryEntry(
        id: "documents",
        category: "user_content",
        path: fileManager.urls(for: .documentDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Documents", isDirectory: true).path,
        description: "Current user's Documents directory."
      ),
      MacOSUserDirectoryEntry(
        id: "downloads",
        category: "user_content",
        path: fileManager.urls(for: .downloadsDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Downloads", isDirectory: true).path,
        description: "Current user's Downloads directory."
      ),
      MacOSUserDirectoryEntry(
        id: "movies",
        category: "user_content",
        path: fileManager.urls(for: .moviesDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Movies", isDirectory: true).path,
        description: "Current user's Movies directory."
      ),
      MacOSUserDirectoryEntry(
        id: "music",
        category: "user_content",
        path: fileManager.urls(for: .musicDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Music", isDirectory: true).path,
        description: "Current user's Music directory."
      ),
      MacOSUserDirectoryEntry(
        id: "pictures",
        category: "user_content",
        path: fileManager.urls(for: .picturesDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Pictures", isDirectory: true).path,
        description: "Current user's Pictures directory."
      ),
      MacOSUserDirectoryEntry(
        id: "user_library",
        category: "user_library",
        path: fileManager.urls(for: .libraryDirectory, in: .userDomainMask).first?.path
          ?? home.appendingPathComponent("Library", isDirectory: true).path,
        description: "Current user's Library directory."
      ),
      MacOSUserDirectoryEntry(
        id: "user_applications",
        category: "applications",
        path: home.appendingPathComponent("Applications", isDirectory: true).path,
        description: "Current user's Applications directory."
      ),
    ]

    if includeSystem {
      entries.append(
        contentsOf: [
          MacOSUserDirectoryEntry(
            id: "local_applications",
            category: "applications",
            path: "/Applications",
            description: "Local system-wide Applications directory."
          ),
          MacOSUserDirectoryEntry(
            id: "system_applications",
            category: "applications",
            path: "/System/Applications",
            description: "Apple system Applications directory."
          ),
        ])
    }

    if includeTemporary {
      entries.append(
        MacOSUserDirectoryEntry(
          id: "temporary",
          category: "temporary",
          path: URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true).path,
          description: "Current process temporary directory."
        ))
    }

    return entries
  }

  private func macOSUserDirectoryInfo(_ entry: MacOSUserDirectoryEntry)
    -> MacOSUserDirectoryInfo
  {
    let path = (entry.path as NSString).standardizingPath
    let attributes = try? FileManager.default.attributesOfItem(atPath: path)
    let symlinkDestination = try? FileManager.default.destinationOfSymbolicLink(atPath: path)
    let exists = attributes != nil
    let type =
      exists
      ? (symlinkDestination == nil ? fileType(attributes?[.type]) : "symlink")
      : "missing"
    let isDirectory = type == "directory"

    return MacOSUserDirectoryInfo(
      id: entry.id,
      category: entry.category,
      description: entry.description,
      path: path,
      exists: exists,
      type: type,
      size: (attributes?[.size] as? NSNumber)?.int64Value,
      createdAt: attributes?[.creationDate] as? Date,
      modifiedAt: attributes?[.modificationDate] as? Date,
      isReadable: exists && FileManager.default.isReadableFile(atPath: path),
      isWritable: exists && FileManager.default.isWritableFile(atPath: path),
      isTraversable: isDirectory && FileManager.default.isExecutableFile(atPath: path),
      isSymlink: symlinkDestination != nil,
      symlinkDestination: symlinkDestination
    )
  }

  private func macOSDefaultApplication(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object)
    let urlString = try optionalString("url", in: object)
    let includeCandidates = try optionalBool("include_candidates", in: object) ?? false
    let maxCandidates = optionalInt("max_candidates", in: object) ?? 20
    try validateBoundedPositive(maxCandidates, name: "max_candidates", upperBound: 200)

    let targetCount = [path, urlString].compactMap { value in
      value?.isEmpty == false ? value : nil
    }.count
    guard targetCount == 1 else {
      throw GatewayToolError.invalidArguments("Provide exactly one of: path, url.")
    }

    let targetURL: URL
    let target: JSONValue
    if let path, !path.isEmpty {
      try validateUTF8ByteLimit(path, name: "path", maxBytes: 4_096)
      let fileURL = try resolvedWorkspaceURL(path)
      guard FileManager.default.fileExists(atPath: fileURL.path) else {
        throw GatewayToolError.invalidArguments("Path does not exist: \(path)")
      }
      targetURL = fileURL
      target = .object([
        "type": .string("path"),
        "path": .string(fileURL.path),
        "workspace_relative_path": .string(workspaceRelativePath(fileURL)),
      ])
    } else {
      let urlString = urlString ?? ""
      try validateUTF8ByteLimit(urlString, name: "url", maxBytes: 4_096)
      guard let url = URL(string: urlString), let scheme = url.scheme?.lowercased() else {
        throw GatewayToolError.invalidArguments("url must be an absolute URL.")
      }
      let allowedSchemes = Set(["http", "https", "mailto"])
      guard allowedSchemes.contains(scheme) else {
        throw GatewayToolError.invalidArguments(
          "url scheme must be one of: http, https, mailto.")
      }
      if ["http", "https"].contains(scheme), url.host?.isEmpty ?? true {
        throw GatewayToolError.invalidArguments("http and https URLs must include a host.")
      }
      targetURL = url
      target = .object([
        "type": .string("url"),
        "url": .string(urlString),
        "scheme": .string(scheme),
      ])
    }

    let defaultApplication = NSWorkspace.shared.urlForApplication(toOpen: targetURL)
    let candidates: [URL]
    if includeCandidates {
      var seen = Set<String>()
      candidates = NSWorkspace.shared.urlsForApplications(toOpen: targetURL).compactMap { url in
        let path = url.standardizedFileURL.path
        guard seen.insert(path).inserted else {
          return nil
        }
        return url
      }
    } else {
      candidates = []
    }
    let selectedCandidates = Array(candidates.prefix(maxCandidates))

    return .object([
      "operation": .string("macos.default_application"),
      "target": target,
      "include_candidates": .bool(includeCandidates),
      "max_candidates": .number(Double(maxCandidates)),
      "default_application_available": .bool(defaultApplication != nil),
      "default_application": defaultApplication.map { macOSApplicationInfo(url: $0).json } ?? .null,
      "candidate_count": .number(Double(candidates.count)),
      "candidate_applications": .array(
        selectedCandidates.map { macOSApplicationInfo(url: $0).json }),
      "truncated": .bool(candidates.count > selectedCandidates.count),
    ])
  }

  private func macOSApplications(arguments object: [String: JSONValue]) throws -> JSONValue {
    let includeSystem = try optionalBool("include_system", in: object) ?? true
    let includeUser = try optionalBool("include_user", in: object) ?? true
    let maxResults = optionalInt("max_results", in: object) ?? 500
    let maxDepth = optionalInt("max_depth", in: object) ?? 3
    let maxVisited = optionalInt("max_visited", in: object) ?? 20_000
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 5_000)
    try validateBoundedNonNegative(maxDepth, name: "max_depth", upperBound: 8)
    try validateBoundedPositive(maxVisited, name: "max_visited", upperBound: 200_000)

    let roots = macOSApplicationRoots(includeSystem: includeSystem, includeUser: includeUser)
    var applications: [MacOSApplicationInfo] = []
    var visited = 0
    var truncated = false

    for root in roots where !truncated {
      try collectMacOSApplications(
        root: root,
        currentDepth: 0,
        maxDepth: maxDepth,
        maxResults: maxResults,
        maxVisited: maxVisited,
        applications: &applications,
        visited: &visited,
        truncated: &truncated
      )
    }

    applications.sort {
      if $0.name == $1.name {
        return $0.path.localizedStandardCompare($1.path) == .orderedAscending
      }
      return $0.name.localizedStandardCompare($1.name) == .orderedAscending
    }

    return .object([
      "include_system": .bool(includeSystem),
      "include_user": .bool(includeUser),
      "roots": .array(roots.map { .string($0.path) }),
      "max_depth": .number(Double(maxDepth)),
      "max_visited": .number(Double(maxVisited)),
      "visited_entries": .number(Double(visited)),
      "application_count": .number(Double(applications.count)),
      "truncated": .bool(truncated),
      "applications": .array(applications.map(\.json)),
    ])
  }

  private func macOSScreens() -> JSONValue {
    let screens = NSScreen.screens.enumerated().map { index, screen in
      var deviceID: JSONValue = .null
      if let screenNumber = screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")]
        as? NSNumber
      {
        deviceID = .number(screenNumber.doubleValue)
      }

      return JSONValue.object([
        "index": .number(Double(index)),
        "localized_name": .string(screen.localizedName),
        "is_main": .bool(screen == NSScreen.main),
        "is_deepest": .bool(screen == NSScreen.deepest),
        "frame": rectJSON(screen.frame),
        "visible_frame": rectJSON(screen.visibleFrame),
        "backing_scale_factor": .number(Double(screen.backingScaleFactor)),
        "color_space": screen.colorSpace?.localizedName.map(JSONValue.string) ?? .null,
        "device_id": deviceID,
      ])
    }

    return .object([
      "screen_count": .number(Double(screens.count)),
      "screens": .array(screens),
    ])
  }

  private func macOSSpotlightSearch(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let query = try requiredString("query", in: object)
    let maxResults = optionalInt("max_results", in: object) ?? 100
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateUTF8ByteLimit(query, name: "query", maxBytes: 4_096)
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 10_000)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let directory = try resolvedWorkspaceURL(path)
    try requireDirectory(directory, originalPath: path)

    let result = try commandRunner.run(
      executable: "/usr/bin/mdfind",
      arguments: ["-onlyin", directory.path, query],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    let base = configuration.workspaceDirectory.standardizedFileURL.resolvingSymlinksInPath()
    let basePath = base.path
    let basePrefix = basePath.hasSuffix("/") ? basePath : "\(basePath)/"
    var matched: [FileInfo] = []
    var skippedEscaped = 0
    var skippedMissing = 0
    var totalReturnedPaths = 0

    for line in result.stdout.split(separator: "\n", omittingEmptySubsequences: true) {
      totalReturnedPaths += 1
      let candidate = URL(fileURLWithPath: String(line))
        .standardizedFileURL
        .resolvingSymlinksInPath()
      guard candidate.path == basePath || candidate.path.hasPrefix(basePrefix) else {
        skippedEscaped += 1
        continue
      }

      guard FileManager.default.fileExists(atPath: candidate.path) else {
        skippedMissing += 1
        continue
      }

      if matched.count < maxResults {
        matched.append(try fileInfo(url: candidate))
      }
    }

    matched.sort {
      $0.workspaceRelativePath.localizedStandardCompare($1.workspaceRelativePath)
        == .orderedAscending
    }
    let containedPathCount = totalReturnedPaths - skippedEscaped - skippedMissing

    return .object([
      "operation": .string("macos.spotlight_search"),
      "path": .string(directory.path),
      "workspace_relative_path": .string(workspaceRelativePath(directory)),
      "query": .string(query),
      "max_results": .number(Double(maxResults)),
      "max_output_bytes": .number(Double(maxOutputBytes)),
      "returned_path_count": .number(Double(totalReturnedPaths)),
      "result_count": .number(Double(matched.count)),
      "truncated": .bool(result.stdoutTruncated || containedPathCount > matched.count),
      "skipped_escaped_results": .number(Double(skippedEscaped)),
      "skipped_missing_results": .number(Double(skippedMissing)),
      "results": .array(matched.map(\.json)),
      "command": result.json,
    ])
  }

  private func macOSRunningApplications(arguments object: [String: JSONValue]) throws -> JSONValue {
    let includeBackground = try optionalBool("include_background", in: object) ?? false
    let query = try optionalString("query", in: object)
    let matchMode = try fileNameMatchMode(try optionalString("match", in: object) ?? "contains")
    let caseSensitive = try optionalBool("case_sensitive", in: object) ?? false
    let maxResults = optionalInt("max_results", in: object) ?? 200
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 2_000)

    let running = NSWorkspace.shared.runningApplications
      .filter { includeBackground || $0.activationPolicy == .regular }
      .filter { application in
        guard let query, !query.isEmpty else {
          return true
        }
        return macOSRunningApplication(
          application,
          matches: query,
          mode: matchMode,
          caseSensitive: caseSensitive
        )
      }
      .sorted { lhs, rhs in
        let lhsName = lhs.localizedName ?? lhs.bundleIdentifier ?? ""
        let rhsName = rhs.localizedName ?? rhs.bundleIdentifier ?? ""
        if lhsName == rhsName {
          return lhs.processIdentifier < rhs.processIdentifier
        }
        return lhsName.localizedStandardCompare(rhsName) == .orderedAscending
      }

    let selected = Array(running.prefix(maxResults))
    return .object([
      "include_background": .bool(includeBackground),
      "query": query.map(JSONValue.string) ?? .null,
      "match": .string(matchMode.rawValue),
      "case_sensitive": .bool(caseSensitive),
      "max_results": .number(Double(maxResults)),
      "application_count": .number(Double(running.count)),
      "truncated": .bool(running.count > selected.count),
      "applications": .array(selected.map { macOSRunningApplicationInfo($0).json }),
    ])
  }

  private func macOSFrontmostApplication() -> JSONValue {
    let application = NSWorkspace.shared.frontmostApplication
    return .object([
      "available": .bool(application != nil),
      "application": application.map { macOSRunningApplicationInfo($0).json } ?? .null,
    ])
  }

  private func describeEnvironment() -> JSONValue {
    let processEnvironment = ProcessInfo.processInfo.environment
    var declaredKeys = Set<String>()

    var serverEntries: [JSONValue] = []
    if let accessTokenEnv = configuration.server.http.accessTokenEnv {
      serverEntries.append(
        environmentEntry(
          key: accessTokenEnv,
          owner: "server.http",
          purpose: "access_token_env",
          valueOrigin: "process_environment",
          processEnvironment: processEnvironment,
          declaredKeys: &declaredKeys
        ))
    }
    let cliEntries: [JSONValue] = configuration.cli.commands.map { command in
      JSONValue.object([
        "id": .string(command.id),
        "env": .array(
          command.env.keys.sorted().map { key in
            environmentEntry(
              key: key,
              owner: "cli.\(command.id)",
              purpose: "env",
              valueOrigin: "configured_provider_env",
              processEnvironment: processEnvironment,
              declaredKeys: &declaredKeys
            )
          }),
      ])
    }

    let mcpEntries: [JSONValue] = configuration.mcp.servers.map { server in
      JSONValue.object([
        "id": .string(server.id),
        "env": .array(
          server.env.keys.sorted().map { key in
            environmentEntry(
              key: key,
              owner: "mcp.\(server.id)",
              purpose: "env",
              valueOrigin: "configured_provider_env",
              processEnvironment: processEnvironment,
              declaredKeys: &declaredKeys
            )
          }),
      ])
    }

    let presentCount = declaredKeys.filter { processEnvironment[$0] != nil }.count
    return .object([
      "summary": .object([
        "declared_key_count": .number(Double(declaredKeys.count)),
        "process_environment_present_count": .number(Double(presentCount)),
        "values_redacted": .bool(true),
      ]),
      "server": .array(serverEntries),
      "cli": .array(cliEntries),
      "mcp": .array(mcpEntries),
    ])
  }

  private func fileExists(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let url = try resolvedWorkspaceURL(path)
    var isDirectory: ObjCBool = false
    let exists = FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory)

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "exists": .bool(exists),
      "is_directory": exists ? .bool(isDirectory.boolValue) : .null,
      "is_file": exists ? .bool(!isDirectory.boolValue) : .null,
    ])
  }

  private func listFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let requestedPath = try optionalStringAllowingEmpty("path", in: object)
    let path =
      requestedPath.flatMap { value in
        value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : value
      } ?? "."
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let recursiveDepth = optionalInt("recursive_depth", in: object) ?? 0
    let maxEntries = optionalInt("max_entries", in: object) ?? 200

    guard recursiveDepth >= 0 else {
      throw GatewayToolError.invalidArguments("recursive_depth must be zero or greater.")
    }
    guard maxEntries > 0 else {
      throw GatewayToolError.invalidArguments("max_entries must be greater than zero.")
    }
    guard maxEntries <= 10_000 else {
      throw GatewayToolError.invalidArguments("max_entries must be less than or equal to 10000.")
    }

    let directory = try resolvedWorkspaceURL(path)
    var isDirectory: ObjCBool = false
    guard FileManager.default.fileExists(atPath: directory.path, isDirectory: &isDirectory) else {
      throw GatewayToolError.invalidArguments("Directory does not exist: \(path)")
    }
    guard isDirectory.boolValue else {
      throw GatewayToolError.invalidArguments("Path is not a directory: \(path)")
    }

    var entries: [ListedFile] = []
    var truncated = false
    try collectDirectoryEntries(
      directory: directory,
      currentDepth: 0,
      maxDepth: recursiveDepth,
      includeHidden: includeHidden,
      maxEntries: maxEntries,
      entries: &entries,
      truncated: &truncated
    )
    entries.sort { $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending }

    return .object([
      "path": .string(directory.path),
      "workspace_relative_path": .string(workspaceRelativePath(directory)),
      "recursive_depth": .number(Double(recursiveDepth)),
      "include_hidden": .bool(includeHidden),
      "max_entries": .number(Double(maxEntries)),
      "entry_count": .number(Double(entries.count)),
      "truncated": .bool(truncated),
      "entries": .array(entries.map(\.json)),
    ])
  }

  private func treeFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let maxDepth = optionalInt("max_depth", in: object) ?? 2
    let maxEntries = optionalInt("max_entries", in: object) ?? 500
    let directoriesOnly = try optionalBool("directories_only", in: object) ?? false

    try validateBoundedNonNegative(maxDepth, name: "max_depth", upperBound: 20)
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 50_000)

    let root = try resolvedWorkspaceURL(path)
    try requireDirectory(root, originalPath: path)

    var emitted = 0
    var truncated = false
    let tree = try fileTreeNode(
      url: root,
      depth: 0,
      maxDepth: maxDepth,
      includeHidden: includeHidden,
      directoriesOnly: directoriesOnly,
      maxEntries: maxEntries,
      emitted: &emitted,
      truncated: &truncated
    )

    return .object([
      "path": .string(root.path),
      "workspace_relative_path": .string(workspaceRelativePath(root)),
      "include_hidden": .bool(includeHidden),
      "max_depth": .number(Double(maxDepth)),
      "max_entries": .number(Double(maxEntries)),
      "directories_only": .bool(directoriesOnly),
      "entry_count": .number(Double(emitted)),
      "truncated": .bool(truncated),
      "tree": tree,
    ])
  }

  private func statFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let url = try resolvedWorkspaceURL(path)
    return try fileInfo(url: url).json
  }

  private func filePermissions(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    let attributes = try FileManager.default.attributesOfItem(atPath: url.path)
    let mode = (attributes[.posixPermissions] as? NSNumber)?.intValue
    let ownerID = (attributes[.ownerAccountID] as? NSNumber)?.intValue
    let groupID = (attributes[.groupOwnerAccountID] as? NSNumber)?.intValue
    let ownerName = attributes[.ownerAccountName] as? String
    let groupName = attributes[.groupOwnerAccountName] as? String
    let immutable = (attributes[.immutable] as? NSNumber)?.boolValue
    let appendOnly = (attributes[.appendOnly] as? NSNumber)?.boolValue
    let extensionHidden = (attributes[.extensionHidden] as? NSNumber)?.boolValue

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "type": .string(info.type),
      "mode": mode.map { .number(Double($0)) } ?? .null,
      "mode_octal": mode.map { .string(String(format: "%04o", $0 & 0o7777)) } ?? .null,
      "owner_account_id": ownerID.map { .number(Double($0)) } ?? .null,
      "owner_account_name": ownerName.map(JSONValue.string) ?? .null,
      "group_owner_account_id": groupID.map { .number(Double($0)) } ?? .null,
      "group_owner_account_name": groupName.map(JSONValue.string) ?? .null,
      "permissions": mode.map(permissionSummary) ?? .null,
      "current_process_access": .object([
        "readable": .bool(info.isReadable),
        "writable": .bool(info.isWritable),
        "executable": .bool(info.isExecutable),
      ]),
      "flags": .object([
        "immutable": immutable.map(JSONValue.bool) ?? .null,
        "append_only": appendOnly.map(JSONValue.bool) ?? .null,
        "extension_hidden": extensionHidden.map(JSONValue.bool) ?? .null,
      ]),
    ])
  }

  private func chmodFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let mode = try parsePOSIXMode(try requiredString("mode", in: object), name: "mode")
    let expectedCurrentMode = try optionalString("expected_current_mode", in: object)
      .map { try parsePOSIXMode($0, name: "expected_current_mode") }
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let url = try resolvedWorkspaceURL(path)

    guard FileManager.default.fileExists(atPath: url.path) else {
      throw GatewayToolError.invalidArguments("Path does not exist: \(path)")
    }

    let attributesBefore = try FileManager.default.attributesOfItem(atPath: url.path)
    let modeBefore = (attributesBefore[.posixPermissions] as? NSNumber)?.intValue
    if let expectedCurrentMode, modeBefore.map({ $0 & 0o7777 }) != expectedCurrentMode {
      throw GatewayToolError.invalidArguments("expected_current_mode does not match current mode.")
    }

    if !dryRun {
      try FileManager.default.setAttributes([.posixPermissions: mode], ofItemAtPath: url.path)
    }
    let attributesAfter = try FileManager.default.attributesOfItem(atPath: url.path)
    let modeAfter = (attributesAfter[.posixPermissions] as? NSNumber)?.intValue
    let normalizedModeBefore = modeBefore.map { $0 & 0o7777 }
    let normalizedModeAfter = modeAfter.map { $0 & 0o7777 }

    return .object([
      "operation": .string("file.chmod"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "dry_run": .bool(dryRun),
      "mode_before": normalizedModeBefore.map { .number(Double($0)) } ?? .null,
      "mode_before_octal": normalizedModeBefore.map { .string(String(format: "%04o", $0)) }
        ?? .null,
      "mode_after": normalizedModeAfter.map { .number(Double($0)) } ?? .null,
      "mode_after_octal": normalizedModeAfter.map { .string(String(format: "%04o", $0)) }
        ?? .null,
      "requested_mode": .number(Double(mode)),
      "requested_mode_octal": .string(String(format: "%04o", mode)),
      "would_mode_after": .number(Double(mode)),
      "would_mode_after_octal": .string(String(format: "%04o", mode)),
      "would_change": normalizedModeBefore.map { $0 != mode }.map(JSONValue.bool) ?? .null,
      "changed": .bool(!dryRun && normalizedModeBefore.map { $0 != mode } == true),
      "result": dryRun ? .null : try fileInfo(url: url).json,
    ])
  }

  private func typeFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let result = try commandRunner.run(
      executable: "/usr/bin/file",
      arguments: ["-b", "--mime", url.path],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    let raw = result.stdout.trimmingCharacters(in: .whitespacesAndNewlines)
    let parts = raw.split(separator: ";", maxSplits: 1, omittingEmptySubsequences: false)
    let mimeType = parts.first.map { String($0).trimmingCharacters(in: .whitespaces) } ?? ""
    var charset: String?
    if parts.count > 1 {
      for parameter in parts[1].split(separator: ";") {
        let trimmed = String(parameter).trimmingCharacters(in: .whitespaces)
        if trimmed.hasPrefix("charset=") {
          charset = String(trimmed.dropFirst("charset=".count))
          break
        }
      }
    }

    return .object([
      "operation": .string("file.type"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "mime_type": mimeType.isEmpty ? .null : .string(mimeType),
      "charset": charset.map(JSONValue.string) ?? .null,
      "raw": .string(raw),
      "result": result.json,
    ])
  }

  private func countFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let result = try commandRunner.run(
      executable: "/usr/bin/wc",
      arguments: ["-l", "-w", "-c", url.path],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    let tokens = result.stdout.split { $0 == " " || $0 == "\t" || $0 == "\n" }
    let lineCount = tokens.count >= 1 ? Int(tokens[0]) : nil
    let wordCount = tokens.count >= 2 ? Int(tokens[1]) : nil
    let byteCount = tokens.count >= 3 ? Int(tokens[2]) : nil

    return .object([
      "operation": .string("file.count"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "line_count": lineCount.map { .number(Double($0)) } ?? .null,
      "word_count": wordCount.map { .number(Double($0)) } ?? .null,
      "byte_count": byteCount.map { .number(Double($0)) } ?? .null,
      "result": result.json,
    ])
  }

  private func diskUsage(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let timeout = optionalInt("timeout_ms", in: object) ?? 30_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    let result = try commandRunner.run(
      executable: "/usr/bin/du",
      arguments: ["-sk", url.path],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    let tokens = result.stdout.split { $0 == " " || $0 == "\t" || $0 == "\n" }
    let usageKiB = tokens.first.flatMap { Int64($0) }

    return .object([
      "operation": .string("file.disk_usage"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "type": .string(info.type),
      "apparent_size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "disk_usage_kib": usageKiB.map { .number(Double($0)) } ?? .null,
      "disk_usage_bytes": usageKiB.map { .number(Double($0) * 1_024) } ?? .null,
      "result": result.json,
    ])
  }

  private func fileVolumeInfo(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    let keys = Set(volumeResourceKeys())
    let values = try url.resourceValues(forKeys: keys)
    let volumeURL = values.volume ?? url

    return .object([
      "operation": .string("file.volume_info"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "type": .string(info.type),
      "volume": volumeInfo(url: volumeURL, keys: keys),
    ])
  }

  private func findFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let query = try requiredString("query", in: object)
    let matchMode = try fileNameMatchMode(try optionalString("match", in: object) ?? "contains")
    let caseSensitive = try optionalBool("case_sensitive", in: object) ?? false
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let maxDepth = optionalInt("max_depth", in: object) ?? 8
    let maxResults = optionalInt("max_results", in: object) ?? 200
    let maxVisited = optionalInt("max_visited", in: object) ?? 20_000

    try validateNonNegative(maxDepth, name: "max_depth")
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 10_000)
    try validateBoundedPositive(maxVisited, name: "max_visited", upperBound: 200_000)

    let directory = try resolvedWorkspaceURL(path)
    try requireDirectory(directory, originalPath: path)

    var results: [FileInfo] = []
    var visited = 0
    var truncated = false
    try collectFindResults(
      directory: directory,
      currentDepth: 0,
      maxDepth: maxDepth,
      query: query,
      matchMode: matchMode,
      caseSensitive: caseSensitive,
      includeHidden: includeHidden,
      maxResults: maxResults,
      maxVisited: maxVisited,
      visited: &visited,
      results: &results,
      truncated: &truncated
    )
    results.sort {
      $0.workspaceRelativePath.localizedStandardCompare($1.workspaceRelativePath)
        == .orderedAscending
    }

    return .object([
      "path": .string(directory.path),
      "workspace_relative_path": .string(workspaceRelativePath(directory)),
      "query": .string(query),
      "match": .string(matchMode.rawValue),
      "case_sensitive": .bool(caseSensitive),
      "include_hidden": .bool(includeHidden),
      "max_depth": .number(Double(maxDepth)),
      "max_results": .number(Double(maxResults)),
      "max_visited": .number(Double(maxVisited)),
      "visited_entries": .number(Double(visited)),
      "result_count": .number(Double(results.count)),
      "truncated": .bool(truncated),
      "results": .array(results.map(\.json)),
    ])
  }

  private func searchFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let query = try requiredString("query", in: object)
    let caseSensitive = try optionalBool("case_sensitive", in: object) ?? false
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let maxDepth = optionalInt("max_depth", in: object) ?? 8
    let maxFiles = optionalInt("max_files", in: object) ?? 500
    let maxMatches = optionalInt("max_matches", in: object) ?? 100
    let maxBytesPerFile = optionalInt("max_bytes_per_file", in: object) ?? 1_048_576

    try validateNonNegative(maxDepth, name: "max_depth")
    try validateBoundedPositive(maxFiles, name: "max_files", upperBound: 50_000)
    try validateBoundedPositive(maxMatches, name: "max_matches", upperBound: 10_000)
    try validateBoundedPositive(maxBytesPerFile, name: "max_bytes_per_file", upperBound: 20_971_520)

    let root = try resolvedWorkspaceURL(path)
    var matches: [FileSearchMatch] = []
    var filesScanned = 0
    var filesSkipped = 0
    var bytesScanned = 0
    var truncatedFiles = 0
    var truncated = false

    let rootInfo = try fileInfo(url: root)
    if rootInfo.type == "directory" {
      try collectSearchMatches(
        directory: root,
        currentDepth: 0,
        maxDepth: maxDepth,
        query: query,
        caseSensitive: caseSensitive,
        includeHidden: includeHidden,
        maxFiles: maxFiles,
        maxMatches: maxMatches,
        maxBytesPerFile: maxBytesPerFile,
        filesScanned: &filesScanned,
        filesSkipped: &filesSkipped,
        bytesScanned: &bytesScanned,
        truncatedFiles: &truncatedFiles,
        matches: &matches,
        truncated: &truncated
      )
    } else {
      try searchFileIfAllowed(
        url: root,
        info: rootInfo,
        query: query,
        caseSensitive: caseSensitive,
        maxFiles: maxFiles,
        maxMatches: maxMatches,
        maxBytesPerFile: maxBytesPerFile,
        filesScanned: &filesScanned,
        filesSkipped: &filesSkipped,
        bytesScanned: &bytesScanned,
        truncatedFiles: &truncatedFiles,
        matches: &matches,
        truncated: &truncated
      )
    }

    return .object([
      "path": .string(root.path),
      "workspace_relative_path": .string(workspaceRelativePath(root)),
      "query": .string(query),
      "case_sensitive": .bool(caseSensitive),
      "include_hidden": .bool(includeHidden),
      "max_depth": .number(Double(maxDepth)),
      "max_files": .number(Double(maxFiles)),
      "max_matches": .number(Double(maxMatches)),
      "max_bytes_per_file": .number(Double(maxBytesPerFile)),
      "files_scanned": .number(Double(filesScanned)),
      "files_skipped": .number(Double(filesSkipped)),
      "bytes_scanned": .number(Double(bytesScanned)),
      "truncated_files": .number(Double(truncatedFiles)),
      "match_count": .number(Double(matches.count)),
      "truncated": .bool(truncated),
      "matches": .array(matches.map(\.json)),
    ])
  }

  private func fileTimeline(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let maxDepth = optionalInt("max_depth", in: object) ?? 8
    let maxResults = optionalInt("max_results", in: object) ?? 200
    let maxScanEntries = optionalInt("max_scan_entries", in: object) ?? 20_000
    let sort = try fileTimelineSort(try optionalString("sort", in: object) ?? "modified_desc")
    let modifiedAfter = try optionalISO8601Date("modified_after", in: object)
    let modifiedBefore = try optionalISO8601Date("modified_before", in: object)
    if let modifiedAfter, let modifiedBefore, modifiedAfter > modifiedBefore {
      throw GatewayToolError.invalidArguments(
        "modified_after must be earlier than or equal to modified_before.")
    }

    try validateBoundedNonNegative(maxDepth, name: "max_depth", upperBound: 50)
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 10_000)
    try validateBoundedPositive(maxScanEntries, name: "max_scan_entries", upperBound: 200_000)

    let directory = try resolvedWorkspaceURL(path)
    try requireDirectory(directory, originalPath: path)

    var scannedEntries = 0
    var scannedFileCount = 0
    var skippedMissingModifiedDateCount = 0
    var scanTruncated = false
    var entries: [TimelineFileEntry] = []
    try collectTimelineFiles(
      directory: directory,
      currentDepth: 0,
      maxDepth: maxDepth,
      includeHidden: includeHidden,
      modifiedAfter: modifiedAfter,
      modifiedBefore: modifiedBefore,
      maxScanEntries: maxScanEntries,
      scannedEntries: &scannedEntries,
      scannedFileCount: &scannedFileCount,
      skippedMissingModifiedDateCount: &skippedMissingModifiedDateCount,
      scanTruncated: &scanTruncated,
      entries: &entries
    )

    let sortedEntries = entries.sorted { lhs, rhs in
      switch sort {
      case .modifiedDesc:
        if lhs.modifiedAt != rhs.modifiedAt {
          return lhs.modifiedAt > rhs.modifiedAt
        }
      case .modifiedAsc:
        if lhs.modifiedAt != rhs.modifiedAt {
          return lhs.modifiedAt < rhs.modifiedAt
        }
      case .path:
        break
      }
      return lhs.workspaceRelativePath.localizedStandardCompare(rhs.workspaceRelativePath)
        == .orderedAscending
    }
    let resultTruncated = sortedEntries.count > maxResults
    let returned = resultTruncated ? Array(sortedEntries.prefix(maxResults)) : sortedEntries

    return .object([
      "operation": .string("file.timeline"),
      "path": .string(directory.path),
      "workspace_relative_path": .string(workspaceRelativePath(directory)),
      "include_hidden": .bool(includeHidden),
      "modified_after": modifiedAfter.map { .string(iso8601String($0)) } ?? .null,
      "modified_before": modifiedBefore.map { .string(iso8601String($0)) } ?? .null,
      "sort": .string(sort.rawValue),
      "max_depth": .number(Double(maxDepth)),
      "max_results": .number(Double(maxResults)),
      "max_scan_entries": .number(Double(maxScanEntries)),
      "scanned_entry_count": .number(Double(scannedEntries)),
      "scanned_file_count": .number(Double(scannedFileCount)),
      "matched_file_count": .number(Double(sortedEntries.count)),
      "returned_count": .number(Double(returned.count)),
      "skipped_missing_modified_date_count": .number(Double(skippedMissingModifiedDateCount)),
      "scan_truncated": .bool(scanTruncated),
      "result_truncated": .bool(resultTruncated),
      "truncated": .bool(scanTruncated || resultTruncated),
      "files": .array(returned.map(\.json)),
    ])
  }

  private func readFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    guard maxBytes > 0 else {
      throw GatewayToolError.invalidArguments("max_bytes must be greater than zero.")
    }

    let url = try resolvedWorkspaceURL(path)
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let truncated = data.count > maxBytes
    let contentData = truncated ? Data(data.prefix(maxBytes)) : data

    return .object([
      "path": .string(url.path),
      "encoding": .string("utf-8"),
      "content": .string(String(decoding: contentData, as: UTF8.self)),
      "bytes_read": .number(Double(contentData.count)),
      "truncated": .bool(truncated),
    ])
  }

  private func readFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let paths = try requiredStringArray("paths", in: object)
    let maxBytes =
      optionalInt("max_bytes_per_file", in: object)
      ?? configuration.policy.maxOutputBytes
    let encoding = try optionalString("encoding", in: object) ?? "utf8"
    guard !paths.isEmpty else {
      throw GatewayToolError.invalidArguments("paths must not be empty.")
    }
    guard paths.count <= 50 else {
      throw GatewayToolError.invalidArguments("paths must contain at most 50 values.")
    }
    try validateBoundedPositive(maxBytes, name: "max_bytes_per_file", upperBound: 20_971_520)
    guard encoding == "utf8" || encoding == "base64" else {
      throw GatewayToolError.invalidArguments("encoding must be utf8 or base64.")
    }

    var files: [JSONValue] = []
    var totalBytesRead = 0
    var truncatedCount = 0
    for path in paths {
      let file = try readWorkspaceFileEntry(
        path: path,
        maxBytes: maxBytes,
        encoding: encoding
      )
      totalBytesRead += file.bytesRead
      if file.truncated {
        truncatedCount += 1
      }
      files.append(file.json)
    }

    return .object([
      "operation": .string("file.read_files"),
      "encoding": .string(encoding),
      "max_bytes_per_file": .number(Double(maxBytes)),
      "requested_count": .number(Double(paths.count)),
      "file_count": .number(Double(files.count)),
      "total_bytes_read": .number(Double(totalBytesRead)),
      "truncated_file_count": .number(Double(truncatedCount)),
      "files": .array(files),
    ])
  }

  private func readWorkspaceFileEntry(
    path: String,
    maxBytes: Int,
    encoding: String
  ) throws -> FileReadEntry {
    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let truncated = data.count > maxBytes
    let contentData = truncated ? Data(data.prefix(maxBytes)) : data
    let validUTF8 = String(data: contentData, encoding: .utf8) != nil
    let content =
      encoding == "base64"
      ? contentData.base64EncodedString()
      : String(decoding: contentData, as: UTF8.self)

    return FileReadEntry(
      info: info,
      encoding: encoding,
      content: content,
      bytesRead: contentData.count,
      truncated: truncated,
      validUTF8: validUTF8
    )
  }

  private func readFileWindow(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let offset = optionalInt("offset_bytes", in: object) ?? 0
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedNonNegative(offset, name: "offset_bytes", upperBound: 9_007_199_254_740_991)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let fileSize = try handle.seekToEnd()
    let offsetValue = UInt64(offset)
    let data: Data
    if offsetValue >= fileSize {
      data = Data()
    } else {
      try handle.seek(toOffset: offsetValue)
      data = try handle.read(upToCount: maxBytes) ?? Data()
    }
    let nextOffset = offsetValue + UInt64(data.count)
    let validUTF8 = String(data: data, encoding: .utf8) != nil

    return .object([
      "operation": .string("file.read_window"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "offset_bytes": .number(Double(offset)),
      "max_bytes": .number(Double(maxBytes)),
      "file_size_bytes": .number(Double(fileSize)),
      "bytes_read": .number(Double(data.count)),
      "next_offset_bytes": .number(Double(nextOffset)),
      "eof": .bool(nextOffset >= fileSize),
      "truncated": .bool(nextOffset < fileSize),
      "valid_utf8": .bool(validUTF8),
      "content": .string(String(decoding: data, as: UTF8.self)),
    ])
  }

  private func readFileLines(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let startLine = optionalInt("start_line", in: object) ?? 1
    let maxLines = optionalInt("max_lines", in: object) ?? 200
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(startLine, name: "start_line", upperBound: 10_000_000)
    try validateBoundedPositive(maxLines, name: "max_lines", upperBound: 10_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let fileTruncated = data.count > maxBytes
    let contentData = fileTruncated ? Data(data.prefix(maxBytes)) : data
    let content = String(decoding: contentData, as: UTF8.self)
    let allLines = content.split(separator: "\n", omittingEmptySubsequences: false)
    let selected = allLines.enumerated().compactMap { index, line -> JSONValue? in
      let lineNumber = index + 1
      guard lineNumber >= startLine, lineNumber < startLine + maxLines else {
        return nil
      }
      return .object([
        "line": .number(Double(lineNumber)),
        "text": .string(String(line)),
      ])
    }
    let returnedCount = selected.count

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "start_line": .number(Double(startLine)),
      "max_lines": .number(Double(maxLines)),
      "max_bytes": .number(Double(maxBytes)),
      "bytes_scanned": .number(Double(contentData.count)),
      "file_truncated": .bool(fileTruncated),
      "line_count": .number(Double(returnedCount)),
      "lines": .array(selected),
    ])
  }

  private func readFileContext(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let line = optionalInt("line", in: object) ?? 0
    let before = optionalInt("before", in: object) ?? 5
    let after = optionalInt("after", in: object) ?? 5
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(line, name: "line", upperBound: 10_000_000)
    try validateBoundedNonNegative(before, name: "before", upperBound: 10_000)
    try validateBoundedNonNegative(after, name: "after", upperBound: 10_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let startLine = max(1, line - before)
    let endLine = line + after

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let fileTruncated = data.count > maxBytes
    let contentData = fileTruncated ? Data(data.prefix(maxBytes)) : data
    let content = String(decoding: contentData, as: UTF8.self)
    let allLines = content.split(separator: "\n", omittingEmptySubsequences: false)
    let selected = allLines.enumerated().compactMap { index, text -> JSONValue? in
      let lineNumber = index + 1
      guard lineNumber >= startLine, lineNumber <= endLine else {
        return nil
      }
      return .object([
        "line": .number(Double(lineNumber)),
        "relative_line": .number(Double(lineNumber - line)),
        "is_target": .bool(lineNumber == line),
        "text": .string(String(text)),
      ])
    }
    let targetLineReturned = selected.contains { value in
      value.objectValue?["is_target"]?.boolValue == true
    }
    let rangeMayBeTruncated = fileTruncated && allLines.count < endLine

    return .object([
      "operation": .string("file.read_context"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "line": .number(Double(line)),
      "before": .number(Double(before)),
      "after": .number(Double(after)),
      "start_line": .number(Double(startLine)),
      "end_line": .number(Double(endLine)),
      "start_clamped": .bool(line - before < 1),
      "max_bytes": .number(Double(maxBytes)),
      "bytes_scanned": .number(Double(contentData.count)),
      "file_truncated": .bool(fileTruncated),
      "range_may_be_truncated": .bool(rangeMayBeTruncated),
      "target_line_returned": .bool(targetLineReturned),
      "line_count": .number(Double(selected.count)),
      "lines": .array(selected),
    ])
  }

  private func headFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxLines = optionalInt("max_lines", in: object) ?? 200
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxLines, name: "max_lines", upperBound: 10_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let fileSize = try handle.seekToEnd()
    try handle.seek(toOffset: 0)
    let bytesToRead = Int(min(UInt64(maxBytes), fileSize))
    let data = try handle.read(upToCount: bytesToRead) ?? Data()
    let fileTruncated = fileSize > UInt64(data.count)
    var content = String(decoding: data, as: UTF8.self)
    let byteWindowEndsMidLine = fileTruncated && !content.isEmpty && !content.hasSuffix("\n")
    if content.hasSuffix("\n") {
      content.removeLast()
    }

    let allLines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    let selectedLines = Array(allLines.prefix(maxLines))
    let resultTruncated = allLines.count > selectedLines.count
    let lastReturnedLineTruncated =
      byteWindowEndsMidLine && selectedLines.count == allLines.count && !selectedLines.isEmpty
    let selected = selectedLines.enumerated().map { index, line in
      JSONValue.object([
        "line": .number(Double(index + 1)),
        "head_index": .number(Double(index + 1)),
        "text": .string(line),
        "line_truncated": .bool(lastReturnedLineTruncated && index == selectedLines.count - 1),
      ])
    }

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "max_lines": .number(Double(maxLines)),
      "max_bytes": .number(Double(maxBytes)),
      "file_size_bytes": .number(Double(fileSize)),
      "bytes_read": .number(Double(data.count)),
      "file_truncated": .bool(fileTruncated),
      "result_truncated": .bool(resultTruncated),
      "last_line_truncated": .bool(lastReturnedLineTruncated),
      "line_count": .number(Double(selected.count)),
      "truncated": .bool(fileTruncated || resultTruncated),
      "lines": .array(selected),
    ])
  }

  private func outlineFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxResults = optionalInt("max_results", in: object) ?? 200
    let includeImports = try optionalBool("include_imports", in: object) ?? false
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 10_000)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let fileTruncated = data.count > maxBytes
    let contentData = fileTruncated ? Data(data.prefix(maxBytes)) : data
    guard let content = String(data: contentData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("File is not valid UTF-8: \(path)")
    }

    let language = outlineLanguage(for: url)
    let allItems = outlineItems(
      in: content,
      language: language,
      includeImports: includeImports
    )
    let returnedItems = Array(allItems.prefix(maxResults))
    let resultTruncated = allItems.count > returnedItems.count

    return .object([
      "operation": .string("file.outline"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "language": language.map(JSONValue.string) ?? .null,
      "encoding": .string("utf-8"),
      "include_imports": .bool(includeImports),
      "max_bytes": .number(Double(maxBytes)),
      "max_results": .number(Double(maxResults)),
      "bytes_scanned": .number(Double(contentData.count)),
      "file_truncated": .bool(fileTruncated),
      "outline_count": .number(Double(allItems.count)),
      "returned_count": .number(Double(returnedItems.count)),
      "result_truncated": .bool(resultTruncated),
      "truncated": .bool(fileTruncated || resultTruncated),
      "items": .array(returnedItems.map(\.json)),
    ])
  }

  private func outlineItems(
    in content: String,
    language: String?,
    includeImports: Bool
  ) -> [FileOutlineItem] {
    var allItems: [FileOutlineItem] = []
    let lines = content.split(separator: "\n", omittingEmptySubsequences: false)
    var insideMarkdownFence = false
    for (index, line) in lines.enumerated() {
      if language == "markdown" {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.hasPrefix("```") || trimmed.hasPrefix("~~~") {
          insideMarkdownFence.toggle()
          continue
        }
        if insideMarkdownFence {
          continue
        }
      }
      guard
        let item = outlineItem(line: String(line), lineNumber: index + 1, language: language)
      else {
        continue
      }
      if item.kind == "import" && !includeImports {
        continue
      }
      allItems.append(item)
    }
    return allItems
  }

  private func markdownLinks(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let includeImages = try optionalBool("include_images", in: object) ?? true
    let includeReferenceDefinitions =
      try optionalBool("include_reference_definitions", in: object) ?? true
    let includeAutolinks = try optionalBool("include_autolinks", in: object) ?? true
    let includeCodeBlocks = try optionalBool("include_code_blocks", in: object) ?? false
    let maxLinks = optionalInt("max_links", in: object) ?? 200
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxLinks, name: "max_links", upperBound: 100_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let inventory = try readMarkdownLinkInventory(
      path: path,
      includeImages: includeImages,
      includeReferenceDefinitions: includeReferenceDefinitions,
      includeAutolinks: includeAutolinks,
      includeCodeBlocks: includeCodeBlocks,
      maxBytes: maxBytes
    )

    let returnedLinks = Array(inventory.links.prefix(maxLinks))
    let resultTruncated = inventory.links.count > returnedLinks.count

    return .object([
      "operation": .string("markdown.links"),
      "path": .string(inventory.url.path),
      "workspace_relative_path": .string(inventory.info.workspaceRelativePath),
      "encoding": .string("utf-8"),
      "include_images": .bool(includeImages),
      "include_reference_definitions": .bool(includeReferenceDefinitions),
      "include_autolinks": .bool(includeAutolinks),
      "include_code_blocks": .bool(includeCodeBlocks),
      "max_links": .number(Double(maxLinks)),
      "max_bytes": .number(Double(maxBytes)),
      "bytes_scanned": .number(Double(inventory.bytesScanned)),
      "file_truncated": .bool(inventory.fileTruncated),
      "link_count": .number(Double(inventory.links.count)),
      "returned_count": .number(Double(returnedLinks.count)),
      "result_truncated": .bool(resultTruncated),
      "truncated": .bool(inventory.fileTruncated || resultTruncated),
      "links": .array(returnedLinks.map(\.json)),
    ])
  }

  private func markdownTables(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let includeCodeBlocks = try optionalBool("include_code_blocks", in: object) ?? false
    let maxTables = optionalInt("max_tables", in: object) ?? 20
    let maxRowsPerTable = optionalInt("max_rows_per_table", in: object) ?? 100
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxTables, name: "max_tables", upperBound: 10_000)
    try validateBoundedPositive(maxRowsPerTable, name: "max_rows_per_table", upperBound: 100_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let fileTruncated = data.count > maxBytes
    let contentData = fileTruncated ? Data(data.prefix(maxBytes)) : data
    guard let content = String(data: contentData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("Markdown file is not valid UTF-8: \(path)")
    }

    let tables = markdownTablesInContent(content, includeCodeBlocks: includeCodeBlocks)
    let returnedTables = Array(tables.prefix(maxTables))
    let tableResultTruncated = tables.count > returnedTables.count
    let rowTruncatedCount = returnedTables.filter { $0.rows.count > maxRowsPerTable }.count

    return .object([
      "operation": .string("markdown.tables"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "encoding": .string("utf-8"),
      "include_code_blocks": .bool(includeCodeBlocks),
      "max_tables": .number(Double(maxTables)),
      "max_rows_per_table": .number(Double(maxRowsPerTable)),
      "max_bytes": .number(Double(maxBytes)),
      "bytes_scanned": .number(Double(contentData.count)),
      "file_truncated": .bool(fileTruncated),
      "table_count": .number(Double(tables.count)),
      "returned_count": .number(Double(returnedTables.count)),
      "row_truncated_table_count": .number(Double(rowTruncatedCount)),
      "result_truncated": .bool(tableResultTruncated),
      "truncated": .bool(tableResultTruncated || rowTruncatedCount > 0 || fileTruncated),
      "tables": .array(returnedTables.map { $0.json(maxRowsPerTable: maxRowsPerTable) }),
    ])
  }

  private func markdownTablesInContent(
    _ content: String,
    includeCodeBlocks: Bool
  ) -> [MarkdownTableInfo] {
    let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    var tables: [MarkdownTableInfo] = []
    var insideFence = false
    var index = 0

    while index < lines.count {
      let trimmed = lines[index].trimmingCharacters(in: .whitespaces)
      if markdownFenceToggleLine(trimmed) {
        insideFence.toggle()
        index += 1
        continue
      }
      if insideFence && !includeCodeBlocks {
        index += 1
        continue
      }
      guard index + 1 < lines.count,
        let header = markdownTableCells(lines[index]),
        let delimiter = markdownTableDelimiter(lines[index + 1]),
        header.count == delimiter.count
      else {
        index += 1
        continue
      }

      var rows: [MarkdownTableRowInfo] = []
      var rowIndex = index + 2
      while rowIndex < lines.count {
        let rowTrimmed = lines[rowIndex].trimmingCharacters(in: .whitespaces)
        if markdownFenceToggleLine(rowTrimmed) {
          break
        }
        guard let cells = markdownTableCells(lines[rowIndex]) else {
          break
        }
        rows.append(MarkdownTableRowInfo(line: rowIndex + 1, cells: cells))
        rowIndex += 1
      }

      let rawEndIndex = max(index + 2, rowIndex)
      let raw = Array(lines[index..<rawEndIndex]).joined(separator: "\n")
      tables.append(
        MarkdownTableInfo(
          startLine: index + 1,
          endLine: rawEndIndex,
          headerLine: index + 1,
          delimiterLine: index + 2,
          headers: header,
          alignments: delimiter,
          rows: rows,
          raw: raw
        ))
      index = rawEndIndex
    }

    return tables
  }

  private func markdownTableCells(_ line: String) -> [String]? {
    guard line.contains("|") else {
      return nil
    }
    var cells: [String] = []
    var current = ""
    var escaped = false
    for character in line {
      if escaped {
        current.append(character)
        escaped = false
        continue
      }
      if character == "\\" {
        escaped = true
        current.append(character)
        continue
      }
      if character == "|" {
        cells.append(markdownTableCellText(current))
        current = ""
      } else {
        current.append(character)
      }
    }
    cells.append(markdownTableCellText(current))
    if cells.first == "" {
      cells.removeFirst()
    }
    if cells.last == "" {
      cells.removeLast()
    }
    return cells.count >= 2 ? cells : nil
  }

  private func markdownTableCellText(_ text: String) -> String {
    text.trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "\\|", with: "|")
  }

  private func markdownTableDelimiter(_ line: String) -> [String]? {
    guard let cells = markdownTableCells(line) else {
      return nil
    }
    var alignments: [String] = []
    for cell in cells {
      guard let alignment = markdownTableDelimiterAlignment(cell) else {
        return nil
      }
      alignments.append(alignment)
    }
    return alignments
  }

  private func markdownTableDelimiterAlignment(_ cell: String) -> String? {
    let trimmed = cell.trimmingCharacters(in: .whitespaces)
    guard trimmed.count >= 3 else {
      return nil
    }
    var body = trimmed
    let left = body.first == ":"
    if left {
      body.removeFirst()
    }
    let right = body.last == ":"
    if right {
      body.removeLast()
    }
    guard body.count >= 3, body.allSatisfy({ $0 == "-" }) else {
      return nil
    }
    if left && right {
      return "center"
    }
    if right {
      return "right"
    }
    if left {
      return "left"
    }
    return "none"
  }

  private func markdownFenceToggleLine(_ trimmedLine: String) -> Bool {
    trimmedLine.hasPrefix("```") || trimmedLine.hasPrefix("~~~")
  }

  private func markdownSection(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let heading = try requiredString("heading", in: object)
    let level = optionalInt("level", in: object)
    let occurrence = optionalInt("occurrence", in: object) ?? 1
    let includeHeading = try optionalBool("include_heading", in: object) ?? true
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxSectionBytes =
      optionalInt("max_section_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(
      maxSectionBytes, name: "max_section_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(occurrence, name: "occurrence", upperBound: 10_000)
    if let level {
      try validateBoundedPositive(level, name: "level", upperBound: 6)
    }

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let fileTruncated = data.count > maxBytes
    let contentData = fileTruncated ? Data(data.prefix(maxBytes)) : data
    guard let content = String(data: contentData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("Markdown file is not valid UTF-8: \(path)")
    }

    let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    var insideFence = false
    var matchCount = 0
    var selectedHeading: FileOutlineItem?
    var selectedStartIndex: Int?
    var selectedEndIndex: Int?
    var followingHeading: FileOutlineItem?

    for (index, line) in lines.enumerated() {
      let trimmed = line.trimmingCharacters(in: .whitespaces)
      if trimmed.hasPrefix("```") || trimmed.hasPrefix("~~~") {
        insideFence.toggle()
        continue
      }
      guard !insideFence, let item = markdownHeading(trimmed, lineNumber: index + 1),
        item.kind == "heading", let itemLevel = item.level
      else {
        continue
      }

      if let selectedStartIndex, selectedEndIndex == nil,
        let selectedLevel = selectedHeading?.level,
        index > selectedStartIndex,
        itemLevel <= selectedLevel
      {
        selectedEndIndex = index
        followingHeading = item
      }

      if item.name == heading && (level == nil || itemLevel == level) {
        matchCount += 1
        if matchCount == occurrence {
          selectedHeading = item
          selectedStartIndex = index
        }
      }
    }

    guard let selectedHeading, let selectedStartIndex else {
      return .object([
        "operation": .string("markdown.section"),
        "path": .string(url.path),
        "workspace_relative_path": .string(info.workspaceRelativePath),
        "encoding": .string("utf-8"),
        "heading": .string(heading),
        "level": level.map { .number(Double($0)) } ?? .null,
        "occurrence": .number(Double(occurrence)),
        "include_heading": .bool(includeHeading),
        "max_bytes": .number(Double(maxBytes)),
        "max_section_bytes": .number(Double(maxSectionBytes)),
        "bytes_scanned": .number(Double(contentData.count)),
        "file_truncated": .bool(fileTruncated),
        "match_count": .number(Double(matchCount)),
        "matched": .bool(false),
        "failure": .object([
          "reason": .string("missing_heading")
        ]),
        "section": .null,
        "outline_context": markdownSectionOutlineContext(info.workspaceRelativePath),
      ])
    }

    let endIndex = selectedEndIndex ?? lines.count
    let contentStartIndex = includeHeading ? selectedStartIndex : selectedStartIndex + 1
    let selectedLines =
      contentStartIndex < endIndex ? Array(lines[contentStartIndex..<endIndex]) : []
    let rawSection = selectedLines.joined(separator: "\n")
    let rawSectionData = Data(rawSection.utf8)
    let sectionData =
      rawSectionData.count > maxSectionBytes
      ? Data(rawSectionData.prefix(maxSectionBytes)) : rawSectionData
    let sectionContentTruncated = rawSectionData.count > sectionData.count
    let sectionMayBeTruncated = fileTruncated && selectedEndIndex == nil
    let startLine = selectedLines.isEmpty ? selectedHeading.line : contentStartIndex + 1
    let endLine =
      selectedLines.isEmpty ? selectedHeading.line : contentStartIndex + selectedLines.count

    return .object([
      "operation": .string("markdown.section"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "encoding": .string("utf-8"),
      "heading": .string(heading),
      "level": level.map { .number(Double($0)) } ?? .null,
      "occurrence": .number(Double(occurrence)),
      "include_heading": .bool(includeHeading),
      "max_bytes": .number(Double(maxBytes)),
      "max_section_bytes": .number(Double(maxSectionBytes)),
      "bytes_scanned": .number(Double(contentData.count)),
      "file_truncated": .bool(fileTruncated),
      "match_count": .number(Double(matchCount)),
      "matched": .bool(true),
      "failure": .null,
      "matched_heading": selectedHeading.json,
      "following_heading": followingHeading?.json ?? .null,
      "section": .object([
        "start_line": .number(Double(startLine)),
        "end_line": .number(Double(endLine)),
        "heading_line": .number(Double(selectedHeading.line)),
        "line_count": .number(Double(selectedLines.count)),
        "content_bytes": .number(Double(rawSectionData.count)),
        "returned_content_bytes": .number(Double(sectionData.count)),
        "content_truncated": .bool(sectionContentTruncated),
        "section_may_be_truncated": .bool(sectionMayBeTruncated),
        "content": .string(String(decoding: sectionData, as: UTF8.self)),
      ]),
      "read_context": .object([
        "tool": .string("file.read_context"),
        "arguments": .object([
          "path": .string(info.workspaceRelativePath),
          "line": .number(Double(selectedHeading.line)),
          "before": .number(2),
          "after": .number(20),
        ]),
      ]),
      "outline_context": markdownSectionOutlineContext(info.workspaceRelativePath),
    ])
  }

  private func markdownSectionOutlineContext(_ path: String) -> JSONValue {
    .object([
      "tool": .string("file.outline"),
      "arguments": .object([
        "path": .string(path)
      ]),
    ])
  }

  private func markdownFrontmatter(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let requestedFormat = try optionalString("format", in: object) ?? "auto"
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxDepth = optionalInt("max_depth", in: object) ?? 128
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(maxDepth, name: "max_depth", upperBound: 512)
    let formats = try markdownFrontmatterFormats(requestedFormat)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let data = try readBoundedFileData(url: url, path: path, maxBytes: maxBytes)
    guard let content = String(data: data, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("Markdown file is not valid UTF-8: \(path)")
    }
    let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    guard let firstLine = lines.first?.trimmingCharacters(in: .whitespacesAndNewlines),
      let opening = markdownFrontmatterOpening(firstLine, allowedFormats: formats)
    else {
      return markdownFrontmatterPayload(
        path: url.path,
        workspaceRelativePath: info.workspaceRelativePath,
        requestedFormat: requestedFormat,
        format: nil,
        maxBytes: maxBytes,
        maxDepth: maxDepth,
        bytesScanned: data.count,
        lineCount: lines.count,
        hasOpening: false,
        hasClosing: false,
        found: false,
        raw: nil,
        rawStartLine: nil,
        rawEndLine: nil,
        closingLine: nil,
        bodyStartLine: nil,
        parsed: false,
        value: .null,
        documentMetadata: .null,
        failureReason: "missing_frontmatter",
        parseError: nil
      )
    }

    let closingIndex = lines.dropFirst().enumerated().first { _, line in
      markdownFrontmatterClosing(
        line.trimmingCharacters(in: .whitespacesAndNewlines),
        format: opening.format
      )
    }?.offset

    guard let closingOffset = closingIndex else {
      return markdownFrontmatterPayload(
        path: url.path,
        workspaceRelativePath: info.workspaceRelativePath,
        requestedFormat: requestedFormat,
        format: opening.format,
        maxBytes: maxBytes,
        maxDepth: maxDepth,
        bytesScanned: data.count,
        lineCount: lines.count,
        hasOpening: true,
        hasClosing: false,
        found: false,
        raw: nil,
        rawStartLine: nil,
        rawEndLine: nil,
        closingLine: nil,
        bodyStartLine: nil,
        parsed: false,
        value: .null,
        documentMetadata: .null,
        failureReason: "unterminated_frontmatter",
        parseError: nil
      )
    }

    let closingLineIndex = closingOffset + 1
    let rawLines = closingLineIndex > 1 ? Array(lines[1..<closingLineIndex]) : []
    let raw = rawLines.joined(separator: "\n")
    let rawData = Data(raw.utf8)
    let parsedDocument: StructuredDocument?
    let parseError: String?
    do {
      parsedDocument = try parseStructuredValue(
        data: rawData,
        format: opening.format,
        path: path,
        maxBytes: max(rawData.count, 1),
        maxDocuments: 1,
        maxDepth: maxDepth
      )
      parseError = nil
    } catch {
      parsedDocument = nil
      parseError = error.localizedDescription
    }

    return markdownFrontmatterPayload(
      path: url.path,
      workspaceRelativePath: info.workspaceRelativePath,
      requestedFormat: requestedFormat,
      format: opening.format,
      maxBytes: maxBytes,
      maxDepth: maxDepth,
      bytesScanned: data.count,
      lineCount: lines.count,
      hasOpening: true,
      hasClosing: true,
      found: true,
      raw: raw,
      rawStartLine: 2,
      rawEndLine: closingLineIndex,
      closingLine: closingLineIndex + 1,
      bodyStartLine: closingLineIndex + 2,
      parsed: parsedDocument != nil,
      value: parsedDocument?.value ?? .null,
      documentMetadata: parsedDocument?.metadata ?? .null,
      failureReason: nil,
      parseError: parseError
    )
  }

  private func markdownFrontmatterFormats(_ requestedFormat: String) throws -> Set<String> {
    let normalized = requestedFormat.lowercased()
    switch normalized {
    case "auto":
      return ["yaml", "toml"]
    case "yaml", "toml":
      return [normalized]
    default:
      throw GatewayToolError.invalidArguments("format must be one of: auto, yaml, toml.")
    }
  }

  private func markdownFrontmatterOpening(
    _ line: String,
    allowedFormats: Set<String>
  ) -> (format: String, delimiter: String)? {
    if line == "---", allowedFormats.contains("yaml") {
      return ("yaml", "---")
    }
    if line == "+++", allowedFormats.contains("toml") {
      return ("toml", "+++")
    }
    return nil
  }

  private func markdownFrontmatterClosing(_ line: String, format: String) -> Bool {
    switch format {
    case "yaml":
      return line == "---" || line == "..."
    case "toml":
      return line == "+++"
    default:
      return false
    }
  }

  private func markdownFrontmatterPayload(
    path: String,
    workspaceRelativePath: String,
    requestedFormat: String,
    format: String?,
    maxBytes: Int,
    maxDepth: Int,
    bytesScanned: Int,
    lineCount: Int,
    hasOpening: Bool,
    hasClosing: Bool,
    found: Bool,
    raw: String?,
    rawStartLine: Int?,
    rawEndLine: Int?,
    closingLine: Int?,
    bodyStartLine: Int?,
    parsed: Bool,
    value: JSONValue,
    documentMetadata: JSONValue,
    failureReason: String?,
    parseError: String?
  ) -> JSONValue {
    .object([
      "operation": .string("markdown.frontmatter"),
      "path": .string(path),
      "workspace_relative_path": .string(workspaceRelativePath),
      "encoding": .string("utf-8"),
      "requested_format": .string(requestedFormat),
      "format": format.map(JSONValue.string) ?? .null,
      "max_bytes": .number(Double(maxBytes)),
      "max_depth": .number(Double(maxDepth)),
      "bytes_scanned": .number(Double(bytesScanned)),
      "line_count": .number(Double(lineCount)),
      "has_opening_delimiter": .bool(hasOpening),
      "has_closing_delimiter": .bool(hasClosing),
      "found": .bool(found),
      "raw": raw.map(JSONValue.string) ?? .null,
      "raw_bytes": raw.map { .number(Double(Data($0.utf8).count)) } ?? .null,
      "raw_start_line": rawStartLine.map { .number(Double($0)) } ?? .null,
      "raw_end_line": rawEndLine.map { .number(Double($0)) } ?? .null,
      "closing_line": closingLine.map { .number(Double($0)) } ?? .null,
      "body_start_line": bodyStartLine.map { .number(Double($0)) } ?? .null,
      "parsed": .bool(parsed),
      "parse_error": parseError.map(JSONValue.string) ?? .null,
      "failure": failureReason.map { .object(["reason": .string($0)]) } ?? .null,
      "value": value,
      "document_metadata": documentMetadata,
      "structured_get_context": found && parsed
        ? .object([
          "tool": .string("structured.get"),
          "note": .string(
            "For field-level access, copy this frontmatter value or read a standalone structured file; embedded Markdown frontmatter is not a filesystem path."
          ),
        ]) : .null,
    ])
  }

  private func markdownLinkCheck(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let includeImages = try optionalBool("include_images", in: object) ?? true
    let includeReferenceDefinitions =
      try optionalBool("include_reference_definitions", in: object) ?? true
    let includeAutolinks = try optionalBool("include_autolinks", in: object) ?? true
    let includeCodeBlocks = try optionalBool("include_code_blocks", in: object) ?? false
    let checkFragments = try optionalBool("check_fragments", in: object) ?? true
    let maxLinks = optionalInt("max_links", in: object) ?? 200
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxTargetBytes =
      optionalInt("max_target_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxLinks, name: "max_links", upperBound: 100_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(maxTargetBytes, name: "max_target_bytes", upperBound: 20_971_520)

    let inventory = try readMarkdownLinkInventory(
      path: path,
      includeImages: includeImages,
      includeReferenceDefinitions: true,
      includeAutolinks: includeAutolinks,
      includeCodeBlocks: includeCodeBlocks,
      maxBytes: maxBytes
    )
    let definitions = markdownReferenceDefinitions(inventory.links)
    let linksToCheck = inventory.links.filter {
      includeReferenceDefinitions || $0.kind != "reference_definition"
    }

    var checks: [MarkdownLinkCheckResult] = []
    var okCount = 0
    var brokenCount = 0
    var uncheckedCount = 0
    var localCount = 0
    var externalCount = 0
    var fragmentCount = 0
    var targetTruncatedCount = 0

    for link in linksToCheck {
      let result = markdownLinkCheckResult(
        link: link,
        sourceURL: inventory.url,
        definitions: definitions,
        checkFragments: checkFragments,
        maxTargetBytes: maxTargetBytes
      )
      checks.append(result)
      switch result.category {
      case "ok":
        okCount += 1
      case "broken":
        brokenCount += 1
      default:
        uncheckedCount += 1
      }
      if result.isLocal {
        localCount += 1
      }
      if result.isExternal {
        externalCount += 1
      }
      if result.hasFragment {
        fragmentCount += 1
      }
      if result.targetTruncated {
        targetTruncatedCount += 1
      }
    }

    let returnedChecks = Array(checks.prefix(maxLinks))
    let resultTruncated = checks.count > returnedChecks.count

    return .object([
      "operation": .string("markdown.link_check"),
      "path": .string(inventory.url.path),
      "workspace_relative_path": .string(inventory.info.workspaceRelativePath),
      "encoding": .string("utf-8"),
      "include_images": .bool(includeImages),
      "include_reference_definitions": .bool(includeReferenceDefinitions),
      "include_autolinks": .bool(includeAutolinks),
      "include_code_blocks": .bool(includeCodeBlocks),
      "check_fragments": .bool(checkFragments),
      "max_links": .number(Double(maxLinks)),
      "max_bytes": .number(Double(maxBytes)),
      "max_target_bytes": .number(Double(maxTargetBytes)),
      "bytes_scanned": .number(Double(inventory.bytesScanned)),
      "file_truncated": .bool(inventory.fileTruncated),
      "check_count": .number(Double(checks.count)),
      "returned_count": .number(Double(returnedChecks.count)),
      "ok_count": .number(Double(okCount)),
      "broken_count": .number(Double(brokenCount)),
      "unchecked_count": .number(Double(uncheckedCount)),
      "local_count": .number(Double(localCount)),
      "external_count": .number(Double(externalCount)),
      "fragment_count": .number(Double(fragmentCount)),
      "target_truncated_count": .number(Double(targetTruncatedCount)),
      "reference_definition_count": .number(Double(definitions.count)),
      "result_truncated": .bool(resultTruncated),
      "truncated": .bool(inventory.fileTruncated || resultTruncated || targetTruncatedCount > 0),
      "checks": .array(returnedChecks.map(\.json)),
    ])
  }

  private func readMarkdownLinkInventory(
    path: String,
    includeImages: Bool,
    includeReferenceDefinitions: Bool,
    includeAutolinks: Bool,
    includeCodeBlocks: Bool,
    maxBytes: Int
  ) throws -> MarkdownLinkInventory {
    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let fileTruncated = data.count > maxBytes
    let contentData = fileTruncated ? Data(data.prefix(maxBytes)) : data
    guard let content = String(data: contentData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("Markdown file is not valid UTF-8: \(path)")
    }

    let links = markdownLinksInContent(
      content,
      sourceURL: url,
      includeImages: includeImages,
      includeReferenceDefinitions: includeReferenceDefinitions,
      includeAutolinks: includeAutolinks,
      includeCodeBlocks: includeCodeBlocks
    )
    return MarkdownLinkInventory(
      url: url,
      info: info,
      bytesScanned: contentData.count,
      fileTruncated: fileTruncated,
      links: links
    )
  }

  private func markdownLinksInContent(
    _ content: String,
    sourceURL: URL,
    includeImages: Bool,
    includeReferenceDefinitions: Bool,
    includeAutolinks: Bool,
    includeCodeBlocks: Bool
  ) -> [MarkdownLinkInfo] {
    var links: [MarkdownLinkInfo] = []
    let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    var insideFence = false
    for (index, line) in lines.enumerated() {
      let lineNumber = index + 1
      let trimmed = line.trimmingCharacters(in: .whitespaces)
      if trimmed.hasPrefix("```") || trimmed.hasPrefix("~~~") {
        if includeCodeBlocks {
          links.append(
            contentsOf: markdownLinksInLine(
              line,
              lineNumber: lineNumber,
              sourceURL: sourceURL,
              includeImages: includeImages,
              includeReferenceDefinitions: includeReferenceDefinitions,
              includeAutolinks: includeAutolinks
            ))
        }
        insideFence.toggle()
        continue
      }
      if insideFence && !includeCodeBlocks {
        continue
      }
      links.append(
        contentsOf: markdownLinksInLine(
          line,
          lineNumber: lineNumber,
          sourceURL: sourceURL,
          includeImages: includeImages,
          includeReferenceDefinitions: includeReferenceDefinitions,
          includeAutolinks: includeAutolinks
        ))
    }
    return links
  }

  private func markdownReferenceDefinitions(_ links: [MarkdownLinkInfo]) -> [String:
    MarkdownLinkInfo]
  {
    var definitions: [String: MarkdownLinkInfo] = [:]
    for link in links where link.kind == "reference_definition" {
      guard let label = link.referenceLabel ?? link.label else {
        continue
      }
      let key = markdownReferenceKey(label)
      if !key.isEmpty, definitions[key] == nil {
        definitions[key] = link
      }
    }
    return definitions
  }

  private func markdownReferenceKey(_ label: String) -> String {
    label
      .split(whereSeparator: \.isWhitespace)
      .joined(separator: " ")
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased()
  }

  private func markdownLinkCheckResult(
    link: MarkdownLinkInfo,
    sourceURL: URL,
    definitions: [String: MarkdownLinkInfo],
    checkFragments: Bool,
    maxTargetBytes: Int
  ) -> MarkdownLinkCheckResult {
    var resolvedDestination = link.destination
    var resolvedTarget = link.target
    var resolvedViaReferenceDefinition = false
    var referenceDefinitionLine: Int?

    if resolvedDestination == nil, link.kind == "reference_link" || link.kind == "reference_image" {
      let key = markdownReferenceKey(link.referenceLabel ?? link.label ?? "")
      if let definition = definitions[key] {
        resolvedDestination = definition.destination
        resolvedTarget = definition.target
        resolvedViaReferenceDefinition = true
        referenceDefinitionLine = definition.line
      } else {
        return MarkdownLinkCheckResult(
          link: link,
          resolvedDestination: nil,
          resolvedViaReferenceDefinition: false,
          referenceDefinitionLine: nil,
          status: "missing_reference_definition",
          category: "broken",
          issue: "Reference link has no matching reference definition.",
          target: nil
        )
      }
    }

    guard let destination = resolvedDestination, !destination.isEmpty else {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "empty_destination",
        category: "broken",
        issue: "Link destination is empty.",
        target: resolvedTarget
      )
    }
    guard let target = resolvedTarget else {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: destination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "external_unchecked",
        category: "unchecked",
        issue: "Destination target was not resolved by the Markdown parser.",
        target: nil
      )
    }

    switch target.kind {
    case "url", "email":
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: destination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "external_unchecked",
        category: "unchecked",
        issue: "External destinations are not fetched by the gateway.",
        target: target,
        isExternal: true
      )

    case "empty":
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: destination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "empty_destination",
        category: "broken",
        issue: "Link destination is empty.",
        target: target
      )

    case "fragment":
      return markdownLocalLinkCheckResult(
        link: link,
        resolvedDestination: destination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        target: target,
        targetURL: sourceURL,
        fragment: target.fragment,
        checkFragments: checkFragments,
        maxTargetBytes: maxTargetBytes
      )

    case "relative_path", "absolute_path":
      guard target.targetWorkspaceContained == true, let targetPath = target.targetPath else {
        return MarkdownLinkCheckResult(
          link: link,
          resolvedDestination: destination,
          resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
          referenceDefinitionLine: referenceDefinitionLine,
          status: "outside_workspace",
          category: "broken",
          issue: "Local link target is outside the configured workspace.",
          target: target,
          isLocal: true
        )
      }
      return markdownLocalLinkCheckResult(
        link: link,
        resolvedDestination: destination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        target: target,
        targetURL: URL(fileURLWithPath: targetPath),
        fragment: target.fragment,
        checkFragments: checkFragments,
        maxTargetBytes: maxTargetBytes
      )

    default:
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: destination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "external_unchecked",
        category: "unchecked",
        issue: "Unsupported Markdown target kind: \(target.kind)",
        target: target
      )
    }
  }

  private func markdownLocalLinkCheckResult(
    link: MarkdownLinkInfo,
    resolvedDestination: String,
    resolvedViaReferenceDefinition: Bool,
    referenceDefinitionLine: Int?,
    target: MarkdownLinkTargetInfo,
    targetURL: URL,
    fragment: String?,
    checkFragments: Bool,
    maxTargetBytes: Int
  ) -> MarkdownLinkCheckResult {
    var isDirectory = ObjCBool(false)
    let exists = FileManager.default.fileExists(atPath: targetURL.path, isDirectory: &isDirectory)
    guard exists else {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "missing_target",
        category: "broken",
        issue: "Local link target does not exist.",
        target: target,
        targetExists: false,
        isLocal: true,
        hasFragment: fragment != nil
      )
    }

    guard let fragment else {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "ok",
        category: "ok",
        issue: nil,
        target: target,
        targetExists: true,
        targetIsDirectory: isDirectory.boolValue,
        isLocal: true
      )
    }

    if fragment.isEmpty {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "ok",
        category: "ok",
        issue: nil,
        target: target,
        targetExists: true,
        targetIsDirectory: isDirectory.boolValue,
        isLocal: true,
        hasFragment: true,
        fragmentChecked: false
      )
    }

    guard checkFragments else {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "fragment_unchecked",
        category: "unchecked",
        issue: "Fragment checking is disabled.",
        target: target,
        targetExists: true,
        targetIsDirectory: isDirectory.boolValue,
        isLocal: true,
        hasFragment: true,
        fragmentChecked: false
      )
    }

    guard !isDirectory.boolValue, outlineLanguage(for: targetURL) == "markdown" else {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "fragment_unchecked",
        category: "unchecked",
        issue: "Fragments are checked only for Markdown file targets.",
        target: target,
        targetExists: true,
        targetIsDirectory: isDirectory.boolValue,
        isLocal: true,
        hasFragment: true,
        fragmentChecked: false
      )
    }

    let scan: MarkdownAnchorScanResult
    do {
      scan = try markdownAnchorScan(url: targetURL, maxBytes: maxTargetBytes)
    } catch {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "fragment_unchecked",
        category: "unchecked",
        issue: "Unable to read Markdown target for fragment checking.",
        target: target,
        targetExists: true,
        targetIsDirectory: false,
        isLocal: true,
        hasFragment: true,
        fragmentChecked: false
      )
    }

    let normalizedFragment = markdownAnchorKey(fragment)
    let fragmentFound = scan.anchors.contains(normalizedFragment)
    if fragmentFound {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "ok",
        category: "ok",
        issue: nil,
        target: target,
        targetExists: true,
        targetIsDirectory: false,
        isLocal: true,
        hasFragment: true,
        fragmentChecked: true,
        fragmentFound: true,
        targetBytesScanned: scan.bytesScanned,
        targetTruncated: scan.truncated
      )
    }

    if scan.truncated {
      return MarkdownLinkCheckResult(
        link: link,
        resolvedDestination: resolvedDestination,
        resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
        referenceDefinitionLine: referenceDefinitionLine,
        status: "fragment_unchecked",
        category: "unchecked",
        issue: "Markdown target was truncated before the fragment was found.",
        target: target,
        targetExists: true,
        targetIsDirectory: false,
        isLocal: true,
        hasFragment: true,
        fragmentChecked: true,
        fragmentFound: false,
        targetBytesScanned: scan.bytesScanned,
        targetTruncated: true
      )
    }

    return MarkdownLinkCheckResult(
      link: link,
      resolvedDestination: resolvedDestination,
      resolvedViaReferenceDefinition: resolvedViaReferenceDefinition,
      referenceDefinitionLine: referenceDefinitionLine,
      status: "missing_fragment",
      category: "broken",
      issue: "Markdown fragment was not found in the target file.",
      target: target,
      targetExists: true,
      targetIsDirectory: false,
      isLocal: true,
      hasFragment: true,
      fragmentChecked: true,
      fragmentFound: false,
      targetBytesScanned: scan.bytesScanned,
      targetTruncated: false
    )
  }

  private func markdownAnchorScan(url: URL, maxBytes: Int) throws -> MarkdownAnchorScanResult {
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let truncated = data.count > maxBytes
    let contentData = truncated ? Data(data.prefix(maxBytes)) : data
    guard let content = String(data: contentData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("Markdown target is not valid UTF-8: \(url.path)")
    }

    var anchors = Set<String>()
    var slugCounts: [String: Int] = [:]
    let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    for (index, line) in lines.enumerated() {
      let trimmed = line.trimmingCharacters(in: .whitespaces)
      if let heading = markdownHeading(trimmed, lineNumber: index + 1) {
        anchors.insert(markdownAnchorKey(heading.name))
        let slug = markdownHeadingSlug(heading.name)
        if !slug.isEmpty {
          let count = slugCounts[slug] ?? 0
          slugCounts[slug] = count + 1
          anchors.insert(count == 0 ? slug : "\(slug)-\(count)")
        }
      }
      for anchor in markdownExplicitAnchors(in: line) {
        anchors.insert(markdownAnchorKey(anchor))
      }
    }
    return MarkdownAnchorScanResult(
      anchors: anchors,
      bytesScanned: contentData.count,
      truncated: truncated
    )
  }

  private func markdownAnchorKey(_ value: String) -> String {
    (value.removingPercentEncoding ?? value)
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased()
  }

  private func markdownHeadingSlug(_ heading: String) -> String {
    let trimmed = heading.trimmingCharacters(in: .whitespacesAndNewlines)
    var scalars: [UnicodeScalar] = []
    var previousWasHyphen = false
    for scalar in trimmed.lowercased().unicodeScalars {
      if CharacterSet.alphanumerics.contains(scalar) || scalar == "_" {
        scalars.append(scalar)
        previousWasHyphen = false
      } else if CharacterSet.whitespacesAndNewlines.contains(scalar) || scalar == "-" {
        if !previousWasHyphen, !scalars.isEmpty {
          scalars.append("-")
          previousWasHyphen = true
        }
      }
    }
    while scalars.last == "-" {
      scalars.removeLast()
    }
    return String(String.UnicodeScalarView(scalars))
  }

  private func markdownExplicitAnchors(in line: String) -> [String] {
    let pattern = #"(?:id|name)\s*=\s*["']([^"']+)["']"#
    guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive])
    else {
      return []
    }
    let range = NSRange(line.startIndex..<line.endIndex, in: line)
    return regex.matches(in: line, options: [], range: range).compactMap { match in
      guard match.numberOfRanges > 1,
        let matchRange = Range(match.range(at: 1), in: line)
      else {
        return nil
      }
      return String(line[matchRange])
    }
  }

  private func markdownLinksInLine(
    _ line: String,
    lineNumber: Int,
    sourceURL: URL,
    includeImages: Bool,
    includeReferenceDefinitions: Bool,
    includeAutolinks: Bool
  ) -> [MarkdownLinkInfo] {
    var links: [MarkdownLinkInfo] = []
    if includeReferenceDefinitions,
      let definition = markdownReferenceDefinition(
        line, lineNumber: lineNumber, sourceURL: sourceURL)
    {
      links.append(definition)
    }
    if includeAutolinks {
      links.append(
        contentsOf: markdownAutolinks(line, lineNumber: lineNumber, sourceURL: sourceURL))
    }

    var index = line.startIndex
    while index < line.endIndex {
      guard line[index] == "[" else {
        index = line.index(after: index)
        continue
      }
      let isImage = index > line.startIndex && line[line.index(before: index)] == "!"
      if isImage && !includeImages {
        index = line.index(after: index)
        continue
      }
      if index > line.startIndex, line[line.index(before: index)] == "\\" {
        index = line.index(after: index)
        continue
      }
      guard let close = markdownClosingBracket(in: line, open: index) else {
        index = line.index(after: index)
        continue
      }

      let labelStart = line.index(after: index)
      let label = String(line[labelStart..<close])
      let next = line.index(after: close)
      if next < line.endIndex, line[next] == "(",
        let closeParen = markdownClosingParen(in: line, open: next)
      {
        let targetStart = line.index(after: next)
        let rawTarget = String(line[targetStart..<closeParen])
        let target = markdownInlineTarget(rawTarget)
        links.append(
          markdownLinkInfo(
            lineNumber: lineNumber,
            kind: isImage ? "inline_image" : "inline_link",
            label: label,
            referenceLabel: nil,
            destination: target.destination,
            title: target.title,
            raw: String(line[(isImage ? line.index(before: index) : index)...closeParen]),
            isImage: isImage,
            sourceURL: sourceURL
          ))
        index = line.index(after: closeParen)
        continue
      }
      if next < line.endIndex, line[next] == "[",
        let referenceClose = markdownClosingBracket(in: line, open: next)
      {
        let referenceStart = line.index(after: next)
        let referenceLabel = String(line[referenceStart..<referenceClose])
        links.append(
          markdownLinkInfo(
            lineNumber: lineNumber,
            kind: isImage ? "reference_image" : "reference_link",
            label: label,
            referenceLabel: referenceLabel.isEmpty ? label : referenceLabel,
            destination: nil,
            title: nil,
            raw: String(line[(isImage ? line.index(before: index) : index)...referenceClose]),
            isImage: isImage,
            sourceURL: sourceURL
          ))
        index = line.index(after: referenceClose)
        continue
      }

      index = line.index(after: close)
    }
    return links
  }

  private func markdownReferenceDefinition(
    _ line: String,
    lineNumber: Int,
    sourceURL: URL
  ) -> MarkdownLinkInfo? {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    guard trimmed.hasPrefix("[") else {
      return nil
    }
    guard let close = markdownClosingBracket(in: trimmed, open: trimmed.startIndex) else {
      return nil
    }
    let afterClose = trimmed.index(after: close)
    guard afterClose < trimmed.endIndex, trimmed[afterClose] == ":" else {
      return nil
    }
    let label = String(trimmed[trimmed.index(after: trimmed.startIndex)..<close])
    let restStart = trimmed.index(after: afterClose)
    let rest = trimmed[restStart...].trimmingCharacters(in: .whitespaces)
    guard !label.isEmpty, !rest.isEmpty else {
      return nil
    }
    let target = markdownInlineTarget(rest)
    return markdownLinkInfo(
      lineNumber: lineNumber,
      kind: "reference_definition",
      label: label,
      referenceLabel: label,
      destination: target.destination,
      title: target.title,
      raw: trimmed,
      isImage: false,
      sourceURL: sourceURL
    )
  }

  private func markdownAutolinks(
    _ line: String,
    lineNumber: Int,
    sourceURL: URL
  ) -> [MarkdownLinkInfo] {
    var links: [MarkdownLinkInfo] = []
    var index = line.startIndex
    while index < line.endIndex {
      guard line[index] == "<" else {
        index = line.index(after: index)
        continue
      }
      guard let close = line[index...].firstIndex(of: ">") else {
        break
      }
      let valueStart = line.index(after: index)
      let value = String(line[valueStart..<close])
      if isMarkdownAutolinkDestination(value) {
        links.append(
          markdownLinkInfo(
            lineNumber: lineNumber,
            kind: "autolink",
            label: value,
            referenceLabel: nil,
            destination: value,
            title: nil,
            raw: String(line[index...close]),
            isImage: false,
            sourceURL: sourceURL
          ))
      }
      index = line.index(after: close)
    }
    return links
  }

  private func isMarkdownAutolinkDestination(_ value: String) -> Bool {
    let lowercased = value.lowercased()
    if lowercased.hasPrefix("http://") || lowercased.hasPrefix("https://")
      || lowercased.hasPrefix("mailto:")
    {
      return true
    }
    return value.contains("@") && value.contains(".") && !value.contains(" ")
  }

  private func markdownClosingBracket(in line: String, open: String.Index) -> String.Index? {
    var index = line.index(after: open)
    while index < line.endIndex {
      if line[index] == "]", index == line.startIndex || line[line.index(before: index)] != "\\" {
        return index
      }
      index = line.index(after: index)
    }
    return nil
  }

  private func markdownClosingParen(in line: String, open: String.Index) -> String.Index? {
    var index = line.index(after: open)
    var inSingleQuote = false
    var inDoubleQuote = false
    var angleDepth = 0
    while index < line.endIndex {
      let character = line[index]
      let escaped = index > line.startIndex && line[line.index(before: index)] == "\\"
      if !escaped {
        if character == "\"", !inSingleQuote {
          inDoubleQuote.toggle()
        } else if character == "'", !inDoubleQuote {
          inSingleQuote.toggle()
        } else if character == "<", !inSingleQuote, !inDoubleQuote {
          angleDepth += 1
        } else if character == ">", !inSingleQuote, !inDoubleQuote, angleDepth > 0 {
          angleDepth -= 1
        } else if character == ")", !inSingleQuote, !inDoubleQuote, angleDepth == 0 {
          return index
        }
      }
      index = line.index(after: index)
    }
    return nil
  }

  private func markdownInlineTarget(_ raw: String) -> (destination: String?, title: String?) {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
      return (nil, nil)
    }
    if trimmed.hasPrefix("<"), let close = trimmed.firstIndex(of: ">") {
      let destination = String(trimmed[trimmed.index(after: trimmed.startIndex)..<close])
      let title = markdownTitle(String(trimmed[trimmed.index(after: close)...]))
      return (destination, title)
    }
    var destinationEnd = trimmed.endIndex
    var index = trimmed.startIndex
    while index < trimmed.endIndex {
      if trimmed[index].isWhitespace {
        destinationEnd = index
        break
      }
      index = trimmed.index(after: index)
    }
    let destination = String(trimmed[..<destinationEnd])
    let title = markdownTitle(String(trimmed[destinationEnd...]))
    return (destination.isEmpty ? nil : destination, title)
  }

  private func markdownTitle(_ raw: String) -> String? {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.count >= 2 else {
      return nil
    }
    if (trimmed.hasPrefix("\"") && trimmed.hasSuffix("\""))
      || (trimmed.hasPrefix("'") && trimmed.hasSuffix("'"))
    {
      return String(trimmed.dropFirst().dropLast())
    }
    if trimmed.hasPrefix("("), trimmed.hasSuffix(")") {
      return String(trimmed.dropFirst().dropLast())
    }
    return nil
  }

  private func markdownLinkInfo(
    lineNumber: Int,
    kind: String,
    label: String?,
    referenceLabel: String?,
    destination: String?,
    title: String?,
    raw: String,
    isImage: Bool,
    sourceURL: URL
  ) -> MarkdownLinkInfo {
    MarkdownLinkInfo(
      line: lineNumber,
      kind: kind,
      label: label,
      referenceLabel: referenceLabel,
      destination: destination,
      title: title,
      raw: raw,
      isImage: isImage,
      target: destination.flatMap { markdownLinkTarget(destination: $0, sourceURL: sourceURL) }
    )
  }

  private func markdownLinkTarget(destination: String, sourceURL: URL) -> MarkdownLinkTargetInfo {
    let normalized = destination.trimmingCharacters(in: .whitespacesAndNewlines)
    if normalized.isEmpty {
      return MarkdownLinkTargetInfo(kind: "empty")
    }
    if normalized.hasPrefix("#") {
      return MarkdownLinkTargetInfo(kind: "fragment", fragment: String(normalized.dropFirst()))
    }
    if let scheme = markdownDestinationScheme(normalized) {
      return MarkdownLinkTargetInfo(kind: scheme == "mailto" ? "email" : "url", scheme: scheme)
    }

    let split = markdownDestinationPathAndFragment(normalized)
    let targetURL: URL
    let kind: String
    if split.path.hasPrefix("/") {
      targetURL = URL(fileURLWithPath: split.path).standardizedFileURL
      kind = "absolute_path"
    } else {
      targetURL =
        sourceURL.deletingLastPathComponent().appendingPathComponent(split.path)
        .standardizedFileURL
      kind = "relative_path"
    }
    let contained = isWorkspaceContained(targetURL)
    return MarkdownLinkTargetInfo(
      kind: kind,
      fragment: split.fragment,
      targetPath: targetURL.path,
      targetWorkspaceRelativePath: contained ? workspaceRelativePath(targetURL) : nil,
      targetWorkspaceContained: contained
    )
  }

  private func markdownDestinationScheme(_ destination: String) -> String? {
    guard let colon = destination.firstIndex(of: ":") else {
      return nil
    }
    if let slash = destination.firstIndex(of: "/"), slash < colon {
      return nil
    }
    let scheme = String(destination[..<colon]).lowercased()
    guard !scheme.isEmpty,
      scheme.allSatisfy({
        $0.isLetter || $0.isNumber || $0 == "+"
          || $0 == "-" || $0 == "."
      })
    else {
      return nil
    }
    return scheme
  }

  private func markdownDestinationPathAndFragment(_ destination: String) -> (
    path: String, fragment: String?
  ) {
    let pathEnd =
      destination.firstIndex { character in character == "#" || character == "?" }
      ?? destination.endIndex
    let path = String(destination[..<pathEnd])
    let fragment: String?
    if let hash = destination.firstIndex(of: "#") {
      fragment = String(destination[destination.index(after: hash)...])
    } else {
      fragment = nil
    }
    return (path.isEmpty ? "." : path, fragment)
  }

  private func outlineLanguage(for url: URL) -> String? {
    let name = url.lastPathComponent.lowercased()
    let ext = url.pathExtension.lowercased()
    if ["md", "markdown", "mdown"].contains(ext) {
      return "markdown"
    }
    if ext == "swift" {
      return "swift"
    }
    if ["js", "jsx", "mjs", "cjs"].contains(ext) {
      return "javascript"
    }
    if ["ts", "tsx", "mts", "cts"].contains(ext) {
      return "typescript"
    }
    if ext == "py" {
      return "python"
    }
    if ext == "go" {
      return "go"
    }
    if ext == "rs" {
      return "rust"
    }
    if ext == "java" {
      return "java"
    }
    if ["kt", "kts"].contains(ext) {
      return "kotlin"
    }
    if ["c", "h", "cc", "cpp", "cxx", "hpp"].contains(ext) {
      return "c-family"
    }
    if name == "makefile" || ext == "mk" {
      return "make"
    }
    return nil
  }

  private func outlineItem(line: String, lineNumber: Int, language: String?) -> FileOutlineItem? {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    guard !trimmed.isEmpty else {
      return nil
    }

    if language == "markdown", let heading = markdownHeading(trimmed, lineNumber: lineNumber) {
      return heading
    }

    var tokens = trimmed.split(whereSeparator: { $0 == " " || $0 == "\t" }).map(String.init)
    guard !tokens.isEmpty else {
      return nil
    }

    let modifiers = Set([
      "public", "private", "internal", "fileprivate", "open", "static", "final", "override",
      "mutating", "nonmutating", "lazy", "async", "throws", "rethrows", "export", "default",
      "pub", "abstract", "sealed", "data", "inline", "extern", "virtual",
    ])
    while let first = tokens.first, modifiers.contains(first) {
      tokens.removeFirst()
    }
    guard !tokens.isEmpty else {
      return nil
    }

    if tokens.count >= 2, tokens[0] == "async", tokens[1] == "def" {
      return declarationOutlineItem(
        kind: "function",
        rawName: tokens.dropFirst(2).first,
        line: line,
        lineNumber: lineNumber
      )
    }

    let keyword = tokens[0]
    let rawName = tokens.dropFirst().first
    let kind: String
    switch keyword {
    case "class":
      kind = "class"
    case "struct":
      kind = "struct"
    case "enum":
      kind = "enum"
    case "protocol", "interface", "trait":
      kind = "interface"
    case "actor":
      kind = "actor"
    case "extension", "impl":
      kind = "extension"
    case "func", "function", "def", "fn":
      kind = "function"
    case "init", "deinit", "constructor":
      kind = "function"
    case "var", "let", "const":
      kind = "variable"
    case "typealias", "type":
      kind = "type"
    case "import", "package", "mod", "use":
      kind = "import"
    default:
      if language == "make", trimmed.hasSuffix(":"), !trimmed.hasPrefix("\t"),
        !trimmed.contains("=")
      {
        let target = String(trimmed.dropLast()).trimmingCharacters(in: .whitespaces)
        guard !target.isEmpty else {
          return nil
        }
        return FileOutlineItem(
          line: lineNumber,
          kind: "target",
          level: nil,
          name: target,
          text: line
        )
      }
      return nil
    }

    return declarationOutlineItem(kind: kind, rawName: rawName, line: line, lineNumber: lineNumber)
  }

  private func markdownHeading(_ trimmed: String, lineNumber: Int) -> FileOutlineItem? {
    var level = 0
    for scalar in trimmed.unicodeScalars {
      if scalar == "#" {
        level += 1
        continue
      }
      break
    }
    guard level > 0, level <= 6 else {
      return nil
    }
    let index = trimmed.index(trimmed.startIndex, offsetBy: level)
    guard index < trimmed.endIndex, trimmed[index].isWhitespace else {
      return nil
    }
    let name = trimmed[index...].trimmingCharacters(in: .whitespaces)
    guard !name.isEmpty else {
      return nil
    }
    return FileOutlineItem(
      line: lineNumber, kind: "heading", level: level, name: name, text: trimmed)
  }

  private func declarationOutlineItem(
    kind: String,
    rawName: String?,
    line: String,
    lineNumber: Int
  ) -> FileOutlineItem? {
    guard let rawName else {
      return nil
    }
    let name = cleanedOutlineName(rawName)
    guard !name.isEmpty else {
      return nil
    }
    return FileOutlineItem(
      line: lineNumber,
      kind: kind,
      level: nil,
      name: name,
      text: line.trimmingCharacters(in: .whitespaces)
    )
  }

  private func cleanedOutlineName(_ raw: String) -> String {
    let delimiters = CharacterSet(charactersIn: "({[:=<,")
    let scalarView = raw.unicodeScalars
    if let delimiter = scalarView.firstIndex(where: { delimiters.contains($0) }) {
      return String(String.UnicodeScalarView(scalarView[..<delimiter]))
        .trimmingCharacters(in: .whitespacesAndNewlines)
    }
    return raw.trimmingCharacters(in: CharacterSet(charactersIn: " \t({[:=<,"))
  }

  private func tailFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxLines = optionalInt("max_lines", in: object) ?? 200
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxLines, name: "max_lines", upperBound: 10_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let fileSize = try handle.seekToEnd()
    let bytesToRead = min(UInt64(maxBytes), fileSize)
    let startOffset = fileSize - bytesToRead
    try handle.seek(toOffset: startOffset)
    let data = try handle.read(upToCount: Int(bytesToRead)) ?? Data()
    let fileTruncated = startOffset > 0

    var content = String(decoding: data, as: UTF8.self)
    var droppedPartialFirstLine = false
    if fileTruncated, let newline = content.firstIndex(of: "\n") {
      content.removeSubrange(content.startIndex...newline)
      droppedPartialFirstLine = true
    }

    var allLines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    if content.hasSuffix("\n"), !allLines.isEmpty {
      allLines.removeLast()
    }
    let selectedLines = Array(allLines.suffix(maxLines))
    let lineNumbersKnown = !fileTruncated
    let firstLineNumber = allLines.count - selectedLines.count + 1
    let selected = selectedLines.enumerated().map { index, line in
      JSONValue.object([
        "line": lineNumbersKnown ? .number(Double(firstLineNumber + index)) : .null,
        "tail_index": .number(Double(index + 1)),
        "text": .string(line),
      ])
    }

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "max_lines": .number(Double(maxLines)),
      "max_bytes": .number(Double(maxBytes)),
      "file_size_bytes": .number(Double(fileSize)),
      "start_offset_bytes": .number(Double(startOffset)),
      "bytes_read": .number(Double(data.count)),
      "file_truncated": .bool(fileTruncated),
      "dropped_partial_first_line": .bool(droppedPartialFirstLine),
      "line_numbers_known": .bool(lineNumbersKnown),
      "line_count": .number(Double(selected.count)),
      "lines": .array(selected),
    ])
  }

  private func hexdumpFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let offset = optionalInt("offset_bytes", in: object) ?? 0
    let maxBytes = optionalInt("max_bytes", in: object) ?? 256
    try validateBoundedNonNegative(offset, name: "offset_bytes", upperBound: 9_007_199_254_740_991)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 65_536)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let fileSize = try handle.seekToEnd()
    let offsetValue = UInt64(offset)
    let data: Data
    if offsetValue >= fileSize {
      data = Data()
    } else {
      try handle.seek(toOffset: offsetValue)
      data = try handle.read(upToCount: maxBytes) ?? Data()
    }

    let bytes = [UInt8](data)
    let lines = stride(from: 0, to: bytes.count, by: 16).map { start -> JSONValue in
      let lineBytes = Array(bytes[start..<min(start + 16, bytes.count)])
      return .object([
        "offset_bytes": .number(Double(offset + start)),
        "hex": .string(lineBytes.map { String(format: "%02x", $0) }.joined(separator: " ")),
        "ascii": .string(hexdumpASCII(lineBytes)),
        "byte_count": .number(Double(lineBytes.count)),
      ])
    }
    let nextOffset = offsetValue + UInt64(bytes.count)

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "offset_bytes": .number(Double(offset)),
      "max_bytes": .number(Double(maxBytes)),
      "file_size_bytes": .number(Double(fileSize)),
      "bytes_read": .number(Double(bytes.count)),
      "next_offset_bytes": .number(Double(nextOffset)),
      "eof": .bool(nextOffset >= fileSize),
      "truncated": .bool(nextOffset < fileSize),
      "lines": .array(lines),
    ])
  }

  private func extendedAttributes(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let includeValues = try optionalBool("include_values", in: object) ?? false
    let maxValueBytes = optionalInt("max_value_bytes", in: object) ?? 1_024
    try validateBoundedPositive(maxValueBytes, name: "max_value_bytes", upperBound: 65_536)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    let names = try extendedAttributeNames(url: url).sorted {
      $0.localizedStandardCompare($1) == .orderedAscending
    }

    let attributes = try names.map { name -> JSONValue in
      let size = try extendedAttributeSize(url: url, name: name)
      var object: [String: JSONValue] = [
        "name": .string(name),
        "size_bytes": .number(Double(size)),
      ]

      if includeValues {
        if size > maxValueBytes {
          object["value_bytes_read"] = .number(0)
          object["value_truncated"] = .bool(true)
          object["value_base64"] = .null
          object["value_utf8"] = .null
          object["value_omitted_reason"] = .string("attribute exceeds max_value_bytes")
        } else {
          let value = try extendedAttributeValue(
            url: url,
            name: name,
            size: size,
            maxBytes: maxValueBytes
          )
          object["value_bytes_read"] = .number(Double(value.count))
          object["value_truncated"] = .bool(false)
          object["value_base64"] = .string(value.base64EncodedString())
          object["value_utf8"] = String(data: value, encoding: .utf8).map(JSONValue.string) ?? .null
        }
      }

      return .object(object)
    }

    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "type": .string(info.type),
      "include_values": .bool(includeValues),
      "max_value_bytes": .number(Double(maxValueBytes)),
      "attribute_count": .number(Double(attributes.count)),
      "attributes": .array(attributes),
    ])
  }

  private func removeExtendedAttribute(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let name = try requiredString("name", in: object)
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    try validateExtendedAttributeName(name)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    let namesBefore = try extendedAttributeNames(url: url).sorted {
      $0.localizedStandardCompare($1) == .orderedAscending
    }
    guard namesBefore.contains(name) else {
      throw GatewayToolError.invalidArguments("Extended attribute does not exist: \(name)")
    }

    if !dryRun {
      try removeExtendedAttribute(url: url, name: name)
    }
    let namesAfter = try extendedAttributeNames(url: url).sorted {
      $0.localizedStandardCompare($1) == .orderedAscending
    }
    let wouldNamesAfter = namesBefore.filter { $0 != name }

    return .object([
      "operation": .string("file.remove_xattr"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "type": .string(info.type),
      "dry_run": .bool(dryRun),
      "name": .string(name),
      "removed": .bool(!dryRun),
      "would_remove": .bool(true),
      "attributes_before": .array(namesBefore.map(JSONValue.string)),
      "attributes_after": .array(namesAfter.map(JSONValue.string)),
      "would_attributes_after": .array(wouldNamesAfter.map(JSONValue.string)),
    ])
  }

  private func fileMetadata(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let attributes = try optionalStringArray("attributes", in: object)
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    for attribute in attributes {
      try validateMetadataAttributeName(attribute)
    }

    let arguments = ["-plist", "-", url.path]

    let result = try commandRunner.run(
      executable: "/usr/bin/mdls",
      arguments: arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    let parsed = metadataPayload(from: result)
    let metadata = filteredMetadata(parsed.metadata, attributes: attributes)

    return .object([
      "operation": .string("file.metadata"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "type": .string(info.type),
      "requested_attributes": .array(attributes.map(JSONValue.string)),
      "metadata": metadata,
      "metadata_parse_error": parsed.error.map(JSONValue.string) ?? .null,
      "metadata_omitted_reason": parsed.omittedReason.map(JSONValue.string) ?? .null,
      "result": .object([
        "executable": .string(result.executable),
        "arguments": .array(result.arguments.map(JSONValue.string)),
        "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
        "timed_out": .bool(result.timedOut),
        "stderr": .string(result.stderr),
        "stderr_truncated": .bool(result.stderrTruncated),
        "stdout_truncated": .bool(result.stdoutTruncated),
      ]),
    ])
  }

  private func readSymbolicLink(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let url = try resolvedWorkspaceURLPreservingFinalSymlink(path)

    let destination: String
    do {
      destination = try FileManager.default.destinationOfSymbolicLink(atPath: url.path)
    } catch {
      throw GatewayToolError.invalidArguments("Path is not a symbolic link: \(path)")
    }

    let destinationURL =
      destination.hasPrefix("/")
      ? URL(fileURLWithPath: destination)
      : url.deletingLastPathComponent().appendingPathComponent(destination)
    let resolvedDestination = destinationURL.standardizedFileURL.resolvingSymlinksInPath()
    let destinationContained = isWorkspaceContained(resolvedDestination)
    let destinationExists = FileManager.default.fileExists(atPath: resolvedDestination.path)

    return .object([
      "operation": .string("file.readlink"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePathPreservingSymlinks(url)),
      "destination": .string(destination),
      "destination_is_absolute": .bool(destination.hasPrefix("/")),
      "destination_workspace_contained": .bool(destinationContained),
      "destination_exists": .bool(destinationExists),
      "resolved_destination_path": .string(resolvedDestination.path),
      "destination_workspace_relative_path": destinationContained
        ? .string(workspaceRelativePath(resolvedDestination)) : .null,
    ])
  }

  private func resolveFilePath(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let lexicalURL = try resolvedWorkspaceURLPreservingFinalSymlink(path)
    let exists = FileManager.default.fileExists(atPath: lexicalURL.path)
    let symlinkDestination = try? FileManager.default.destinationOfSymbolicLink(
      atPath: lexicalURL.path)
    let resolvedURL = exists ? lexicalURL.resolvingSymlinksInPath() : lexicalURL
    let resolvedContained = isWorkspaceContained(resolvedURL)

    return .object([
      "operation": .string("file.resolve"),
      "input_path": .string(path),
      "path": .string(lexicalURL.path),
      "workspace_relative_path": .string(workspaceRelativePathPreservingSymlinks(lexicalURL)),
      "exists": .bool(exists),
      "is_symlink": .bool(symlinkDestination != nil),
      "symlink_destination": symlinkDestination.map(JSONValue.string) ?? .null,
      "resolved_path": .string(resolvedURL.path),
      "resolved_workspace_contained": .bool(resolvedContained),
      "resolved_workspace_relative_path": resolvedContained
        ? .string(workspaceRelativePath(resolvedURL)) : .null,
    ])
  }

  private func imageInfo(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let includeProperties = try optionalBool("include_properties", in: object) ?? false
    let maxPropertyDepth = optionalInt("max_property_depth", in: object) ?? 2
    try validateBoundedNonNegative(maxPropertyDepth, name: "max_property_depth", upperBound: 6)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else {
      throw GatewayToolError.invalidArguments("Unable to read image metadata: \(path)")
    }

    let imageCount = CGImageSourceGetCount(source)
    guard imageCount > 0 else {
      throw GatewayToolError.invalidArguments("Unable to read image metadata: \(path)")
    }

    let typeIdentifier = CGImageSourceGetType(source).map { String($0) }
    let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any]
    let globalProperties = CGImageSourceCopyProperties(source, nil) as? [CFString: Any]

    let pixelWidth = intImageProperty(properties, kCGImagePropertyPixelWidth)
    let pixelHeight = intImageProperty(properties, kCGImagePropertyPixelHeight)
    let depth = intImageProperty(properties, kCGImagePropertyDepth)
    let orientation = intImageProperty(properties, kCGImagePropertyOrientation)
    let dpiWidth = doubleImageProperty(properties, kCGImagePropertyDPIWidth)
    let dpiHeight = doubleImageProperty(properties, kCGImagePropertyDPIHeight)
    let hasAlpha = boolImageProperty(properties, kCGImagePropertyHasAlpha)
    let isFloat = boolImageProperty(properties, kCGImagePropertyIsFloat)
    let colorModel = stringImageProperty(properties, kCGImagePropertyColorModel)
    let profileName = stringImageProperty(properties, kCGImagePropertyProfileName)
    var propertiesTruncated = false

    var result: [String: JSONValue] = [
      "operation": .string("image.info"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "type_identifier": typeIdentifier.map(JSONValue.string) ?? .null,
      "mime_type": typeIdentifier.flatMap(imageMIMEType(for:)).map(JSONValue.string) ?? .null,
      "frame_count": .number(Double(imageCount)),
      "pixel_width": pixelWidth.map { .number(Double($0)) } ?? .null,
      "pixel_height": pixelHeight.map { .number(Double($0)) } ?? .null,
      "depth": depth.map { .number(Double($0)) } ?? .null,
      "orientation": orientation.map { .number(Double($0)) } ?? .null,
      "dpi_width": dpiWidth.map(JSONValue.number) ?? .null,
      "dpi_height": dpiHeight.map(JSONValue.number) ?? .null,
      "has_alpha": hasAlpha.map(JSONValue.bool) ?? .null,
      "is_float": isFloat.map(JSONValue.bool) ?? .null,
      "color_model": colorModel.map(JSONValue.string) ?? .null,
      "profile_name": profileName.map(JSONValue.string) ?? .null,
      "properties_included": .bool(includeProperties),
    ]

    if includeProperties {
      result["properties"] = imagePropertiesJSON(
        properties,
        maxDepth: maxPropertyDepth,
        truncated: &propertiesTruncated
      )
      result["global_properties"] = imagePropertiesJSON(
        globalProperties,
        maxDepth: maxPropertyDepth,
        truncated: &propertiesTruncated
      )
    }
    result["properties_truncated"] = .bool(propertiesTruncated)
    result["truncated"] = .bool(propertiesTruncated)

    return .object(result)
  }

  private func intImageProperty(_ properties: [CFString: Any]?, _ key: CFString) -> Int? {
    guard let value = properties?[key] else {
      return nil
    }
    if let number = value as? NSNumber {
      return number.intValue
    }
    if let string = value as? String {
      return Int(string)
    }
    return nil
  }

  private func doubleImageProperty(_ properties: [CFString: Any]?, _ key: CFString) -> Double? {
    guard let value = properties?[key] else {
      return nil
    }
    if let number = value as? NSNumber {
      return number.doubleValue
    }
    if let string = value as? String {
      return Double(string)
    }
    return nil
  }

  private func boolImageProperty(_ properties: [CFString: Any]?, _ key: CFString) -> Bool? {
    guard let value = properties?[key] else {
      return nil
    }
    if let bool = value as? Bool {
      return bool
    }
    if let number = value as? NSNumber {
      return number.boolValue
    }
    if let string = value as? String {
      return Bool(string)
    }
    return nil
  }

  private func stringImageProperty(_ properties: [CFString: Any]?, _ key: CFString) -> String? {
    guard let value = properties?[key] else {
      return nil
    }
    if let string = value as? String {
      return string
    }
    if let number = value as? NSNumber {
      return number.stringValue
    }
    return nil
  }

  private func imageMIMEType(for typeIdentifier: String) -> String? {
    let lowercased = typeIdentifier.lowercased()
    if lowercased.contains("png") {
      return "image/png"
    }
    if lowercased.contains("jpeg") || lowercased.contains("jpg") {
      return "image/jpeg"
    }
    if lowercased.contains("gif") {
      return "image/gif"
    }
    if lowercased.contains("tiff") || lowercased.contains("tif") {
      return "image/tiff"
    }
    if lowercased.contains("bmp") {
      return "image/bmp"
    }
    if lowercased.contains("webp") {
      return "image/webp"
    }
    if lowercased.contains("heic") {
      return "image/heic"
    }
    if lowercased.contains("heif") {
      return "image/heif"
    }
    if lowercased.contains("ico") {
      return "image/vnd.microsoft.icon"
    }
    if lowercased.contains("icns") {
      return "image/icns"
    }
    return nil
  }

  private func imagePropertiesJSON(
    _ properties: [CFString: Any]?,
    maxDepth: Int,
    truncated: inout Bool
  ) -> JSONValue {
    guard let properties else {
      return .null
    }

    let entries = properties.sorted {
      String($0.key).localizedStandardCompare(String($1.key)) == .orderedAscending
    }
    var object: [String: JSONValue] = [:]
    for (index, entry) in entries.enumerated() {
      if index >= 200 {
        truncated = true
        break
      }
      object[String(entry.key)] = imagePropertyValueJSON(
        entry.value,
        depth: maxDepth,
        truncated: &truncated
      )
    }
    return .object(object)
  }

  private func imagePropertyValueJSON(
    _ value: Any,
    depth: Int,
    truncated: inout Bool
  ) -> JSONValue {
    if let bool = value as? Bool {
      return .bool(bool)
    }
    if let number = value as? NSNumber {
      if CFGetTypeID(number) == CFBooleanGetTypeID() {
        return .bool(number.boolValue)
      }
      return .number(number.doubleValue)
    }
    if let string = value as? String {
      if string.utf8.count > 4_096 {
        let preview = utf8Preview(string, maxBytes: 4_096)
        truncated = true
        return .string(preview.text)
      }
      return .string(string)
    }
    if let date = value as? Date {
      return .string(iso8601String(date))
    }
    if let data = value as? Data {
      let maxBytes = 256
      let bounded = data.prefix(maxBytes)
      if data.count > maxBytes {
        truncated = true
      }
      return .object([
        "type": .string("data"),
        "size_bytes": .number(Double(data.count)),
        "base64_prefix": .string(Data(bounded).base64EncodedString()),
        "truncated": .bool(data.count > maxBytes),
      ])
    }
    if let dictionary = value as? [CFString: Any] {
      return imageDictionaryJSON(dictionary, depth: depth, truncated: &truncated)
    }
    if let dictionary = value as? [String: Any] {
      return imageDictionaryJSON(dictionary, depth: depth, truncated: &truncated)
    }
    if let array = value as? [Any] {
      guard depth > 0 else {
        truncated = true
        return .object([
          "type": .string("array"),
          "count": .number(Double(array.count)),
          "truncated": .bool(true),
        ])
      }
      let maxItems = 100
      if array.count > maxItems {
        truncated = true
      }
      return .array(
        array.prefix(maxItems).map {
          imagePropertyValueJSON($0, depth: depth - 1, truncated: &truncated)
        })
    }

    return .string(String(describing: value))
  }

  private func imageDictionaryJSON(
    _ dictionary: [CFString: Any],
    depth: Int,
    truncated: inout Bool
  ) -> JSONValue {
    let stringDictionary = Dictionary(
      uniqueKeysWithValues: dictionary.map { (String($0.key), $0.value) })
    return imageDictionaryJSON(stringDictionary, depth: depth, truncated: &truncated)
  }

  private func imageDictionaryJSON(
    _ dictionary: [String: Any],
    depth: Int,
    truncated: inout Bool
  ) -> JSONValue {
    guard depth > 0 else {
      truncated = true
      return .object([
        "type": .string("dictionary"),
        "count": .number(Double(dictionary.count)),
        "truncated": .bool(true),
      ])
    }

    let entries = dictionary.sorted {
      $0.key.localizedStandardCompare($1.key) == .orderedAscending
    }
    let maxEntries = 200
    if entries.count > maxEntries {
      truncated = true
    }
    var object: [String: JSONValue] = [:]
    for entry in entries.prefix(maxEntries) {
      object[entry.key] = imagePropertyValueJSON(
        entry.value,
        depth: depth - 1,
        truncated: &truncated
      )
    }
    return .object(object)
  }

  private func pdfInfo(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxPages = optionalInt("max_pages", in: object) ?? 20
    let includePageBoxes = try optionalBool("include_page_boxes", in: object) ?? true
    let includeAttributes = try optionalBool("include_attributes", in: object) ?? true
    try validateBoundedNonNegative(maxPages, name: "max_pages", upperBound: 10_000)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    guard let document = PDFDocument(url: url) else {
      throw GatewayToolError.invalidArguments("Unable to read PDF metadata: \(path)")
    }

    let pageCount = document.pageCount
    let returnedPageCount = min(maxPages, pageCount)
    var pages: [JSONValue] = []
    for index in 0..<returnedPageCount {
      guard let page = document.page(at: index) else {
        continue
      }
      var pageObject: [String: JSONValue] = [
        "index": .number(Double(index)),
        "number": .number(Double(index + 1)),
        "label": page.label.map(JSONValue.string) ?? .null,
        "rotation": .number(Double(page.rotation)),
      ]
      if includePageBoxes {
        pageObject["boxes"] = .object([
          "media": pdfRectJSON(page.bounds(for: .mediaBox)),
          "crop": pdfRectJSON(page.bounds(for: .cropBox)),
          "bleed": pdfRectJSON(page.bounds(for: .bleedBox)),
          "trim": pdfRectJSON(page.bounds(for: .trimBox)),
          "art": pdfRectJSON(page.bounds(for: .artBox)),
        ])
      }
      pages.append(.object(pageObject))
    }

    var attributesTruncated = false
    var result: [String: JSONValue] = [
      "operation": .string("pdf.info"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "page_count": .number(Double(pageCount)),
      "returned_page_count": .number(Double(pages.count)),
      "pages_truncated": .bool(pageCount > returnedPageCount),
      "include_page_boxes": .bool(includePageBoxes),
      "attributes_included": .bool(includeAttributes),
      "is_encrypted": .bool(document.isEncrypted),
      "is_locked": .bool(document.isLocked),
      "allows_copying": .bool(document.allowsCopying),
      "allows_printing": .bool(document.allowsPrinting),
      "pages": .array(pages),
    ]

    if includeAttributes {
      result["attributes"] = pdfAttributesJSON(
        document.documentAttributes ?? [:],
        truncated: &attributesTruncated
      )
    }
    result["attributes_truncated"] = .bool(attributesTruncated)
    result["truncated"] = .bool(pageCount > returnedPageCount || attributesTruncated)

    return .object(result)
  }

  private func pdfText(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let startPage = optionalInt("start_page", in: object) ?? 1
    let maxPages = optionalInt("max_pages", in: object) ?? 10
    let maxCharacters = optionalInt("max_characters", in: object) ?? 100_000
    try validateBoundedPositive(startPage, name: "start_page", upperBound: 1_000_000)
    try validateBoundedPositive(maxPages, name: "max_pages", upperBound: 10_000)
    try validateBoundedPositive(maxCharacters, name: "max_characters", upperBound: 5_000_000)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    guard let document = PDFDocument(url: url) else {
      throw GatewayToolError.invalidArguments("Unable to read PDF text: \(path)")
    }
    guard !document.isLocked else {
      throw GatewayToolError.invalidArguments("Unable to read PDF text: document is locked.")
    }
    guard document.allowsCopying else {
      throw GatewayToolError.invalidArguments("Unable to read PDF text: copying is not allowed.")
    }

    let pageCount = document.pageCount
    if pageCount == 0 {
      return .object([
        "operation": .string("pdf.text"),
        "path": .string(url.path),
        "workspace_relative_path": .string(info.workspaceRelativePath),
        "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
        "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
        "page_count": .number(0),
        "start_page": .number(Double(startPage)),
        "max_pages": .number(Double(maxPages)),
        "max_characters": .number(Double(maxCharacters)),
        "returned_page_count": .number(0),
        "total_extracted_character_count": .number(0),
        "page_range_truncated": .bool(false),
        "text_truncated": .bool(false),
        "truncated": .bool(false),
        "pages": .array([]),
      ])
    }
    guard startPage <= pageCount else {
      throw GatewayToolError.invalidArguments(
        "start_page exceeds PDF page_count (\(pageCount)): \(startPage)")
    }

    let startIndex = startPage - 1
    let exclusiveEndIndex = min(pageCount, startIndex + maxPages)
    var pages: [JSONValue] = []
    var remainingCharacters = maxCharacters
    var totalExtractedCharacters = 0
    var textTruncated = false

    for index in startIndex..<exclusiveEndIndex {
      guard let page = document.page(at: index) else {
        continue
      }
      guard remainingCharacters > 0 else {
        textTruncated = true
        break
      }

      let rawText = page.string ?? ""
      let pageCharacterCount = rawText.count
      let pageText: String
      let pageTextTruncated: Bool
      if pageCharacterCount > remainingCharacters {
        pageText = String(rawText.prefix(remainingCharacters))
        pageTextTruncated = true
        textTruncated = true
        remainingCharacters = 0
      } else {
        pageText = rawText
        pageTextTruncated = false
        remainingCharacters -= pageCharacterCount
      }
      totalExtractedCharacters += pageText.count
      pages.append(
        .object([
          "index": .number(Double(index)),
          "number": .number(Double(index + 1)),
          "label": page.label.map(JSONValue.string) ?? .null,
          "text": .string(pageText),
          "character_count": .number(Double(pageCharacterCount)),
          "extracted_character_count": .number(Double(pageText.count)),
          "text_truncated": .bool(pageTextTruncated),
        ]))
      if pageTextTruncated {
        break
      }
    }

    let pageRangeTruncated = exclusiveEndIndex < pageCount
    return .object([
      "operation": .string("pdf.text"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "page_count": .number(Double(pageCount)),
      "start_page": .number(Double(startPage)),
      "max_pages": .number(Double(maxPages)),
      "max_characters": .number(Double(maxCharacters)),
      "returned_page_count": .number(Double(pages.count)),
      "total_extracted_character_count": .number(Double(totalExtractedCharacters)),
      "page_range_truncated": .bool(pageRangeTruncated),
      "text_truncated": .bool(textTruncated),
      "truncated": .bool(pageRangeTruncated || textTruncated),
      "pages": .array(pages),
    ])
  }

  private func pdfRectJSON(_ rect: CGRect) -> JSONValue {
    .object([
      "x": .number(Double(rect.origin.x)),
      "y": .number(Double(rect.origin.y)),
      "width": .number(Double(rect.width)),
      "height": .number(Double(rect.height)),
      "min_x": .number(Double(rect.minX)),
      "min_y": .number(Double(rect.minY)),
      "max_x": .number(Double(rect.maxX)),
      "max_y": .number(Double(rect.maxY)),
    ])
  }

  private func pdfAttributesJSON(
    _ attributes: [AnyHashable: Any],
    truncated: inout Bool
  ) -> JSONValue {
    let entries = attributes.sorted {
      pdfAttributeName($0.key).localizedStandardCompare(pdfAttributeName($1.key))
        == .orderedAscending
    }
    let maxEntries = 200
    if entries.count > maxEntries {
      truncated = true
    }
    var object: [String: JSONValue] = [:]
    for entry in entries.prefix(maxEntries) {
      object[pdfAttributeName(entry.key)] = pdfAttributeValueJSON(
        entry.value,
        depth: 2,
        truncated: &truncated
      )
    }
    return .object(object)
  }

  private func pdfAttributeName(_ key: AnyHashable) -> String {
    if let attribute = key.base as? PDFDocumentAttribute {
      return attribute.rawValue
    }
    return String(describing: key.base)
  }

  private func pdfAttributeValueJSON(
    _ value: Any,
    depth: Int,
    truncated: inout Bool
  ) -> JSONValue {
    if let bool = value as? Bool {
      return .bool(bool)
    }
    if let number = value as? NSNumber {
      if CFGetTypeID(number) == CFBooleanGetTypeID() {
        return .bool(number.boolValue)
      }
      return .number(number.doubleValue)
    }
    if let string = value as? String {
      if string.utf8.count > 4_096 {
        let preview = utf8Preview(string, maxBytes: 4_096)
        truncated = true
        return .string(preview.text)
      }
      return .string(string)
    }
    if let date = value as? Date {
      return .string(iso8601String(date))
    }
    if let array = value as? [Any] {
      guard depth > 0 else {
        truncated = true
        return .object([
          "type": .string("array"),
          "count": .number(Double(array.count)),
          "truncated": .bool(true),
        ])
      }
      let maxItems = 100
      if array.count > maxItems {
        truncated = true
      }
      return .array(
        array.prefix(maxItems).map {
          pdfAttributeValueJSON($0, depth: depth - 1, truncated: &truncated)
        })
    }
    if let dictionary = value as? [String: Any] {
      guard depth > 0 else {
        truncated = true
        return .object([
          "type": .string("dictionary"),
          "count": .number(Double(dictionary.count)),
          "truncated": .bool(true),
        ])
      }
      let entries = dictionary.sorted {
        $0.key.localizedStandardCompare($1.key) == .orderedAscending
      }
      let maxEntries = 200
      if entries.count > maxEntries {
        truncated = true
      }
      var object: [String: JSONValue] = [:]
      for entry in entries.prefix(maxEntries) {
        object[entry.key] = pdfAttributeValueJSON(
          entry.value,
          depth: depth - 1,
          truncated: &truncated
        )
      }
      return .object(object)
    }
    return .string(String(describing: value))
  }

  private func mediaInfo(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxTracks = optionalInt("max_tracks", in: object) ?? 20
    let loadTimeoutMS = optionalInt("load_timeout_ms", in: object) ?? 5_000
    try validateBoundedNonNegative(maxTracks, name: "max_tracks", upperBound: 1_000)
    try validateBoundedPositive(loadTimeoutMS, name: "load_timeout_ms", upperBound: 600_000)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let duration: CMTime
    let tracks: [AVAssetTrack]
    let isPlayable: Bool
    let hasProtectedContent: Bool
    let providesPreciseDurationAndTiming: Bool
    let availableMetadataFormats: [AVMetadataFormat]
    do {
      duration = try loadMediaProperty(timeoutMilliseconds: loadTimeoutMS) {
        try await AVURLAsset(url: url).load(.duration)
      }
      tracks = try loadMediaProperty(timeoutMilliseconds: loadTimeoutMS) {
        try await AVURLAsset(url: url).load(.tracks)
      }
      isPlayable = try loadMediaProperty(timeoutMilliseconds: loadTimeoutMS) {
        try await AVURLAsset(url: url).load(.isPlayable)
      }
      hasProtectedContent = try loadMediaProperty(timeoutMilliseconds: loadTimeoutMS) {
        try await AVURLAsset(url: url).load(.hasProtectedContent)
      }
      providesPreciseDurationAndTiming = try loadMediaProperty(timeoutMilliseconds: loadTimeoutMS) {
        try await AVURLAsset(url: url).load(.providesPreciseDurationAndTiming)
      }
      availableMetadataFormats = try loadMediaProperty(timeoutMilliseconds: loadTimeoutMS) {
        try await AVURLAsset(url: url).load(.availableMetadataFormats)
      }
    } catch {
      throw GatewayToolError.invalidArguments(
        "Unable to read media metadata: \(error.localizedDescription)")
    }

    var mediaTypes = Set<String>()
    var trackRows: [JSONValue] = []
    for (index, track) in tracks.prefix(maxTracks).enumerated() {
      let mediaType = mediaTypeName(track.mediaType)
      mediaTypes.insert(mediaType)
      trackRows.append(
        mediaTrackJSON(
          track,
          index: index,
          mediaType: mediaType,
          timeoutMilliseconds: loadTimeoutMS
        ))
    }

    return .object([
      "operation": .string("media.info"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "extension": .string((info.workspaceRelativePath as NSString).pathExtension.lowercased()),
      "duration_seconds": finiteMediaSeconds(duration).map(JSONValue.number) ?? .null,
      "duration_timescale": .number(Double(duration.timescale)),
      "is_playable": .bool(isPlayable),
      "has_protected_content": .bool(hasProtectedContent),
      "provides_precise_duration_and_timing": .bool(providesPreciseDurationAndTiming),
      "track_count": .number(Double(tracks.count)),
      "returned_track_count": .number(Double(trackRows.count)),
      "tracks_truncated": .bool(tracks.count > trackRows.count),
      "media_types": .array(mediaTypes.sorted().map(JSONValue.string)),
      "metadata_format_count": .number(Double(availableMetadataFormats.count)),
      "available_metadata_formats": .array(
        availableMetadataFormats.map { .string($0.rawValue) }),
      "load_timeout_ms": .number(Double(loadTimeoutMS)),
      "tracks": .array(trackRows),
      "truncated": .bool(tracks.count > trackRows.count),
    ])
  }

  private func mediaTrackJSON(
    _ track: AVAssetTrack,
    index: Int,
    mediaType: String,
    timeoutMilliseconds: Int
  ) -> JSONValue {
    let naturalSize = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.naturalSize)
    }
    let nominalFrameRate = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.nominalFrameRate)
    }
    let estimatedDataRate = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.estimatedDataRate)
    }
    let timeRange = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.timeRange)
    }
    let languageCode = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.languageCode)
    }
    let isEnabled = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.isEnabled)
    }
    let isPlayable = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.isPlayable)
    }
    let formatDescriptions = try? loadMediaProperty(timeoutMilliseconds: timeoutMilliseconds) {
      try await track.load(.formatDescriptions)
    }

    var object: [String: JSONValue] = [
      "index": .number(Double(index)),
      "media_type": .string(mediaType),
      "duration_seconds": timeRange.flatMap { finiteMediaSeconds($0.duration) }.map(
        JSONValue.number)
        ?? .null,
      "is_enabled": isEnabled.map(JSONValue.bool) ?? .null,
      "is_playable": isPlayable.map(JSONValue.bool) ?? .null,
      "estimated_data_rate": estimatedDataRate.map { .number(Double($0)) } ?? .null,
      "language_code": languageCode.map(JSONValue.string) ?? .null,
      "codec_types": .array(mediaCodecTypes(formatDescriptions ?? []).map(JSONValue.string)),
    ]

    if let naturalSize {
      object["natural_size"] = .object([
        "width": .number(Double(naturalSize.width)),
        "height": .number(Double(naturalSize.height)),
      ])
    } else {
      object["natural_size"] = .null
    }
    if let nominalFrameRate {
      object["nominal_frame_rate"] = .number(Double(nominalFrameRate))
    } else {
      object["nominal_frame_rate"] = .null
    }

    return .object(object)
  }

  private func loadMediaProperty<T>(
    timeoutMilliseconds: Int,
    _ operation: @escaping @Sendable () async throws -> T
  ) throws -> T {
    let semaphore = DispatchSemaphore(value: 0)
    let resultBox = AsyncMediaLoadResultBox<T>()
    let task = Task {
      do {
        resultBox.set(.success(try await operation()))
      } catch {
        resultBox.set(.failure(error))
      }
      semaphore.signal()
    }

    let timeout = DispatchTime.now() + .milliseconds(timeoutMilliseconds)
    guard semaphore.wait(timeout: timeout) == .success else {
      task.cancel()
      throw GatewayToolError.invalidArguments("Timed out reading media metadata.")
    }
    guard let result = resultBox.get() else {
      throw GatewayToolError.invalidArguments("Unable to read media metadata.")
    }
    return try result.get()
  }

  private func mediaTypeName(_ mediaType: AVMediaType) -> String {
    switch mediaType {
    case .audio:
      return "audio"
    case .video:
      return "video"
    case .text:
      return "text"
    case .closedCaption:
      return "closed_caption"
    case .subtitle:
      return "subtitle"
    case .timecode:
      return "timecode"
    case .metadata:
      return "metadata"
    case .muxed:
      return "muxed"
    default:
      return mediaType.rawValue
    }
  }

  private func finiteMediaSeconds(_ time: CMTime) -> Double? {
    guard time.isValid, !time.isIndefinite, !time.isPositiveInfinity, !time.isNegativeInfinity
    else {
      return nil
    }
    let seconds = CMTimeGetSeconds(time)
    guard seconds.isFinite else {
      return nil
    }
    return seconds
  }

  private func mediaCodecTypes(_ formatDescriptions: [CMFormatDescription]) -> [String] {
    Array(
      Set(
        formatDescriptions.map {
          fourCharacterCodeString(CMFormatDescriptionGetMediaSubType($0))
        }
      )
    )
    .sorted()
  }

  private func fourCharacterCodeString(_ code: FourCharCode) -> String {
    let littleEndian = code.littleEndian
    let bytes = [
      UInt8((littleEndian >> 24) & 0xff),
      UInt8((littleEndian >> 16) & 0xff),
      UInt8((littleEndian >> 8) & 0xff),
      UInt8(littleEndian & 0xff),
    ]
    let scalars = bytes.map { byte -> UnicodeScalar in
      if byte >= 32, byte <= 126 {
        return UnicodeScalar(byte)
      }
      return UnicodeScalar(0x2e)
    }
    return String(String.UnicodeScalarView(scalars))
  }

  private func readJSON(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    if let size = info.size, size > Int64(maxBytes) {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let value: JSONValue
    do {
      value = try JSONDecoder().decode(JSONValue.self, from: data)
    } catch {
      throw GatewayToolError.invalidArguments("Unable to parse JSON: \(error.localizedDescription)")
    }

    return .object([
      "operation": .string("json.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "bytes_read": .number(Double(data.count)),
      "value": value,
    ])
  }

  private func readJSONLines(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let startLine = optionalInt("start_line", in: object) ?? 1
    let maxRecords = optionalInt("max_records", in: object) ?? 100
    let maxErrors = optionalInt("max_errors", in: object) ?? 50
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let skipBlankLines = try optionalBool("skip_blank_lines", in: object) ?? true
    let includePartialLine = try optionalBool("include_partial_line", in: object) ?? false
    try validateBoundedPositive(startLine, name: "start_line", upperBound: 10_000_000)
    try validateBoundedPositive(maxRecords, name: "max_records", upperBound: 100_000)
    try validateBoundedNonNegative(maxErrors, name: "max_errors", upperBound: 100_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let contentTruncated = data.count > maxBytes
    let boundedData = contentTruncated ? Data(data.prefix(maxBytes)) : data
    guard let text = String(data: boundedData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("JSONL file is not valid UTF-8: \(path)")
    }

    var lines = text.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    if text.hasSuffix("\n"), lines.last?.isEmpty == true {
      lines.removeLast()
    }
    let lastLineMayBePartial = contentTruncated && !text.hasSuffix("\n")
    let partialLineDropped = lastLineMayBePartial && !includePartialLine && !lines.isEmpty
    if partialLineDropped {
      lines.removeLast()
    }

    let decoder = JSONDecoder()
    var records: [JSONValue] = []
    var errors: [JSONValue] = []
    var parsedRecordCount = 0
    var parseErrorCount = 0
    var scannedLineCount = 0
    var skippedBlankLineCount = 0

    for (index, rawLine) in lines.enumerated() {
      let lineNumber = index + 1
      guard lineNumber >= startLine else {
        continue
      }
      scannedLineCount += 1
      var line = rawLine
      if line.hasSuffix("\r") {
        line.removeLast()
      }
      if skipBlankLines && line.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        skippedBlankLineCount += 1
        continue
      }

      let lineData = Data(line.utf8)
      do {
        let value = try decoder.decode(JSONValue.self, from: lineData)
        parsedRecordCount += 1
        if records.count < maxRecords {
          records.append(
            .object([
              "line": .number(Double(lineNumber)),
              "byte_count": .number(Double(lineData.count)),
              "value": value,
            ]))
        }
      } catch {
        parseErrorCount += 1
        if errors.count < maxErrors {
          let preview = utf8Preview(line, maxBytes: 240)
          errors.append(
            .object([
              "line": .number(Double(lineNumber)),
              "byte_count": .number(Double(lineData.count)),
              "message": .string(error.localizedDescription),
              "raw_preview": .string(preview.text),
              "raw_preview_truncated": .bool(preview.truncated),
            ]))
        }
      }
    }

    let recordCountTruncated = parsedRecordCount > records.count
    let errorCountTruncated = parseErrorCount > errors.count

    return .object([
      "operation": .string("jsonl.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "encoding": .string("utf-8"),
      "start_line": .number(Double(startLine)),
      "max_records": .number(Double(maxRecords)),
      "max_errors": .number(Double(maxErrors)),
      "max_bytes": .number(Double(maxBytes)),
      "skip_blank_lines": .bool(skipBlankLines),
      "include_partial_line": .bool(includePartialLine),
      "bytes_read": .number(Double(boundedData.count)),
      "content_truncated": .bool(contentTruncated),
      "last_line_may_be_partial": .bool(lastLineMayBePartial),
      "partial_line_dropped": .bool(partialLineDropped),
      "scanned_line_count": .number(Double(scannedLineCount)),
      "skipped_blank_line_count": .number(Double(skippedBlankLineCount)),
      "record_count": .number(Double(parsedRecordCount)),
      "returned_record_count": .number(Double(records.count)),
      "record_count_truncated": .bool(recordCountTruncated),
      "error_count": .number(Double(parseErrorCount)),
      "returned_error_count": .number(Double(errors.count)),
      "error_count_truncated": .bool(errorCountTruncated),
      "parse_incomplete": .bool(lastLineMayBePartial),
      "truncated": .bool(
        contentTruncated || partialLineDropped || recordCountTruncated || errorCountTruncated),
      "records": .array(records),
      "errors": .array(errors),
    ])
  }

  private func writeJSON(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    guard let value = object["value"] else {
      throw GatewayToolError.invalidArguments("Missing required JSON argument: value")
    }
    let pretty = try optionalBool("pretty", in: object) ?? true
    let sortedKeys = try optionalBool("sorted_keys", in: object) ?? true
    let appendNewline = try optionalBool("append_newline", in: object) ?? true
    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmWrite = try optionalBool("confirm_write", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    guard dryRun || confirmWrite else {
      throw GatewayToolError.invalidArguments(
        "json.write requires confirm_write=true when dry_run is false.")
    }

    let encoder = JSONEncoder()
    var formatting: JSONEncoder.OutputFormatting = []
    if pretty {
      formatting.insert(.prettyPrinted)
    }
    if sortedKeys {
      formatting.insert(.sortedKeys)
    }
    encoder.outputFormatting = formatting
    var data: Data
    do {
      data = try encoder.encode(value)
    } catch {
      throw GatewayToolError.invalidArguments(
        "Unable to encode JSON: \(error.localizedDescription)")
    }
    if appendNewline {
      data.append(0x0a)
    }
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("Encoded JSON exceeds max_bytes.")
    }

    let url = try resolvedWorkspaceURL(path)
    let parent = url.deletingLastPathComponent()
    let fileManager = FileManager.default
    var parentIsDirectory = ObjCBool(false)
    let parentExists = fileManager.fileExists(
      atPath: parent.path,
      isDirectory: &parentIsDirectory
    )
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
      }
    } else {
      guard createDirectories else {
        throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
      }
    }

    var isDirectory = ObjCBool(false)
    let existed = fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory)
    if existed {
      guard !isDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Path is a directory: \(path)")
      }
    }
    if existed && !overwrite {
      throw GatewayToolError.invalidArguments("Refusing to overwrite existing file: \(path)")
    }

    let existingSizeBytes = try existingFileSizeBytes(url: url, existed: existed)
    if !dryRun {
      if createDirectories && !parentExists {
        try fileManager.createDirectory(
          at: parent,
          withIntermediateDirectories: true
        )
      }
      try data.write(to: url, options: .atomic)
    }

    var payload: [String: JSONValue] = [
      "operation": .string("json.write"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "dry_run": .bool(dryRun),
      "confirm_write": .bool(confirmWrite),
      "overwrite": .bool(overwrite),
      "create_directories": .bool(createDirectories),
      "pretty": .bool(pretty),
      "sorted_keys": .bool(sortedKeys),
      "append_newline": .bool(appendNewline),
      "existed": .bool(existed),
      "would_create": .bool(!existed),
      "would_overwrite": .bool(existed),
      "would_create_parent_directories": .bool(!parentExists && createDirectories),
      "bytes_before": .number(Double(existingSizeBytes)),
      "bytes_after": .number(Double(data.count)),
      "bytes_to_write": .number(Double(data.count)),
      "bytes_written": .number(Double(dryRun ? 0 : data.count)),
      "written": .bool(!dryRun),
    ]

    if includePreview {
      let content = String(decoding: data, as: UTF8.self)
      let preview = utf8Preview(content, maxBytes: previewMaxBytes)
      payload["preview"] = .object([
        "preview_max_bytes": .number(Double(previewMaxBytes)),
        "content": .string(preview.text),
        "content_truncated": .bool(preview.truncated),
      ])
    }

    return .object(payload)
  }

  private func readTOML(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    if let size = info.size, size > Int64(maxBytes) {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let decoder = TOMLDecoder()
    decoder.limits = TOMLDecoder.DecodingLimits(
      maxInputSize: maxBytes,
      maxDepth: 128,
      maxTableKeys: 10_000,
      maxArrayLength: 100_000,
      maxStringLength: min(maxBytes, 1_048_576)
    )

    let value: DecodedTOMLValue
    do {
      value = try decoder.decode(DecodedTOMLValue.self, from: data)
    } catch {
      throw GatewayToolError.invalidArguments("Unable to parse TOML: \(error.localizedDescription)")
    }

    return .object([
      "operation": .string("toml.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "bytes_read": .number(Double(data.count)),
      "value": tomlJSONValue(value),
    ])
  }

  private func readYAML(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxDocuments = optionalInt("max_documents", in: object) ?? 50
    let maxDepth = optionalInt("max_depth", in: object) ?? 128
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(maxDocuments, name: "max_documents", upperBound: 1_000)
    try validateBoundedPositive(maxDepth, name: "max_depth", upperBound: 512)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    if let size = info.size, size > Int64(maxBytes) {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }
    guard let text = String(data: data, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("YAML file is not valid UTF-8: \(path)")
    }

    var sequence: YamlSequence<Any>
    do {
      sequence = try Yams.load_all(yaml: text)
    } catch {
      throw GatewayToolError.invalidArguments("Unable to parse YAML: \(error.localizedDescription)")
    }

    var stats = YAMLConversionStats()
    var documents: [JSONValue] = []
    var values: [JSONValue] = []
    var parsedDocumentCount = 0
    while let document = sequence.next() {
      parsedDocumentCount += 1
      if documents.count < maxDocuments {
        let value = try yamlJSONValue(
          document,
          stats: &stats,
          depth: 0,
          maxDepth: maxDepth
        )
        values.append(value)
        documents.append(
          .object([
            "index": .number(Double(parsedDocumentCount - 1)),
            "value": value,
          ]))
      }
    }
    if let error = sequence.error {
      throw GatewayToolError.invalidArguments("Unable to parse YAML: \(error.localizedDescription)")
    }

    let documentCountTruncated = parsedDocumentCount > documents.count
    let topLevelValue: JSONValue
    switch values.count {
    case 0:
      topLevelValue = .null
    case 1:
      topLevelValue = values[0]
    default:
      topLevelValue = .array(values)
    }

    return .object([
      "operation": .string("yaml.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "encoding": .string("utf-8"),
      "bytes_read": .number(Double(data.count)),
      "max_bytes": .number(Double(maxBytes)),
      "max_documents": .number(Double(maxDocuments)),
      "max_depth": .number(Double(maxDepth)),
      "document_count": .number(Double(parsedDocumentCount)),
      "returned_document_count": .number(Double(documents.count)),
      "document_count_truncated": .bool(documentCountTruncated),
      "truncated": .bool(documentCountTruncated),
      "conversion": stats.json,
      "documents": .array(documents),
      "value": topLevelValue,
    ])
  }

  private func readXML(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxNodes = optionalInt("max_nodes", in: object) ?? 10_000
    let maxDepth = optionalInt("max_depth", in: object) ?? 64
    let maxTextBytes = optionalInt("max_text_bytes", in: object) ?? 8_192
    let trimText = try optionalBool("trim_text", in: object) ?? true
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(maxNodes, name: "max_nodes", upperBound: 100_000)
    try validateBoundedPositive(maxDepth, name: "max_depth", upperBound: 512)
    try validateBoundedPositive(maxTextBytes, name: "max_text_bytes", upperBound: 1_048_576)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    if let size = info.size, size > Int64(maxBytes) {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let delegate = XMLTreeParserDelegate(
      maxNodes: maxNodes,
      maxDepth: maxDepth,
      maxTextBytes: maxTextBytes
    )
    let parser = XMLParser(data: data)
    parser.delegate = delegate
    parser.shouldProcessNamespaces = false
    parser.shouldReportNamespacePrefixes = false
    parser.shouldResolveExternalEntities = false

    guard parser.parse() else {
      let message = parser.parserError?.localizedDescription ?? "unknown parse error"
      throw GatewayToolError.invalidArguments(
        "Unable to parse XML at line \(parser.lineNumber), column \(parser.columnNumber): \(message)"
      )
    }

    let truncated = delegate.nodeCountTruncated || delegate.depthTruncated || delegate.textTruncated
    return .object([
      "operation": .string("xml.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "bytes_read": .number(Double(data.count)),
      "max_bytes": .number(Double(maxBytes)),
      "max_nodes": .number(Double(maxNodes)),
      "max_depth": .number(Double(maxDepth)),
      "max_text_bytes": .number(Double(maxTextBytes)),
      "trim_text": .bool(trimText),
      "element_count": .number(Double(delegate.elementCount)),
      "returned_element_count": .number(Double(delegate.returnedElementCount)),
      "max_depth_observed": .number(Double(delegate.maxDepthObserved)),
      "node_count_truncated": .bool(delegate.nodeCountTruncated),
      "depth_truncated": .bool(delegate.depthTruncated),
      "text_truncated": .bool(delegate.textTruncated),
      "truncated": .bool(truncated),
      "root": delegate.root?.json(trimText: trimText) ?? .null,
    ])
  }

  private func readPropertyList(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    if let size = info.size, size > Int64(maxBytes) {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    var format = PropertyListSerialization.PropertyListFormat.xml
    let plist: Any
    do {
      plist = try PropertyListSerialization.propertyList(from: data, options: [], format: &format)
    } catch {
      throw GatewayToolError.invalidArguments(
        "Unable to parse property list: \(error.localizedDescription)")
    }

    return .object([
      "operation": .string("plist.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "format": .string(propertyListFormatName(format)),
      "bytes_read": .number(Double(data.count)),
      "value": try propertyListJSONValue(plist),
    ])
  }

  private func getStructuredValue(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let format = try optionalString("format", in: object) ?? "auto"
    let queryPath = try requiredStructuredPath("query_path", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let maxDocuments = optionalInt("max_documents", in: object) ?? 50
    let maxDepth = optionalInt("max_depth", in: object) ?? 128
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(maxDocuments, name: "max_documents", upperBound: 1_000)
    try validateBoundedPositive(maxDepth, name: "max_depth", upperBound: 512)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    if let size = info.size, size > Int64(maxBytes) {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }

    let data = try readBoundedFileData(url: url, path: path, maxBytes: maxBytes)
    let resolvedFormat = try structuredFormat(format, path: url.path)
    let document = try parseStructuredValue(
      data: data,
      format: resolvedFormat,
      path: path,
      maxBytes: maxBytes,
      maxDocuments: maxDocuments,
      maxDepth: maxDepth
    )
    let selection = selectStructuredValue(document.value, path: queryPath)

    return .object([
      "operation": .string("structured.get"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "format": .string(resolvedFormat),
      "requested_format": .string(format),
      "bytes_read": .number(Double(data.count)),
      "max_bytes": .number(Double(maxBytes)),
      "max_documents": .number(Double(maxDocuments)),
      "max_depth": .number(Double(maxDepth)),
      "query_path": .array(queryPath.map(\.json)),
      "query_pointer": .string(structuredPointer(queryPath)),
      "matched": .bool(selection.matched),
      "failure": selection.failure?.json ?? .null,
      "value_kind": .string(jsonValueKind(selection.value)),
      "value": selection.value,
      "document_metadata": document.metadata,
    ])
  }

  private func writePropertyList(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    guard let value = object["value"] else {
      throw GatewayToolError.invalidArguments("Missing required property list argument: value")
    }
    let formatName = try optionalString("format", in: object) ?? "xml"
    let format: PropertyListSerialization.PropertyListFormat
    switch formatName {
    case "xml":
      format = .xml
    case "binary":
      format = .binary
    default:
      throw GatewayToolError.invalidArguments("format must be xml or binary.")
    }

    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmWrite = try optionalBool("confirm_write", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    guard dryRun || confirmWrite else {
      throw GatewayToolError.invalidArguments(
        "plist.write requires confirm_write=true when dry_run is false.")
    }

    let plist = try propertyListObject(from: value)
    var data: Data
    do {
      data = try PropertyListSerialization.data(
        fromPropertyList: plist,
        format: format,
        options: 0
      )
    } catch {
      throw GatewayToolError.invalidArguments(
        "Unable to encode property list: \(error.localizedDescription)")
    }
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("Encoded property list exceeds max_bytes.")
    }

    let url = try resolvedWorkspaceURL(path)
    let parent = url.deletingLastPathComponent()
    let fileManager = FileManager.default
    var parentIsDirectory = ObjCBool(false)
    let parentExists = fileManager.fileExists(
      atPath: parent.path,
      isDirectory: &parentIsDirectory
    )
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
      }
    } else {
      guard createDirectories else {
        throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
      }
    }

    var isDirectory = ObjCBool(false)
    let existed = fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory)
    if existed {
      guard !isDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Path is a directory: \(path)")
      }
    }
    if existed && !overwrite {
      throw GatewayToolError.invalidArguments("Refusing to overwrite existing file: \(path)")
    }

    let existingSizeBytes = try existingFileSizeBytes(url: url, existed: existed)
    if !dryRun {
      if createDirectories && !parentExists {
        try fileManager.createDirectory(
          at: parent,
          withIntermediateDirectories: true
        )
      }
      try data.write(to: url, options: .atomic)
    }

    var payload: [String: JSONValue] = [
      "operation": .string("plist.write"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "format": .string(formatName),
      "dry_run": .bool(dryRun),
      "confirm_write": .bool(confirmWrite),
      "overwrite": .bool(overwrite),
      "create_directories": .bool(createDirectories),
      "existed": .bool(existed),
      "would_create": .bool(!existed),
      "would_overwrite": .bool(existed),
      "would_create_parent_directories": .bool(!parentExists && createDirectories),
      "bytes_before": .number(Double(existingSizeBytes)),
      "bytes_after": .number(Double(data.count)),
      "bytes_to_write": .number(Double(data.count)),
      "bytes_written": .number(Double(dryRun ? 0 : data.count)),
      "written": .bool(!dryRun),
    ]

    if includePreview {
      payload["preview"] = propertyListPreview(
        data: data, format: format, maxBytes: previewMaxBytes)
    }

    return .object(payload)
  }

  private func readCSV(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let delimiterInput = try optionalString("delimiter", in: object) ?? "auto"
    let hasHeader = try optionalBool("has_header", in: object) ?? true
    let maxRows = optionalInt("max_rows", in: object) ?? 100
    let maxColumns = optionalInt("max_columns", in: object) ?? 200
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxRows, name: "max_rows", upperBound: 100_000)
    try validateBoundedPositive(maxColumns, name: "max_columns", upperBound: 10_000)
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let contentTruncated = data.count > maxBytes
    let boundedData = contentTruncated ? Data(data.prefix(maxBytes)) : data
    guard let text = String(data: boundedData, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("CSV file is not valid UTF-8: \(path)")
    }

    let delimiter = try csvDelimiter(from: delimiterInput, sample: text)
    let requestedRecords = maxRows + (hasHeader ? 1 : 0)
    let parsed = parseDelimitedText(
      text,
      delimiter: delimiter.character,
      maxRecords: requestedRecords,
      maxColumns: maxColumns
    )
    let records = parsed.records
    let headers: [String]
    let rowRecords: ArraySlice<[String]>
    if hasHeader, let first = records.first {
      headers = first
      rowRecords = records.dropFirst()
    } else {
      headers = []
      rowRecords = records[...]
    }

    let rows: [JSONValue] = rowRecords.enumerated().map { index, cells in
      JSONValue.object([
        "record_number": .number(Double(index + (hasHeader ? 2 : 1))),
        "cells": .array(cells.map(JSONValue.string)),
      ])
    }
    let rowCountTruncated =
      parsed.recordsTruncated
      || (!hasHeader && records.count > maxRows)
      || (hasHeader && max(records.count - 1, 0) > maxRows)

    let payload: [String: JSONValue] = [
      "operation": .string("csv.read"),
      "path": .string(url.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      "delimiter": .string(delimiter.name),
      "delimiter_character": .string(String(delimiter.character)),
      "delimiter_source": .string(delimiter.source),
      "has_header": .bool(hasHeader),
      "headers": .array(headers.map(JSONValue.string)),
      "header_count": .number(Double(headers.count)),
      "rows": .array(rows),
      "returned_row_count": .number(Double(rows.count)),
      "max_rows": .number(Double(maxRows)),
      "max_columns": .number(Double(maxColumns)),
      "bytes_read": .number(Double(boundedData.count)),
      "content_truncated": .bool(contentTruncated),
      "row_count_truncated": .bool(rowCountTruncated),
      "column_count_truncated": .bool(parsed.columnsTruncated),
      "parse_incomplete": .bool(contentTruncated || parsed.openQuotedField),
      "truncated": .bool(contentTruncated || rowCountTruncated || parsed.columnsTruncated),
    ]
    return .object(payload)
  }

  private func csvDelimiter(from input: String, sample: String) throws -> CSVDelimiter {
    switch input {
    case "auto":
      let inferred = inferDelimitedTextDelimiter(sample)
      return CSVDelimiter(
        character: inferred.character,
        name: inferred.name,
        source: "auto"
      )
    case "comma", ",":
      return CSVDelimiter(character: ",", name: "comma", source: "configured")
    case "tab", "\\t", "\t":
      return CSVDelimiter(character: "\t", name: "tab", source: "configured")
    case "semicolon", ";":
      return CSVDelimiter(character: ";", name: "semicolon", source: "configured")
    case "pipe", "|":
      return CSVDelimiter(character: "|", name: "pipe", source: "configured")
    default:
      let characters = Array(input)
      guard characters.count == 1, characters[0] != "\n", characters[0] != "\r",
        characters[0] != "\""
      else {
        throw GatewayToolError.invalidArguments(
          "delimiter must be auto, comma, tab, semicolon, pipe, or one non-newline character.")
      }
      return CSVDelimiter(character: characters[0], name: input, source: "configured")
    }
  }

  private func inferDelimitedTextDelimiter(_ text: String) -> CSVDelimiter {
    let candidates: [(Character, String)] = [
      (",", "comma"),
      ("\t", "tab"),
      (";", "semicolon"),
      ("|", "pipe"),
    ]
    var counts = Dictionary(uniqueKeysWithValues: candidates.map { ($0.1, 0) })
    var inQuotes = false
    var index = text.startIndex
    var scannedBytes = 0
    while index < text.endIndex && scannedBytes < 8_192 {
      let character = text[index]
      scannedBytes += String(character).utf8.count
      if character == "\"" {
        let next = text.index(after: index)
        if inQuotes, next < text.endIndex, text[next] == "\"" {
          index = text.index(after: next)
          continue
        }
        inQuotes.toggle()
      } else if !inQuotes {
        for (candidate, name) in candidates where character == candidate {
          counts[name, default: 0] += 1
        }
      }
      index = text.index(after: index)
    }

    let best =
      candidates.max { lhs, rhs in
        counts[lhs.1, default: 0] < counts[rhs.1, default: 0]
      } ?? (",", "comma")
    if counts[best.1, default: 0] == 0 {
      return CSVDelimiter(character: ",", name: "comma", source: "auto")
    }
    return CSVDelimiter(character: best.0, name: best.1, source: "auto")
  }

  private func parseDelimitedText(
    _ text: String,
    delimiter: Character,
    maxRecords: Int,
    maxColumns: Int
  ) -> DelimitedTextParseResult {
    var records: [[String]] = []
    var currentRecord: [String] = []
    var currentField = ""
    var inQuotes = false
    var atFieldStart = true
    var pendingField = false
    var recordsTruncated = false
    var columnsTruncated = false

    func appendField() {
      if currentRecord.count < maxColumns {
        currentRecord.append(currentField)
      } else {
        columnsTruncated = true
      }
      currentField = ""
      atFieldStart = true
      pendingField = true
    }

    func appendRecord() {
      guard records.count < maxRecords else {
        recordsTruncated = true
        currentRecord.removeAll()
        currentField = ""
        pendingField = false
        return
      }
      records.append(currentRecord)
      currentRecord.removeAll()
      currentField = ""
      atFieldStart = true
      pendingField = false
    }

    var index = text.startIndex
    while index < text.endIndex {
      if recordsTruncated {
        break
      }
      let character = text[index]

      if inQuotes {
        if character == "\"" {
          let next = text.index(after: index)
          if next < text.endIndex, text[next] == "\"" {
            currentField.append("\"")
            pendingField = true
            atFieldStart = false
            index = text.index(after: next)
            continue
          }
          inQuotes = false
          atFieldStart = false
        } else {
          currentField.append(character)
          pendingField = true
          atFieldStart = false
        }
      } else if character == "\"" && atFieldStart {
        inQuotes = true
        pendingField = true
        atFieldStart = false
      } else if character == delimiter {
        appendField()
      } else if character == "\n" || character == "\r" {
        appendField()
        appendRecord()
        if character == "\r" {
          let next = text.index(after: index)
          if next < text.endIndex, text[next] == "\n" {
            index = next
          }
        }
      } else {
        currentField.append(character)
        pendingField = true
        atFieldStart = false
      }

      index = text.index(after: index)
    }

    if !recordsTruncated, pendingField || !currentRecord.isEmpty || !currentField.isEmpty {
      appendField()
      appendRecord()
    }

    return DelimitedTextParseResult(
      records: records,
      recordsTruncated: recordsTruncated,
      columnsTruncated: columnsTruncated,
      openQuotedField: inQuotes
    )
  }

  private func sqliteSchema(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let includeViews = try optionalBool("include_views", in: object) ?? true
    let includeIndexes = try optionalBool("include_indexes", in: object) ?? true
    let includeTriggers = try optionalBool("include_triggers", in: object) ?? true
    let includeInternal = try optionalBool("include_internal", in: object) ?? false
    let includeSQL = try optionalBool("include_sql", in: object) ?? true
    let maxEntries = optionalInt("max_entries", in: object) ?? 500
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 100_000)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    var types = ["table"]
    if includeViews {
      types.append("view")
    }
    if includeIndexes {
      types.append("index")
    }
    if includeTriggers {
      types.append("trigger")
    }
    let typeList = types.map { "'\($0)'" }.joined(separator: ", ")
    var predicates = ["type IN (\(typeList))"]
    if !includeInternal {
      predicates.append("name NOT LIKE 'sqlite_%'")
    }
    let sqlColumn = includeSQL ? "sql" : "NULL AS sql"
    let sql = """
      SELECT type, name, tbl_name, \(sqlColumn)
      FROM sqlite_schema
      WHERE \(predicates.joined(separator: " AND "))
      ORDER BY CASE type WHEN 'table' THEN 0 WHEN 'view' THEN 1 WHEN 'index' THEN 2 \
      WHEN 'trigger' THEN 3 ELSE 4 END, name
      LIMIT \(maxEntries + 1);
      """

    let result = try commandRunner.run(
      executable: "/usr/bin/sqlite3",
      arguments: ["-batch", "-readonly", "-json", url.path, sql],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    guard !result.timedOut else {
      throw GatewayToolError.executionFailed("sqlite.schema timed out.")
    }
    guard result.exitCode == 0 else {
      throw GatewayToolError.executionFailed(
        "sqlite.schema failed with exit code \(result.exitCode.map(String.init) ?? "unknown"): \(result.stderr)"
      )
    }
    guard !result.stdoutTruncated else {
      throw GatewayToolError.executionFailed("sqlite.schema output exceeded max_output_bytes.")
    }

    let decoded: JSONValue
    do {
      decoded = try JSONDecoder().decode(JSONValue.self, from: Data(result.stdout.utf8))
    } catch {
      throw GatewayToolError.invalidArguments(
        "Unable to parse sqlite schema JSON: \(error.localizedDescription)")
    }
    guard let allEntries = decoded.arrayValue else {
      throw GatewayToolError.invalidArguments("Unable to parse sqlite schema JSON: expected array.")
    }

    let truncated = allEntries.count > maxEntries
    let entries = truncated ? Array(allEntries.prefix(maxEntries)) : allEntries

    return .object([
      "operation": .string("sqlite.schema"),
      "database": .object([
        "path": .string(url.path),
        "workspace_relative_path": .string(info.workspaceRelativePath),
        "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
        "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      ]),
      "include_views": .bool(includeViews),
      "include_indexes": .bool(includeIndexes),
      "include_triggers": .bool(includeTriggers),
      "include_internal": .bool(includeInternal),
      "include_sql": .bool(includeSQL),
      "max_entries": .number(Double(maxEntries)),
      "returned_count": .number(Double(entries.count)),
      "truncated": .bool(truncated),
      "sql": .string(sql),
      "argv": .array(result.arguments.map(JSONValue.string)),
      "entries": .array(entries),
      "result": .object([
        "executable": .string(result.executable),
        "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
        "timed_out": .bool(result.timedOut),
        "stdout_bytes": .number(Double(result.stdout.utf8.count)),
        "stdout_truncated": .bool(result.stdoutTruncated),
        "stderr": .string(result.stderr),
        "stderr_truncated": .bool(result.stderrTruncated),
      ]),
    ])
  }

  private func sqliteQuery(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let query = try requiredString("query", in: object)
    let maxRows = optionalInt("max_rows", in: object) ?? 100
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxRows, name: "max_rows", upperBound: 100_000)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let readonlyQuery = try validatedReadonlySQLiteQuery(query)
    let executableSQL: String
    switch readonlyQuery.kind {
    case "select", "with":
      executableSQL = """
        SELECT *
        FROM (
        \(readonlyQuery.sql)
        )
        LIMIT \(maxRows + 1);
        """
    default:
      executableSQL = readonlyQuery.sql
    }

    let result = try commandRunner.run(
      executable: "/usr/bin/sqlite3",
      arguments: ["-batch", "-readonly", "-json", url.path, executableSQL],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    guard !result.timedOut else {
      throw GatewayToolError.executionFailed("sqlite.query timed out.")
    }
    guard result.exitCode == 0 else {
      throw GatewayToolError.executionFailed(
        "sqlite.query failed with exit code \(result.exitCode.map(String.init) ?? "unknown"): \(result.stderr)"
      )
    }
    guard !result.stdoutTruncated else {
      throw GatewayToolError.executionFailed("sqlite.query output exceeded max_output_bytes.")
    }

    let decoded: JSONValue
    do {
      decoded = try JSONDecoder().decode(JSONValue.self, from: Data(result.stdout.utf8))
    } catch {
      throw GatewayToolError.invalidArguments(
        "Unable to parse sqlite query JSON: \(error.localizedDescription)")
    }
    guard let allRows = decoded.arrayValue else {
      throw GatewayToolError.invalidArguments("Unable to parse sqlite query JSON: expected array.")
    }

    let truncated = allRows.count > maxRows
    let rows = truncated ? Array(allRows.prefix(maxRows)) : allRows

    return .object([
      "operation": .string("sqlite.query"),
      "database": .object([
        "path": .string(url.path),
        "workspace_relative_path": .string(info.workspaceRelativePath),
        "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
        "modified_at": info.modifiedAt.map { .string(iso8601String($0)) } ?? .null,
      ]),
      "query_kind": .string(readonlyQuery.kind),
      "query": .string(readonlyQuery.sql),
      "executed_sql": .string(executableSQL),
      "max_rows": .number(Double(maxRows)),
      "returned_count": .number(Double(rows.count)),
      "truncated": .bool(truncated),
      "rows": .array(rows),
      "argv": .array(result.arguments.map(JSONValue.string)),
      "result": .object([
        "executable": .string(result.executable),
        "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
        "timed_out": .bool(result.timedOut),
        "stdout_bytes": .number(Double(result.stdout.utf8.count)),
        "stdout_truncated": .bool(result.stdoutTruncated),
        "stderr": .string(result.stderr),
        "stderr_truncated": .bool(result.stderrTruncated),
      ]),
    ])
  }

  private func validatedReadonlySQLiteQuery(_ sql: String) throws -> (sql: String, kind: String) {
    let withoutComments = try sqliteSQLWithoutComments(sql)
    let statement = try sqliteSingleStatement(withoutComments)
    guard !statement.isEmpty else {
      throw GatewayToolError.invalidArguments("query must not be empty.")
    }

    let tokens = sqliteTokensOutsideLiterals(statement)
    guard let first = tokens.first else {
      throw GatewayToolError.invalidArguments("query must contain a SQL statement.")
    }
    let allowedKinds = Set(["select", "with", "pragma"])
    guard allowedKinds.contains(first) else {
      throw GatewayToolError.invalidArguments(
        "sqlite.query only accepts read-only SELECT, WITH, or PRAGMA statements.")
    }

    let denied = Set([
      "alter", "analyze", "attach", "create", "delete", "detach", "drop", "insert",
      "reindex", "replace", "update", "vacuum",
    ])
    if let token = tokens.first(where: { denied.contains($0) }) {
      throw GatewayToolError.invalidArguments(
        "sqlite.query rejected non-read-only SQL token: \(token).")
    }
    if first == "pragma" {
      guard !sqliteContainsEqualsOutsideLiterals(statement) else {
        throw GatewayToolError.invalidArguments(
          "sqlite.query only accepts read-only PRAGMA statements without assignment.")
      }
      if tokens.contains("optimize") || tokens.contains("writable_schema") {
        throw GatewayToolError.invalidArguments("sqlite.query rejected unsafe PRAGMA statement.")
      }
    }

    return (statement, first)
  }

  private func sqliteSQLWithoutComments(_ sql: String) throws -> String {
    var output = ""
    var index = sql.startIndex
    var quote: Character?
    while index < sql.endIndex {
      let character = sql[index]
      let nextIndex = sql.index(after: index)
      let next = nextIndex < sql.endIndex ? sql[nextIndex] : nil

      if let currentQuote = quote {
        output.append(character)
        if character == currentQuote {
          if next == currentQuote, currentQuote == "'" || currentQuote == "\"" {
            output.append(next!)
            index = sql.index(after: nextIndex)
            continue
          }
          quote = nil
        }
        index = nextIndex
        continue
      }

      if character == "'" || character == "\"" || character == "`" {
        quote = character
        output.append(character)
        index = nextIndex
      } else if character == "[", let closeIndex = sql[index...].firstIndex(of: "]") {
        output.append(contentsOf: sql[index...closeIndex])
        index = sql.index(after: closeIndex)
      } else if character == "-", next == "-" {
        var cursor = sql.index(after: nextIndex)
        while cursor < sql.endIndex, sql[cursor] != "\n" {
          cursor = sql.index(after: cursor)
        }
        output.append(" ")
        index = cursor
      } else if character == "/", next == "*" {
        var cursor = sql.index(after: nextIndex)
        var closed = false
        while cursor < sql.endIndex {
          let afterCursor = sql.index(after: cursor)
          if sql[cursor] == "*", afterCursor < sql.endIndex, sql[afterCursor] == "/" {
            cursor = sql.index(after: afterCursor)
            closed = true
            break
          }
          cursor = afterCursor
        }
        guard closed else {
          throw GatewayToolError.invalidArguments("query contains an unterminated block comment.")
        }
        output.append(" ")
        index = cursor
      } else {
        output.append(character)
        index = nextIndex
      }
    }

    guard quote == nil else {
      throw GatewayToolError.invalidArguments("query contains an unterminated quoted literal.")
    }
    return output
  }

  private func sqliteSingleStatement(_ sql: String) throws -> String {
    var semicolonIndex: String.Index?
    var index = sql.startIndex
    var quote: Character?
    while index < sql.endIndex {
      let character = sql[index]
      let nextIndex = sql.index(after: index)
      let next = nextIndex < sql.endIndex ? sql[nextIndex] : nil

      if let currentQuote = quote {
        if character == currentQuote {
          if next == currentQuote, currentQuote == "'" || currentQuote == "\"" {
            index = sql.index(after: nextIndex)
            continue
          }
          quote = nil
        }
        index = nextIndex
        continue
      }

      if character == "'" || character == "\"" || character == "`" {
        quote = character
      } else if character == "[", let closeIndex = sql[index...].firstIndex(of: "]") {
        index = sql.index(after: closeIndex)
        continue
      } else if character == ";" {
        guard semicolonIndex == nil else {
          throw GatewayToolError.invalidArguments("sqlite.query accepts one SQL statement only.")
        }
        semicolonIndex = index
      }
      index = nextIndex
    }

    guard quote == nil else {
      throw GatewayToolError.invalidArguments("query contains an unterminated quoted literal.")
    }

    if let semicolonIndex {
      let rest = sql[sql.index(after: semicolonIndex)...]
      guard rest.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        throw GatewayToolError.invalidArguments("sqlite.query accepts one SQL statement only.")
      }
      return String(sql[..<semicolonIndex]).trimmingCharacters(in: .whitespacesAndNewlines)
    }
    return sql.trimmingCharacters(in: .whitespacesAndNewlines)
  }

  private func sqliteTokensOutsideLiterals(_ sql: String) -> [String] {
    var tokens: [String] = []
    var current = ""
    var index = sql.startIndex
    var quote: Character?

    func flush() {
      if !current.isEmpty {
        tokens.append(current.lowercased())
        current.removeAll()
      }
    }

    while index < sql.endIndex {
      let character = sql[index]
      let nextIndex = sql.index(after: index)
      let next = nextIndex < sql.endIndex ? sql[nextIndex] : nil

      if let currentQuote = quote {
        if character == currentQuote {
          if next == currentQuote, currentQuote == "'" || currentQuote == "\"" {
            index = sql.index(after: nextIndex)
            continue
          }
          quote = nil
        }
        index = nextIndex
        continue
      }

      if character == "'" || character == "\"" || character == "`" {
        flush()
        quote = character
      } else if character == "[", let closeIndex = sql[index...].firstIndex(of: "]") {
        flush()
        index = sql.index(after: closeIndex)
        continue
      } else if character.isLetter || character.isNumber || character == "_" {
        current.append(character)
      } else {
        flush()
      }
      index = nextIndex
    }
    flush()
    return tokens
  }

  private func sqliteContainsEqualsOutsideLiterals(_ sql: String) -> Bool {
    var index = sql.startIndex
    var quote: Character?
    while index < sql.endIndex {
      let character = sql[index]
      let nextIndex = sql.index(after: index)
      let next = nextIndex < sql.endIndex ? sql[nextIndex] : nil

      if let currentQuote = quote {
        if character == currentQuote {
          if next == currentQuote, currentQuote == "'" || currentQuote == "\"" {
            index = sql.index(after: nextIndex)
            continue
          }
          quote = nil
        }
        index = nextIndex
        continue
      }

      if character == "'" || character == "\"" || character == "`" {
        quote = character
      } else if character == "[", let closeIndex = sql[index...].firstIndex(of: "]") {
        index = sql.index(after: closeIndex)
        continue
      } else if character == "=" {
        return true
      }
      index = nextIndex
    }
    return false
  }

  private func hashFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let algorithm = try optionalString("algorithm", in: object) ?? "sha256"
    guard algorithm == "sha256" else {
      throw GatewayToolError.invalidArguments("algorithm must be sha256.")
    }

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let digest = try sha256Hex(url: url)
    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "algorithm": .string(algorithm),
      "hex": .string(digest.hex),
      "bytes_read": .number(Double(digest.bytesRead)),
    ])
  }

  private func sha256Hex(url: URL) throws -> (hex: String, bytesRead: Int) {
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    var hasher = SHA256()
    var bytesRead = 0
    while true {
      let data = try handle.read(upToCount: 1_048_576) ?? Data()
      guard !data.isEmpty else {
        break
      }
      hasher.update(data: data)
      bytesRead += data.count
    }
    return (hexString(hasher.finalize()), bytesRead)
  }

  private func diffFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let sourcePath = try requiredString("source", in: object)
    let targetPath = try requiredString("target", in: object)
    let contextLines = optionalInt("context_lines", in: object) ?? 3
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedNonNegative(contextLines, name: "context_lines", upperBound: 1_000)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let source = try resolvedWorkspaceURL(sourcePath)
    let target = try resolvedWorkspaceURL(targetPath)
    let sourceInfo = try fileInfo(url: source)
    let targetInfo = try fileInfo(url: target)
    guard sourceInfo.type == "file" else {
      throw GatewayToolError.invalidArguments("Source is not a file: \(sourcePath)")
    }
    guard targetInfo.type == "file" else {
      throw GatewayToolError.invalidArguments("Target is not a file: \(targetPath)")
    }

    let result = try commandRunner.run(
      executable: "/usr/bin/diff",
      arguments: ["-U", "\(contextLines)", source.path, target.path],
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    return .object([
      "operation": .string("file.diff"),
      "source": .object([
        "path": .string(source.path),
        "workspace_relative_path": .string(workspaceRelativePath(source)),
      ]),
      "target": .object([
        "path": .string(target.path),
        "workspace_relative_path": .string(workspaceRelativePath(target)),
      ]),
      "context_lines": .number(Double(contextLines)),
      "max_output_bytes": .number(Double(maxOutputBytes)),
      "result": result.json,
    ])
  }

  private func compareFileTrees(arguments object: [String: JSONValue]) throws -> JSONValue {
    let leftPath = try requiredString("left", in: object)
    let rightPath = try requiredString("right", in: object)
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let compareHashes = try optionalBool("compare_hashes", in: object) ?? false
    let maxDepth = optionalInt("max_depth", in: object) ?? 8
    let maxEntries = optionalInt("max_entries", in: object) ?? 20_000
    let maxResults = optionalInt("max_results", in: object) ?? 200
    let maxHashFiles = optionalInt("max_hash_files", in: object) ?? 1_000
    let maxHashFileBytes = optionalInt("max_hash_file_bytes", in: object) ?? 10_485_760

    try validateBoundedNonNegative(maxDepth, name: "max_depth", upperBound: 50)
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 200_000)
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 10_000)
    try validateBoundedPositive(maxHashFiles, name: "max_hash_files", upperBound: 20_000)
    try validateBoundedPositive(
      maxHashFileBytes,
      name: "max_hash_file_bytes",
      upperBound: 1_073_741_824
    )

    let left = try resolvedWorkspaceURL(leftPath)
    let right = try resolvedWorkspaceURL(rightPath)
    try requireDirectory(left, originalPath: leftPath)
    try requireDirectory(right, originalPath: rightPath)

    var leftScanned = 0
    var rightScanned = 0
    var leftTruncated = false
    var rightTruncated = false
    let leftEntries = try collectTreeCompareEntries(
      root: left,
      includeHidden: includeHidden,
      maxDepth: maxDepth,
      maxEntries: maxEntries,
      scannedEntries: &leftScanned,
      truncated: &leftTruncated
    )
    let rightEntries = try collectTreeCompareEntries(
      root: right,
      includeHidden: includeHidden,
      maxDepth: maxDepth,
      maxEntries: maxEntries,
      scannedEntries: &rightScanned,
      truncated: &rightTruncated
    )

    var differenceCounts: [String: Int] = [:]
    var differences: [TreeCompareDifference] = []
    var resultTruncated = false
    var metadataMatchCount = 0
    var hashMatchCount = 0
    var hashSkippedCount = 0
    var hashFilesCompared = 0
    var hashBytesRead = 0
    let allRelativePaths = Set(leftEntries.keys).union(rightEntries.keys).sorted {
      $0.localizedStandardCompare($1) == .orderedAscending
    }

    for relativePath in allRelativePaths {
      guard let leftEntry = leftEntries[relativePath] else {
        recordTreeCompareDifference(
          kind: "right_only",
          relativePath: relativePath,
          left: nil,
          right: rightEntries[relativePath],
          detail: "Entry exists only under right.",
          differenceCounts: &differenceCounts,
          differences: &differences,
          maxResults: maxResults,
          resultTruncated: &resultTruncated
        )
        continue
      }
      guard let rightEntry = rightEntries[relativePath] else {
        recordTreeCompareDifference(
          kind: "left_only",
          relativePath: relativePath,
          left: leftEntry,
          right: nil,
          detail: "Entry exists only under left.",
          differenceCounts: &differenceCounts,
          differences: &differences,
          maxResults: maxResults,
          resultTruncated: &resultTruncated
        )
        continue
      }

      if leftEntry.type != rightEntry.type {
        recordTreeCompareDifference(
          kind: "type_mismatch",
          relativePath: relativePath,
          left: leftEntry,
          right: rightEntry,
          detail: "Entry types differ.",
          differenceCounts: &differenceCounts,
          differences: &differences,
          maxResults: maxResults,
          resultTruncated: &resultTruncated
        )
        continue
      }

      if leftEntry.isSymlink || rightEntry.isSymlink {
        if leftEntry.symlinkDestination == rightEntry.symlinkDestination {
          metadataMatchCount += 1
        } else {
          recordTreeCompareDifference(
            kind: "symlink_mismatch",
            relativePath: relativePath,
            left: leftEntry,
            right: rightEntry,
            detail: "Symlink destinations differ.",
            differenceCounts: &differenceCounts,
            differences: &differences,
            maxResults: maxResults,
            resultTruncated: &resultTruncated
          )
        }
        continue
      }

      guard leftEntry.type == "file" else {
        metadataMatchCount += 1
        continue
      }

      if leftEntry.sizeBytes != rightEntry.sizeBytes {
        recordTreeCompareDifference(
          kind: "size_mismatch",
          relativePath: relativePath,
          left: leftEntry,
          right: rightEntry,
          detail: "File sizes differ.",
          differenceCounts: &differenceCounts,
          differences: &differences,
          maxResults: maxResults,
          resultTruncated: &resultTruncated
        )
        continue
      }

      if compareHashes {
        guard
          let leftSize = leftEntry.sizeBytes,
          leftSize <= Int64(maxHashFileBytes),
          hashFilesCompared + 2 <= maxHashFiles
        else {
          metadataMatchCount += 1
          hashSkippedCount += 1
          continue
        }

        var hashedLeftEntry = leftEntry
        var hashedRightEntry = rightEntry
        let leftHash = try sha256Hex(url: leftEntry.url)
        let rightHash = try sha256Hex(url: rightEntry.url)
        hashedLeftEntry.sha256 = leftHash.hex
        hashedRightEntry.sha256 = rightHash.hex
        hashFilesCompared += 2
        hashBytesRead += leftHash.bytesRead + rightHash.bytesRead

        if leftHash.hex == rightHash.hex {
          hashMatchCount += 1
        } else {
          recordTreeCompareDifference(
            kind: "hash_mismatch",
            relativePath: relativePath,
            left: hashedLeftEntry,
            right: hashedRightEntry,
            detail: "SHA-256 hashes differ.",
            differenceCounts: &differenceCounts,
            differences: &differences,
            maxResults: maxResults,
            resultTruncated: &resultTruncated
          )
        }
      } else {
        metadataMatchCount += 1
      }
    }

    let differenceCount = differenceCounts.values.reduce(0, +)
    return .object([
      "operation": .string("file.compare_trees"),
      "left": .object([
        "path": .string(left.path),
        "workspace_relative_path": .string(workspaceRelativePath(left)),
        "scanned_entries": .number(Double(leftScanned)),
        "truncated": .bool(leftTruncated),
      ]),
      "right": .object([
        "path": .string(right.path),
        "workspace_relative_path": .string(workspaceRelativePath(right)),
        "scanned_entries": .number(Double(rightScanned)),
        "truncated": .bool(rightTruncated),
      ]),
      "include_hidden": .bool(includeHidden),
      "max_depth": .number(Double(maxDepth)),
      "max_entries": .number(Double(maxEntries)),
      "max_results": .number(Double(maxResults)),
      "compare_hashes": .bool(compareHashes),
      "max_hash_files": .number(Double(maxHashFiles)),
      "max_hash_file_bytes": .number(Double(maxHashFileBytes)),
      "left_entry_count": .number(Double(leftEntries.count)),
      "right_entry_count": .number(Double(rightEntries.count)),
      "metadata_match_count": .number(Double(metadataMatchCount)),
      "hash_match_count": .number(Double(hashMatchCount)),
      "hash_skipped_count": .number(Double(hashSkippedCount)),
      "hash_files_compared": .number(Double(hashFilesCompared)),
      "hash_bytes_read": .number(Double(hashBytesRead)),
      "difference_count": .number(Double(differenceCount)),
      "difference_counts": .object(
        differenceCounts
          .sorted { $0.key.localizedStandardCompare($1.key) == .orderedAscending }
          .reduce(into: [String: JSONValue]()) { result, pair in
            result[pair.key] = .number(Double(pair.value))
          }),
      "result_count": .number(Double(differences.count)),
      "result_truncated": .bool(resultTruncated),
      "scan_truncated": .bool(leftTruncated || rightTruncated),
      "differences": .array(differences.map(\.json)),
    ])
  }

  private func findDuplicateFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try optionalString("path", in: object) ?? "."
    let includeHidden = try optionalBool("include_hidden", in: object) ?? false
    let minSizeBytes = optionalInt("min_size_bytes", in: object) ?? 1
    let maxDepth = optionalInt("max_depth", in: object) ?? 8
    let maxEntries = optionalInt("max_entries", in: object) ?? 20_000
    let maxHashFiles = optionalInt("max_hash_files", in: object) ?? 5_000
    let maxHashFileBytes = optionalInt("max_hash_file_bytes", in: object) ?? 10_485_760
    let maxGroups = optionalInt("max_groups", in: object) ?? 100
    let maxFilesPerGroup = optionalInt("max_files_per_group", in: object) ?? 20

    try validateBoundedNonNegative(
      minSizeBytes,
      name: "min_size_bytes",
      upperBound: 1_099_511_627_776
    )
    try validateBoundedNonNegative(maxDepth, name: "max_depth", upperBound: 50)
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 200_000)
    try validateBoundedPositive(maxHashFiles, name: "max_hash_files", upperBound: 200_000)
    try validateBoundedPositive(
      maxHashFileBytes,
      name: "max_hash_file_bytes",
      upperBound: 1_073_741_824
    )
    try validateBoundedPositive(maxGroups, name: "max_groups", upperBound: 10_000)
    try validateBoundedPositive(maxFilesPerGroup, name: "max_files_per_group", upperBound: 1_000)

    let root = try resolvedWorkspaceURL(path)
    try requireDirectory(root, originalPath: path)

    var scannedEntries = 0
    var scannedFileCount = 0
    var skippedSmallFileCount = 0
    var skippedLargeFileCount = 0
    var scanTruncated = false
    var candidates: [DuplicateFileCandidate] = []
    try collectDuplicateFileCandidates(
      directory: root,
      currentDepth: 0,
      maxDepth: maxDepth,
      includeHidden: includeHidden,
      minSizeBytes: Int64(minSizeBytes),
      maxHashFileBytes: Int64(maxHashFileBytes),
      maxEntries: maxEntries,
      scannedEntries: &scannedEntries,
      scannedFileCount: &scannedFileCount,
      skippedSmallFileCount: &skippedSmallFileCount,
      skippedLargeFileCount: &skippedLargeFileCount,
      scanTruncated: &scanTruncated,
      candidates: &candidates
    )

    let sizeBuckets = Dictionary(grouping: candidates, by: \.sizeBytes)
      .filter { $0.value.count > 1 }
    var hashBuckets: [DuplicateHashBucket] = []
    var hashedFileCount = 0
    var hashedSizeBucketCount = 0
    var hashBytesRead = 0
    var hashSkippedFileCount = 0
    var hashSkippedSizeBucketCount = 0

    for size in sizeBuckets.keys.sorted() {
      let bucket = (sizeBuckets[size] ?? []).sorted()
      guard hashedFileCount + bucket.count <= maxHashFiles else {
        hashSkippedFileCount += bucket.count
        hashSkippedSizeBucketCount += 1
        continue
      }

      hashedSizeBucketCount += 1
      var hashedByDigest: [String: [DuplicateFileCandidate]] = [:]
      for candidate in bucket {
        let digest = try sha256Hex(url: candidate.url)
        hashBytesRead += digest.bytesRead
        hashedFileCount += 1
        var hashedCandidate = candidate
        hashedCandidate.sha256 = digest.hex
        hashedByDigest[digest.hex, default: []].append(hashedCandidate)
      }

      for digest in hashedByDigest.keys.sorted() {
        guard let files = hashedByDigest[digest], files.count > 1 else {
          continue
        }
        hashBuckets.append(
          DuplicateHashBucket(
            sha256: digest,
            sizeBytes: size,
            files: files.sorted()
          ))
      }
    }

    let sortedGroups = hashBuckets.sorted()
    let duplicateGroupCount = sortedGroups.count
    let duplicateFileCount = sortedGroups.reduce(0) { $0 + $1.files.count }
    let duplicateBytes = sortedGroups.reduce(Int64(0)) {
      $0 + $1.sizeBytes * Int64($1.files.count)
    }
    let redundantBytes = sortedGroups.reduce(Int64(0)) {
      $0 + $1.sizeBytes * Int64(max($1.files.count - 1, 0))
    }
    var returnedDuplicateFileCount = 0
    var resultTruncated = sortedGroups.count > maxGroups
    let returnedGroups = sortedGroups.prefix(maxGroups).map { group -> JSONValue in
      let returnedFiles = Array(group.files.prefix(maxFilesPerGroup))
      if returnedFiles.count < group.files.count {
        resultTruncated = true
      }
      returnedDuplicateFileCount += returnedFiles.count
      return group.json(maxFiles: maxFilesPerGroup)
    }

    return .object([
      "operation": .string("file.duplicates"),
      "path": .string(root.path),
      "workspace_relative_path": .string(workspaceRelativePath(root)),
      "include_hidden": .bool(includeHidden),
      "min_size_bytes": .number(Double(minSizeBytes)),
      "max_depth": .number(Double(maxDepth)),
      "max_entries": .number(Double(maxEntries)),
      "max_hash_files": .number(Double(maxHashFiles)),
      "max_hash_file_bytes": .number(Double(maxHashFileBytes)),
      "max_groups": .number(Double(maxGroups)),
      "max_files_per_group": .number(Double(maxFilesPerGroup)),
      "scanned_entries": .number(Double(scannedEntries)),
      "scanned_file_count": .number(Double(scannedFileCount)),
      "candidate_file_count": .number(Double(candidates.count)),
      "candidate_size_bucket_count": .number(Double(sizeBuckets.count)),
      "skipped_small_file_count": .number(Double(skippedSmallFileCount)),
      "skipped_large_file_count": .number(Double(skippedLargeFileCount)),
      "hashed_file_count": .number(Double(hashedFileCount)),
      "hashed_size_bucket_count": .number(Double(hashedSizeBucketCount)),
      "hash_bytes_read": .number(Double(hashBytesRead)),
      "hash_skipped_file_count": .number(Double(hashSkippedFileCount)),
      "hash_skipped_size_bucket_count": .number(Double(hashSkippedSizeBucketCount)),
      "duplicate_group_count": .number(Double(duplicateGroupCount)),
      "returned_group_count": .number(Double(returnedGroups.count)),
      "duplicate_file_count": .number(Double(duplicateFileCount)),
      "returned_duplicate_file_count": .number(Double(returnedDuplicateFileCount)),
      "duplicate_bytes": .number(Double(duplicateBytes)),
      "redundant_bytes_if_one_kept_per_group": .number(Double(redundantBytes)),
      "scan_truncated": .bool(scanTruncated),
      "result_truncated": .bool(resultTruncated),
      "truncated": .bool(scanTruncated || resultTruncated),
      "groups": .array(returnedGroups),
    ])
  }

  private func listArchive(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let maxEntries = optionalInt("max_entries", in: object) ?? 1_000
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 100_000)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    let archive = try archiveListCommand(for: url)
    let result = try commandRunner.run(
      executable: archive.executable,
      arguments: archive.arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )

    let allEntries = result.stdout.split(separator: "\n", omittingEmptySubsequences: true)
      .map(String.init)
    let entries = allEntries.prefix(maxEntries).map { entry -> JSONValue in
      .object([
        "path": .string(entry),
        "is_directory": .bool(entry.hasSuffix("/")),
      ])
    }

    return .object([
      "operation": .string("archive.list"),
      "archive": .object([
        "path": .string(url.path),
        "workspace_relative_path": .string(info.workspaceRelativePath),
        "format": .string(archive.format),
      ]),
      "argv": .array(archive.arguments.map(JSONValue.string)),
      "max_entries": .number(Double(maxEntries)),
      "entry_count": .number(Double(entries.count)),
      "truncated": .bool(result.stdoutTruncated || allEntries.count > entries.count),
      "entries": .array(Array(entries)),
      "result": .object([
        "executable": .string(result.executable),
        "arguments": .array(result.arguments.map(JSONValue.string)),
        "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
        "timed_out": .bool(result.timedOut),
        "stderr": .string(result.stderr),
        "stderr_truncated": .bool(result.stderrTruncated),
        "stdout_truncated": .bool(result.stdoutTruncated),
      ]),
    ])
  }

  private func readArchiveFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let entry = try requiredString("entry", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    let timeout = optionalInt("timeout_ms", in: object) ?? 10_000
    let encoding = try optionalString("encoding", in: object) ?? "utf8"
    guard encoding == "utf8" || encoding == "base64" || encoding == "auto" else {
      throw GatewayToolError.invalidArguments("encoding must be utf8, base64, or auto.")
    }
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)

    let archiveURL = try resolvedWorkspaceURL(path)
    let archiveInfo = try fileInfo(url: archiveURL)
    guard archiveInfo.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let normalizedEntry = try normalizedReadableArchiveEntryPath(entry)
    let archive = try archiveListCommand(for: archiveURL)
    let readCommand = try archiveReadFileCommand(
      archive: archive,
      archiveURL: archiveURL,
      entry: normalizedEntry
    )
    let result = try commandRunner.runData(
      executable: readCommand.executable,
      arguments: readCommand.arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxBytes
    )
    try requireSuccessfulArchiveRead(result)
    let validUTF8 = String(data: result.stdout, encoding: .utf8) != nil
    let resolvedEncoding: String
    let content: String
    switch encoding {
    case "utf8":
      guard let text = String(data: result.stdout, encoding: .utf8) else {
        throw GatewayToolError.invalidArguments(
          "archive.read_file member is not valid UTF-8; use encoding=base64 or encoding=auto.")
      }
      resolvedEncoding = "utf8"
      content = text
    case "base64":
      resolvedEncoding = "base64"
      content = result.stdout.base64EncodedString()
    case "auto":
      if let text = String(data: result.stdout, encoding: .utf8) {
        resolvedEncoding = "utf8"
        content = text
      } else {
        resolvedEncoding = "base64"
        content = result.stdout.base64EncodedString()
      }
    default:
      throw GatewayToolError.invalidArguments("encoding must be utf8, base64, or auto.")
    }

    return .object([
      "operation": .string("archive.read_file"),
      "archive": .object([
        "path": .string(archiveURL.path),
        "workspace_relative_path": .string(archiveInfo.workspaceRelativePath),
        "format": .string(archive.format),
      ]),
      "entry": .object([
        "requested_path": .string(entry),
        "normalized_path": .string(normalizedEntry),
      ]),
      "argv": .array(readCommand.arguments.map(JSONValue.string)),
      "requested_encoding": .string(encoding),
      "encoding": .string(resolvedEncoding),
      "valid_utf8": .bool(validUTF8),
      "content": .string(content),
      "bytes_read": .number(Double(result.stdout.count)),
      "max_bytes": .number(Double(maxBytes)),
      "content_truncated": .bool(result.stdoutTruncated),
      "truncated": .bool(result.stdoutTruncated),
      "result": .object([
        "executable": .string(result.executable),
        "arguments": .array(result.arguments.map(JSONValue.string)),
        "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
        "timed_out": .bool(result.timedOut),
        "stderr": .string(result.stderrString),
        "stderr_truncated": .bool(result.stderrTruncated),
        "stdout_truncated": .bool(result.stdoutTruncated),
      ]),
    ])
  }

  private func extractArchive(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let destinationPath = try requiredString("destination", in: object)
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmExtract = try optionalBool("confirm_extract", in: object) ?? false
    guard dryRun || confirmExtract else {
      throw GatewayToolError.invalidArguments(
        "archive.extract requires confirm_extract=true when dry_run is false.")
    }

    let maxEntries = optionalInt("max_entries", in: object) ?? 100_000
    let maxPreviewEntries = optionalInt("max_preview_entries", in: object) ?? 100
    let timeout = optionalInt("timeout_ms", in: object) ?? 30_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 100_000)
    try validateBoundedNonNegative(
      maxPreviewEntries,
      name: "max_preview_entries",
      upperBound: 5_000
    )
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let archiveURL = try resolvedWorkspaceURL(path)
    let archiveInfo = try fileInfo(url: archiveURL)
    guard archiveInfo.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }
    let destinationURL = try resolvedWorkspaceURL(destinationPath)
    let fileManager = FileManager.default
    var destinationIsDirectory = ObjCBool(false)
    let destinationExists = fileManager.fileExists(
      atPath: destinationURL.path,
      isDirectory: &destinationIsDirectory
    )
    if destinationExists {
      guard destinationIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments(
          "Destination exists and is not a directory: \(destinationPath)")
      }
    } else if !createDirectories {
      throw GatewayToolError.invalidArguments(
        "Destination directory does not exist; set create_directories=true to create it.")
    }

    let archive = try archiveListCommand(for: archiveURL)
    let listResult = try commandRunner.run(
      executable: archive.executable,
      arguments: archive.arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    try requireSuccessfulArchivePreflight(listResult, operation: "archive list")
    let rawEntries = listResult.stdout.split(separator: "\n", omittingEmptySubsequences: true)
      .map(String.init)
    guard rawEntries.count <= maxEntries else {
      throw GatewayToolError.invalidArguments(
        "archive contains more than max_entries entries; increase max_entries to validate extraction."
      )
    }
    let linkEntries = try archiveLinkEntries(
      archiveURL: archiveURL,
      archive: archive,
      timeout: timeout,
      maxOutputBytes: maxOutputBytes
    )
    guard linkEntries.isEmpty else {
      throw GatewayToolError.invalidArguments(
        "archive.extract refuses archives containing link entries: \(linkEntries.prefix(5).joined(separator: ", "))"
      )
    }

    let entries = try validateArchiveEntries(
      rawEntries,
      destination: destinationURL,
      overwrite: overwrite
    )
    let previewEntries = entries.prefix(maxPreviewEntries).map(\.json)
    let extractCommand = try archiveExtractCommand(
      archive: archive,
      archiveURL: archiveURL,
      destinationURL: destinationURL,
      overwrite: overwrite
    )

    var result: JSONValue = .null
    if !dryRun {
      if !destinationExists {
        try fileManager.createDirectory(
          at: destinationURL,
          withIntermediateDirectories: true
        )
      }
      let commandResult = try commandRunner.run(
        executable: extractCommand.executable,
        arguments: extractCommand.arguments,
        workingDirectory: configuration.workspaceDirectory,
        environment: [:],
        timeoutMilliseconds: timeout,
        maxOutputBytes: maxOutputBytes
      )
      result = commandResult.json
    }

    return .object([
      "operation": .string("archive.extract"),
      "archive": .object([
        "path": .string(archiveURL.path),
        "workspace_relative_path": .string(archiveInfo.workspaceRelativePath),
        "format": .string(archive.format),
      ]),
      "destination": .object([
        "path": .string(destinationURL.path),
        "workspace_relative_path": .string(workspaceRelativePath(destinationURL)),
        "exists": .bool(destinationExists),
        "would_create": .bool(!destinationExists && createDirectories),
      ]),
      "argv": .array(extractCommand.arguments.map(JSONValue.string)),
      "confirm_extract": .bool(confirmExtract),
      "create_directories": .bool(createDirectories),
      "dry_run": .bool(dryRun),
      "entry_count": .number(Double(entries.count)),
      "entries": .array(Array(previewEntries)),
      "entries_truncated": .bool(entries.count > previewEntries.count),
      "format": .string(archive.format),
      "link_entry_count": .number(Double(linkEntries.count)),
      "max_entries": .number(Double(maxEntries)),
      "max_preview_entries": .number(Double(maxPreviewEntries)),
      "overwrite": .bool(overwrite),
      "result": result,
      "would_extract": .bool(true),
    ])
  }

  private func createArchive(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let sourcePaths = try requiredStringArray("sources", in: object)
    guard !sourcePaths.isEmpty else {
      throw GatewayToolError.invalidArguments("sources must not be empty.")
    }
    let requestedFormat = try optionalString("format", in: object)
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmCreate = try optionalBool("confirm_create", in: object) ?? false
    guard dryRun || confirmCreate else {
      throw GatewayToolError.invalidArguments(
        "archive.create requires confirm_create=true when dry_run is false.")
    }

    let maxEntries = optionalInt("max_entries", in: object) ?? 100_000
    let maxPreviewEntries = optionalInt("max_preview_entries", in: object) ?? 100
    let timeout = optionalInt("timeout_ms", in: object) ?? 30_000
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxEntries, name: "max_entries", upperBound: 100_000)
    try validateBoundedNonNegative(
      maxPreviewEntries,
      name: "max_preview_entries",
      upperBound: 5_000
    )
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let archiveURL = try resolvedWorkspaceURLPreservingFinalSymlink(path)
    let archiveParentURL = archiveURL.deletingLastPathComponent()
    let fileManager = FileManager.default
    var parentIsDirectory = ObjCBool(false)
    let parentExists = fileManager.fileExists(
      atPath: archiveParentURL.path,
      isDirectory: &parentIsDirectory
    )
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Archive parent is not a directory: \(path)")
      }
    } else if !createDirectories {
      throw GatewayToolError.invalidArguments(
        "Archive parent directory does not exist; set create_directories=true to create it.")
    }

    var archiveIsDirectory = ObjCBool(false)
    let archiveExists = fileManager.fileExists(
      atPath: archiveURL.path,
      isDirectory: &archiveIsDirectory
    )
    if archiveExists {
      let archiveInfo = try fileInfo(url: archiveURL)
      guard !archiveInfo.isSymlink else {
        throw GatewayToolError.invalidArguments("Archive output path is a symlink: \(path)")
      }
      guard !archiveIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Archive output path is a directory: \(path)")
      }
      guard overwrite else {
        throw GatewayToolError.invalidArguments(
          "Archive output already exists; set overwrite=true to replace it.")
      }
    }

    let sourceSnapshot = try validateArchiveCreateSources(
      sourcePaths,
      archiveURL: archiveURL,
      maxEntries: maxEntries,
      maxPreviewEntries: maxPreviewEntries
    )
    let createCommand = try archiveCreateCommand(
      for: archiveURL,
      requestedFormat: requestedFormat,
      sourcePaths: sourceSnapshot.argvSourcePaths
    )

    var result: JSONValue = .null
    if !dryRun {
      if !parentExists {
        try fileManager.createDirectory(
          at: archiveParentURL,
          withIntermediateDirectories: true
        )
      }
      if archiveExists && overwrite {
        try fileManager.removeItem(at: archiveURL)
      }
      let commandResult = try commandRunner.run(
        executable: createCommand.executable,
        arguments: createCommand.arguments,
        workingDirectory: configuration.workspaceDirectory,
        environment: [:],
        timeoutMilliseconds: timeout,
        maxOutputBytes: maxOutputBytes
      )
      result = commandResult.json
    }

    return .object([
      "operation": .string("archive.create"),
      "archive": .object([
        "path": .string(archiveURL.path),
        "workspace_relative_path": .string(workspaceRelativePathPreservingSymlinks(archiveURL)),
        "format": .string(createCommand.format),
        "exists": .bool(archiveExists),
        "would_create_parent_directories": .bool(!parentExists && createDirectories),
        "would_overwrite": .bool(archiveExists && overwrite),
      ]),
      "argv": .array(createCommand.arguments.map(JSONValue.string)),
      "confirm_create": .bool(confirmCreate),
      "create_directories": .bool(createDirectories),
      "dry_run": .bool(dryRun),
      "entry_count": .number(Double(sourceSnapshot.entryCount)),
      "entries": .array(sourceSnapshot.previewEntries.map(\.json)),
      "entries_truncated": .bool(sourceSnapshot.entryCount > sourceSnapshot.previewEntries.count),
      "format": .string(createCommand.format),
      "max_entries": .number(Double(maxEntries)),
      "max_preview_entries": .number(Double(maxPreviewEntries)),
      "overwrite": .bool(overwrite),
      "result": result,
      "source_count": .number(Double(sourceSnapshot.sources.count)),
      "sources": .array(sourceSnapshot.sources.map(\.json)),
      "would_create": .bool(true),
    ])
  }

  private func downloadFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let urlString = try requiredString("url", in: object)
    let path = try requiredString("path", in: object)
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmDownload = try optionalBool("confirm_download", in: object) ?? false
    guard dryRun || confirmDownload else {
      throw GatewayToolError.invalidArguments(
        "file.download requires confirm_download=true when dry_run is false.")
    }

    let followRedirects = try optionalBool("follow_redirects", in: object) ?? false
    let maxRedirects = optionalInt("max_redirects", in: object) ?? 5
    let connectTimeoutSeconds = optionalInt("connect_timeout_seconds", in: object) ?? 5
    let timeout = optionalInt("timeout_ms", in: object) ?? 30_000
    let maxDownloadBytes = optionalInt("max_download_bytes", in: object) ?? 10_485_760
    let maxOutputBytes =
      optionalInt("max_output_bytes", in: object)
      ?? min(configuration.policy.maxOutputBytes, 16_384)
    let validatedURL = try validateHTTPCheckURL(urlString)
    try validateBoundedPositive(maxRedirects, name: "max_redirects", upperBound: 20)
    try validateBoundedPositive(
      connectTimeoutSeconds, name: "connect_timeout_seconds", upperBound: 60)
    try validateBoundedPositive(timeout, name: "timeout_ms", upperBound: 600_000)
    try validateBoundedPositive(
      maxDownloadBytes, name: "max_download_bytes", upperBound: 104_857_600)
    try validateBoundedPositive(maxOutputBytes, name: "max_output_bytes", upperBound: 20_971_520)

    let destinationURL = try resolvedWorkspaceURLPreservingFinalSymlink(path)
    let parentURL = destinationURL.deletingLastPathComponent()
    let fileManager = FileManager.default
    var parentIsDirectory = ObjCBool(false)
    let parentExists = fileManager.fileExists(
      atPath: parentURL.path, isDirectory: &parentIsDirectory)
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Download parent is not a directory: \(path)")
      }
    } else if !createDirectories {
      throw GatewayToolError.invalidArguments(
        "Download parent directory does not exist; set create_directories=true to create it.")
    }

    var destinationIsDirectory = ObjCBool(false)
    let destinationExists = fileManager.fileExists(
      atPath: destinationURL.path,
      isDirectory: &destinationIsDirectory
    )
    if destinationExists {
      let destinationInfo = try fileInfo(url: destinationURL)
      guard !destinationInfo.isSymlink else {
        throw GatewayToolError.invalidArguments("Download destination is a symlink: \(path)")
      }
      guard !destinationIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Download destination is a directory: \(path)")
      }
      guard overwrite else {
        throw GatewayToolError.invalidArguments(
          "Download destination already exists; set overwrite=true to replace it.")
      }
    }

    let tempURL = parentURL.appendingPathComponent(
      ".\(destinationURL.lastPathComponent).computer-mcp-download.tmp"
    )
    if fileManager.fileExists(atPath: tempURL.path) {
      throw GatewayToolError.invalidArguments(
        "Temporary download path already exists: \(workspaceRelativePathPreservingSymlinks(tempURL))"
      )
    }

    let marker = "__COMPUTER_MCP_FILE_DOWNLOAD_META__"
    var arguments = [
      "--fail",
      "--silent",
      "--show-error",
      "--max-time",
      "\(max(1, timeout / 1000))",
      "--connect-timeout",
      "\(connectTimeoutSeconds)",
      "--max-filesize",
      "\(maxDownloadBytes)",
    ]
    if followRedirects {
      arguments += ["--location", "--max-redirs", "\(maxRedirects)"]
    }
    arguments += [
      "--output",
      tempURL.path,
      "--write-out",
      "\n\(marker)\nhttp_code=%{http_code}\nurl_effective=%{url_effective}\ncontent_type=%{content_type}\nredirect_url=%{redirect_url}\ntime_total=%{time_total}\nsize_download=%{size_download}\n",
      validatedURL.absoluteString,
    ]

    var result: JSONValue = .null
    var http: HTTPCheckOutput?
    var downloaded = false
    var downloadedFile: JSONValue = .null
    var downloadedSizeBytes: Int64?

    if !dryRun {
      if !parentExists {
        try fileManager.createDirectory(at: parentURL, withIntermediateDirectories: true)
      }
      let commandResult = try commandRunner.run(
        executable: "/usr/bin/curl",
        arguments: arguments,
        workingDirectory: configuration.workspaceDirectory,
        environment: [:],
        timeoutMilliseconds: timeout,
        maxOutputBytes: maxOutputBytes
      )
      result = networkCommandSummary(commandResult)
      let parsed = parseHTTPCheckOutput(
        commandResult.stdout,
        marker: marker,
        includeBody: false,
        maxBodyBytes: 0,
        stdoutTruncated: commandResult.stdoutTruncated
      )
      http = parsed

      if commandResult.exitCode == 0 && !commandResult.timedOut {
        do {
          let tempInfo = try fileInfo(url: tempURL)
          guard !tempInfo.isSymlink, tempInfo.type == "file" else {
            try? fileManager.removeItem(at: tempURL)
            throw GatewayToolError.executionFailed("Download temp path is not a regular file.")
          }
          let size = tempInfo.size ?? 0
          guard size <= Int64(maxDownloadBytes) else {
            try? fileManager.removeItem(at: tempURL)
            throw GatewayToolError.executionFailed(
              "Downloaded file exceeds max_download_bytes.")
          }
          if destinationExists && overwrite {
            try fileManager.removeItem(at: destinationURL)
          }
          try fileManager.moveItem(at: tempURL, to: destinationURL)
          let finalInfo = try fileInfo(url: destinationURL)
          downloaded = true
          downloadedSizeBytes = finalInfo.size
          downloadedFile = finalInfo.json
        } catch {
          try? fileManager.removeItem(at: tempURL)
          throw error
        }
      } else {
        try? fileManager.removeItem(at: tempURL)
      }
    }

    return .object([
      "operation": .string("file.download"),
      "url": .string(validatedURL.absoluteString),
      "scheme": .string(validatedURL.scheme ?? ""),
      "host": .string(validatedURL.host ?? ""),
      "destination": .object([
        "path": .string(destinationURL.path),
        "workspace_relative_path": .string(workspaceRelativePathPreservingSymlinks(destinationURL)),
        "exists": .bool(destinationExists),
        "would_create_parent_directories": .bool(!parentExists && createDirectories),
        "would_overwrite": .bool(destinationExists && overwrite),
      ]),
      "temporary_path": .string(tempURL.path),
      "temporary_workspace_relative_path": .string(
        workspaceRelativePathPreservingSymlinks(tempURL)),
      "argv": .array(arguments.map(JSONValue.string)),
      "confirm_download": .bool(confirmDownload),
      "create_directories": .bool(createDirectories),
      "downloaded": .bool(downloaded),
      "downloaded_file": downloadedFile,
      "downloaded_size_bytes": downloadedSizeBytes.map { .number(Double($0)) } ?? .null,
      "dry_run": .bool(dryRun),
      "follow_redirects": .bool(followRedirects),
      "http_code": http?.httpCode.map { .number(Double($0)) } ?? .null,
      "url_effective": http?.urlEffective.map(JSONValue.string) ?? .null,
      "content_type": http?.contentType.map(JSONValue.string) ?? .null,
      "redirect_url": http?.redirectURL.map(JSONValue.string) ?? .null,
      "time_total_seconds": http?.timeTotal.map { .number($0) } ?? .null,
      "size_download_bytes": http?.sizeDownload.map { .number($0) } ?? .null,
      "max_download_bytes": .number(Double(maxDownloadBytes)),
      "max_output_bytes": .number(Double(maxOutputBytes)),
      "max_redirects": .number(Double(maxRedirects)),
      "overwrite": .bool(overwrite),
      "result": result,
      "would_download": .bool(true),
    ])
  }

  private func writeFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let content = try requiredString("content", in: object)
    let overwrite = try optionalBool("overwrite", in: object) ?? true
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    let url = try resolvedWorkspaceURL(path)
    let parent = url.deletingLastPathComponent()
    let fileManager = FileManager.default

    var parentIsDirectory: ObjCBool = false
    let parentExists = fileManager.fileExists(atPath: parent.path, isDirectory: &parentIsDirectory)
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
      }
    } else {
      guard createDirectories else {
        throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
      }
    }

    if createDirectories && !dryRun {
      try fileManager.createDirectory(
        at: url.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
    }

    var isDirectory: ObjCBool = false
    let existed = fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory)
    if existed {
      guard !isDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Path is a directory: \(path)")
      }
    }

    if !overwrite && existed {
      throw GatewayToolError.invalidArguments("Refusing to overwrite existing file: \(path)")
    }

    let data = Data(content.utf8)
    let existingSizeBytes = try existingFileSizeBytes(url: url, existed: existed)
    if !dryRun {
      try data.write(to: url, options: .atomic)
    }

    var payload: [String: JSONValue] = [
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "dry_run": .bool(dryRun),
      "overwrite": .bool(overwrite),
      "create_directories": .bool(createDirectories),
      "existed": .bool(existed),
      "would_create": .bool(!existed),
      "would_overwrite": .bool(existed),
      "would_create_parent_directories": .bool(!parentExists && createDirectories),
      "bytes_before": .number(Double(existingSizeBytes)),
      "bytes_after": .number(Double(data.count)),
      "bytes_to_write": .number(Double(data.count)),
      "bytes_written": .number(Double(dryRun ? 0 : data.count)),
      "written": .bool(!dryRun),
    ]

    if includePreview {
      let contentPreview = utf8Preview(content, maxBytes: previewMaxBytes)
      payload["preview"] = .object([
        "preview_max_bytes": .number(Double(previewMaxBytes)),
        "content": .string(contentPreview.text),
        "content_truncated": .bool(contentPreview.truncated),
      ])
    }

    return .object(payload)
  }

  private func writeFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let entries = try requiredObjectArray("files", in: object)
    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmWrite = try optionalBool("confirm_write", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    guard dryRun || confirmWrite else {
      throw GatewayToolError.invalidArguments(
        "file.write_files requires confirm_write=true when dry_run is false.")
    }
    guard !entries.isEmpty else {
      throw GatewayToolError.invalidArguments("files must not be empty.")
    }
    guard entries.count <= 50 else {
      throw GatewayToolError.invalidArguments("files must contain at most 50 entries.")
    }

    let fileManager = FileManager.default
    var seenPaths = Set<String>()
    var plans: [FileWritePlan] = []
    var totalBytesToWrite = 0

    for (index, entry) in entries.enumerated() {
      let path = try requiredString("path", in: entry)
      let content = try requiredStringAllowingEmpty("content", in: entry)
      let data = Data(content.utf8)
      guard data.count <= configuration.policy.maxOutputBytes else {
        throw GatewayToolError.invalidArguments(
          "files[\(index)].content exceeds policy.max_output_bytes (\(configuration.policy.maxOutputBytes))."
        )
      }
      let url = try resolvedWorkspaceURL(path)
      guard seenPaths.insert(url.path).inserted else {
        throw GatewayToolError.invalidArguments("Duplicate output path: \(path)")
      }
      let parent = url.deletingLastPathComponent()

      var parentIsDirectory = ObjCBool(false)
      let parentExists = fileManager.fileExists(
        atPath: parent.path,
        isDirectory: &parentIsDirectory
      )
      if parentExists {
        guard parentIsDirectory.boolValue else {
          throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
        }
      } else {
        guard createDirectories else {
          throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
        }
      }

      var isDirectory = ObjCBool(false)
      let existed = fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory)
      if existed {
        guard !isDirectory.boolValue else {
          throw GatewayToolError.invalidArguments("Path is a directory: \(path)")
        }
      }
      if existed && !overwrite {
        throw GatewayToolError.invalidArguments(
          "Refusing to overwrite existing file: \(path)")
      }

      let existingSizeBytes = try existingFileSizeBytes(url: url, existed: existed)
      totalBytesToWrite += data.count
      plans.append(
        FileWritePlan(
          requestedPath: path,
          url: url,
          workspaceRelativePath: workspaceRelativePath(url),
          parent: parent,
          parentExists: parentExists,
          existed: existed,
          existingSizeBytes: existingSizeBytes,
          data: data,
          preview: utf8Preview(content, maxBytes: previewMaxBytes)
        ))
    }

    if !dryRun {
      for plan in plans {
        if createDirectories && !plan.parentExists {
          try fileManager.createDirectory(
            at: plan.parent,
            withIntermediateDirectories: true
          )
        }
        try plan.data.write(to: plan.url, options: .atomic)
      }
    }

    return .object([
      "operation": .string("file.write_files"),
      "dry_run": .bool(dryRun),
      "confirm_write": .bool(confirmWrite),
      "overwrite": .bool(overwrite),
      "create_directories": .bool(createDirectories),
      "requested_count": .number(Double(entries.count)),
      "file_count": .number(Double(plans.count)),
      "total_bytes_to_write": .number(Double(totalBytesToWrite)),
      "total_bytes_written": .number(Double(dryRun ? 0 : totalBytesToWrite)),
      "written": .bool(!dryRun),
      "files": .array(
        plans.map {
          $0.json(
            dryRun: dryRun,
            overwrite: overwrite,
            createDirectories: createDirectories,
            includePreview: includePreview,
            previewMaxBytes: previewMaxBytes
          )
        }),
    ])
  }

  private func appendFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let content = try requiredString("content", in: object)
    let createIfMissing = try optionalBool("create_if_missing", in: object) ?? true
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let appendNewline = try optionalBool("append_newline", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    let url = try resolvedWorkspaceURL(path)
    let parent = url.deletingLastPathComponent()
    let fileManager = FileManager.default

    let finalContent = appendNewline ? "\(content)\n" : content
    let data = Data(finalContent.utf8)
    guard data.count <= configuration.policy.maxOutputBytes else {
      throw GatewayToolError.invalidArguments(
        "content exceeds policy.max_output_bytes (\(configuration.policy.maxOutputBytes)).")
    }

    var parentIsDirectory: ObjCBool = false
    let parentExists = fileManager.fileExists(atPath: parent.path, isDirectory: &parentIsDirectory)
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
      }
    } else {
      guard createDirectories else {
        throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
      }
    }

    if createDirectories && !dryRun {
      try fileManager.createDirectory(
        at: url.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
    }

    var isDirectory: ObjCBool = false
    let existed = fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory)
    if existed {
      guard !isDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Path is a directory: \(path)")
      }
    } else {
      guard createIfMissing else {
        throw GatewayToolError.invalidArguments("Path does not exist: \(path)")
      }
      if !dryRun {
        guard fileManager.createFile(atPath: url.path, contents: Data()) else {
          throw GatewayToolError.executionFailed("Failed to create file: \(path)")
        }
      }
    }

    let sizeBefore: UInt64
    if dryRun {
      sizeBefore = try existingFileSizeBytes(url: url, existed: existed)
    } else {
      let handle = try FileHandle(forWritingTo: url)
      defer {
        try? handle.close()
      }
      sizeBefore = try handle.seekToEnd()
      try handle.write(contentsOf: data)
    }
    let sizeAfter = sizeBefore + UInt64(data.count)

    var payload: [String: JSONValue] = [
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "dry_run": .bool(dryRun),
      "created": .bool(!dryRun && !existed),
      "would_create": .bool(!existed),
      "would_create_parent_directories": .bool(!parentExists && createDirectories),
      "append_newline": .bool(appendNewline),
      "bytes_to_append": .number(Double(data.count)),
      "bytes_appended": .number(Double(dryRun ? 0 : data.count)),
      "size_before_bytes": .number(Double(sizeBefore)),
      "size_after_bytes": .number(Double(sizeAfter)),
      "would_change": .bool(!data.isEmpty),
      "changed": .bool(!dryRun && !data.isEmpty),
    ]

    if includePreview {
      let contentPreview = utf8Preview(finalContent, maxBytes: previewMaxBytes)
      payload["preview"] = .object([
        "preview_max_bytes": .number(Double(previewMaxBytes)),
        "content": .string(contentPreview.text),
        "content_truncated": .bool(contentPreview.truncated),
      ])
    }

    return .object(payload)
  }

  private func existingFileSizeBytes(url: URL, existed: Bool) throws -> UInt64 {
    guard existed else {
      return 0
    }
    let attributes = try FileManager.default.attributesOfItem(atPath: url.path)
    guard let number = attributes[.size] as? NSNumber else {
      return 0
    }
    return number.uint64Value
  }

  private func replaceTextInFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let search = try requiredString("search", in: object)
    let replacement = try requiredStringAllowingEmpty("replacement", in: object)
    let replaceAll = try optionalBool("replace_all", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)
    let expectedReplacements = optionalInt("expected_replacements", in: object)
    if let expectedReplacements {
      try validateBoundedNonNegative(
        expectedReplacements,
        name: "expected_replacements",
        upperBound: 1_000_000
      )
    }

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }
    guard let content = String(data: data, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("File is not valid UTF-8: \(path)")
    }

    let totalMatches = countOccurrences(of: search, in: content)
    let replacements = replaceAll ? totalMatches : min(totalMatches, 1)
    if let expectedReplacements, expectedReplacements != replacements {
      throw GatewayToolError.invalidArguments(
        "Expected \(expectedReplacements) replacements but would perform \(replacements).")
    }

    let updatedContent: String
    if replacements == 0 {
      updatedContent = content
    } else if replaceAll {
      updatedContent = content.replacingOccurrences(of: search, with: replacement)
    } else if let range = content.range(of: search) {
      var copy = content
      copy.replaceSubrange(range, with: replacement)
      updatedContent = copy
    } else {
      updatedContent = content
    }

    let updatedData = Data(updatedContent.utf8)
    let wouldChange = updatedContent != content
    if !dryRun && wouldChange {
      try updatedData.write(to: url, options: .atomic)
    }

    var payload: [String: JSONValue] = [
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "replace_all": .bool(replaceAll),
      "dry_run": .bool(dryRun),
      "total_matches": .number(Double(totalMatches)),
      "replacements": .number(Double(replacements)),
      "would_change": .bool(wouldChange),
      "changed": .bool(!dryRun && wouldChange),
      "bytes_before": .number(Double(data.count)),
      "bytes_after": .number(Double(updatedData.count)),
    ]

    if includePreview {
      let searchPreview = utf8Preview(search, maxBytes: previewMaxBytes)
      let replacementPreview = utf8Preview(replacement, maxBytes: previewMaxBytes)
      payload["preview"] = .object([
        "preview_max_bytes": .number(Double(previewMaxBytes)),
        "search": .string(searchPreview.text),
        "search_truncated": .bool(searchPreview.truncated),
        "replacement": .string(replacementPreview.text),
        "replacement_truncated": .bool(replacementPreview.truncated),
      ])
    }

    return .object(payload)
  }

  private func insertTextInFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let line = optionalInt("line", in: object) ?? 1
    try validateBoundedPositive(line, name: "line", upperBound: 10_000_000)
    let contentToInsert = try requiredString("content", in: object)
    let position = try fileInsertPosition(try optionalString("position", in: object) ?? "before")
    let appendNewline = try optionalBool("append_newline", in: object) ?? true
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    let expectedLine = try optionalString("expected_line", in: object)
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let insertData = Data(contentToInsert.utf8)
    guard insertData.count <= configuration.policy.maxOutputBytes else {
      throw GatewayToolError.invalidArguments(
        "content exceeds policy.max_output_bytes (\(configuration.policy.maxOutputBytes)).")
    }

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }
    guard let content = String(data: data, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("File is not valid UTF-8: \(path)")
    }

    let lineStarts = existingLineStarts(in: content)
    guard lineStarts.indices.contains(line - 1) else {
      throw GatewayToolError.invalidArguments(
        "line must be between 1 and \(max(lineStarts.count, 1)).")
    }
    let targetLine = lineText(at: line, starts: lineStarts, in: content)
    if let expectedLine, expectedLine != targetLine {
      throw GatewayToolError.invalidArguments("expected_line does not match target line.")
    }

    let insertionIndex: String.Index
    switch position {
    case .before:
      insertionIndex = lineStarts[line - 1]
    case .after:
      insertionIndex = line < lineStarts.count ? lineStarts[line] : content.endIndex
    }

    var insertion = contentToInsert
    if appendNewline, !insertion.hasSuffix("\n") {
      insertion += "\n"
    }
    if position == .after, line == lineStarts.count, !content.isEmpty, !content.hasSuffix("\n") {
      insertion = "\n\(insertion)"
    }

    var updatedContent = content
    updatedContent.insert(contentsOf: insertion, at: insertionIndex)
    let updatedData = Data(updatedContent.utf8)
    let wouldChange = updatedContent != content
    if !dryRun && wouldChange {
      try updatedData.write(to: url, options: .atomic)
    }

    var payload: [String: JSONValue] = [
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "line": .number(Double(line)),
      "position": .string(position.rawValue),
      "append_newline": .bool(appendNewline),
      "dry_run": .bool(dryRun),
      "line_count_before": .number(Double(lineStarts.count)),
      "bytes_inserted": .number(Double(Data(insertion.utf8).count)),
      "bytes_before": .number(Double(data.count)),
      "bytes_after": .number(Double(updatedData.count)),
      "would_change": .bool(wouldChange),
      "changed": .bool(!dryRun && wouldChange),
    ]

    if includePreview {
      let targetLinePreview = utf8Preview(targetLine, maxBytes: previewMaxBytes)
      let insertedContentPreview = utf8Preview(insertion, maxBytes: previewMaxBytes)
      payload["preview"] = .object([
        "preview_max_bytes": .number(Double(previewMaxBytes)),
        "target_line": .string(targetLinePreview.text),
        "target_line_truncated": .bool(targetLinePreview.truncated),
        "inserted_content": .string(insertedContentPreview.text),
        "inserted_content_truncated": .bool(insertedContentPreview.truncated),
      ])
    }

    return .object(payload)
  }

  private func replaceLinesInFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    guard let startLine = optionalInt("start_line", in: object) else {
      throw GatewayToolError.invalidArguments("Missing required integer argument: start_line")
    }
    guard let endLine = optionalInt("end_line", in: object) else {
      throw GatewayToolError.invalidArguments("Missing required integer argument: end_line")
    }
    try validateBoundedPositive(startLine, name: "start_line", upperBound: 10_000_000)
    try validateBoundedPositive(endLine, name: "end_line", upperBound: 10_000_000)
    guard endLine >= startLine else {
      throw GatewayToolError.invalidArguments(
        "end_line must be greater than or equal to start_line.")
    }
    let replacementContent = try requiredStringAllowingEmpty("content", in: object)
    let appendNewline = try optionalBool("append_newline", in: object) ?? true
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let includePreview = try optionalBool("include_preview", in: object) ?? dryRun
    let previewMaxBytes = optionalInt("preview_max_bytes", in: object) ?? 8_192
    try validateBoundedPositive(previewMaxBytes, name: "preview_max_bytes", upperBound: 1_048_576)
    let expectedContent: String?
    if let expectedValue = object["expected_content"] {
      guard let value = expectedValue.stringValue else {
        throw GatewayToolError.invalidArguments("expected_content must be a string.")
      }
      expectedContent = value
    } else {
      expectedContent = nil
    }
    let maxBytes = optionalInt("max_bytes", in: object) ?? configuration.policy.maxOutputBytes
    try validateBoundedPositive(maxBytes, name: "max_bytes", upperBound: 20_971_520)

    let replacementData = Data(replacementContent.utf8)
    guard replacementData.count <= configuration.policy.maxOutputBytes else {
      throw GatewayToolError.invalidArguments(
        "content exceeds policy.max_output_bytes (\(configuration.policy.maxOutputBytes)).")
    }

    let url = try resolvedWorkspaceURL(path)
    let info = try fileInfo(url: url)
    guard info.type == "file" else {
      throw GatewayToolError.invalidArguments("Path is not a file: \(path)")
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }
    guard let content = String(data: data, encoding: .utf8) else {
      throw GatewayToolError.invalidArguments("File is not valid UTF-8: \(path)")
    }

    let lineStarts = existingLineStarts(in: content)
    guard !lineStarts.isEmpty else {
      throw GatewayToolError.invalidArguments("File has no replaceable lines: \(path)")
    }
    guard lineStarts.indices.contains(startLine - 1),
      lineStarts.indices.contains(endLine - 1)
    else {
      throw GatewayToolError.invalidArguments(
        "line range must be between 1 and \(lineStarts.count).")
    }

    let rangeStart = lineStarts[startLine - 1]
    let rangeEnd = endLine < lineStarts.count ? lineStarts[endLine] : content.endIndex
    let originalContent = String(content[rangeStart..<rangeEnd])
    if let expectedContent, expectedContent != originalContent {
      throw GatewayToolError.invalidArguments("expected_content does not match selected lines.")
    }

    var replacement = replacementContent
    if appendNewline, !replacement.isEmpty, !replacement.hasSuffix("\n") {
      replacement += "\n"
    }

    var updatedContent = content
    updatedContent.replaceSubrange(rangeStart..<rangeEnd, with: replacement)
    let updatedData = Data(updatedContent.utf8)
    let wouldChange = updatedContent != content
    if !dryRun && wouldChange {
      try updatedData.write(to: url, options: .atomic)
    }

    var payload: [String: JSONValue] = [
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "encoding": .string("utf-8"),
      "start_line": .number(Double(startLine)),
      "end_line": .number(Double(endLine)),
      "append_newline": .bool(appendNewline),
      "dry_run": .bool(dryRun),
      "line_count_before": .number(Double(lineStarts.count)),
      "deleted_line_count": .number(Double(endLine - startLine + 1)),
      "inserted_line_count": .number(Double(existingLineStarts(in: replacement).count)),
      "bytes_replaced": .number(Double(Data(originalContent.utf8).count)),
      "bytes_inserted": .number(Double(Data(replacement.utf8).count)),
      "bytes_before": .number(Double(data.count)),
      "bytes_after": .number(Double(updatedData.count)),
      "would_change": .bool(wouldChange),
      "changed": .bool(!dryRun && wouldChange),
    ]

    if includePreview {
      let selectedPreview = utf8Preview(originalContent, maxBytes: previewMaxBytes)
      let replacementPreview = utf8Preview(replacement, maxBytes: previewMaxBytes)
      payload["preview"] = .object([
        "preview_max_bytes": .number(Double(previewMaxBytes)),
        "selected_content": .string(selectedPreview.text),
        "selected_truncated": .bool(selectedPreview.truncated),
        "replacement_content": .string(replacementPreview.text),
        "replacement_truncated": .bool(replacementPreview.truncated),
      ])
    }

    return .object(payload)
  }

  private func touchFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let createIfMissing = try optionalBool("create_if_missing", in: object) ?? true
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let url = try resolvedWorkspaceURL(path)
    let parent = url.deletingLastPathComponent()
    var parentIsDirectory: ObjCBool = false
    let parentExists = FileManager.default.fileExists(
      atPath: parent.path,
      isDirectory: &parentIsDirectory
    )

    if createDirectories {
      if parentExists && !parentIsDirectory.boolValue {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
      }
      if !dryRun {
        try FileManager.default.createDirectory(
          at: parent,
          withIntermediateDirectories: true
        )
      }
    } else {
      guard parentExists && parentIsDirectory.boolValue
      else {
        throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
      }
    }

    let now = Date()
    var isDirectory: ObjCBool = false
    let existed = FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory)
    if existed {
      guard !isDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Path is a directory: \(path)")
      }
      if !dryRun {
        try FileManager.default.setAttributes([.modificationDate: now], ofItemAtPath: url.path)
      }
    } else {
      guard createIfMissing else {
        throw GatewayToolError.invalidArguments("Path does not exist: \(path)")
      }
      if !dryRun {
        guard
          FileManager.default.createFile(
            atPath: url.path,
            contents: Data(),
            attributes: [.modificationDate: now]
          )
        else {
          throw GatewayToolError.executionFailed("Failed to create file: \(path)")
        }
      }
    }

    var payload: [String: JSONValue] = [
      "operation": .string("file.touch"),
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "dry_run": .bool(dryRun),
      "create_if_missing": .bool(createIfMissing),
      "create_directories": .bool(createDirectories),
      "existed": .bool(existed),
      "created": .bool(!dryRun && !existed),
      "modified": .bool(!dryRun),
      "would_create": .bool(!existed),
      "would_update_modification_time": .bool(existed),
      "would_create_parent_directories": .bool(createDirectories && !parentExists),
    ]
    payload["result"] = dryRun ? .null : try fileInfo(url: url).json
    return .object(payload)
  }

  private func makeDirectory(arguments object: [String: JSONValue]) throws -> JSONValue {
    let path = try requiredString("path", in: object)
    let intermediateDirectories = try optionalBool("intermediate_directories", in: object) ?? true
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let url = try resolvedWorkspaceURL(path)
    var isDirectory: ObjCBool = false

    if FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory) {
      guard isDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Path exists and is not a directory: \(path)")
      }
      return .object([
        "path": .string(url.path),
        "workspace_relative_path": .string(workspaceRelativePath(url)),
        "dry_run": .bool(dryRun),
        "intermediate_directories": .bool(intermediateDirectories),
        "created": .bool(false),
        "would_create": .bool(false),
        "would_create_parent_directories": .bool(false),
      ])
    }

    let parent = url.deletingLastPathComponent()
    var parentIsDirectory: ObjCBool = false
    let parentExists = FileManager.default.fileExists(
      atPath: parent.path,
      isDirectory: &parentIsDirectory
    )
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(path)")
      }
    } else {
      guard intermediateDirectories else {
        throw GatewayToolError.invalidArguments("Parent directory does not exist: \(path)")
      }
    }

    if !dryRun {
      try FileManager.default.createDirectory(
        at: url,
        withIntermediateDirectories: intermediateDirectories
      )
    }
    return .object([
      "path": .string(url.path),
      "workspace_relative_path": .string(workspaceRelativePath(url)),
      "dry_run": .bool(dryRun),
      "intermediate_directories": .bool(intermediateDirectories),
      "created": .bool(!dryRun),
      "would_create": .bool(true),
      "would_create_parent_directories": .bool(!parentExists),
    ])
  }

  private func copyFile(arguments object: [String: JSONValue]) throws -> JSONValue {
    let sourcePath = try requiredString("source", in: object)
    let destinationPath = try requiredString("destination", in: object)
    let overwrite = try optionalBool("overwrite", in: object) ?? false
    let createDirectories = try optionalBool("create_directories", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    let source = try resolvedWorkspaceURL(sourcePath)
    let destination = try resolvedWorkspaceURL(destinationPath)

    guard FileManager.default.fileExists(atPath: source.path) else {
      throw GatewayToolError.invalidArguments("Source does not exist: \(sourcePath)")
    }
    let preparation = try inspectDestinationPreparation(
      destination,
      originalPath: destinationPath,
      overwrite: overwrite,
      createDirectories: createDirectories
    )
    if !dryRun {
      try prepareDestination(
        destination,
        originalPath: destinationPath,
        overwrite: overwrite,
        createDirectories: createDirectories
      )
      try FileManager.default.copyItem(at: source, to: destination)
    }
    return try organizationResult(
      operation: "file.copy",
      source: source,
      destination: destination,
      dryRun: dryRun,
      overwritten: !dryRun && preparation.destinationExists && overwrite,
      wouldOverwrite: preparation.destinationExists && overwrite,
      wouldCreateParentDirectories: preparation.wouldCreateParentDirectories,
      performedKey: "copied",
      wouldPerformKey: "would_copy"
    )
  }

