  private func gitTrackingStatus(arguments object: [String: JSONValue]) throws -> JSONValue {
    let command = try gitCLICommand()
    let args = ["status", "--branch", "--porcelain=v1"]
    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: false
    )
    let branchLine = result.stdout.split(separator: "\n", omittingEmptySubsequences: true)
      .map(String.init)
      .first { $0.hasPrefix("## ") }
    let parsed = parseGitTrackingStatus(branchLine)

    return .object([
      "operation": .string("git.tracking_status"),
      "provider": .string(command.id),
      "argv": .array(args.map(JSONValue.string)),
      "parsed": .bool(parsed != nil),
      "status": parsed?.json ?? .null,
      "result": gitCommandMetadata(result),
    ])
  }

  private func parseGitTrackingStatus(_ branchLine: String?) -> GitTrackingStatusInfo? {
    guard let branchLine, branchLine.hasPrefix("## ") else {
      return nil
    }

    let body = String(branchLine.dropFirst(3))
    if body == "HEAD (no branch)" {
      return GitTrackingStatusInfo(
        branch: nil,
        upstream: nil,
        ahead: nil,
        behind: nil,
        flags: [],
        detached: true,
        unborn: false,
        rawBranchLine: branchLine
      )
    }

    if body.hasPrefix("No commits yet on ") {
      return GitTrackingStatusInfo(
        branch: String(body.dropFirst("No commits yet on ".count)),
        upstream: nil,
        ahead: nil,
        behind: nil,
        flags: [],
        detached: false,
        unborn: true,
        rawBranchLine: branchLine
      )
    }

    let parsedBody = splitGitTrackingStatusBody(body)
    let tracking = splitGitTrackingBranchAndUpstream(parsedBody.base)
    let details = parseGitTrackingDetails(parsedBody.details)

    return GitTrackingStatusInfo(
      branch: tracking.branch,
      upstream: tracking.upstream,
      ahead: tracking.upstream == nil ? nil : details.ahead,
      behind: tracking.upstream == nil ? nil : details.behind,
      flags: details.flags,
      detached: false,
      unborn: false,
      rawBranchLine: branchLine
    )
  }

  private func splitGitTrackingBranchAndUpstream(_ value: String) -> (
    branch: String?, upstream: String?
  ) {
    guard let range = value.range(of: "...") else {
      return (value.isEmpty ? nil : value, nil)
    }
    let branch = String(value[..<range.lowerBound])
    let upstream = String(value[range.upperBound...])
    return (branch.isEmpty ? nil : branch, upstream.isEmpty ? nil : upstream)
  }

  private func splitGitTrackingStatusBody(_ body: String) -> (base: String, details: String?) {
    guard body.hasSuffix("]"), let open = body.lastIndex(of: "[") else {
      return (body, nil)
    }
    let base = String(body[..<open]).trimmingCharacters(in: .whitespaces)
    let detailsStart = body.index(after: open)
    let detailsEnd = body.index(before: body.endIndex)
    return (base, String(body[detailsStart..<detailsEnd]))
  }

  private func parseGitTrackingDetails(_ details: String?) -> (
    ahead: Int, behind: Int, flags: [String]
  ) {
    guard let details, !details.isEmpty else {
      return (0, 0, [])
    }
    var ahead = 0
    var behind = 0
    var flags: [String] = []
    for part in details.split(separator: ",").map({ $0.trimmingCharacters(in: .whitespaces) }) {
      if part.hasPrefix("ahead "), let value = Int(part.dropFirst("ahead ".count)) {
        ahead = value
      } else if part.hasPrefix("behind "), let value = Int(part.dropFirst("behind ".count)) {
        behind = value
      } else if !part.isEmpty {
        flags.append(part)
      }
    }
    return (ahead, behind, flags)
  }

  private func gitCleanPreview(arguments object: [String: JSONValue]) throws -> JSONValue {
    let includeIgnored = try optionalBool("include_ignored", in: object) ?? false
    let ignoredOnly = try optionalBool("ignored_only", in: object) ?? false
    let paths = try optionalGitPaths(in: object)
    let maxResults = optionalInt("max_results", in: object) ?? 200
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 5_000)
    if includeIgnored && ignoredOnly {
      throw GatewayToolError.invalidArguments(
        "include_ignored and ignored_only cannot both be true.")
    }

    var args = ["clean", "--dry-run", "-d"]
    if includeIgnored {
      args.append("-x")
    }
    if ignoredOnly {
      args.append("-X")
    }
    if !paths.isEmpty {
      args.append("--")
      args.append(contentsOf: paths)
    }

    let command = try gitCLICommand()
    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: false
    )
    let rawLines = result.stdout.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .filter { !$0.isEmpty }
    let items = rawLines.map(parseGitCleanPreviewLine)
    let returnedItems = Array(items.prefix(maxResults))
    let returnedRawLines = Array(rawLines.prefix(maxResults))
    let resultTruncated =
      items.count > returnedItems.count || rawLines.count > returnedRawLines.count

    return .object([
      "operation": .string("git.clean_preview"),
      "provider": .string(command.id),
      "argv": .array(args.map(JSONValue.string)),
      "include_ignored": .bool(includeIgnored),
      "ignored_only": .bool(ignoredOnly),
      "paths": .array(paths.map(JSONValue.string)),
      "max_results": .number(Double(maxResults)),
      "item_count": .number(Double(items.count)),
      "returned_item_count": .number(Double(returnedItems.count)),
      "raw_line_count": .number(Double(rawLines.count)),
      "returned_raw_line_count": .number(Double(returnedRawLines.count)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(result.stdoutTruncated),
      "parse_incomplete": .bool(result.stdoutTruncated),
      "truncated": .bool(resultTruncated || result.stdoutTruncated),
      "items": .array(returnedItems.map(\.json)),
      "raw_lines": .array(returnedRawLines.map(JSONValue.string)),
      "result": gitCommandMetadata(result),
    ])
  }

  private func parseGitCleanPreviewLine(_ line: String) -> GitCleanPreviewItem {
    let prefixes = [
      ("Would remove ", "remove"),
      ("Would skip repository ", "skip_repository"),
      ("Would not remove ", "not_remove"),
    ]
    for (prefix, action) in prefixes where line.hasPrefix(prefix) {
      let path = String(line.dropFirst(prefix.count))
      return GitCleanPreviewItem(
        action: action,
        path: path.isEmpty ? nil : path,
        directory: path.hasSuffix("/"),
        rawLine: line
      )
    }
    return GitCleanPreviewItem(action: "other", path: nil, directory: false, rawLine: line)
  }

  private func gitClean(arguments object: [String: JSONValue]) throws -> JSONValue {
    let includeIgnored = try optionalBool("include_ignored", in: object) ?? false
    let ignoredOnly = try optionalBool("ignored_only", in: object) ?? false
    guard !(includeIgnored && ignoredOnly) else {
      throw GatewayToolError.invalidArguments(
        "include_ignored and ignored_only cannot both be true.")
    }

    let paths = try optionalGitPaths(in: object)
    let allPaths = try optionalBool("all_paths", in: object) ?? false
    guard allPaths || !paths.isEmpty else {
      throw GatewayToolError.invalidArguments("git.clean requires paths or all_paths=true.")
    }
    guard !(allPaths && !paths.isEmpty) else {
      throw GatewayToolError.invalidArguments("git.clean cannot combine paths with all_paths=true.")
    }

    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmDelete = try optionalBool("confirm_delete", in: object) ?? false
    guard dryRun || confirmDelete else {
      throw GatewayToolError.invalidArguments(
        "git.clean requires confirm_delete=true when dry_run is false.")
    }

    var args = ["clean"]
    if dryRun {
      args.append("--dry-run")
    } else {
      args.append("-f")
    }
    args.append("-d")
    if includeIgnored {
      args.append("-x")
    }
    if ignoredOnly {
      args.append("-X")
    }
    if !allPaths {
      args.append("--")
      args.append(contentsOf: paths)
    }

    return try gitResult(
      operation: "git.clean",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object),
      extra: [
        "all_paths": .bool(allPaths),
        "confirm_delete": .bool(confirmDelete),
        "dry_run": .bool(dryRun),
        "ignored_only": .bool(ignoredOnly),
        "include_ignored": .bool(includeIgnored),
        "paths": .array(paths.map(JSONValue.string)),
      ]
    )
  }

  private func gitReflog(arguments object: [String: JSONValue]) throws -> JSONValue {
    let limit = optionalInt("limit", in: object) ?? 50
    try validateBoundedPositive(limit, name: "limit", upperBound: 200)
    let maxResults = optionalInt("max_results", in: object) ?? limit
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 200)

    let args = [
      "reflog",
      "show",
      "--date=iso-strict",
      "--pretty=format:%H%x09%h%x09%gd%x09%gs%x09%ad",
      "-n",
      "\(limit)",
    ]
    let command = try gitCLICommand()
    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: false
    )
    let rawLines = result.stdout.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .filter { !$0.isEmpty }
    let entries = rawLines.map(parseGitReflogLine)
    let returnedEntries = Array(entries.prefix(maxResults))
    let returnedRawLines = Array(rawLines.prefix(maxResults))
    let resultTruncated =
      entries.count > returnedEntries.count || rawLines.count > returnedRawLines.count

    return .object([
      "operation": .string("git.reflog"),
      "provider": .string(command.id),
      "argv": .array(args.map(JSONValue.string)),
      "limit": .number(Double(limit)),
      "max_results": .number(Double(maxResults)),
      "entry_count": .number(Double(entries.count)),
      "returned_entry_count": .number(Double(returnedEntries.count)),
      "raw_line_count": .number(Double(rawLines.count)),
      "returned_raw_line_count": .number(Double(returnedRawLines.count)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(result.stdoutTruncated),
      "parse_incomplete": .bool(result.stdoutTruncated),
      "truncated": .bool(resultTruncated || result.stdoutTruncated),
      "entries": .array(returnedEntries.map(\.json)),
      "raw_lines": .array(returnedRawLines.map(JSONValue.string)),
      "result": gitCommandMetadata(result),
    ])
  }

  private func parseGitReflogLine(_ line: String) -> GitReflogEntry {
    let parts = line.split(separator: "\t", maxSplits: 4, omittingEmptySubsequences: false)
      .map(String.init)
    guard parts.count == 5 else {
      return GitReflogEntry(
        commit: nil,
        abbreviatedCommit: nil,
        selector: nil,
        action: nil,
        message: nil,
        committedAt: nil,
        rawLine: line
      )
    }

    let parsedMessage = parseGitReflogSubject(parts[3])
    return GitReflogEntry(
      commit: parts[0].isEmpty ? nil : parts[0],
      abbreviatedCommit: parts[1].isEmpty ? nil : parts[1],
      selector: parts[2].isEmpty ? nil : parts[2],
      action: parsedMessage.action,
      message: parsedMessage.message,
      committedAt: parts[4].isEmpty ? nil : parts[4],
      rawLine: line
    )
  }

  private func parseGitReflogSubject(_ subject: String) -> (action: String?, message: String?) {
    guard let separator = subject.range(of: ": ") else {
      return (subject.isEmpty ? nil : subject, nil)
    }
    let action = String(subject[..<separator.lowerBound])
    let message = String(subject[separator.upperBound...])
    return (action.isEmpty ? nil : action, message.isEmpty ? nil : message)
  }

  private func gitRefs(arguments object: [String: JSONValue]) throws -> JSONValue {
    let includeBranches = try optionalBool("include_branches", in: object) ?? true
    let includeRemotes = try optionalBool("include_remotes", in: object) ?? true
    let includeTags = try optionalBool("include_tags", in: object) ?? false
    guard includeBranches || includeRemotes || includeTags else {
      throw GatewayToolError.invalidArguments(
        "At least one of include_branches, include_remotes, or include_tags must be true.")
    }

    let limit = optionalInt("limit", in: object) ?? 200
    try validateBoundedPositive(limit, name: "limit", upperBound: 1_000)
    let maxResults = optionalInt("max_results", in: object) ?? limit
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 1_000)

    var namespaces: [String] = []
    if includeBranches {
      namespaces.append("refs/heads")
    }
    if includeRemotes {
      namespaces.append("refs/remotes")
    }
    if includeTags {
      namespaces.append("refs/tags")
    }

    var args = [
      "for-each-ref",
      "--sort=-committerdate",
      "--count",
      "\(limit)",
      "--format=%(refname)%09%(refname:short)%09%(objectname)%09%(objectname:short)%09%(objecttype)%09%(committerdate:iso-strict)%09%(subject)",
    ]
    args.append(contentsOf: namespaces)

    let command = try gitCLICommand()
    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: false
    )
    let rawLines = result.stdout.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .filter { !$0.isEmpty }
    let refs = rawLines.map(parseGitRefLine)
    let returnedRefs = Array(refs.prefix(maxResults))
    let returnedRawLines = Array(rawLines.prefix(maxResults))
    let resultTruncated = refs.count > returnedRefs.count || rawLines.count > returnedRawLines.count

    return .object([
      "operation": .string("git.refs"),
      "provider": .string(command.id),
      "argv": .array(args.map(JSONValue.string)),
      "include_branches": .bool(includeBranches),
      "include_remotes": .bool(includeRemotes),
      "include_tags": .bool(includeTags),
      "namespaces": .array(namespaces.map(JSONValue.string)),
      "limit": .number(Double(limit)),
      "max_results": .number(Double(maxResults)),
      "ref_count": .number(Double(refs.count)),
      "returned_ref_count": .number(Double(returnedRefs.count)),
      "raw_line_count": .number(Double(rawLines.count)),
      "returned_raw_line_count": .number(Double(returnedRawLines.count)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(result.stdoutTruncated),
      "parse_incomplete": .bool(result.stdoutTruncated),
      "truncated": .bool(resultTruncated || result.stdoutTruncated),
      "refs": .array(returnedRefs.map(\.json)),
      "raw_lines": .array(returnedRawLines.map(JSONValue.string)),
      "result": gitCommandMetadata(result),
    ])
  }

  private func parseGitRefLine(_ line: String) -> GitRefInfo {
    let parts = line.split(separator: "\t", maxSplits: 6, omittingEmptySubsequences: false)
      .map(String.init)
    guard parts.count == 7 else {
      return GitRefInfo(
        kind: "other",
        refname: nil,
        shortName: nil,
        object: nil,
        abbreviatedObject: nil,
        objectType: nil,
        committerDate: nil,
        subject: nil,
        rawLine: line
      )
    }

    return GitRefInfo(
      kind: gitRefKind(parts[0]),
      refname: parts[0].isEmpty ? nil : parts[0],
      shortName: parts[1].isEmpty ? nil : parts[1],
      object: parts[2].isEmpty ? nil : parts[2],
      abbreviatedObject: parts[3].isEmpty ? nil : parts[3],
      objectType: parts[4].isEmpty ? nil : parts[4],
      committerDate: parts[5].isEmpty ? nil : parts[5],
      subject: parts[6].isEmpty ? nil : parts[6],
      rawLine: line
    )
  }

  private func gitRefKind(_ refname: String) -> String {
    if refname.hasPrefix("refs/heads/") {
      return "local_branch"
    }
    if refname.hasPrefix("refs/remotes/") {
      return "remote_branch"
    }
    if refname.hasPrefix("refs/tags/") {
      return "tag"
    }
    return "other"
  }

  private func gitCompareRefs(arguments object: [String: JSONValue]) throws -> JSONValue {
    let base = try validatedGitRefArgument("base", in: object)
    let head = try validatedGitRefArgument("head", in: object)
    let limit = optionalInt("limit", in: object) ?? 20
    try validateBoundedPositive(limit, name: "limit", upperBound: 200)
    let maxResults = optionalInt("max_results", in: object) ?? limit
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 200)
    let cherryPick = try optionalBool("cherry_pick", in: object) ?? false
    let timeout = optionalInt("timeout_ms", in: object)
    let range = "\(base)...\(head)"

    var countArgs = ["rev-list", "--left-right", "--count"]
    if cherryPick {
      countArgs.append("--cherry-pick")
    }
    countArgs.append(range)

    let mergeBaseArgs = ["merge-base", base, head]

    var logArgs = [
      "log",
      "--left-right",
      "--date=iso-strict",
      "--pretty=format:%m%x09%H%x09%h%x09%ad%x09%an%x09%s",
      "-n",
      "\(limit)",
    ]
    if cherryPick {
      logArgs.insert("--cherry-pick", at: 2)
    }
    logArgs.append(range)

    let command = try gitCLICommand()
    let countResult = try runRegisteredCLI(
      command: command,
      args: countArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    let mergeBaseResult = try runRegisteredCLI(
      command: command,
      args: mergeBaseArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    let logResult = try runRegisteredCLI(
      command: command,
      args: logArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )

    let counts = parseGitCompareCounts(countResult.stdout)
    let rawLines = logResult.stdout.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .filter { !$0.isEmpty }
    let commits = rawLines.map(parseGitCompareCommitLine)
    let returnedCommits = Array(commits.prefix(maxResults))
    let returnedRawLines = Array(rawLines.prefix(maxResults))
    let resultTruncated =
      commits.count > returnedCommits.count || rawLines.count > returnedRawLines.count
    let mergeBase = mergeBaseResult.exitCode == 0 ? firstNonEmptyLine(mergeBaseResult.stdout) : nil
    let parseIncomplete =
      countResult.stdoutTruncated || mergeBaseResult.stdoutTruncated || logResult.stdoutTruncated
      || counts == nil

    return .object([
      "operation": .string("git.compare_refs"),
      "provider": .string(command.id),
      "base": .string(base),
      "head": .string(head),
      "range": .string(range),
      "cherry_pick": .bool(cherryPick),
      "limit": .number(Double(limit)),
      "max_results": .number(Double(maxResults)),
      "argv": .object([
        "counts": .array(countArgs.map(JSONValue.string)),
        "merge_base": .array(mergeBaseArgs.map(JSONValue.string)),
        "commits": .array(logArgs.map(JSONValue.string)),
      ]),
      "counts": counts?.json ?? .null,
      "base_only_count": counts.map { .number(Double($0.baseOnly)) } ?? .null,
      "head_only_count": counts.map { .number(Double($0.headOnly)) } ?? .null,
      "head_ahead": counts.map { .number(Double($0.headOnly)) } ?? .null,
      "head_behind": counts.map { .number(Double($0.baseOnly)) } ?? .null,
      "merge_base": mergeBase.map(JSONValue.string) ?? .null,
      "has_merge_base": .bool(mergeBase != nil),
      "commit_count": .number(Double(commits.count)),
      "returned_commit_count": .number(Double(returnedCommits.count)),
      "raw_line_count": .number(Double(rawLines.count)),
      "returned_raw_line_count": .number(Double(returnedRawLines.count)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(
        countResult.stdoutTruncated || mergeBaseResult.stdoutTruncated || logResult.stdoutTruncated
      ),
      "parse_incomplete": .bool(parseIncomplete),
      "truncated": .bool(resultTruncated || parseIncomplete),
      "commits": .array(returnedCommits.map(\.json)),
      "raw_lines": .array(returnedRawLines.map(JSONValue.string)),
      "results": .object([
        "counts": gitCommandMetadata(countResult),
        "merge_base": gitCommandMetadata(mergeBaseResult),
        "commits": gitCommandMetadata(logResult),
      ]),
    ])
  }

  private func gitResolveRef(arguments object: [String: JSONValue]) throws -> JSONValue {
    let ref = try validatedGitRefArgument("ref", in: object)
    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let objectSpec = "\(ref)^{object}"
    let revParseArgs = ["rev-parse", "--verify", objectSpec]
    let revParseResult = try runRegisteredCLI(
      command: command,
      args: revParseArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !revParseResult.timedOut else {
      throw GatewayToolError.invalidArguments("git.resolve_ref timed out while resolving ref.")
    }
    guard revParseResult.exitCode == 0, let objectID = firstNonEmptyLine(revParseResult.stdout)
    else {
      throw GatewayToolError.invalidArguments("git.resolve_ref failed for the supplied ref.")
    }

    let typeArgs = ["cat-file", "-t", objectID]
    let typeResult = try runRegisteredCLI(
      command: command,
      args: typeArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !typeResult.timedOut else {
      throw GatewayToolError.invalidArguments(
        "git.resolve_ref timed out while reading object type.")
    }
    guard typeResult.exitCode == 0, let objectType = firstNonEmptyLine(typeResult.stdout) else {
      throw GatewayToolError.invalidArguments("git.resolve_ref failed while reading object type.")
    }

    return .object([
      "operation": .string("git.resolve_ref"),
      "provider": .string(command.id),
      "ref": .string(ref),
      "object_spec": .string(objectSpec),
      "object": .string(objectID),
      "object_type": .string(objectType),
      "argv": .object([
        "resolve": .array(revParseArgs.map(JSONValue.string)),
        "type": .array(typeArgs.map(JSONValue.string)),
      ]),
      "results": .object([
        "resolve": gitCommandMetadata(revParseResult),
        "type": gitCommandMetadata(typeResult),
      ]),
    ])
  }

  private func gitMergeBase(arguments object: [String: JSONValue]) throws -> JSONValue {
    let rawRefs = try requiredStringArray("refs", in: object)
    guard rawRefs.count >= 2 else {
      throw GatewayToolError.invalidArguments("refs must contain at least 2 values.")
    }
    guard rawRefs.count <= 16 else {
      throw GatewayToolError.invalidArguments("refs must contain at most 16 values.")
    }

    var refs: [String] = []
    for (index, ref) in rawRefs.enumerated() {
      guard !ref.isEmpty else {
        throw GatewayToolError.invalidArguments("refs[\(index)] must not be empty.")
      }
      refs.append(try validateGitRefToken(ref, name: "refs[\(index)]"))
    }

    let all = try optionalBool("all", in: object) ?? false
    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    var args = ["merge-base"]
    if all {
      args.append("--all")
    }
    args.append(contentsOf: refs)

    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !result.timedOut else {
      throw GatewayToolError.invalidArguments("git.merge_base timed out.")
    }
    guard result.exitCode == 0 || result.exitCode == 1 else {
      throw GatewayToolError.invalidArguments("git.merge_base failed for the supplied refs.")
    }

    let mergeBases =
      result.exitCode == 0
      ? result.stdout.split(separator: "\n", omittingEmptySubsequences: false)
        .map(String.init)
        .filter { !$0.isEmpty }
      : []

    return .object([
      "operation": .string("git.merge_base"),
      "provider": .string(command.id),
      "refs": .array(refs.map(JSONValue.string)),
      "all": .bool(all),
      "argv": .array(args.map(JSONValue.string)),
      "merge_bases": .array(mergeBases.map(JSONValue.string)),
      "merge_base": mergeBases.first.map(JSONValue.string) ?? .null,
      "merge_base_count": .number(Double(mergeBases.count)),
      "has_merge_base": .bool(!mergeBases.isEmpty),
      "result": gitCommandMetadata(result),
    ])
  }

  private func gitIsAncestor(arguments object: [String: JSONValue]) throws -> JSONValue {
    let ancestor = try validatedGitRefArgument("ancestor", in: object)
    let descendant = try validatedGitRefArgument("descendant", in: object)
    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let args = ["merge-base", "--is-ancestor", ancestor, descendant]
    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !result.timedOut else {
      throw GatewayToolError.invalidArguments("git.is_ancestor timed out.")
    }
    guard result.exitCode == 0 || result.exitCode == 1 else {
      throw GatewayToolError.invalidArguments("git.is_ancestor failed for the supplied refs.")
    }

    return .object([
      "operation": .string("git.is_ancestor"),
      "provider": .string(command.id),
      "ancestor": .string(ancestor),
      "descendant": .string(descendant),
      "argv": .array(args.map(JSONValue.string)),
      "is_ancestor": .bool(result.exitCode == 0),
      "result": result.json,
    ])
  }

  private func validatedGitRefArgument(_ name: String, in object: [String: JSONValue]) throws
    -> String
  {
    let ref = try requiredString(name, in: object)
    return try validateGitRefToken(ref, name: name)
  }

  private func optionalValidatedGitRefArgument(_ name: String, in object: [String: JSONValue])
    throws
    -> String?
  {
    guard let ref = try optionalString(name, in: object) else {
      return nil
    }
    return try validateGitRefToken(ref, name: name)
  }

  private func validateGitRefToken(_ ref: String, name: String) throws -> String {
    guard ref.utf8.count <= 256 else {
      throw GatewayToolError.invalidArguments("\(name) must be 256 bytes or fewer.")
    }
    guard !ref.hasPrefix("-") else {
      throw GatewayToolError.invalidArguments("\(name) must not start with '-'.")
    }
    guard !ref.hasPrefix("/"), !ref.hasSuffix("/") else {
      throw GatewayToolError.invalidArguments("\(name) must not start or end with '/'.")
    }
    let forbiddenSubstrings = ["..", "@{", "//", ".lock"]
    for substring in forbiddenSubstrings where ref.contains(substring) {
      throw GatewayToolError.invalidArguments(
        "\(name) contains unsupported Git ref syntax: \(substring)")
    }
    let allowedPunctuation = Set("._/@+-")
    for scalar in ref.unicodeScalars {
      let isAlphaNumeric =
        (scalar.value >= 48 && scalar.value <= 57)
        || (scalar.value >= 65 && scalar.value <= 90)
        || (scalar.value >= 97 && scalar.value <= 122)
      let isAllowedPunctuation = allowedPunctuation.contains(Character(scalar))
      guard isAlphaNumeric || isAllowedPunctuation else {
        throw GatewayToolError.invalidArguments(
          "\(name) may only contain ASCII letters, digits, '.', '_', '/', '@', '+', or '-'.")
      }
    }
    return ref
  }

  private func validatedGitBranchNameArgument(_ name: String, in object: [String: JSONValue]) throws
    -> String
  {
    let branch = try requiredString(name, in: object)
    _ = try validateGitRefToken(branch, name: name)
    guard branch != "HEAD" else {
      throw GatewayToolError.invalidArguments("\(name) must not be HEAD.")
    }
    guard !branch.hasPrefix("refs/") else {
      throw GatewayToolError.invalidArguments("\(name) must be a branch name, not a full ref.")
    }
    guard !branch.contains("@") else {
      throw GatewayToolError.invalidArguments("\(name) must not contain '@'.")
    }
    return branch
  }

  private func validatedGitTagNameArgument(_ name: String, in object: [String: JSONValue]) throws
    -> String
  {
    let tag = try requiredString(name, in: object)
    _ = try validateGitRefToken(tag, name: name)
    guard tag != "HEAD" else {
      throw GatewayToolError.invalidArguments("\(name) must not be HEAD.")
    }
    guard !tag.hasPrefix("refs/") else {
      throw GatewayToolError.invalidArguments("\(name) must be a tag name, not a full ref.")
    }
    guard !tag.contains("@") else {
      throw GatewayToolError.invalidArguments("\(name) must not contain '@'.")
    }
    return tag
  }

  private func optionalGitStashRef(in object: [String: JSONValue]) throws -> String {
    let stash = try optionalString("stash", in: object) ?? "stash@{0}"
    guard stash.utf8.count <= 64 else {
      throw GatewayToolError.invalidArguments("stash must be 64 bytes or fewer.")
    }
    guard stash.hasPrefix("stash@{"), stash.hasSuffix("}") else {
      throw GatewayToolError.invalidArguments("stash must use stash@{N} syntax.")
    }

    let start = stash.index(stash.startIndex, offsetBy: "stash@{".count)
    let digits = stash[start..<stash.index(before: stash.endIndex)]
    guard !digits.isEmpty else {
      throw GatewayToolError.invalidArguments("stash index must not be empty.")
    }
    for scalar in digits.unicodeScalars {
      guard scalar.value >= 48 && scalar.value <= 57 else {
        throw GatewayToolError.invalidArguments("stash index must be a non-negative integer.")
      }
    }
    guard Int(String(digits)) != nil else {
      throw GatewayToolError.invalidArguments("stash index is too large.")
    }
    return stash
  }

  private func validateGitGrepQuery(_ query: String) throws {
    guard !query.isEmpty else {
      throw GatewayToolError.invalidArguments("query must not be empty.")
    }
    try validateUTF8ByteLimit(query, name: "query", maxBytes: 1_024)
    guard !query.contains("\0") else {
      throw GatewayToolError.invalidArguments("query must not contain null bytes.")
    }
    guard query.rangeOfCharacter(from: .newlines) == nil else {
      throw GatewayToolError.invalidArguments("query must not contain newlines.")
    }
  }

  private func parseGitGrepZ(_ stdout: String) -> (matches: [GitGrepMatch], parseIncomplete: Bool) {
    var matches: [GitGrepMatch] = []
    var index = stdout.startIndex
    var parseIncomplete = false

    while index < stdout.endIndex {
      guard let pathEnd = stdout[index...].firstIndex(of: "\0") else {
        parseIncomplete = true
        break
      }
      let path = String(stdout[index..<pathEnd])
      index = stdout.index(after: pathEnd)

      guard index < stdout.endIndex,
        let lineEnd = stdout[index...].firstIndex(of: "\0")
      else {
        parseIncomplete = true
        break
      }
      let lineString = String(stdout[index..<lineEnd])
      index = stdout.index(after: lineEnd)

      let textEnd = stdout[index...].firstIndex(of: "\n") ?? stdout.endIndex
      let text = String(stdout[index..<textEnd])
      if textEnd < stdout.endIndex {
        index = stdout.index(after: textEnd)
      } else {
        index = stdout.endIndex
      }

      guard !path.isEmpty, let line = Int(lineString), line > 0 else {
        parseIncomplete = true
        continue
      }
      matches.append(
        GitGrepMatch(
          path: path,
          line: line,
          text: text,
          rawRecord: "\(path)\t\(lineString)\t\(text)"
        ))
    }

    return (matches, parseIncomplete)
  }

  private func parseGitCompareCounts(_ stdout: String) -> GitCompareCounts? {
    let values = stdout.split { $0 == " " || $0 == "\t" || $0 == "\n" }.compactMap { Int($0) }
    guard values.count >= 2 else {
      return nil
    }
    return GitCompareCounts(baseOnly: values[0], headOnly: values[1])
  }

  private func parseGitCompareCommitLine(_ line: String) -> GitCompareCommit {
    let parts = line.split(separator: "\t", maxSplits: 5, omittingEmptySubsequences: false)
      .map(String.init)
    guard parts.count == 6 else {
      return GitCompareCommit(
        side: nil,
        refSide: "other",
        commit: nil,
        abbreviatedCommit: nil,
        committedAt: nil,
        author: nil,
        subject: nil,
        rawLine: line
      )
    }

    return GitCompareCommit(
      side: parts[0].isEmpty ? nil : parts[0],
      refSide: gitCompareRefSide(parts[0]),
      commit: parts[1].isEmpty ? nil : parts[1],
      abbreviatedCommit: parts[2].isEmpty ? nil : parts[2],
      committedAt: parts[3].isEmpty ? nil : parts[3],
      author: parts[4].isEmpty ? nil : parts[4],
      subject: parts[5].isEmpty ? nil : parts[5],
      rawLine: line
    )
  }

  private func gitCompareRefSide(_ marker: String) -> String {
    switch marker {
    case "<":
      return "base"
    case ">":
      return "head"
    default:
      return "other"
    }
  }

  private func firstNonEmptyLine(_ stdout: String) -> String? {
    stdout.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .first { !$0.isEmpty }
  }

  private func gitPorcelainZEntryCount(_ stdout: String) -> Int {
    stdout.split(separator: "\u{0}", omittingEmptySubsequences: true).count
  }

  private func gitDiff(arguments object: [String: JSONValue]) throws -> JSONValue {
    let staged = try optionalBool("staged", in: object) ?? false
    let stat = try optionalBool("stat", in: object) ?? false
    let paths = try optionalGitPaths(in: object)
    let contextLines = optionalInt("context_lines", in: object)
    if let contextLines {
      try validateBoundedNonNegative(contextLines, name: "context_lines", upperBound: 100)
    }

    var args = ["diff", "--no-ext-diff"]
    if staged {
      args.append("--cached")
    }
    if stat {
      args.append("--stat")
    }
    if let contextLines {
      args.append("-U\(contextLines)")
    }
    if !paths.isEmpty {
      args.append("--")
      args.append(contentsOf: paths)
    }
    return try gitResult(
      operation: "git.diff",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object)
    )
  }

  private func gitDiffSummary(arguments object: [String: JSONValue]) throws -> JSONValue {
    let staged = try optionalBool("staged", in: object) ?? false
    let paths = try optionalGitPaths(in: object)
    let maxResults = optionalInt("max_results", in: object) ?? 200
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 5_000)

    let command = try gitCLICommand()
    var baseArgs = ["diff", "--no-ext-diff", "--no-color"]
    if staged {
      baseArgs.append("--cached")
    }

    var numstatArgs = baseArgs + ["--numstat", "-z"]
    var summaryArgs = baseArgs + ["--summary"]
    if !paths.isEmpty {
      numstatArgs.append("--")
      numstatArgs.append(contentsOf: paths)
      summaryArgs.append("--")
      summaryArgs.append(contentsOf: paths)
    }

    let timeout = optionalInt("timeout_ms", in: object)
    let numstatResult = try runRegisteredCLI(
      command: command,
      args: numstatArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    let summaryResult = try runRegisteredCLI(
      command: command,
      args: summaryArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )

    let files = parseGitDiffNumstatZ(numstatResult.stdout)
    let summaryItems = parseGitDiffSummaryLines(summaryResult.stdout)
    let returnedFiles = Array(files.prefix(maxResults))
    let returnedSummaryItems = Array(summaryItems.prefix(maxResults))
    let totalAdditions = files.compactMap(\.additions).reduce(0, +)
    let totalDeletions = files.compactMap(\.deletions).reduce(0, +)
    let binaryFileCount = files.filter(\.binary).count
    let resultTruncated =
      files.count > returnedFiles.count
      || summaryItems.count > returnedSummaryItems.count
    let stdoutTruncated = numstatResult.stdoutTruncated || summaryResult.stdoutTruncated

    return .object([
      "operation": .string("git.diff_summary"),
      "provider": .string(command.id),
      "staged": .bool(staged),
      "paths": .array(paths.map(JSONValue.string)),
      "max_results": .number(Double(maxResults)),
      "commands": .object([
        "numstat": .array(numstatArgs.map(JSONValue.string)),
        "summary": .array(summaryArgs.map(JSONValue.string)),
      ]),
      "file_count": .number(Double(files.count)),
      "returned_file_count": .number(Double(returnedFiles.count)),
      "summary_count": .number(Double(summaryItems.count)),
      "returned_summary_count": .number(Double(returnedSummaryItems.count)),
      "total_additions": .number(Double(totalAdditions)),
      "total_deletions": .number(Double(totalDeletions)),
      "binary_file_count": .number(Double(binaryFileCount)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(stdoutTruncated),
      "parse_incomplete": .bool(stdoutTruncated),
      "truncated": .bool(resultTruncated || stdoutTruncated),
      "files": .array(returnedFiles.map(\.json)),
      "summary": .array(returnedSummaryItems.map(\.json)),
      "results": .object([
        "numstat": gitCommandMetadata(numstatResult),
        "summary": gitCommandMetadata(summaryResult),
      ]),
    ])
  }

  private func parseGitDiffNumstatZ(_ stdout: String) -> [GitDiffNumstatFile] {
    let records = stdout.split(separator: "\0", omittingEmptySubsequences: false).map(String.init)
    var files: [GitDiffNumstatFile] = []
    var index = 0

    while index < records.count {
      let record = records[index]
      guard !record.isEmpty else {
        index += 1
        continue
      }

      let parts = record.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
      guard parts.count >= 3 else {
        index += 1
        continue
      }

      let additions = gitNumstatValue(parts[0])
      let deletions = gitNumstatValue(parts[1])
      let binary = parts[0] == "-" || parts[1] == "-"
      let path = parts[2]
      if path.isEmpty {
        guard index + 2 < records.count else {
          break
        }
        files.append(
          GitDiffNumstatFile(
            path: records[index + 2],
            oldPath: records[index + 1],
            additions: additions,
            deletions: deletions,
            binary: binary
          ))
        index += 3
      } else {
        files.append(
          GitDiffNumstatFile(
            path: path,
            oldPath: nil,
            additions: additions,
            deletions: deletions,
            binary: binary
          ))
        index += 1
      }
    }

    return files
  }

  private func gitNumstatValue(_ value: String) -> Int? {
    value == "-" ? nil : Int(value)
  }

  private func parseGitDiffSummaryLines(_ stdout: String) -> [GitDiffSummaryItem] {
    stdout.split(separator: "\n", omittingEmptySubsequences: true).map { line in
      parseGitDiffSummaryLine(String(line))
    }
  }

  private func parseGitDiffSummaryLine(_ line: String) -> GitDiffSummaryItem {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if let item = parseGitDiffModeSummaryLine(trimmed, rawLine: line) {
      return item
    }
    if let item = parseGitDiffMoveSummaryLine(trimmed, rawLine: line) {
      return item
    }
    return GitDiffSummaryItem(
      kind: "other", path: nil, oldPath: nil, newPath: nil, oldMode: nil,
      newMode: nil, mode: nil, similarity: nil, rawLine: line)
  }

  private func parseGitDiffModeSummaryLine(_ trimmed: String, rawLine: String)
    -> GitDiffSummaryItem?
  {
    if trimmed.hasPrefix("create mode ") {
      let rest = String(trimmed.dropFirst("create mode ".count))
      let parts = rest.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: true)
      guard parts.count == 2 else {
        return nil
      }
      return GitDiffSummaryItem(
        kind: "create", path: String(parts[1]), oldPath: nil,
        newPath: String(parts[1]), oldMode: nil, newMode: nil, mode: String(parts[0]),
        similarity: nil, rawLine: rawLine)
    }

    if trimmed.hasPrefix("delete mode ") {
      let rest = String(trimmed.dropFirst("delete mode ".count))
      let parts = rest.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: true)
      guard parts.count == 2 else {
        return nil
      }
      return GitDiffSummaryItem(
        kind: "delete", path: String(parts[1]), oldPath: String(parts[1]),
        newPath: nil, oldMode: nil, newMode: nil, mode: String(parts[0]),
        similarity: nil, rawLine: rawLine)
    }

    if trimmed.hasPrefix("mode change ") {
      let rest = String(trimmed.dropFirst("mode change ".count))
      let parts = rest.split(separator: " ", maxSplits: 3, omittingEmptySubsequences: true)
      guard parts.count == 4, parts[1] == "=>" else {
        return nil
      }
      return GitDiffSummaryItem(
        kind: "mode_change", path: String(parts[3]), oldPath: nil,
        newPath: nil, oldMode: String(parts[0]), newMode: String(parts[2]), mode: nil,
        similarity: nil, rawLine: rawLine)
    }

    return nil
  }

  private func parseGitDiffMoveSummaryLine(_ trimmed: String, rawLine: String)
    -> GitDiffSummaryItem?
  {
    let kind: String
    let prefix: String
    if trimmed.hasPrefix("rename ") {
      kind = "rename"
      prefix = "rename "
    } else if trimmed.hasPrefix("copy ") {
      kind = "copy"
      prefix = "copy "
    } else {
      return nil
    }

    let rest = String(trimmed.dropFirst(prefix.count))
    let similarity: Int?
    let body: String
    if let open = rest.lastIndex(of: "("), rest.hasSuffix("%)") {
      let percentStart = rest.index(after: open)
      let percentEnd = rest.index(rest.endIndex, offsetBy: -2)
      similarity = Int(rest[percentStart..<percentEnd])
      body = String(rest[..<open]).trimmingCharacters(in: .whitespaces)
    } else {
      similarity = nil
      body = rest
    }

    let separator = " => "
    guard let range = body.range(of: separator) else {
      return GitDiffSummaryItem(
        kind: kind, path: nil, oldPath: nil, newPath: nil, oldMode: nil,
        newMode: nil, mode: nil, similarity: similarity, rawLine: rawLine)
    }
    let oldPath = String(body[..<range.lowerBound])
    let newPath = String(body[range.upperBound...])
    return GitDiffSummaryItem(
      kind: kind, path: newPath, oldPath: oldPath, newPath: newPath,
      oldMode: nil, newMode: nil, mode: nil, similarity: similarity, rawLine: rawLine)
  }

  private func gitDiffCheck(arguments object: [String: JSONValue]) throws -> JSONValue {
    let staged = try optionalBool("staged", in: object) ?? false
    let paths = try optionalGitPaths(in: object)
    let maxResults = optionalInt("max_results", in: object) ?? 200
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 5_000)

    var args = ["diff", "--no-ext-diff", "--no-color", "--check"]
    if staged {
      args.append("--cached")
    }
    if !paths.isEmpty {
      args.append("--")
      args.append(contentsOf: paths)
    }

    let command = try gitCLICommand()
    let result = try runRegisteredCLI(
      command: command,
      args: args,
      timeout: optionalInt("timeout_ms", in: object),
      requireArbitraryArgs: false
    )
    let issues = parseGitDiffCheckIssues(result.stdout)
    let rawLines = result.stdout.split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
      .filter { !$0.isEmpty }
    let returnedIssues = Array(issues.prefix(maxResults))
    let returnedRawLines = Array(rawLines.prefix(maxResults))
    let resultTruncated =
      issues.count > returnedIssues.count || rawLines.count > returnedRawLines.count

    return .object([
      "operation": .string("git.diff_check"),
      "provider": .string(command.id),
      "argv": .array(args.map(JSONValue.string)),
      "staged": .bool(staged),
      "paths": .array(paths.map(JSONValue.string)),
      "max_results": .number(Double(maxResults)),
      "passed": .bool(result.exitCode == 0 && issues.isEmpty && !result.stdoutTruncated),
      "issue_count": .number(Double(issues.count)),
      "returned_issue_count": .number(Double(returnedIssues.count)),
      "raw_line_count": .number(Double(rawLines.count)),
      "returned_raw_line_count": .number(Double(returnedRawLines.count)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(result.stdoutTruncated),
      "parse_incomplete": .bool(result.stdoutTruncated),
      "truncated": .bool(resultTruncated || result.stdoutTruncated),
      "issues": .array(returnedIssues.map(\.json)),
      "raw_lines": .array(returnedRawLines.map(JSONValue.string)),
      "result": gitCommandMetadata(result),
    ])
  }

  private func parseGitDiffCheckIssues(_ stdout: String) -> [GitDiffCheckIssue] {
    stdout.split(separator: "\n", omittingEmptySubsequences: true).compactMap { rawLine in
      parseGitDiffCheckIssueLine(String(rawLine))
    }
  }

  private func parseGitDiffCheckIssueLine(_ line: String) -> GitDiffCheckIssue? {
    guard let secondColon = line.range(of: ":", options: [], range: line.startIndex..<line.endIndex)
    else {
      return nil
    }
    let path = String(line[..<secondColon.lowerBound])
    let afterPath = line[secondColon.upperBound...]
    guard let lineColon = afterPath.firstIndex(of: ":") else {
      return nil
    }
    let lineNumberText = String(afterPath[..<lineColon])
    guard let lineNumber = Int(lineNumberText) else {
      return nil
    }
    let message = String(afterPath[afterPath.index(after: lineColon)...])
      .trimmingCharacters(in: .whitespaces)
    guard !path.isEmpty, !message.isEmpty else {
      return nil
    }
    return GitDiffCheckIssue(path: path, line: lineNumber, message: message, rawLine: line)
  }

  private func gitBranch(arguments object: [String: JSONValue]) throws -> JSONValue {
    let all = try optionalBool("all", in: object) ?? false
    let verbose = try optionalBool("verbose", in: object) ?? false
    var args = ["--no-pager", "branch", "--list", "--no-color", "--no-column"]
    if all {
      args.append("--all")
    }
    if verbose {
      args.append("--verbose")
    }
    return try gitResult(
      operation: "git.branch",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object)
    )
  }

  private func gitBranchCreate(arguments object: [String: JSONValue]) throws -> JSONValue {
    let branchName = try validatedGitBranchNameArgument("name", in: object)
    let startPoint = try optionalValidatedGitRefArgument("start_point", in: object) ?? "HEAD"
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmCreate = try optionalBool("confirm_create", in: object) ?? false
    guard dryRun || confirmCreate else {
      throw GatewayToolError.invalidArguments(
        "git.branch_create requires confirm_create=true when dry_run is false.")
    }

    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let checkNameArgs = ["check-ref-format", "--branch", branchName]
    let existsArgs = ["show-ref", "--verify", "--quiet", "refs/heads/\(branchName)"]
    let startPointArgs = ["rev-parse", "--verify", "\(startPoint)^{commit}"]

    let checkNameResult = try runRegisteredCLI(
      command: command,
      args: checkNameArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !checkNameResult.timedOut, checkNameResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "branch name is not accepted by git check-ref-format: \(branchName)")
    }

    let existsResult = try runRegisteredCLI(
      command: command,
      args: existsArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !existsResult.timedOut else {
      throw GatewayToolError.invalidArguments("branch existence check timed out.")
    }
    guard existsResult.exitCode != 0 else {
      throw GatewayToolError.invalidArguments("branch already exists: \(branchName)")
    }
    guard existsResult.exitCode == 1 else {
      throw GatewayToolError.invalidArguments("branch existence check failed for: \(branchName)")
    }

    let startPointResult = try runRegisteredCLI(
      command: command,
      args: startPointArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !startPointResult.timedOut, startPointResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "start_point is not a commit-ish ref: \(startPoint)")
    }

    let createArgs = ["branch", branchName, startPoint]
    var result: JSONValue = .null
    if !dryRun {
      let createResult = try runRegisteredCLI(
        command: command,
        args: createArgs,
        timeout: timeout,
        requireArbitraryArgs: false
      )
      result = createResult.json
    }

    return .object([
      "operation": .string("git.branch_create"),
      "provider": .string(command.id),
      "name": .string(branchName),
      "start_point": .string(startPoint),
      "argv": .array(createArgs.map(JSONValue.string)),
      "dry_run": .bool(dryRun),
      "confirm_create": .bool(confirmCreate),
      "preflight": .object([
        "check_ref_format": gitCommandMetadata(checkNameResult),
        "existing_branch": gitCommandMetadata(existsResult),
        "start_point": gitCommandMetadata(startPointResult),
      ]),
      "result": result,
      "would_create": .bool(true),
    ])
  }

  private func gitBranchDelete(arguments object: [String: JSONValue]) throws -> JSONValue {
    let branchName = try validatedGitBranchNameArgument("name", in: object)
    let force = try optionalBool("force", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmDelete = try optionalBool("confirm_delete", in: object) ?? false
    guard dryRun || confirmDelete else {
      throw GatewayToolError.invalidArguments(
        "git.branch_delete requires confirm_delete=true when dry_run is false.")
    }

    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let checkNameArgs = ["check-ref-format", "--branch", branchName]
    let existsArgs = ["show-ref", "--verify", "--quiet", "refs/heads/\(branchName)"]
    let currentBranchArgs = ["branch", "--show-current"]

    let checkNameResult = try runRegisteredCLI(
      command: command,
      args: checkNameArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !checkNameResult.timedOut, checkNameResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "branch name is not accepted by git check-ref-format: \(branchName)")
    }

    let existsResult = try runRegisteredCLI(
      command: command,
      args: existsArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !existsResult.timedOut else {
      throw GatewayToolError.invalidArguments("branch existence check timed out.")
    }
    guard existsResult.exitCode == 0 else {
      if existsResult.exitCode == 1 {
        throw GatewayToolError.invalidArguments("local branch does not exist: \(branchName)")
      }
      throw GatewayToolError.invalidArguments("branch existence check failed for: \(branchName)")
    }

    let currentBranchResult = try runRegisteredCLI(
      command: command,
      args: currentBranchArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !currentBranchResult.timedOut, currentBranchResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments("current branch check failed.")
    }
    let currentBranch = firstNonEmptyLine(currentBranchResult.stdout) ?? ""
    guard currentBranch != branchName else {
      throw GatewayToolError.invalidArguments("cannot delete the current branch: \(branchName)")
    }

    let deleteArgs = ["branch", force ? "-D" : "-d", branchName]
    var result: JSONValue = .null
    if !dryRun {
      let deleteResult = try runRegisteredCLI(
        command: command,
        args: deleteArgs,
        timeout: timeout,
        requireArbitraryArgs: false
      )
      result = deleteResult.json
    }

    return .object([
      "operation": .string("git.branch_delete"),
      "provider": .string(command.id),
      "name": .string(branchName),
      "force": .bool(force),
      "argv": .array(deleteArgs.map(JSONValue.string)),
      "dry_run": .bool(dryRun),
      "confirm_delete": .bool(confirmDelete),
      "current_branch": currentBranch.isEmpty ? .null : .string(currentBranch),
      "preflight": .object([
        "check_ref_format": gitCommandMetadata(checkNameResult),
        "existing_branch": gitCommandMetadata(existsResult),
        "current_branch": gitCommandMetadata(currentBranchResult),
      ]),
      "result": result,
      "would_delete": .bool(true),
    ])
  }

  private func gitBranchRename(arguments object: [String: JSONValue]) throws -> JSONValue {
    let oldName = try validatedGitBranchNameArgument("old_name", in: object)
    let newName = try validatedGitBranchNameArgument("new_name", in: object)
    let force = try optionalBool("force", in: object) ?? false
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmRename = try optionalBool("confirm_rename", in: object) ?? false
    guard oldName != newName else {
      throw GatewayToolError.invalidArguments("old_name and new_name must be different.")
    }
    guard dryRun || confirmRename else {
      throw GatewayToolError.invalidArguments(
        "git.branch_rename requires confirm_rename=true when dry_run is false.")
    }

    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let checkOldNameArgs = ["check-ref-format", "--branch", oldName]
    let checkNewNameArgs = ["check-ref-format", "--branch", newName]
    let oldExistsArgs = ["show-ref", "--verify", "--quiet", "refs/heads/\(oldName)"]
    let newExistsArgs = ["show-ref", "--verify", "--quiet", "refs/heads/\(newName)"]
    let currentBranchArgs = ["branch", "--show-current"]

    let checkOldNameResult = try runRegisteredCLI(
      command: command,
      args: checkOldNameArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !checkOldNameResult.timedOut, checkOldNameResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "old_name is not accepted by git check-ref-format: \(oldName)")
    }

    let checkNewNameResult = try runRegisteredCLI(
      command: command,
      args: checkNewNameArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !checkNewNameResult.timedOut, checkNewNameResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "new_name is not accepted by git check-ref-format: \(newName)")
    }

    let oldExistsResult = try runRegisteredCLI(
      command: command,
      args: oldExistsArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !oldExistsResult.timedOut else {
      throw GatewayToolError.invalidArguments("old branch existence check timed out.")
    }
    guard oldExistsResult.exitCode == 0 else {
      if oldExistsResult.exitCode == 1 {
        throw GatewayToolError.invalidArguments("local branch does not exist: \(oldName)")
      }
      throw GatewayToolError.invalidArguments("old branch existence check failed for: \(oldName)")
    }

    let newExistsResult = try runRegisteredCLI(
      command: command,
      args: newExistsArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !newExistsResult.timedOut else {
      throw GatewayToolError.invalidArguments("new branch existence check timed out.")
    }
    if newExistsResult.exitCode == 0, !force {
      throw GatewayToolError.invalidArguments("target branch already exists: \(newName)")
    }
    guard newExistsResult.exitCode == 0 || newExistsResult.exitCode == 1 else {
      throw GatewayToolError.invalidArguments("new branch existence check failed for: \(newName)")
    }

    let currentBranchResult = try runRegisteredCLI(
      command: command,
      args: currentBranchArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !currentBranchResult.timedOut, currentBranchResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments("current branch check failed.")
    }
    let currentBranch = firstNonEmptyLine(currentBranchResult.stdout) ?? ""

    let renameArgs = ["branch", force ? "-M" : "-m", oldName, newName]
    var result: JSONValue = .null
    if !dryRun {
      let renameResult = try runRegisteredCLI(
        command: command,
        args: renameArgs,
        timeout: timeout,
        requireArbitraryArgs: false
      )
      result = renameResult.json
    }

    return .object([
      "operation": .string("git.branch_rename"),
      "provider": .string(command.id),
      "old_name": .string(oldName),
      "new_name": .string(newName),
      "force": .bool(force),
      "argv": .array(renameArgs.map(JSONValue.string)),
      "dry_run": .bool(dryRun),
      "confirm_rename": .bool(confirmRename),
      "current_branch": currentBranch.isEmpty ? .null : .string(currentBranch),
      "renames_current_branch": .bool(currentBranch == oldName),
      "target_exists": .bool(newExistsResult.exitCode == 0),
      "preflight": .object([
        "check_old_ref_format": gitCommandMetadata(checkOldNameResult),
        "check_new_ref_format": gitCommandMetadata(checkNewNameResult),
        "old_branch": gitCommandMetadata(oldExistsResult),
        "target_branch": gitCommandMetadata(newExistsResult),
        "current_branch": gitCommandMetadata(currentBranchResult),
      ]),
      "result": result,
      "would_rename": .bool(true),
    ])
  }

  private func gitBranchSwitch(arguments object: [String: JSONValue]) throws -> JSONValue {
    let branchName = try validatedGitBranchNameArgument("name", in: object)
    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmSwitch = try optionalBool("confirm_switch", in: object) ?? false
    let allowDirty = try optionalBool("allow_dirty", in: object) ?? false
    guard dryRun || confirmSwitch else {
      throw GatewayToolError.invalidArguments(
        "git.branch_switch requires confirm_switch=true when dry_run is false.")
    }

    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let checkNameArgs = ["check-ref-format", "--branch", branchName]
    let existsArgs = ["show-ref", "--verify", "--quiet", "refs/heads/\(branchName)"]
    let currentBranchArgs = ["branch", "--show-current"]
    let statusArgs = ["status", "--porcelain=v1", "-z"]

    let checkNameResult = try runRegisteredCLI(
      command: command,
      args: checkNameArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !checkNameResult.timedOut, checkNameResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "branch name is not accepted by git check-ref-format: \(branchName)")
    }

    let existsResult = try runRegisteredCLI(
      command: command,
      args: existsArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !existsResult.timedOut else {
      throw GatewayToolError.invalidArguments("branch existence check timed out.")
    }
    guard existsResult.exitCode == 0 else {
      if existsResult.exitCode == 1 {
        throw GatewayToolError.invalidArguments("local branch does not exist: \(branchName)")
      }
      throw GatewayToolError.invalidArguments("branch existence check failed for: \(branchName)")
    }

    let currentBranchResult = try runRegisteredCLI(
      command: command,
      args: currentBranchArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !currentBranchResult.timedOut, currentBranchResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments("current branch check failed.")
    }
    let currentBranch = firstNonEmptyLine(currentBranchResult.stdout) ?? ""

    let statusResult = try runRegisteredCLI(
      command: command,
      args: statusArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    guard !statusResult.timedOut, statusResult.exitCode == 0 else {
      throw GatewayToolError.invalidArguments("working tree status check failed.")
    }
    let changeCount = gitPorcelainZEntryCount(statusResult.stdout)
    let dirty = changeCount > 0
    if !dryRun, dirty, !allowDirty {
      throw GatewayToolError.invalidArguments(
        "git.branch_switch requires allow_dirty=true when the working tree has changes.")
    }

    let switchArgs = ["switch", "--no-guess", branchName]
    let alreadyCurrent = currentBranch == branchName
    var result: JSONValue = .null
    if !dryRun, !alreadyCurrent {
      let switchResult = try runRegisteredCLI(
        command: command,
        args: switchArgs,
        timeout: timeout,
        requireArbitraryArgs: false
      )
      result = switchResult.json
    }

    return .object([
      "operation": .string("git.branch_switch"),
      "provider": .string(command.id),
      "name": .string(branchName),
      "argv": .array(switchArgs.map(JSONValue.string)),
      "dry_run": .bool(dryRun),
      "confirm_switch": .bool(confirmSwitch),
      "allow_dirty": .bool(allowDirty),
      "current_branch": currentBranch.isEmpty ? .null : .string(currentBranch),
      "already_current": .bool(alreadyCurrent),
      "dirty_worktree": .bool(dirty),
      "working_tree_change_count": .number(Double(changeCount)),
      "preflight": .object([
        "check_ref_format": gitCommandMetadata(checkNameResult),
        "existing_branch": gitCommandMetadata(existsResult),
        "current_branch": gitCommandMetadata(currentBranchResult),
        "working_tree_status": gitCommandMetadata(statusResult),
      ]),
      "result": result,
      "would_switch": .bool(!alreadyCurrent),
    ])
  }

  private func gitLog(arguments object: [String: JSONValue]) throws -> JSONValue {
    let limit = optionalInt("limit", in: object) ?? 20
    try validateBoundedPositive(limit, name: "limit", upperBound: 200)
    let paths = try optionalGitPaths(in: object)
    var args = [
      "log",
      "--date=iso-strict",
      "--pretty=format:%H%x09%h%x09%ad%x09%an%x09%s",
      "-n",
      "\(limit)",
    ]
    if !paths.isEmpty {
      args.append("--")
      args.append(contentsOf: paths)
    }
    return try gitResult(
      operation: "git.log",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object)
    )
  }

  private func gitCommitFiles(arguments object: [String: JSONValue]) throws -> JSONValue {
    let revision = try validatedGitRefArgument("revision", in: object)
    let maxResults = optionalInt("max_results", in: object) ?? 200
    try validateBoundedPositive(maxResults, name: "max_results", upperBound: 5_000)

    let metadataArgs = [
      "show",
      "-s",
      "--date=iso-strict",
      "--format=%H%x09%h%x09%ad%x09%an%x09%s",
      revision,
    ]
    let filesArgs = [
      "diff-tree",
      "--root",
      "--no-commit-id",
      "--name-status",
      "-M",
      "-r",
      "-z",
      revision,
    ]

    let timeout = optionalInt("timeout_ms", in: object)
    let command = try gitCLICommand()
    let metadataResult = try runRegisteredCLI(
      command: command,
      args: metadataArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    let filesResult = try runRegisteredCLI(
      command: command,
      args: filesArgs,
      timeout: timeout,
      requireArbitraryArgs: false
    )

    let metadata = parseGitCommitMetadataLine(firstNonEmptyLine(metadataResult.stdout) ?? "")
    let files = parseGitCommitFilesZ(filesResult.stdout)
    let returnedFiles = Array(files.prefix(maxResults))
    let rawRecords = files.map(\.rawRecord)
    let returnedRawRecords = Array(rawRecords.prefix(maxResults))
    let resultTruncated =
      files.count > returnedFiles.count || rawRecords.count > returnedRawRecords.count
    let stdoutTruncated = metadataResult.stdoutTruncated || filesResult.stdoutTruncated
    let parseIncomplete = stdoutTruncated || metadata.commit == nil

    return .object([
      "operation": .string("git.commit_files"),
      "provider": .string(command.id),
      "revision": .string(revision),
      "max_results": .number(Double(maxResults)),
      "commands": .object([
        "metadata": .array(metadataArgs.map(JSONValue.string)),
        "files": .array(filesArgs.map(JSONValue.string)),
      ]),
      "commit": metadata.json,
      "commit_hash": metadata.commit.map(JSONValue.string) ?? .null,
      "abbreviated_commit": metadata.abbreviatedCommit.map(JSONValue.string) ?? .null,
      "committed_at": metadata.committedAt.map(JSONValue.string) ?? .null,
      "author": metadata.author.map(JSONValue.string) ?? .null,
      "subject": metadata.subject.map(JSONValue.string) ?? .null,
      "file_count": .number(Double(files.count)),
      "returned_file_count": .number(Double(returnedFiles.count)),
      "raw_record_count": .number(Double(rawRecords.count)),
      "returned_raw_record_count": .number(Double(returnedRawRecords.count)),
      "result_truncated": .bool(resultTruncated),
      "stdout_truncated": .bool(stdoutTruncated),
      "parse_incomplete": .bool(parseIncomplete),
      "truncated": .bool(resultTruncated || stdoutTruncated),
      "files": .array(returnedFiles.map(\.json)),
      "raw_records": .array(returnedRawRecords.map(JSONValue.string)),
      "results": .object([
        "metadata": gitCommandMetadata(metadataResult),
        "files": gitCommandMetadata(filesResult),
      ]),
    ])
  }

  private func parseGitCommitMetadataLine(_ line: String) -> GitCommitMetadata {
    let parts = line.split(separator: "\t", maxSplits: 4, omittingEmptySubsequences: false)
      .map(String.init)
    guard parts.count == 5 else {
      return GitCommitMetadata(
        commit: nil,
        abbreviatedCommit: nil,
        committedAt: nil,
        author: nil,
        subject: nil,
        rawLine: line
      )
    }
    return GitCommitMetadata(
      commit: parts[0].isEmpty ? nil : parts[0],
      abbreviatedCommit: parts[1].isEmpty ? nil : parts[1],
      committedAt: parts[2].isEmpty ? nil : parts[2],
      author: parts[3].isEmpty ? nil : parts[3],
      subject: parts[4].isEmpty ? nil : parts[4],
      rawLine: line
    )
  }

  private func parseGitCommitFilesZ(_ stdout: String) -> [GitCommitFileChange] {
    let records = stdout.split(separator: "\0", omittingEmptySubsequences: false).map(String.init)
    var files: [GitCommitFileChange] = []
    var index = 0
    while index < records.count {
      let status = records[index]
      guard !status.isEmpty else {
        index += 1
        continue
      }
      if status.hasPrefix("R") || status.hasPrefix("C") {
        guard index + 2 < records.count else {
          break
        }
        let oldPath = records[index + 1]
        let newPath = records[index + 2]
        files.append(
          GitCommitFileChange(
            status: status,
            kind: gitCommitFileKind(status),
            path: newPath,
            oldPath: oldPath,
            score: gitCommitFileScore(status),
            rawRecord: [status, oldPath, newPath].joined(separator: "\t")
          ))
        index += 3
      } else {
        guard index + 1 < records.count else {
          break
        }
        let path = records[index + 1]
        files.append(
          GitCommitFileChange(
            status: status,
            kind: gitCommitFileKind(status),
            path: path,
            oldPath: nil,
            score: nil,
            rawRecord: [status, path].joined(separator: "\t")
          ))
        index += 2
      }
    }
    return files
  }

  private func gitCommitFileKind(_ status: String) -> String {
    guard let first = status.first else {
      return "unknown"
    }
    switch first {
    case "A":
      return "added"
    case "M":
      return "modified"
    case "D":
      return "deleted"
    case "R":
      return "renamed"
    case "C":
      return "copied"
    case "T":
      return "type_changed"
    case "U":
      return "unmerged"
    case "X":
      return "unknown"
    case "B":
      return "pairing_broken"
    default:
      return "other"
    }
  }

  private func gitCommitFileScore(_ status: String) -> Int? {
    guard status.count > 1 else {
      return nil
    }
    return Int(status.dropFirst())
  }

  private func gitShow(arguments object: [String: JSONValue]) throws -> JSONValue {
    let revision = try optionalString("revision", in: object) ?? "HEAD"
    let stat = try optionalBool("stat", in: object) ?? false
    let patch = try optionalBool("patch", in: object) ?? false
    let paths = try optionalGitPaths(in: object)
    let contextLines = optionalInt("context_lines", in: object)
    if let contextLines {
      try validateBoundedNonNegative(contextLines, name: "context_lines", upperBound: 100)
    }

    var args = ["show", "--date=iso-strict"]
    if stat {
      args.append("--stat")
    }
    if !patch && !stat {
      args.append("--no-patch")
    }
    if let contextLines, patch {
      args.append("-U\(contextLines)")
    }
    args.append(revision)
    if !paths.isEmpty {
      args.append("--")
      args.append(contentsOf: paths)
    }
    return try gitResult(
      operation: "git.show",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object)
    )
  }

  private func gitAdd(arguments object: [String: JSONValue]) throws -> JSONValue {
    let paths = try optionalGitPaths(in: object)
    guard !paths.isEmpty else {
      throw GatewayToolError.invalidArguments("git.add requires at least one path.")
    }
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    var args = ["add"]
    if dryRun {
      args.append("--dry-run")
    }
    if try optionalBool("intent_to_add", in: object) ?? false {
      args.append("--intent-to-add")
    }
    args.append("--")
    args.append(contentsOf: paths)
    return try gitResult(
      operation: "git.add",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object),
      extra: ["dry_run": .bool(dryRun)]
    )
  }

  private func gitUnstage(arguments object: [String: JSONValue]) throws -> JSONValue {
    let paths = try optionalGitPaths(in: object)
    guard !paths.isEmpty else {
      throw GatewayToolError.invalidArguments("git.unstage requires at least one path.")
    }
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    var args = dryRun ? ["diff", "--cached", "--name-only", "--"] : ["restore", "--staged", "--"]
    args.append(contentsOf: paths)
    return try gitResult(
      operation: "git.unstage",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object),
      extra: ["dry_run": .bool(dryRun)]
    )
  }

  private func gitRestoreWorktree(arguments object: [String: JSONValue]) throws -> JSONValue {
    let paths = try optionalGitPaths(in: object)
    guard !paths.isEmpty else {
      throw GatewayToolError.invalidArguments("git.restore_worktree requires at least one path.")
    }

    let dryRun = try optionalBool("dry_run", in: object) ?? true
    let confirmDiscard = try optionalBool("confirm_discard", in: object) ?? false
    guard dryRun || confirmDiscard else {
      throw GatewayToolError.invalidArguments(
        "git.restore_worktree requires confirm_discard=true when dry_run is false.")
    }

    var args = dryRun ? ["diff", "--name-only", "--"] : ["restore", "--worktree", "--"]
    args.append(contentsOf: paths)
    return try gitResult(
      operation: "git.restore_worktree",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object),
      extra: [
        "confirm_discard": .bool(confirmDiscard),
        "dry_run": .bool(dryRun),
      ]
    )
  }

  private func gitCommit(arguments object: [String: JSONValue]) throws -> JSONValue {
    let message = try requiredString("message", in: object)
    guard message.count <= 10_000 else {
      throw GatewayToolError.invalidArguments("message must be 10000 characters or fewer.")
    }
    var args = ["commit", "-m", message]
    let dryRun = try optionalBool("dry_run", in: object) ?? false
    if dryRun {
      args.insert("--dry-run", at: 1)
    }
    if try optionalBool("all", in: object) ?? false {
      args.append("--all")
    }
    if try optionalBool("allow_empty", in: object) ?? false {
      args.append("--allow-empty")
    }
    return try gitResult(
      operation: "git.commit",
      arguments: args,
      timeout: optionalInt("timeout_ms", in: object),
      extra: ["dry_run": .bool(dryRun)]
    )
  }

  private func requireBuiltinEnabled(_ name: String) throws {
    guard configuration.builtin.enabled.contains(name) else {
      throw GatewayToolError.disabled("\(name) is disabled by configuration.")
    }
  }

  private func resolvedWorkspaceURL(_ path: String) throws -> URL {
    do {
      return try WorkspacePathResolver.resolve(
        path,
        relativeTo: configuration.workspaceDirectory
      )
    } catch {
      throw GatewayToolError.invalidArguments(
        "[policy.workspace_denied] Path escapes workspace: \(path)")
    }
  }

  private func lexicalWorkspaceURL(_ path: String) throws -> URL {
    let base = configuration.workspaceDirectory.standardizedFileURL.resolvingSymlinksInPath()
    let target =
      path.hasPrefix("/")
      ? URL(fileURLWithPath: path)
      : base.appendingPathComponent(path)
    let standardized = target.standardizedFileURL
    let basePath = base.path
    let basePrefix = basePath.hasSuffix("/") ? basePath : "\(basePath)/"
    guard standardized.path == basePath || standardized.path.hasPrefix(basePrefix) else {
      throw GatewayToolError.invalidArguments(
        "[policy.workspace_denied] Path escapes workspace: \(path)")
    }
    return standardized
  }

  private func workspaceInstructionScopeURL(
    targetURL: URL,
    originalPath: String = ".",
    pathIsDirectory: Bool?,
    targetExists: Bool
  ) throws -> URL {
    if targetExists {
      let targetWorkspaceRelativePath = workspaceRelativePathPreservingSymlinks(targetURL)
      let resolvedTarget = try resolvedWorkspaceURL(targetWorkspaceRelativePath)
      var isDirectory = ObjCBool(false)
      FileManager.default.fileExists(atPath: resolvedTarget.path, isDirectory: &isDirectory)
      let treatAsDirectory = pathIsDirectory ?? isDirectory.boolValue
      return treatAsDirectory ? resolvedTarget : resolvedTarget.deletingLastPathComponent()
    }

    let treatAsDirectory =
      pathIsDirectory ?? (originalPath == "." || originalPath.hasSuffix("/"))
    return treatAsDirectory ? targetURL : targetURL.deletingLastPathComponent()
  }

  private func workspaceInstructionScopeDirectories(scopeURL: URL) -> [URL] {
    let base = configuration.workspaceDirectory.standardizedFileURL.resolvingSymlinksInPath()
    let basePath = base.path
    let basePrefix = basePath.hasSuffix("/") ? basePath : "\(basePath)/"
    let scope = scopeURL.standardizedFileURL
    guard scope.path == basePath || scope.path.hasPrefix(basePrefix) else {
      return [base]
    }

    var directories: [URL] = []
    var current = scope
    while current.path != basePath {
      directories.append(current)
      let parent = current.deletingLastPathComponent()
      guard parent.path != current.path else {
        break
      }
      current = parent
    }
    directories.append(base)
    return directories.reversed()
  }

  private func resolvedWorkspaceURLPreservingFinalSymlink(_ path: String) throws -> URL {
    let lexicalBase = WorkspacePathResolver.lexicallyNormalized(configuration.workspaceDirectory)
    let canonicalBase: URL
    let base: URL
    do {
      canonicalBase = try WorkspacePathResolver.canonicalWorkspace(lexicalBase)
      base = try WorkspacePathResolver.resolve(".", relativeTo: lexicalBase)
    } catch {
      throw GatewayToolError.invalidArguments(
        "[policy.workspace_denied] Unable to resolve workspace root: \(lexicalBase.path)")
    }
    let isAbsolute = path.hasPrefix("/")
    let target =
      isAbsolute
      ? URL(fileURLWithPath: path)
      : base.appendingPathComponent(path)
    let standardized = WorkspacePathResolver.lexicallyNormalized(target)
    guard
      WorkspacePathResolver.contains(standardized, in: base)
        || (isAbsolute && WorkspacePathResolver.contains(standardized, in: lexicalBase))
        || (isAbsolute && WorkspacePathResolver.contains(standardized, in: canonicalBase))
    else {
      throw GatewayToolError.invalidArguments(
        "[policy.workspace_denied] Path escapes workspace: \(path)")
    }
    guard standardized.path != base.path else {
      return base
    }
    let parent: URL
    do {
      parent = try WorkspacePathResolver.resolve(
        standardized.deletingLastPathComponent().path,
        relativeTo: base
      )
    } catch {
      throw GatewayToolError.invalidArguments(
        "[policy.workspace_denied] Path escapes workspace through parent symlink: \(path)")
    }
    return parent.appendingPathComponent(standardized.lastPathComponent)
  }

  private func isWorkspaceContained(_ url: URL) -> Bool {
    (try? WorkspacePathResolver.resolve(
      url.path,
      relativeTo: configuration.workspaceDirectory
    )) != nil
  }

  private func workspaceRelativePath(_ url: URL) -> String {
    let base = configuration.workspaceDirectory.standardizedFileURL.resolvingSymlinksInPath().path
    let path = url.standardizedFileURL.resolvingSymlinksInPath().path
    if path == base {
      return "."
    }
    let prefix = base.hasSuffix("/") ? base : "\(base)/"
    if path.hasPrefix(prefix) {
      return String(path.dropFirst(prefix.count))
    }
    return path
  }

  private func workspaceRelativePathPreservingSymlinks(_ url: URL) -> String {
    let base = configuration.workspaceDirectory.standardizedFileURL.resolvingSymlinksInPath().path
    let path = url.standardizedFileURL.path
    if path == base {
      return "."
    }
    let prefix = base.hasSuffix("/") ? base : "\(base)/"
    if path.hasPrefix(prefix) {
      return String(path.dropFirst(prefix.count))
    }
    return path
  }

  private func relativePath(fromDirectoryPath rootPath: String, to url: URL) -> String {
    let path = url.standardizedFileURL.resolvingSymlinksInPath().path
    let prefix = rootPath.hasSuffix("/") ? rootPath : "\(rootPath)/"
    guard path.hasPrefix(prefix) else {
      return url.lastPathComponent
    }
    return String(path.dropFirst(prefix.count))
  }

  private func directoryStatsDepth(_ relativePath: String) -> Int {
    relativePath.split(separator: "/").count - 1
  }

  private func directoryStatsGroupPath(
    rootWorkspaceRelativePath: String,
    relativeToRoot: String
  ) -> String {
    guard let first = relativeToRoot.split(separator: "/").first else {
      return rootWorkspaceRelativePath
    }
    if rootWorkspaceRelativePath == "." {
      return String(first)
    }
    return "\(rootWorkspaceRelativePath)/\(first)"
  }

  private func directoryStatsGroupName(
    _ workspaceRelativePath: String,
    rootWorkspaceRelativePath: String
  ) -> String {
    if workspaceRelativePath == rootWorkspaceRelativePath {
      return "."
    }
    return (workspaceRelativePath as NSString).lastPathComponent
  }

  private func collectWorkspaceEmptyDirectories(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    scannedDirectoryCount: inout Int,
    hiddenSkippedCount: inout Int,
    emptyDirectories: inout [WorkspaceEmptyDirectoryInfo],
    scanTruncated: inout Bool
  ) throws {
    guard !scanTruncated else {
      return
    }

    let directoryInfo = try fileInfo(url: directory)
    scannedDirectoryCount += 1
    let children = try sortedDirectoryChildren(directory, includeHidden: true)
    if children.isEmpty {
      emptyDirectories.append(
        WorkspaceEmptyDirectoryInfo(
          path: directoryInfo.path,
          workspaceRelativePath: directoryInfo.workspaceRelativePath,
          name: directory.lastPathComponent.isEmpty ? "." : directory.lastPathComponent,
          depth: currentDepth,
          isRoot: currentDepth == 0,
          modifiedAt: directoryInfo.modifiedAt
        ))
      return
    }

    guard currentDepth < maxDepth else {
      return
    }

    for child in children {
      guard !scanTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }
      scannedEntries += 1

      let childInfo = try fileInfo(url: child)
      guard childInfo.type == "directory", !childInfo.isSymlink else {
        continue
      }
      if child.lastPathComponent.hasPrefix("."), !includeHidden {
        hiddenSkippedCount += 1
        continue
      }

      try collectWorkspaceEmptyDirectories(
        directory: child,
        currentDepth: currentDepth + 1,
        maxDepth: maxDepth,
        includeHidden: includeHidden,
        maxScanEntries: maxScanEntries,
        scannedEntries: &scannedEntries,
        scannedDirectoryCount: &scannedDirectoryCount,
        hiddenSkippedCount: &hiddenSkippedCount,
        emptyDirectories: &emptyDirectories,
        scanTruncated: &scanTruncated
      )
    }
  }

  private func collectWorkspaceArtifactDirectories(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    hiddenSkippedCount: inout Int,
    artifactDirectories: inout [WorkspaceArtifactDirectoryInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      let name = child.lastPathComponent
      let info = try fileInfo(url: child)
      guard info.type == "directory", !info.isSymlink else {
        scannedEntries += 1
        continue
      }

      if name.hasPrefix("."), !includeHidden {
        hiddenSkippedCount += 1
        continue
      }

      scannedEntries += 1
      if let descriptor = artifactDirectoryDescriptor(forDirectoryName: name) {
        guard artifactDirectories.count < maxResults else {
          resultTruncated = true
          return
        }
        artifactDirectories.append(
          WorkspaceArtifactDirectoryInfo(
            info: info,
            category: descriptor.category,
            kind: descriptor.kind,
            cleanupRisk: descriptor.cleanupRisk,
            matchSource: "directory_name"
          ))
        continue
      }

      if currentDepth < maxDepth {
        try collectWorkspaceArtifactDirectories(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          hiddenSkippedCount: &hiddenSkippedCount,
          artifactDirectories: &artifactDirectories,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func artifactDirectoryDescriptor(forDirectoryName name: String)
    -> WorkspaceArtifactDirectoryDescriptor?
  {
    Self.artifactDirectoryDescriptors[name.lowercased()]
  }

  private func collectDirectoryEntries(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxEntries: Int,
    entries: inout [ListedFile],
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }

    let children = try sortedDirectoryChildren(directory, includeHidden: includeHidden)

    for child in children {
      if entries.count >= maxEntries {
        truncated = true
        return
      }

      let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: resolved)
      entries.append(
        ListedFile(
          name: child.lastPathComponent,
          relativePath: info.workspaceRelativePath,
          info: info
        ))

      if currentDepth < maxDepth && info.type == "directory" && !info.isSymlink {
        try collectDirectoryEntries(
          directory: resolved,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxEntries: maxEntries,
          entries: &entries,
          truncated: &truncated
        )
      }
    }
  }

  private func fileTreeNode(
    url: URL,
    depth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    directoriesOnly: Bool,
    maxEntries: Int,
    emitted: inout Int,
    truncated: inout Bool
  ) throws -> JSONValue {
    let info = try fileInfo(url: url)
    emitted += 1

    var object: [String: JSONValue] = [
      "name": .string(url.lastPathComponent.isEmpty ? "." : url.lastPathComponent),
      "path": .string(info.path),
      "workspace_relative_path": .string(info.workspaceRelativePath),
      "type": .string(info.type),
      "depth": .number(Double(depth)),
      "size_bytes": info.size.map { .number(Double($0)) } ?? .null,
      "is_symlink": .bool(info.isSymlink),
    ]

    if info.type == "directory", !info.isSymlink, depth < maxDepth, !truncated {
      var children: [JSONValue] = []
      for child in try sortedDirectoryChildren(url, includeHidden: includeHidden) {
        guard emitted < maxEntries else {
          truncated = true
          break
        }

        let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
        let childInfo = try fileInfo(url: resolved)
        if directoriesOnly && childInfo.type != "directory" {
          continue
        }

        children.append(
          try fileTreeNode(
            url: resolved,
            depth: depth + 1,
            maxDepth: maxDepth,
            includeHidden: includeHidden,
            directoriesOnly: directoriesOnly,
            maxEntries: maxEntries,
            emitted: &emitted,
            truncated: &truncated
          ))

        if truncated {
          break
        }
      }
      object["children"] = .array(children)
    }

    return .object(object)
  }

  private func collectTreeCompareEntries(
    root: URL,
    includeHidden: Bool,
    maxDepth: Int,
    maxEntries: Int,
    scannedEntries: inout Int,
    truncated: inout Bool
  ) throws -> [String: TreeCompareEntry] {
    var entries: [String: TreeCompareEntry] = [:]
    try collectTreeCompareEntries(
      directory: root,
      rootPath: root.standardizedFileURL.path,
      currentDepth: 0,
      maxDepth: maxDepth,
      includeHidden: includeHidden,
      maxEntries: maxEntries,
      scannedEntries: &scannedEntries,
      truncated: &truncated,
      entries: &entries
    )
    return entries
  }

  private func collectTreeCompareEntries(
    directory: URL,
    rootPath: String,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxEntries: Int,
    scannedEntries: inout Int,
    truncated: inout Bool,
    entries: inout [String: TreeCompareEntry]
  ) throws {
    guard !truncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: includeHidden) {
      guard scannedEntries < maxEntries else {
        truncated = true
        return
      }

      scannedEntries += 1
      let lexical = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: lexical)
      let relativePath = relativePathPreservingSymlinks(fromDirectoryPath: rootPath, to: lexical)
      entries[relativePath] = TreeCompareEntry(
        url: lexical,
        relativePath: relativePath,
        workspaceRelativePath: workspaceRelativePathPreservingSymlinks(lexical),
        type: info.type,
        sizeBytes: info.size,
        modifiedAt: info.modifiedAt,
        isSymlink: info.isSymlink,
        symlinkDestination: info.symlinkDestination,
        sha256: nil
      )

      if currentDepth < maxDepth && info.type == "directory" && !info.isSymlink {
        try collectTreeCompareEntries(
          directory: lexical,
          rootPath: rootPath,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxEntries: maxEntries,
          scannedEntries: &scannedEntries,
          truncated: &truncated,
          entries: &entries
        )
      }
    }
  }

  private func relativePathPreservingSymlinks(fromDirectoryPath rootPath: String, to url: URL)
    -> String
  {
    let path = url.standardizedFileURL.path
    let prefix = rootPath.hasSuffix("/") ? rootPath : "\(rootPath)/"
    guard path.hasPrefix(prefix) else {
      return url.lastPathComponent
    }
    return String(path.dropFirst(prefix.count))
  }

  private func recordTreeCompareDifference(
    kind: String,
    relativePath: String,
    left: TreeCompareEntry?,
    right: TreeCompareEntry?,
    detail: String,
    differenceCounts: inout [String: Int],
    differences: inout [TreeCompareDifference],
    maxResults: Int,
    resultTruncated: inout Bool
  ) {
    differenceCounts[kind, default: 0] += 1
    guard differences.count < maxResults else {
      resultTruncated = true
      return
    }
    differences.append(
      TreeCompareDifference(
        kind: kind,
        relativePath: relativePath,
        left: left,
        right: right,
        detail: detail
      ))
  }

  private func collectDuplicateFileCandidates(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    minSizeBytes: Int64,
    maxHashFileBytes: Int64,
    maxEntries: Int,
    scannedEntries: inout Int,
    scannedFileCount: inout Int,
    skippedSmallFileCount: inout Int,
    skippedLargeFileCount: inout Int,
    scanTruncated: inout Bool,
    candidates: inout [DuplicateFileCandidate]
  ) throws {
    guard !scanTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: includeHidden) {
      guard scannedEntries < maxEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let url = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: url)

      if info.type == "directory", !info.isSymlink, currentDepth < maxDepth {
        try collectDuplicateFileCandidates(
          directory: url,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          minSizeBytes: minSizeBytes,
          maxHashFileBytes: maxHashFileBytes,
          maxEntries: maxEntries,
          scannedEntries: &scannedEntries,
          scannedFileCount: &scannedFileCount,
          skippedSmallFileCount: &skippedSmallFileCount,
          skippedLargeFileCount: &skippedLargeFileCount,
          scanTruncated: &scanTruncated,
          candidates: &candidates
        )
        continue
      }

      guard info.type == "file", !info.isSymlink else {
        continue
      }
      scannedFileCount += 1
      let size = info.size ?? 0
      guard size >= minSizeBytes else {
        skippedSmallFileCount += 1
        continue
      }
      guard size <= maxHashFileBytes else {
        skippedLargeFileCount += 1
        continue
      }
      candidates.append(
        DuplicateFileCandidate(
          url: url,
          workspaceRelativePath: workspaceRelativePathPreservingSymlinks(url),
          sizeBytes: size,
          modifiedAt: info.modifiedAt,
          sha256: nil
        ))
    }
  }

  private func collectFindResults(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    query: String,
    matchMode: FileNameMatchMode,
    caseSensitive: Bool,
    includeHidden: Bool,
    maxResults: Int,
    maxVisited: Int,
    visited: inout Int,
    results: inout [FileInfo],
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: includeHidden) {
      guard visited < maxVisited else {
        truncated = true
        return
      }
      visited += 1

      let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: resolved)
      if fileName(
        child.lastPathComponent, matches: query, mode: matchMode, caseSensitive: caseSensitive)
      {
        guard results.count < maxResults else {
          truncated = true
          return
        }
        results.append(info)
      }

      if currentDepth < maxDepth && info.type == "directory" && !info.isSymlink {
        try collectFindResults(
          directory: resolved,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          query: query,
          matchMode: matchMode,
          caseSensitive: caseSensitive,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxVisited: maxVisited,
          visited: &visited,
          results: &results,
          truncated: &truncated
        )
      }
    }
  }

  private func collectTimelineFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    modifiedAfter: Date?,
    modifiedBefore: Date?,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    scannedFileCount: inout Int,
    skippedMissingModifiedDateCount: inout Int,
    scanTruncated: inout Bool,
    entries: inout [TimelineFileEntry]
  ) throws {
    guard !scanTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: includeHidden) {
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: resolved)

      if info.type == "directory", !info.isSymlink, currentDepth < maxDepth {
        try collectTimelineFiles(
          directory: resolved,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          modifiedAfter: modifiedAfter,
          modifiedBefore: modifiedBefore,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          scannedFileCount: &scannedFileCount,
          skippedMissingModifiedDateCount: &skippedMissingModifiedDateCount,
          scanTruncated: &scanTruncated,
          entries: &entries
        )
        continue
      }

      guard info.type == "file", !info.isSymlink else {
        continue
      }
      scannedFileCount += 1
      guard let modifiedAt = info.modifiedAt else {
        skippedMissingModifiedDateCount += 1
        continue
      }
      if let modifiedAfter, modifiedAt < modifiedAfter {
        continue
      }
      if let modifiedBefore, modifiedAt > modifiedBefore {
        continue
      }
      entries.append(TimelineFileEntry(info: info, modifiedAt: modifiedAt))
    }
  }

  private func collectSearchMatches(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    query: String,
    caseSensitive: Bool,
    includeHidden: Bool,
    maxFiles: Int,
    maxMatches: Int,
    maxBytesPerFile: Int,
    filesScanned: inout Int,
    filesSkipped: inout Int,
    bytesScanned: inout Int,
    truncatedFiles: inout Int,
    matches: inout [FileSearchMatch],
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: includeHidden) {
      guard !truncated else {
        return
      }

      let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: resolved)
      if info.type == "directory" && !info.isSymlink {
        if currentDepth < maxDepth {
          try collectSearchMatches(
            directory: resolved,
            currentDepth: currentDepth + 1,
            maxDepth: maxDepth,
            query: query,
            caseSensitive: caseSensitive,
            includeHidden: includeHidden,
            maxFiles: maxFiles,
            maxMatches: maxMatches,
            maxBytesPerFile: maxBytesPerFile,
            filesScanned: &filesScanned,
            filesSkipped: &filesSkipped,
            bytesScanned: &bytesScanned,
            truncatedFiles: &truncatedFiles,
            matches: &matches,
            truncated: &truncated
          )
        }
        continue
      }

      try searchFileIfAllowed(
        url: resolved,
        info: info,
        query: query,
        caseSensitive: caseSensitive,
        maxFiles: maxFiles,
        maxMatches: maxMatches,
        maxBytesPerFile: maxBytesPerFile,
        filesScanned: &filesScanned,
        filesSkipped: &filesSkipped,
        bytesScanned: &bytesScanned,
        truncatedFiles: &truncatedFiles,
        matches: &matches,
        truncated: &truncated
      )
    }
  }

  private func searchFileIfAllowed(
    url: URL,
    info: FileInfo,
    query: String,
    caseSensitive: Bool,
    maxFiles: Int,
    maxMatches: Int,
    maxBytesPerFile: Int,
    filesScanned: inout Int,
    filesSkipped: inout Int,
    bytesScanned: inout Int,
    truncatedFiles: inout Int,
    matches: inout [FileSearchMatch],
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }
    guard info.type == "file" else {
      filesSkipped += 1
      return
    }
    guard filesScanned < maxFiles else {
      truncated = true
      return
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytesPerFile + 1) ?? Data()
    let limitedData: Data
    if data.count > maxBytesPerFile {
      limitedData = Data(data.prefix(maxBytesPerFile))
      truncatedFiles += 1
    } else {
      limitedData = data
    }
    bytesScanned += limitedData.count
    filesScanned += 1

    guard !limitedData.contains(0) else {
      filesSkipped += 1
      return
    }

    let content = String(decoding: limitedData, as: UTF8.self)
    try appendContentMatches(
      content: content,
      fileInfo: info,
      query: query,
      caseSensitive: caseSensitive,
      maxMatches: maxMatches,
      fileTruncated: data.count > maxBytesPerFile,
      matches: &matches,
      truncated: &truncated
    )
  }

  private func appendContentMatches(
    content: String,
    fileInfo: FileInfo,
    query: String,
    caseSensitive: Bool,
    maxMatches: Int,
    fileTruncated: Bool,
    matches: inout [FileSearchMatch],
    truncated: inout Bool
  ) throws {
    let options: String.CompareOptions = caseSensitive ? [] : [.caseInsensitive]
    for (lineIndex, line) in content.split(separator: "\n", omittingEmptySubsequences: false)
      .enumerated()
    {
      guard let range = line.range(of: query, options: options) else {
        continue
      }
      guard matches.count < maxMatches else {
        truncated = true
        return
      }

      matches.append(
        FileSearchMatch(
          path: fileInfo.path,
          workspaceRelativePath: fileInfo.workspaceRelativePath,
          line: lineIndex + 1,
          column: line.distance(from: line.startIndex, to: range.lowerBound) + 1,
          preview: String(line.prefix(300)),
          fileTruncated: fileTruncated
        ))
    }
  }

  private func collectTodoMatches(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    markers: [String],
    caseSensitive: Bool,
    includeHidden: Bool,
    maxFiles: Int,
    maxMatches: Int,
    maxBytesPerFile: Int,
    filesScanned: inout Int,
    filesSkipped: inout Int,
    bytesScanned: inout Int,
    truncatedFiles: inout Int,
    matches: inout [WorkspaceTodoMatch],
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: includeHidden) {
      guard !truncated else {
        return
      }

      let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: resolved)
      if info.type == "directory" && !info.isSymlink {
        if currentDepth < maxDepth {
          try collectTodoMatches(
            directory: resolved,
            currentDepth: currentDepth + 1,
            maxDepth: maxDepth,
            markers: markers,
            caseSensitive: caseSensitive,
            includeHidden: includeHidden,
            maxFiles: maxFiles,
            maxMatches: maxMatches,
            maxBytesPerFile: maxBytesPerFile,
            filesScanned: &filesScanned,
            filesSkipped: &filesSkipped,
            bytesScanned: &bytesScanned,
            truncatedFiles: &truncatedFiles,
            matches: &matches,
            truncated: &truncated
          )
        }
        continue
      }

      try scanTodoFileIfAllowed(
        url: resolved,
        info: info,
        markers: markers,
        caseSensitive: caseSensitive,
        maxFiles: maxFiles,
        maxMatches: maxMatches,
        maxBytesPerFile: maxBytesPerFile,
        filesScanned: &filesScanned,
        filesSkipped: &filesSkipped,
        bytesScanned: &bytesScanned,
        truncatedFiles: &truncatedFiles,
        matches: &matches,
        truncated: &truncated
      )
    }
  }

  private func scanTodoFileIfAllowed(
    url: URL,
    info: FileInfo,
    markers: [String],
    caseSensitive: Bool,
    maxFiles: Int,
    maxMatches: Int,
    maxBytesPerFile: Int,
    filesScanned: inout Int,
    filesSkipped: inout Int,
    bytesScanned: inout Int,
    truncatedFiles: inout Int,
    matches: inout [WorkspaceTodoMatch],
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }
    guard info.type == "file" else {
      filesSkipped += 1
      return
    }
    guard filesScanned < maxFiles else {
      truncated = true
      return
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytesPerFile + 1) ?? Data()
    let limitedData: Data
    if data.count > maxBytesPerFile {
      limitedData = Data(data.prefix(maxBytesPerFile))
      truncatedFiles += 1
    } else {
      limitedData = data
    }
    bytesScanned += limitedData.count
    filesScanned += 1

    guard !limitedData.contains(0) else {
      filesSkipped += 1
      return
    }

    let content = String(decoding: limitedData, as: UTF8.self)
    appendTodoMatches(
      content: content,
      fileInfo: info,
      markers: markers,
      caseSensitive: caseSensitive,
      maxMatches: maxMatches,
      fileTruncated: data.count > maxBytesPerFile,
      matches: &matches,
      truncated: &truncated
    )
  }

  private func appendTodoMatches(
    content: String,
    fileInfo: FileInfo,
    markers: [String],
    caseSensitive: Bool,
    maxMatches: Int,
    fileTruncated: Bool,
    matches: inout [WorkspaceTodoMatch],
    truncated: inout Bool
  ) {
    let options: String.CompareOptions = caseSensitive ? [] : [.caseInsensitive]
    for (lineIndex, line) in content.split(separator: "\n", omittingEmptySubsequences: false)
      .enumerated()
    {
      var lineMatches: [(markerIndex: Int, range: Range<Substring.Index>)] = []
      for (markerIndex, marker) in markers.enumerated() {
        if let range = firstTodoMarkerRange(in: line, marker: marker, options: options) {
          lineMatches.append((markerIndex: markerIndex, range: range))
        }
      }

      lineMatches.sort { lhs, rhs in
        if lhs.range.lowerBound != rhs.range.lowerBound {
          return lhs.range.lowerBound < rhs.range.lowerBound
        }
        return lhs.markerIndex < rhs.markerIndex
      }

      for lineMatch in lineMatches {
        guard matches.count < maxMatches else {
          truncated = true
          return
        }

        matches.append(
          WorkspaceTodoMatch(
            marker: markers[lineMatch.markerIndex],
            path: fileInfo.path,
            workspaceRelativePath: fileInfo.workspaceRelativePath,
            line: lineIndex + 1,
            column: line.distance(from: line.startIndex, to: lineMatch.range.lowerBound) + 1,
            preview: String(line.prefix(300)),
            fileTruncated: fileTruncated
          ))
      }
    }
  }

  private func firstTodoMarkerRange(
    in line: Substring,
    marker: String,
    options: String.CompareOptions
  ) -> Range<Substring.Index>? {
    var lowerBound = line.startIndex
    while lowerBound < line.endIndex {
      guard let range = line[lowerBound...].range(of: marker, options: options) else {
        return nil
      }
      if isTodoMarkerToken(in: line, range: range) {
        return range
      }
      lowerBound = range.upperBound
    }
    return nil
  }

  private func isTodoMarkerToken(
    in line: Substring,
    range: Range<Substring.Index>
  ) -> Bool {
    if range.lowerBound > line.startIndex {
      let previous = line[line.index(before: range.lowerBound)]
      if isTodoMarkerWordCharacter(previous) {
        return false
      }
    }

    if range.upperBound < line.endIndex {
      let next = line[range.upperBound]
      if isTodoMarkerWordCharacter(next) {
        return false
      }
    }

    return true
  }

  private func isTodoMarkerWordCharacter(_ character: Character) -> Bool {
    character.unicodeScalars.allSatisfy { scalar in
      (scalar.value >= 48 && scalar.value <= 57)
        || (scalar.value >= 65 && scalar.value <= 90)
        || (scalar.value >= 97 && scalar.value <= 122)
        || scalar.value == 95
    }
  }

  private func collectWorkspaceEnvFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHiddenDirectories: Bool,
    maxFiles: Int,
    maxKeysPerFile: Int,
    maxBytesPerFile: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    envFiles: inout [WorkspaceEnvFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      if scannedEntries >= maxScanEntries {
        scanTruncated = true
        return
      }
      scannedEntries += 1

      let resolved = try resolvedWorkspaceURLPreservingFinalSymlink(child.path)
      let info = try fileInfo(url: resolved)
      if info.type == "directory" && !info.isSymlink {
        guard currentDepth < maxDepth else {
          continue
        }
        guard includeHiddenDirectories || !child.lastPathComponent.hasPrefix(".") else {
          continue
        }
        try collectWorkspaceEnvFiles(
          directory: resolved,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHiddenDirectories: includeHiddenDirectories,
          maxFiles: maxFiles,
          maxKeysPerFile: maxKeysPerFile,
          maxBytesPerFile: maxBytesPerFile,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          envFiles: &envFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
        continue
      }

      guard info.type == "file", isEnvFileName(child.lastPathComponent) else {
        continue
      }
      guard envFiles.count < maxFiles else {
        resultTruncated = true
        return
      }
      envFiles.append(
        try parseWorkspaceEnvFile(
          url: resolved,
          info: info,
          maxKeysPerFile: maxKeysPerFile,
          maxBytesPerFile: maxBytesPerFile
        ))
    }
  }

  private func parseWorkspaceEnvFile(
    url: URL,
    info: FileInfo,
    maxKeysPerFile: Int,
    maxBytesPerFile: Int
  ) throws -> WorkspaceEnvFileInfo {
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytesPerFile + 1) ?? Data()
    let fileTruncated = data.count > maxBytesPerFile
    let limitedData = fileTruncated ? Data(data.prefix(maxBytesPerFile)) : data
    guard !limitedData.contains(0) else {
      return WorkspaceEnvFileInfo(
        path: info.path,
        workspaceRelativePath: info.workspaceRelativePath,
        sizeBytes: info.size,
        modifiedAt: info.modifiedAt,
        bytesScanned: limitedData.count,
        fileTruncated: fileTruncated,
        keysTruncated: false,
        invalidLineCount: 0,
        parseError: "File appears to be binary.",
        keys: []
      )
    }
    guard let content = String(data: limitedData, encoding: .utf8) else {
      return WorkspaceEnvFileInfo(
        path: info.path,
        workspaceRelativePath: info.workspaceRelativePath,
        sizeBytes: info.size,
        modifiedAt: info.modifiedAt,
        bytesScanned: limitedData.count,
        fileTruncated: fileTruncated,
        keysTruncated: false,
        invalidLineCount: 0,
        parseError: "File is not valid UTF-8.",
        keys: []
      )
    }

    var keys: [WorkspaceEnvKeyInfo] = []
    var invalidLineCount = 0
    var keysTruncated = false

    for (lineIndex, rawLine) in content.split(separator: "\n", omittingEmptySubsequences: false)
      .enumerated()
    {
      guard let parsed = parseEnvLine(String(rawLine), line: lineIndex + 1) else {
        continue
      }
      switch parsed {
      case .invalid:
        invalidLineCount += 1
      case .key(let key):
        guard keys.count < maxKeysPerFile else {
          keysTruncated = true
          break
        }
        keys.append(key)
      }
    }

    return WorkspaceEnvFileInfo(
      path: info.path,
      workspaceRelativePath: info.workspaceRelativePath,
      sizeBytes: info.size,
      modifiedAt: info.modifiedAt,
      bytesScanned: limitedData.count,
      fileTruncated: fileTruncated,
      keysTruncated: keysTruncated,
      invalidLineCount: invalidLineCount,
      parseError: nil,
      keys: keys
    )
  }

  private func parseEnvLine(_ rawLine: String, line: Int) -> ParsedEnvLine? {
    var text = rawLine.trimmingCharacters(in: .whitespaces)
    guard !text.isEmpty, !text.hasPrefix("#") else {
      return nil
    }

    var exported = false
    if text.hasPrefix("export ") {
      exported = true
      text = String(text.dropFirst("export ".count)).trimmingCharacters(in: .whitespaces)
    }

    let keyText: String
    let hasValue: Bool
    let valueEmpty: Bool
    if let equalsIndex = text.firstIndex(of: "=") {
      keyText = String(text[..<equalsIndex]).trimmingCharacters(in: .whitespaces)
      hasValue = true
      valueEmpty = text[text.index(after: equalsIndex)...].isEmpty
    } else {
      keyText = text.trimmingCharacters(in: .whitespaces)
      hasValue = false
      valueEmpty = true
    }

    guard isEnvKeyName(keyText) else {
      return .invalid
    }

    return .key(
      WorkspaceEnvKeyInfo(
        name: keyText,
        line: line,
        exported: exported,
        hasValue: hasValue,
        valueEmpty: valueEmpty
      ))
  }

  private func isEnvFileName(_ name: String) -> Bool {
    name == ".env"
      || name.hasPrefix(".env.")
      || name.hasSuffix(".env")
      || name.contains(".env.")
  }

  private func isEnvKeyName(_ name: String) -> Bool {
    guard let first = name.unicodeScalars.first else {
      return false
    }
    guard isEnvKeyFirstScalar(first) else {
      return false
    }
    return name.unicodeScalars.dropFirst().allSatisfy(isEnvKeyScalar)
  }

  private func isEnvKeyFirstScalar(_ scalar: UnicodeScalar) -> Bool {
    (scalar.value >= 65 && scalar.value <= 90)
      || (scalar.value >= 97 && scalar.value <= 122)
      || scalar.value == 95
  }

  private func isEnvKeyScalar(_ scalar: UnicodeScalar) -> Bool {
    isEnvKeyFirstScalar(scalar) || (scalar.value >= 48 && scalar.value <= 57)
  }

  private func collectWorkspaceDependencyFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    dependencyFiles: inout [WorkspaceDependencyFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let info = try fileInfo(url: child)

      if name.hasPrefix("."), !includeHidden {
        if info.type == "directory" {
          continue
        }
        if dependencyFileDescriptor(for: name) == nil {
          continue
        }
      }

      if let descriptor = dependencyFileDescriptor(for: name) {
        guard dependencyFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        dependencyFiles.append(
          WorkspaceDependencyFileInfo(
            info: info,
            ecosystem: descriptor.ecosystem,
            role: descriptor.role
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceDependencyFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          dependencyFiles: &dependencyFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func collectWorkspaceProjectDependencyFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    dependencyFiles: inout [WorkspaceDependencyFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.projectRootSkippedDirectoryNames.contains(lowercasedName), info.type == "directory" {
        continue
      }
      if name.hasPrefix("."), !includeHidden {
        if info.type == "directory" {
          continue
        }
        if dependencyFileDescriptor(for: name) == nil {
          continue
        }
      }

      if let descriptor = dependencyFileDescriptor(for: name) {
        guard dependencyFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        dependencyFiles.append(
          WorkspaceDependencyFileInfo(
            info: info,
            ecosystem: descriptor.ecosystem,
            role: descriptor.role
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceProjectDependencyFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          dependencyFiles: &dependencyFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func dependencyFileDescriptor(for name: String) -> WorkspaceDependencyFileDescriptor? {
    if let descriptor = Self.dependencyFileDescriptors.first(where: { $0.name == name }) {
      return descriptor
    }

    let lowercased = name.lowercased()
    if lowercased.hasPrefix("requirements-"), lowercased.hasSuffix(".txt") {
      return WorkspaceDependencyFileDescriptor(
        name: name,
        ecosystem: "python",
        role: "requirements"
      )
    }
    return nil
  }

  private func groupedWorkspaceProjectRoots(
    from dependencyFiles: [WorkspaceDependencyFileInfo]
  ) -> [WorkspaceProjectRootInfo] {
    var grouped: [String: [WorkspaceDependencyFileInfo]] = [:]
    for dependencyFile in dependencyFiles {
      let directory = (dependencyFile.info.workspaceRelativePath as NSString)
        .deletingLastPathComponent
      let normalizedDirectory = directory.isEmpty || directory == "." ? "." : directory
      grouped[normalizedDirectory, default: []].append(dependencyFile)
    }

    return grouped.map { directory, files in
      let sortedFiles = files.sorted {
        $0.info.workspaceRelativePath.localizedStandardCompare($1.info.workspaceRelativePath)
          == .orderedAscending
      }
      let ecosystems = Array(Set(sortedFiles.map(\.ecosystem))).sorted()
      let manifestFiles = sortedFiles.filter { $0.role == "manifest" || $0.role == "requirements" }
      let lockFiles = sortedFiles.filter { $0.role == "lock" }
      let checksumFiles = sortedFiles.filter { $0.role == "checksum" }
      return WorkspaceProjectRootInfo(
        path: projectRootAbsolutePath(directory),
        workspaceRelativePath: directory,
        ecosystems: ecosystems,
        manifestFiles: manifestFiles.map(\.info.workspaceRelativePath),
        lockFiles: lockFiles.map(\.info.workspaceRelativePath),
        checksumFiles: checksumFiles.map(\.info.workspaceRelativePath),
        dependencyFiles: sortedFiles.map {
          WorkspaceProjectDependencyFileInfo(
            workspaceRelativePath: $0.info.workspaceRelativePath,
            name: ($0.info.workspaceRelativePath as NSString).lastPathComponent,
            ecosystem: $0.ecosystem,
            role: $0.role
          )
        },
        isWorkspaceRoot: directory == "."
      )
    }
    .sorted {
      $0.workspaceRelativePath.localizedStandardCompare($1.workspaceRelativePath)
        == .orderedAscending
    }
  }

  private func projectRootAbsolutePath(_ workspaceRelativePath: String) -> String {
    if workspaceRelativePath == "." {
      return configuration.workspaceDirectory.standardizedFileURL.path
    }
    return configuration.workspaceDirectory
      .appendingPathComponent(workspaceRelativePath)
      .standardizedFileURL
      .path
  }

  private func collectWorkspaceDocumentationFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    documentationFiles: inout [WorkspaceDocumentationFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let info = try fileInfo(url: child)

      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file",
        let descriptor = documentationDescriptor(for: info.workspaceRelativePath)
      {
        guard documentationFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        documentationFiles.append(
          WorkspaceDocumentationFileInfo(
            info: info,
            category: descriptor.category,
            source: descriptor.source
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceDocumentationFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          documentationFiles: &documentationFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func documentationDescriptor(for workspaceRelativePath: String)
    -> WorkspaceDocumentationDescriptor?
  {
    let name = (workspaceRelativePath as NSString).lastPathComponent
    let baseName = (name as NSString).deletingPathExtension.lowercased()
    let lowercasedName = name.lowercased()

    if let descriptor = Self.documentationFileDescriptors[lowercasedName] {
      return descriptor
    }
    if let descriptor = Self.documentationFileDescriptors[baseName] {
      return descriptor
    }
    if lowercasedName.hasPrefix("readme.") {
      return WorkspaceDocumentationDescriptor(category: "overview", source: "filename")
    }
    if lowercasedName.hasPrefix("changelog.") || lowercasedName.hasPrefix("changes.") {
      return WorkspaceDocumentationDescriptor(category: "changelog", source: "filename")
    }
    if lowercasedName.hasPrefix("license.") || lowercasedName.hasPrefix("licence.") {
      return WorkspaceDocumentationDescriptor(category: "license", source: "filename")
    }

    if isDocumentationDirectoryPath(workspaceRelativePath),
      isDocumentationFileExtension((name as NSString).pathExtension.lowercased())
    {
      return WorkspaceDocumentationDescriptor(
        category: "documentation", source: "documentation_directory")
    }

    return nil
  }

  private func collectWorkspaceAgentFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    agentFiles: inout [WorkspaceAgentFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let info = try fileInfo(url: child)

      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file",
        let descriptor = agentFileDescriptor(for: info.workspaceRelativePath)
      {
        guard agentFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        agentFiles.append(
          WorkspaceAgentFileInfo(
            info: info,
            kind: descriptor.kind,
            source: descriptor.source
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        guard !Self.agentFileScanSkippedDirectoryNames.contains(name) else {
          continue
        }
        try collectWorkspaceAgentFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          agentFiles: &agentFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func agentFileDescriptor(for workspaceRelativePath: String)
    -> WorkspaceAgentFileDescriptor?
  {
    let normalized = workspaceRelativePath.replacingOccurrences(of: "\\", with: "/")
    let lowercasedPath = normalized.lowercased()
    let name = (normalized as NSString).lastPathComponent
    let lowercasedName = name.lowercased()

    if lowercasedName == "copilot-instructions.md" {
      guard
        lowercasedPath == ".github/copilot-instructions.md"
          || lowercasedPath.hasSuffix("/.github/copilot-instructions.md")
      else {
        return nil
      }
    }

    if let descriptor = Self.agentFileDescriptors[lowercasedName] {
      return descriptor
    }

    if lowercasedPath.hasPrefix(".cursor/rules/")
      || lowercasedPath.contains("/.cursor/rules/"),
      lowercasedName.hasSuffix(".md") || lowercasedName.hasSuffix(".mdc")
    {
      return WorkspaceAgentFileDescriptor(kind: "cursor_rule", source: "cursor_rules_directory")
    }

    if lowercasedPath.hasPrefix(".windsurf/rules/")
      || lowercasedPath.contains("/.windsurf/rules/"),
      lowercasedName.hasSuffix(".md")
    {
      return WorkspaceAgentFileDescriptor(
        kind: "windsurf_rule",
        source: "windsurf_rules_directory"
      )
    }

    if lowercasedName == "skill.md",
      lowercasedPath.hasPrefix("skills/") || lowercasedPath.contains("/skills/")
    {
      return WorkspaceAgentFileDescriptor(kind: "codex_skill", source: "skills_directory")
    }

    return nil
  }

  private func collectWorkspaceInstructionFiles(
    directory: URL,
    scopeWorkspaceRelativePath: String,
    includeContent: Bool,
    maxBytesPerFile: Int,
    maxResults: Int,
    seenPaths: inout Set<String>,
    files: inout [WorkspaceInstructionFileInfo],
    resultTruncated: inout Bool,
    applyOrder: inout Int
  ) throws {
    for filename in Self.scopedInstructionFilenames {
      try appendWorkspaceInstructionFile(
        candidate: directory.appendingPathComponent(filename),
        scopeWorkspaceRelativePath: scopeWorkspaceRelativePath,
        includeContent: includeContent,
        maxBytesPerFile: maxBytesPerFile,
        maxResults: maxResults,
        seenPaths: &seenPaths,
        files: &files,
        resultTruncated: &resultTruncated,
        applyOrder: &applyOrder
      )
      guard !resultTruncated else {
        return
      }
    }

    try appendWorkspaceInstructionFile(
      candidate: directory.appendingPathComponent(".github/copilot-instructions.md"),
      scopeWorkspaceRelativePath: scopeWorkspaceRelativePath,
      includeContent: includeContent,
      maxBytesPerFile: maxBytesPerFile,
      maxResults: maxResults,
      seenPaths: &seenPaths,
      files: &files,
      resultTruncated: &resultTruncated,
      applyOrder: &applyOrder
    )
    guard !resultTruncated else {
      return
    }

    for ruleDirectoryPath in Self.scopedInstructionRuleDirectories {
      let ruleDirectory = directory.appendingPathComponent(ruleDirectoryPath)
      var isDirectory = ObjCBool(false)
      guard FileManager.default.fileExists(atPath: ruleDirectory.path, isDirectory: &isDirectory),
        isDirectory.boolValue
      else {
        continue
      }

      for child in try sortedDirectoryChildren(ruleDirectory, includeHidden: true) {
        try appendWorkspaceInstructionFile(
          candidate: child,
          scopeWorkspaceRelativePath: scopeWorkspaceRelativePath,
          includeContent: includeContent,
          maxBytesPerFile: maxBytesPerFile,
          maxResults: maxResults,
          seenPaths: &seenPaths,
          files: &files,
          resultTruncated: &resultTruncated,
          applyOrder: &applyOrder
        )
        guard !resultTruncated else {
          return
        }
      }
    }
  }

  private func appendWorkspaceInstructionFile(
    candidate: URL,
    scopeWorkspaceRelativePath: String,
    includeContent: Bool,
    maxBytesPerFile: Int,
    maxResults: Int,
    seenPaths: inout Set<String>,
    files: inout [WorkspaceInstructionFileInfo],
    resultTruncated: inout Bool,
    applyOrder: inout Int
  ) throws {
    guard !resultTruncated else {
      return
    }
    guard FileManager.default.fileExists(atPath: candidate.path) else {
      return
    }

    let candidateWorkspaceRelativePath = workspaceRelativePathPreservingSymlinks(candidate)
    let resolved = try resolvedWorkspaceURL(candidateWorkspaceRelativePath)
    let info = try fileInfo(url: resolved)
    guard info.type == "file" else {
      return
    }
    guard seenPaths.insert(info.workspaceRelativePath).inserted else {
      return
    }
    guard
      let descriptor =
        agentFileDescriptor(for: candidateWorkspaceRelativePath)
        ?? agentFileDescriptor(for: info.workspaceRelativePath)
    else {
      return
    }
    guard files.count < maxResults else {
      resultTruncated = true
      return
    }

    let content =
      includeContent
      ? try readWorkspaceInstructionContent(url: resolved, maxBytes: maxBytesPerFile) : nil
    files.append(
      WorkspaceInstructionFileInfo(
        info: info,
        kind: descriptor.kind,
        source: descriptor.source,
        scopeWorkspaceRelativePath: scopeWorkspaceRelativePath,
        applyOrder: applyOrder,
        content: content
      ))
    applyOrder += 1
  }

  private func readWorkspaceInstructionContent(url: URL, maxBytes: Int) throws
    -> WorkspaceInstructionContent
  {
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    let truncated = data.count > maxBytes
    let limitedData = truncated ? Data(data.prefix(maxBytes)) : data
    let content = String(data: limitedData, encoding: .utf8)
    return WorkspaceInstructionContent(
      content: content,
      bytesRead: limitedData.count,
      truncated: truncated,
      validUTF8: content != nil
    )
  }

  private func isDocumentationDirectoryPath(_ workspaceRelativePath: String) -> Bool {
    workspaceRelativePath.split(separator: "/").dropLast().contains { component in
      let lowercased = component.lowercased()
      return lowercased == "docs"
        || lowercased == "doc"
        || lowercased == "documentation"
        || lowercased.hasSuffix(".docc")
    }
  }

  private func isDocumentationFileExtension(_ ext: String) -> Bool {
    ["md", "mdx", "txt", "rst", "adoc"].contains(ext)
  }

  private func collectWorkspaceTestFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    testFiles: inout [WorkspaceTestFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let info = try fileInfo(url: child)

      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file", let descriptor = testFileDescriptor(for: info.workspaceRelativePath) {
        guard testFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        testFiles.append(
          WorkspaceTestFileInfo(
            info: info,
            language: descriptor.language,
            matchSource: descriptor.matchSource,
            style: descriptor.style
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceTestFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          testFiles: &testFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func testFileDescriptor(for workspaceRelativePath: String) -> WorkspaceTestFileDescriptor?
  {
    let name = (workspaceRelativePath as NSString).lastPathComponent
    let ext = (name as NSString).pathExtension.lowercased()
    guard let language = Self.testFileExtensions[ext] else {
      return nil
    }

    let stem = (name as NSString).deletingPathExtension
    let lowercasedName = name.lowercased()
    let lowercasedStem = stem.lowercased()
    let components = workspaceRelativePath.split(separator: "/").dropLast().map {
      $0.lowercased()
    }

    if components.contains(where: { Self.testDirectoryNames.contains($0) }) {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "test_directory",
        style: "directory"
      )
    }

    if lowercasedName.contains(".test.") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "dot_test"
      )
    }
    if lowercasedName.contains(".spec.") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "dot_spec"
      )
    }
    if lowercasedStem.hasPrefix("test_") || lowercasedStem.hasPrefix("test-") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "test_prefix"
      )
    }
    if lowercasedStem.hasSuffix("_test") || lowercasedStem.hasSuffix("-test") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "test_suffix"
      )
    }
    if lowercasedStem.hasSuffix("_spec") || lowercasedStem.hasSuffix("-spec") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "spec_suffix"
      )
    }
    if stem.hasSuffix("Test") || stem.hasSuffix("Tests") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "camel_test_suffix"
      )
    }
    if stem.hasSuffix("Spec") || stem.hasSuffix("Specs") {
      return WorkspaceTestFileDescriptor(
        language: language,
        matchSource: "filename_pattern",
        style: "camel_spec_suffix"
      )
    }

    return nil
  }

  private func collectWorkspaceCIFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    ciFiles: inout [WorkspaceCIFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.ciSkippedDirectoryNames.contains(lowercasedName), info.type == "directory" {
        continue
      }
      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file", let descriptor = ciFileDescriptor(for: info.workspaceRelativePath) {
        guard ciFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        ciFiles.append(
          WorkspaceCIFileInfo(
            info: info,
            provider: descriptor.provider,
            category: descriptor.category,
            matchSource: descriptor.matchSource
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceCIFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          ciFiles: &ciFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func ciFileDescriptor(for workspaceRelativePath: String) -> WorkspaceCIFileDescriptor? {
    let components = workspaceRelativePath.split(separator: "/").map { $0.lowercased() }
    let name = components.last ?? ""
    let ext = ((name as NSString).pathExtension).lowercased()

    if ciWorkflowPath(
      components, marker: ".github", folder: "workflows", extensions: Set(["yml", "yaml"]))
    {
      return WorkspaceCIFileDescriptor(
        provider: "github_actions",
        category: "workflow",
        matchSource: "workflow_directory"
      )
    }
    if ciWorkflowPath(
      components, marker: ".gitea", folder: "workflows", extensions: Set(["yml", "yaml"]))
    {
      return WorkspaceCIFileDescriptor(
        provider: "gitea_actions",
        category: "workflow",
        matchSource: "workflow_directory"
      )
    }
    if ciWorkflowPath(
      components, marker: ".forgejo", folder: "workflows", extensions: Set(["yml", "yaml"]))
    {
      return WorkspaceCIFileDescriptor(
        provider: "forgejo_actions",
        category: "workflow",
        matchSource: "workflow_directory"
      )
    }

    guard Self.ciFileExtensions.contains(ext) || name == "jenkinsfile" else {
      return nil
    }

    if name == ".gitlab-ci.yml" || name == ".gitlab-ci.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "gitlab_ci", category: "pipeline", matchSource: "filename")
    }
    if name == "jenkinsfile" {
      return WorkspaceCIFileDescriptor(
        provider: "jenkins", category: "pipeline", matchSource: "filename")
    }
    if name == "azure-pipelines.yml" || name == "azure-pipelines.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "azure_pipelines", category: "pipeline", matchSource: "filename")
    }
    if name == "bitrise.yml" || name == "bitrise.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "bitrise", category: "pipeline", matchSource: "filename")
    }
    if name == "appveyor.yml" || name == "appveyor.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "appveyor", category: "pipeline", matchSource: "filename")
    }
    if name == ".travis.yml" || name == ".travis.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "travis_ci", category: "pipeline", matchSource: "filename")
    }
    if name == ".drone.yml" || name == ".drone.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "drone", category: "pipeline", matchSource: "filename")
    }
    if name == ".woodpecker.yml" || name == ".woodpecker.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "woodpecker", category: "pipeline", matchSource: "filename")
    }
    if name == ".cirrus.yml" || name == ".cirrus.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "cirrus_ci", category: "pipeline", matchSource: "filename")
    }
    if name == "cloudbuild.yml" || name == "cloudbuild.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "google_cloud_build", category: "pipeline", matchSource: "filename")
    }
    if name == "buildspec.yml" || name == "buildspec.yaml" {
      return WorkspaceCIFileDescriptor(
        provider: "aws_codebuild", category: "pipeline", matchSource: "filename")
    }
    if name == "codemagic.yaml" || name == "codemagic.yml" {
      return WorkspaceCIFileDescriptor(
        provider: "codemagic", category: "pipeline", matchSource: "filename")
    }

    if components.count >= 2, components[components.count - 2] == ".circleci",
      name == "config.yml" || name == "config.yaml"
    {
      return WorkspaceCIFileDescriptor(
        provider: "circleci", category: "pipeline", matchSource: "config_directory")
    }
    if components.count >= 2, components[components.count - 2] == ".buildkite",
      ext == "yml" || ext == "yaml"
    {
      return WorkspaceCIFileDescriptor(
        provider: "buildkite", category: "pipeline", matchSource: "config_directory")
    }
    if components.count >= 2, components[components.count - 2] == ".semaphore",
      name == "semaphore.yml" || name == "semaphore.yaml"
    {
      return WorkspaceCIFileDescriptor(
        provider: "semaphore", category: "pipeline", matchSource: "config_directory")
    }

    return nil
  }

  private func ciWorkflowPath(
    _ components: [String],
    marker: String,
    folder: String,
    extensions: Set<String>
  ) -> Bool {
    guard components.count >= 3,
      let index = components.firstIndex(of: marker),
      index + 2 < components.count,
      components[index + 1] == folder
    else {
      return false
    }
    let name = components.last ?? ""
    return extensions.contains(((name as NSString).pathExtension).lowercased())
  }

  private func collectWorkspaceInfraFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    infraFiles: inout [WorkspaceInfraFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.infraSkippedDirectoryNames.contains(lowercasedName), info.type == "directory" {
        continue
      }
      if name.hasPrefix("."), !includeHidden,
        !Self.infraAlwaysIncludedDirectoryNames.contains(lowercasedName)
      {
        continue
      }

      if info.type == "file",
        let descriptor = infraFileDescriptor(for: info.workspaceRelativePath)
      {
        guard infraFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        infraFiles.append(
          WorkspaceInfraFileInfo(
            info: info,
            category: descriptor.category,
            provider: descriptor.provider,
            kind: descriptor.kind,
            format: descriptor.format,
            matchSource: descriptor.matchSource,
            jsonReadable: descriptor.jsonReadable,
            tomlReadable: descriptor.tomlReadable,
            fileExtension: descriptor.fileExtension
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceInfraFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          infraFiles: &infraFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func infraFileDescriptor(for workspaceRelativePath: String)
    -> WorkspaceInfraFileDescriptor?
  {
    let name = (workspaceRelativePath as NSString).lastPathComponent.lowercased()
    let ext = (workspaceRelativePath as NSString).pathExtension.lowercased()

    if var descriptor = Self.infraExactFileDescriptors[name] {
      descriptor.fileExtension = ext
      return descriptor
    }

    if var descriptor = infraFilenamePatternDescriptor(name: name, ext: ext) {
      descriptor.fileExtension = ext
      return descriptor
    }

    if var descriptor = Self.infraFileExtensions[ext] {
      descriptor.fileExtension = ext
      return descriptor
    }

    guard Self.directoryScopedInfraFileExtensions.contains(ext),
      isInInfraDirectory(workspaceRelativePath)
    else {
      return nil
    }

    var descriptor = directoryScopedInfraDescriptor(
      workspaceRelativePath: workspaceRelativePath,
      ext: ext
    )
    descriptor.fileExtension = ext
    return descriptor
  }

  private func infraFilenamePatternDescriptor(name: String, ext: String)
    -> WorkspaceInfraFileDescriptor?
  {
    if name.hasPrefix("dockerfile.") || name.hasSuffix(".dockerfile") {
      return WorkspaceInfraFileDescriptor(
        category: "container",
        provider: "docker",
        kind: "image_build",
        format: "dockerfile",
        matchSource: "filename_pattern"
      )
    }
    if name.hasPrefix("containerfile.") || name.hasSuffix(".containerfile") {
      return WorkspaceInfraFileDescriptor(
        category: "container",
        provider: "containerfile",
        kind: "image_build",
        format: "containerfile",
        matchSource: "filename_pattern"
      )
    }
    if (ext == "yaml" || ext == "yml" || ext == "json") && name.contains("compose") {
      return WorkspaceInfraFileDescriptor(
        category: "container_orchestration",
        provider: "docker_compose",
        kind: "compose_file",
        format: ext == "json" ? "json" : "yaml",
        matchSource: "filename_pattern",
        jsonReadable: ext == "json"
      )
    }
    if name.hasSuffix(".tf.json") || name.hasSuffix(".tfvars.json") {
      return WorkspaceInfraFileDescriptor(
        category: "infrastructure_as_code",
        provider: "terraform",
        kind: name.hasSuffix(".tfvars.json") ? "variables" : "module",
        format: "json",
        matchSource: "filename_pattern",
        jsonReadable: true
      )
    }
    if name.hasSuffix(".pkr.hcl") {
      return WorkspaceInfraFileDescriptor(
        category: "infrastructure_as_code",
        provider: "packer",
        kind: "template",
        format: "hcl",
        matchSource: "filename_pattern"
      )
    }
    if name.hasSuffix(".nomad") || name.hasSuffix(".nomad.hcl") {
      return WorkspaceInfraFileDescriptor(
        category: "orchestration",
        provider: "nomad",
        kind: "job",
        format: ext == "hcl" ? "hcl" : "nomad",
        matchSource: "filename_pattern"
      )
    }

    return nil
  }

  private func directoryScopedInfraDescriptor(
    workspaceRelativePath: String,
    ext: String
  ) -> WorkspaceInfraFileDescriptor {
    let components = workspaceRelativePath.split(separator: "/").map { $0.lowercased() }
    let format = infraFormat(for: ext)

    if components.contains(".devcontainer") || components.contains("devcontainer") {
      return WorkspaceInfraFileDescriptor(
        category: "development_container",
        provider: "devcontainer",
        kind: "dev_environment",
        format: format,
        matchSource: "infra_directory",
        jsonReadable: ext == "json"
      )
    }
    if components.contains("helm") || components.contains("chart") || components.contains("charts")
    {
      return WorkspaceInfraFileDescriptor(
        category: "package_deployment",
        provider: "helm",
        kind: "chart_manifest",
        format: format,
        matchSource: "infra_directory",
        jsonReadable: ext == "json",
        tomlReadable: ext == "toml"
      )
    }
    if components.contains("k8s") || components.contains("kube")
      || components.contains("kubernetes") || components.contains("manifest")
      || components.contains("manifests")
    {
      return WorkspaceInfraFileDescriptor(
        category: "orchestration",
        provider: "kubernetes",
        kind: "manifest",
        format: format,
        matchSource: "infra_directory",
        jsonReadable: ext == "json"
      )
    }
    if components.contains("terraform") {
      return WorkspaceInfraFileDescriptor(
        category: "infrastructure_as_code",
        provider: "terraform",
        kind: "module",
        format: format,
        matchSource: "infra_directory",
        jsonReadable: ext == "json",
        tomlReadable: ext == "toml"
      )
    }

    return WorkspaceInfraFileDescriptor(
      category: "deployment",
      provider: "generic",
      kind: "deployment_manifest",
      format: format,
      matchSource: "infra_directory",
      jsonReadable: ext == "json",
      tomlReadable: ext == "toml"
    )
  }

  private func infraFormat(for ext: String) -> String {
    switch ext {
    case "yml", "yaml":
      return "yaml"
    case "json", "jsonc":
      return ext
    case "toml":
      return "toml"
    case "hcl":
      return "hcl"
    default:
      return ext
    }
  }

  private func isInInfraDirectory(_ workspaceRelativePath: String) -> Bool {
    let directory = (workspaceRelativePath as NSString).deletingLastPathComponent
    guard !directory.isEmpty, directory != "." else {
      return false
    }
    return directory.split(separator: "/").contains { component in
      Self.infraDirectoryNames.contains(component.lowercased())
    }
  }

  private func collectWorkspaceConfigFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    configFiles: inout [WorkspaceConfigFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.configSkippedDirectoryNames.contains(lowercasedName), info.type == "directory" {
        continue
      }
      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file", let descriptor = configFileDescriptor(for: info.workspaceRelativePath)
      {
        guard configFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        configFiles.append(
          WorkspaceConfigFileInfo(
            info: info,
            tool: descriptor.tool,
            category: descriptor.category,
