  private func collectWorkspaceOutlineItems(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    includeTests: Bool,
    includeImports: Bool,
    maxFiles: Int,
    maxItems: Int,
    maxBytesPerFile: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    outlineFileCount: inout Int,
    bytesScanned: inout Int,
    fileTruncatedCount: inout Int,
    invalidUTF8FileCount: inout Int,
    items: inout [WorkspaceOutlineItem],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.sourceSkippedDirectoryNames.contains(lowercasedName), info.type == "directory" {
        continue
      }
      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file" {
        try appendWorkspaceOutlineItems(
          url: child,
          info: info,
          includeTests: includeTests,
          includeImports: includeImports,
          maxFiles: maxFiles,
          maxItems: maxItems,
          maxBytesPerFile: maxBytesPerFile,
          outlineFileCount: &outlineFileCount,
          bytesScanned: &bytesScanned,
          fileTruncatedCount: &fileTruncatedCount,
          invalidUTF8FileCount: &invalidUTF8FileCount,
          items: &items,
          resultTruncated: &resultTruncated
        )
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceOutlineItems(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          includeTests: includeTests,
          includeImports: includeImports,
          maxFiles: maxFiles,
          maxItems: maxItems,
          maxBytesPerFile: maxBytesPerFile,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          outlineFileCount: &outlineFileCount,
          bytesScanned: &bytesScanned,
          fileTruncatedCount: &fileTruncatedCount,
          invalidUTF8FileCount: &invalidUTF8FileCount,
          items: &items,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func appendWorkspaceOutlineItems(
    url: URL,
    info: FileInfo,
    includeTests: Bool,
    includeImports: Bool,
    maxFiles: Int,
    maxItems: Int,
    maxBytesPerFile: Int,
    outlineFileCount: inout Int,
    bytesScanned: inout Int,
    fileTruncatedCount: inout Int,
    invalidUTF8FileCount: inout Int,
    items: inout [WorkspaceOutlineItem],
    resultTruncated: inout Bool
  ) throws {
    guard !resultTruncated else {
      return
    }
    guard info.type == "file", let language = outlineLanguage(for: url) else {
      return
    }
    guard includeTests || testFileDescriptor(for: info.workspaceRelativePath) == nil else {
      return
    }
    guard outlineFileCount < maxFiles else {
      resultTruncated = true
      return
    }

    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytesPerFile + 1) ?? Data()
    let fileTruncated = data.count > maxBytesPerFile
    let contentData = fileTruncated ? Data(data.prefix(maxBytesPerFile)) : data
    guard let content = String(data: contentData, encoding: .utf8) else {
      invalidUTF8FileCount += 1
      return
    }

    outlineFileCount += 1
    bytesScanned += contentData.count
    if fileTruncated {
      fileTruncatedCount += 1
    }

    for item in outlineItems(in: content, language: language, includeImports: includeImports) {
      guard items.count < maxItems else {
        resultTruncated = true
        return
      }
      items.append(
        WorkspaceOutlineItem(
          info: info,
          language: language,
          item: item,
          fileTruncated: fileTruncated
        ))
    }
  }

  private func sourceFileDescriptor(for workspaceRelativePath: String)
    -> WorkspaceSourceFileDescriptor?
  {
    let name = (workspaceRelativePath as NSString).lastPathComponent
    let ext = (name as NSString).pathExtension.lowercased()
    guard let descriptor = Self.sourceFileExtensions[ext] else {
      return nil
    }
    return descriptor
  }

  private func collectWorkspaceGovernanceFiles(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxResults: Int,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    governanceFiles: inout [WorkspaceGovernanceFileInfo],
    scanTruncated: inout Bool,
    resultTruncated: inout Bool
  ) throws {
    guard !scanTruncated, !resultTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated, !resultTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.governanceSkippedDirectoryNames.contains(lowercasedName),
        info.type == "directory"
      {
        continue
      }
      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if let descriptor = governanceDescriptor(for: info) {
        guard governanceFiles.count < maxResults else {
          resultTruncated = true
          return
        }
        governanceFiles.append(
          WorkspaceGovernanceFileInfo(
            info: info,
            category: descriptor.category,
            provider: descriptor.provider,
            kind: descriptor.kind,
            format: descriptor.format,
            matchSource: descriptor.matchSource,
            jsonReadable: descriptor.jsonReadable,
            tomlReadable: descriptor.tomlReadable
          ))
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceGovernanceFiles(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxResults: maxResults,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          governanceFiles: &governanceFiles,
          scanTruncated: &scanTruncated,
          resultTruncated: &resultTruncated
        )
      }
    }
  }

  private func governanceDescriptor(for info: FileInfo) -> WorkspaceGovernanceDescriptor? {
    let relativePath = info.workspaceRelativePath
    let components = relativePath.split(separator: "/").map { $0.lowercased() }
    let name = components.last ?? ""

    if info.type == "directory", let descriptor = governanceDirectoryDescriptor(components) {
      return descriptor
    }

    if components == ["_ops", "bin", "workspace"], info.type == "file" {
      return WorkspaceGovernanceDescriptor(
        category: "workspace_ops",
        provider: "workspace",
        kind: "workspace_cli",
        format: "executable",
        matchSource: "path"
      )
    }

    if components == [".codex", "skills", "workspace", "skill.md"]
      || components == [".agents", "skills", "workspace", "skill.md"]
    {
      return WorkspaceGovernanceDescriptor(
        category: "agent_governance",
        provider: "workspace_skill",
        kind: "workspace_skill",
        format: "markdown",
        matchSource: "path"
      )
    }

    if components.count >= 2,
      components[components.count - 2] == ".github",
      name == "codeowners"
    {
      return WorkspaceGovernanceDescriptor(
        category: "collaboration_governance",
        provider: "github",
        kind: "ownership_rules",
        format: "text",
        matchSource: "path"
      )
    }

    guard info.type == "file", let descriptor = Self.governanceFileDescriptors[name] else {
      return nil
    }
    return descriptor
  }

  private func governanceDirectoryDescriptor(_ components: [String])
    -> WorkspaceGovernanceDescriptor?
  {
    if components == ["_ops"] {
      return WorkspaceGovernanceDescriptor(
        category: "workspace_ops",
        provider: "workspace",
        kind: "ops_root",
        format: "directory",
        matchSource: "path"
      )
    }
    if components == ["_ops", "bin"] {
      return WorkspaceGovernanceDescriptor(
        category: "workspace_ops",
        provider: "workspace",
        kind: "ops_bin_directory",
        format: "directory",
        matchSource: "path"
      )
    }
    if components == ["_ops", "scaffold"] || components == ["_ops", "scaffolds"] {
      return WorkspaceGovernanceDescriptor(
        category: "workspace_scaffold",
        provider: "workspace",
        kind: "scaffold_root",
        format: "directory",
        matchSource: "path"
      )
    }
    if components == ["references"] {
      return WorkspaceGovernanceDescriptor(
        category: "workspace_references",
        provider: "workspace",
        kind: "references_root",
        format: "directory",
        matchSource: "path"
      )
    }
    if components.count >= 2, components[0] == "references" {
      switch components[1] {
      case "upstreams":
        return WorkspaceGovernanceDescriptor(
          category: "workspace_references",
          provider: "workspace",
          kind: components.count == 2 ? "upstream_refs_root" : "upstream_reference",
          format: "directory",
          matchSource: "path"
        )
      case "forks":
        return WorkspaceGovernanceDescriptor(
          category: "workspace_references",
          provider: "workspace",
          kind: components.count == 2 ? "fork_refs_root" : "fork_reference",
          format: "directory",
          matchSource: "path"
        )
      case "mirrors":
        return WorkspaceGovernanceDescriptor(
          category: "workspace_references",
          provider: "workspace",
          kind: components.count == 2 ? "mirror_refs_root" : "mirror_reference",
          format: "directory",
          matchSource: "path"
        )
      default:
        break
      }
    }
    if components.count >= 3,
      components[0] == "refs",
      components[1] == "notes",
      components[2] == "workspace"
    {
      return WorkspaceGovernanceDescriptor(
        category: "workspace_refs",
        provider: "workspace",
        kind: "workspace_notes",
        format: "directory",
        matchSource: "path"
      )
    }
    return nil
  }

  private func collectWorkspaceCommandManifests(
    directory: URL,
    currentDepth: Int,
    maxDepth: Int,
    includeHidden: Bool,
    maxScanEntries: Int,
    scannedEntries: inout Int,
    manifests: inout [FileInfo],
    scanTruncated: inout Bool
  ) throws {
    guard !scanTruncated else {
      return
    }

    for child in try sortedDirectoryChildren(directory, includeHidden: true) {
      guard !scanTruncated else {
        return
      }
      guard scannedEntries < maxScanEntries else {
        scanTruncated = true
        return
      }

      scannedEntries += 1
      let name = child.lastPathComponent
      let lowercasedName = name.lowercased()
      let info = try fileInfo(url: child)

      if Self.sourceSkippedDirectoryNames.contains(lowercasedName), info.type == "directory" {
        continue
      }
      if name.hasPrefix("."), !includeHidden {
        continue
      }

      if info.type == "file", Self.commandManifestNames.contains(name) {
        manifests.append(info)
      }

      if info.type == "directory", currentDepth < maxDepth {
        try collectWorkspaceCommandManifests(
          directory: child,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          includeHidden: includeHidden,
          maxScanEntries: maxScanEntries,
          scannedEntries: &scannedEntries,
          manifests: &manifests,
          scanTruncated: &scanTruncated
        )
      }
    }
  }

  private func parseWorkspaceCommandManifest(
    info: FileInfo,
    maxBytesPerFile: Int
  ) -> WorkspaceCommandManifestParseResult {
    let url = URL(fileURLWithPath: info.path)
    let name = url.lastPathComponent
    let cwd = (info.workspaceRelativePath as NSString).deletingLastPathComponent
    let normalizedCWD = cwd == "." ? "" : cwd
    let readResult: WorkspaceCommandManifestReadResult
    do {
      readResult = try readWorkspaceCommandManifest(url: url, maxBytesPerFile: maxBytesPerFile)
    } catch {
      return WorkspaceCommandManifestParseResult(
        commands: [],
        errors: [
          WorkspaceCommandParseError(
            sourceWorkspaceRelativePath: info.workspaceRelativePath,
            message: error.localizedDescription)
        ],
        fileTruncated: false
      )
    }

    if let parseError = readResult.parseError {
      return WorkspaceCommandManifestParseResult(
        commands: [],
        errors: [
          WorkspaceCommandParseError(
            sourceWorkspaceRelativePath: info.workspaceRelativePath,
            message: parseError)
        ],
        fileTruncated: readResult.fileTruncated
      )
    }

    switch name {
    case "package.json":
      return parsePackageJSONCommands(
        content: readResult.content,
        info: info,
        cwdWorkspaceRelativePath: normalizedCWD,
        fileTruncated: readResult.fileTruncated
      )
    case "Package.swift":
      return WorkspaceCommandManifestParseResult(
        commands: swiftPackageCommands(info: info, cwdWorkspaceRelativePath: normalizedCWD),
        errors: [],
        fileTruncated: readResult.fileTruncated
      )
    case "Cargo.toml":
      return parseCargoCommands(
        content: readResult.content,
        info: info,
        cwdWorkspaceRelativePath: normalizedCWD,
        fileTruncated: readResult.fileTruncated
      )
    case "go.mod":
      return parseGoModCommands(
        content: readResult.content,
        info: info,
        cwdWorkspaceRelativePath: normalizedCWD,
        fileTruncated: readResult.fileTruncated
      )
    case "Makefile", "makefile", "GNUmakefile":
      return parseMakefileCommands(
        content: readResult.content,
        info: info,
        cwdWorkspaceRelativePath: normalizedCWD,
        fileTruncated: readResult.fileTruncated,
        executable: "make"
      )
    case "Justfile", "justfile":
      return parseMakefileCommands(
        content: readResult.content,
        info: info,
        cwdWorkspaceRelativePath: normalizedCWD,
        fileTruncated: readResult.fileTruncated,
        executable: "just"
      )
    default:
      return WorkspaceCommandManifestParseResult(
        commands: [],
        errors: [],
        fileTruncated: readResult.fileTruncated
      )
    }
  }

  private func readWorkspaceCommandManifest(
    url: URL,
    maxBytesPerFile: Int
  ) throws -> WorkspaceCommandManifestReadResult {
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }

    let data = try handle.read(upToCount: maxBytesPerFile + 1) ?? Data()
    let fileTruncated = data.count > maxBytesPerFile
    let limitedData = fileTruncated ? Data(data.prefix(maxBytesPerFile)) : data
    guard !limitedData.contains(0) else {
      return WorkspaceCommandManifestReadResult(
        content: "",
        fileTruncated: fileTruncated,
        parseError: "File appears to be binary."
      )
    }
    guard let content = String(data: limitedData, encoding: .utf8) else {
      return WorkspaceCommandManifestReadResult(
        content: "",
        fileTruncated: fileTruncated,
        parseError: "File is not valid UTF-8."
      )
    }
    return WorkspaceCommandManifestReadResult(
      content: content,
      fileTruncated: fileTruncated,
      parseError: nil
    )
  }

  private func parsePackageJSONCommands(
    content: String,
    info: FileInfo,
    cwdWorkspaceRelativePath: String,
    fileTruncated: Bool
  ) -> WorkspaceCommandManifestParseResult {
    let data = Data(content.utf8)
    let value: JSONValue
    do {
      value = try JSONDecoder().decode(JSONValue.self, from: data)
    } catch {
      return WorkspaceCommandManifestParseResult(
        commands: [],
        errors: [
          WorkspaceCommandParseError(
            sourceWorkspaceRelativePath: info.workspaceRelativePath,
            message: "Unable to parse package.json: \(error.localizedDescription)")
        ],
        fileTruncated: fileTruncated
      )
    }

    guard let object = value.objectValue else {
      return WorkspaceCommandManifestParseResult(
        commands: [],
        errors: [
          WorkspaceCommandParseError(
            sourceWorkspaceRelativePath: info.workspaceRelativePath,
            message: "package.json root is not an object.")
        ],
        fileTruncated: fileTruncated
      )
    }

    let packageManager = nodePackageManager(
      packageManagerField: object["packageManager"]?.stringValue,
      cwdWorkspaceRelativePath: cwdWorkspaceRelativePath
    )
    let scripts = object["scripts"]?.objectValue ?? [:]
    let commands = scripts.keys.sorted().compactMap { scriptName -> WorkspaceCommandInfo? in
      guard let definition = scripts[scriptName]?.stringValue else {
        return nil
      }
      return commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "node",
        kind: "package_script",
        name: scriptName,
        definition: definition,
        definitionSource: "package.json:scripts",
        suggestedCLIID: packageManager,
        requiredExecutable: packageManager,
        argv: ["run", scriptName],
        fileTruncated: fileTruncated
      )
    }

    return WorkspaceCommandManifestParseResult(
      commands: commands,
      errors: [],
      fileTruncated: fileTruncated
    )
  }

  private func nodePackageManager(
    packageManagerField: String?,
    cwdWorkspaceRelativePath: String
  ) -> String {
    if let packageManagerField {
      if packageManagerField.hasPrefix("pnpm@") {
        return "pnpm"
      }
      if packageManagerField.hasPrefix("yarn@") {
        return "yarn"
      }
      if packageManagerField.hasPrefix("bun@") {
        return "bun"
      }
      if packageManagerField.hasPrefix("npm@") {
        return "npm"
      }
    }

    let directory = workspaceURL(forRelativeDirectory: cwdWorkspaceRelativePath)
    if FileManager.default.fileExists(
      atPath: directory.appendingPathComponent("pnpm-lock.yaml").path)
    {
      return "pnpm"
    }
    if FileManager.default.fileExists(atPath: directory.appendingPathComponent("yarn.lock").path) {
      return "yarn"
    }
    if FileManager.default.fileExists(atPath: directory.appendingPathComponent("bun.lock").path)
      || FileManager.default.fileExists(atPath: directory.appendingPathComponent("bun.lockb").path)
    {
      return "bun"
    }
    return "npm"
  }

  private func swiftPackageCommands(
    info: FileInfo,
    cwdWorkspaceRelativePath: String
  ) -> [WorkspaceCommandInfo] {
    [
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "swift",
        kind: "standard_command",
        name: "build",
        definition: nil,
        definitionSource: "swiftpm",
        suggestedCLIID: "swift",
        requiredExecutable: "swift",
        argv: ["build"],
        fileTruncated: false
      ),
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "swift",
        kind: "standard_command",
        name: "test",
        definition: nil,
        definitionSource: "swiftpm",
        suggestedCLIID: "swift",
        requiredExecutable: "swift",
        argv: ["test"],
        fileTruncated: false
      ),
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "swift",
        kind: "standard_command",
        name: "describe",
        definition: nil,
        definitionSource: "swiftpm",
        suggestedCLIID: "swift",
        requiredExecutable: "swift",
        argv: ["package", "describe", "--type", "json"],
        fileTruncated: false
      ),
    ]
  }

  private func parseCargoCommands(
    content: String,
    info: FileInfo,
    cwdWorkspaceRelativePath: String,
    fileTruncated: Bool
  ) -> WorkspaceCommandManifestParseResult {
    let hasMain = FileManager.default.fileExists(
      atPath: workspaceURL(forRelativeDirectory: cwdWorkspaceRelativePath)
        .appendingPathComponent("src/main.rs").path)
    var commands = [
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "rust",
        kind: "standard_command",
        name: "build",
        definition: nil,
        definitionSource: "cargo",
        suggestedCLIID: "cargo",
        requiredExecutable: "cargo",
        argv: ["build"],
        fileTruncated: fileTruncated
      ),
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "rust",
        kind: "standard_command",
        name: "test",
        definition: nil,
        definitionSource: "cargo",
        suggestedCLIID: "cargo",
        requiredExecutable: "cargo",
        argv: ["test"],
        fileTruncated: fileTruncated
      ),
    ]
    if hasMain || content.contains("[[bin]]") {
      commands.append(
        commandInfo(
          source: info,
          cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
          ecosystem: "rust",
          kind: "standard_command",
          name: "run",
          definition: nil,
          definitionSource: "cargo",
          suggestedCLIID: "cargo",
          requiredExecutable: "cargo",
          argv: ["run"],
          fileTruncated: fileTruncated
        ))
    }
    return WorkspaceCommandManifestParseResult(
      commands: commands,
      errors: [],
      fileTruncated: fileTruncated
    )
  }

  private func parseGoModCommands(
    content: String,
    info: FileInfo,
    cwdWorkspaceRelativePath: String,
    fileTruncated: Bool
  ) -> WorkspaceCommandManifestParseResult {
    let moduleName = content.split(separator: "\n", omittingEmptySubsequences: false)
      .first { $0.trimmingCharacters(in: .whitespaces).hasPrefix("module ") }
      .map { line in
        String(line.trimmingCharacters(in: .whitespaces).dropFirst("module ".count))
      }

    let commands = [
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "go",
        kind: "standard_command",
        name: "test",
        definition: moduleName,
        definitionSource: "go.mod:module",
        suggestedCLIID: "go",
        requiredExecutable: "go",
        argv: ["test", "./..."],
        fileTruncated: fileTruncated
      ),
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "go",
        kind: "standard_command",
        name: "build",
        definition: moduleName,
        definitionSource: "go.mod:module",
        suggestedCLIID: "go",
        requiredExecutable: "go",
        argv: ["build", "./..."],
        fileTruncated: fileTruncated
      ),
      commandInfo(
        source: info,
        cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
        ecosystem: "go",
        kind: "standard_command",
        name: "list",
        definition: moduleName,
        definitionSource: "go.mod:module",
        suggestedCLIID: "go",
        requiredExecutable: "go",
        argv: ["list", "./..."],
        fileTruncated: fileTruncated
      ),
    ]

    return WorkspaceCommandManifestParseResult(
      commands: commands,
      errors: [],
      fileTruncated: fileTruncated
    )
  }

  private func parseMakefileCommands(
    content: String,
    info: FileInfo,
    cwdWorkspaceRelativePath: String,
    fileTruncated: Bool,
    executable: String
  ) -> WorkspaceCommandManifestParseResult {
    var commands: [WorkspaceCommandInfo] = []
    var seen = Set<String>()
    for rawLine in content.split(separator: "\n", omittingEmptySubsequences: false) {
      let line = String(rawLine)
      guard let targets = makefileTargets(in: line) else {
        continue
      }
      for target in targets where seen.insert(target).inserted {
        commands.append(
          commandInfo(
            source: info,
            cwdWorkspaceRelativePath: cwdWorkspaceRelativePath,
            ecosystem: executable == "just" ? "just" : "make",
            kind: "target",
            name: target,
            definition: nil,
            definitionSource: "\(info.workspaceRelativePath):target",
            suggestedCLIID: executable,
            requiredExecutable: executable,
            argv: [target],
            fileTruncated: fileTruncated
          ))
      }
    }

    return WorkspaceCommandManifestParseResult(
      commands: commands,
      errors: [],
      fileTruncated: fileTruncated
    )
  }

  private func makefileTargets(in line: String) -> [String]? {
    guard !line.isEmpty, !line.hasPrefix("\t"), !line.hasPrefix(" ") else {
      return nil
    }
    guard let colon = line.firstIndex(of: ":") else {
      return nil
    }
    let left = String(line[..<colon]).trimmingCharacters(in: .whitespaces)
    guard !left.isEmpty, !left.hasPrefix("."), !left.contains("="), !left.contains("%") else {
      return nil
    }
    let afterColon = line[line.index(after: colon)...]
    if afterColon.first == "=" {
      return nil
    }

    let targets = left.split(whereSeparator: { $0 == " " || $0 == "\t" })
      .map(String.init)
      .filter(isMakefileTargetName)
    return targets.isEmpty ? nil : targets
  }

  private func isMakefileTargetName(_ name: String) -> Bool {
    guard !name.isEmpty else {
      return false
    }
    return name.unicodeScalars.allSatisfy { scalar in
      (scalar.value >= 48 && scalar.value <= 57)
        || (scalar.value >= 65 && scalar.value <= 90)
        || (scalar.value >= 97 && scalar.value <= 122)
        || scalar.value == 45
        || scalar.value == 46
        || scalar.value == 47
        || scalar.value == 95
    }
  }

  private func commandInfo(
    source: FileInfo,
    cwdWorkspaceRelativePath: String,
    ecosystem: String,
    kind: String,
    name: String,
    definition: String?,
    definitionSource: String,
    suggestedCLIID: String,
    requiredExecutable: String,
    argv: [String],
    fileTruncated: Bool
  ) -> WorkspaceCommandInfo {
    WorkspaceCommandInfo(
      sourcePath: source.path,
      sourceWorkspaceRelativePath: source.workspaceRelativePath,
      cwdWorkspaceRelativePath: cwdWorkspaceRelativePath.isEmpty ? "." : cwdWorkspaceRelativePath,
      ecosystem: ecosystem,
      kind: kind,
      name: name,
      definition: definition.map { limitedCommandDefinition($0) },
      definitionTruncated: definition.map { $0 != limitedCommandDefinition($0) } ?? false,
      definitionSource: definitionSource,
      executorTool: "cli.exec",
      suggestedCLIID: suggestedCLIID,
      registeredCLIProvider: configuration.cli.commands.contains { $0.id == suggestedCLIID },
      requiredExecutable: requiredExecutable,
      argv: argv,
      fileTruncated: fileTruncated
    )
  }

  private func limitedCommandDefinition(_ value: String) -> String {
    String(value.prefix(500))
  }

  private func workspaceURL(forRelativeDirectory path: String) -> URL {
    if path.isEmpty || path == "." {
      return configuration.workspaceDirectory
    }
    return configuration.workspaceDirectory.appendingPathComponent(path, isDirectory: true)
  }

  private func sortedDirectoryChildren(_ directory: URL, includeHidden: Bool) throws -> [URL] {
    try FileManager.default.contentsOfDirectory(atPath: directory.path)
      .filter { includeHidden || !$0.hasPrefix(".") }
      .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
      .map { directory.appendingPathComponent($0) }
  }

  private func macOSApplicationRoots(includeSystem: Bool, includeUser: Bool) -> [URL] {
    var roots: [URL] = []
    if includeSystem {
      roots.append(URL(fileURLWithPath: "/Applications", isDirectory: true))
      roots.append(URL(fileURLWithPath: "/System/Applications", isDirectory: true))
    }
    if includeUser {
      roots.append(
        FileManager.default.homeDirectoryForCurrentUser
          .appendingPathComponent("Applications", isDirectory: true))
    }
    var seen = Set<String>()
    return roots.filter { root in
      let path = root.standardizedFileURL.path
      guard seen.insert(path).inserted else {
        return false
      }
      return true
    }
  }

  private func collectMacOSApplications(
    root: URL,
    currentDepth: Int,
    maxDepth: Int,
    maxResults: Int,
    maxVisited: Int,
    applications: inout [MacOSApplicationInfo],
    visited: inout Int,
    truncated: inout Bool
  ) throws {
    guard !truncated else {
      return
    }
    guard applications.count < maxResults else {
      truncated = true
      return
    }
    var isDirectory: ObjCBool = false
    guard FileManager.default.fileExists(atPath: root.path, isDirectory: &isDirectory),
      isDirectory.boolValue
    else {
      return
    }

    for url in try sortedDirectoryChildren(root, includeHidden: false) {
      guard !truncated else {
        return
      }
      guard visited < maxVisited else {
        truncated = true
        return
      }
      visited += 1
      if url.pathExtension == "app" {
        guard applications.count < maxResults else {
          truncated = true
          return
        }
        applications.append(macOSApplicationInfo(url: url))
        continue
      }

      if currentDepth < maxDepth {
        var childIsDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: url.path, isDirectory: &childIsDirectory),
          childIsDirectory.boolValue
        else {
          continue
        }
        try collectMacOSApplications(
          root: url,
          currentDepth: currentDepth + 1,
          maxDepth: maxDepth,
          maxResults: maxResults,
          maxVisited: maxVisited,
          applications: &applications,
          visited: &visited,
          truncated: &truncated
        )
      }
    }
  }

  private func macOSApplicationInfo(url: URL) -> MacOSApplicationInfo {
    let bundle = Bundle(url: url)
    let resourceValues = try? url.resourceValues(forKeys: [.localizedNameKey])
    return MacOSApplicationInfo(
      name: resourceValues?.localizedName ?? url.deletingPathExtension().lastPathComponent,
      path: url.standardizedFileURL.path,
      bundleIdentifier: bundle?.bundleIdentifier,
      version: bundle?.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
    )
  }

  private func rectJSON(_ rect: CGRect) -> JSONValue {
    .object([
      "x": .number(Double(rect.origin.x)),
      "y": .number(Double(rect.origin.y)),
      "width": .number(Double(rect.width)),
      "height": .number(Double(rect.height)),
    ])
  }

  private func validateNetworkInterfaceName(_ name: String) throws {
    try validateUTF8ByteLimit(name, name: "interface", maxBytes: 64)
    guard !name.hasPrefix("-") else {
      throw GatewayToolError.invalidArguments("interface must not be an option.")
    }
    let allowed = CharacterSet(
      charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._-")
    guard name.unicodeScalars.allSatisfy({ allowed.contains($0) }) else {
      throw GatewayToolError.invalidArguments(
        "interface may contain only letters, digits, dot, underscore, or hyphen.")
    }
  }

  private func validateNetworkHost(_ host: String) throws {
    try validateUTF8ByteLimit(host, name: "host", maxBytes: 253)
    guard !host.isEmpty else {
      throw GatewayToolError.invalidArguments("host must not be empty.")
    }
    guard !host.hasPrefix("-") else {
      throw GatewayToolError.invalidArguments("host must not be an option.")
    }
    guard host.rangeOfCharacter(from: .whitespacesAndNewlines) == nil else {
      throw GatewayToolError.invalidArguments("host must not contain whitespace.")
    }
    guard !host.contains("/") && !host.contains("@") else {
      throw GatewayToolError.invalidArguments("host must be a hostname or IP address, not a URL.")
    }
    let allowed = CharacterSet(
      charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.-:%_")
    guard host.unicodeScalars.allSatisfy({ allowed.contains($0) }) else {
      throw GatewayToolError.invalidArguments(
        "host may contain only letters, digits, dot, hyphen, colon, percent, or underscore.")
    }
  }

  private func validateHTTPCheckURL(_ value: String) throws -> URL {
    try validateUTF8ByteLimit(value, name: "url", maxBytes: 4_096)
    guard !value.isEmpty else {
      throw GatewayToolError.invalidArguments("url must not be empty.")
    }
    guard value.rangeOfCharacter(from: .whitespacesAndNewlines) == nil else {
      throw GatewayToolError.invalidArguments("url must not contain whitespace.")
    }
    guard
      value.unicodeScalars.allSatisfy({ scalar in
        !((scalar.value <= 0x1F) || (scalar.value >= 0x7F && scalar.value <= 0x9F))
      })
    else {
      throw GatewayToolError.invalidArguments("url must not contain control characters.")
    }
    guard var components = URLComponents(string: value),
      let scheme = components.scheme?.lowercased(),
      scheme == "http" || scheme == "https",
      let host = components.host,
      !host.isEmpty
    else {
      throw GatewayToolError.invalidArguments("url must be an absolute http or https URL.")
    }
    guard components.user == nil, components.password == nil else {
      throw GatewayToolError.invalidArguments("url must not contain userinfo credentials.")
    }
    components.scheme = scheme
    guard let url = components.url else {
      throw GatewayToolError.invalidArguments("url must be a valid absolute URL.")
    }
    return url
  }

  private func validateNetworkPort(_ port: Int) throws {
    guard (1...65_535).contains(port) else {
      throw GatewayToolError.invalidArguments("port must be between 1 and 65535.")
    }
  }

  private func emptyStringAsNil(_ value: String?) -> String? {
    guard let value, !value.isEmpty else {
      return nil
    }
    return value
  }

  private func addressFamilyValue(_ family: String) throws -> Int32 {
    switch family {
    case "any", "all":
      return AF_UNSPEC
    case "ipv4", "inet":
      return AF_INET
    case "ipv6", "inet6":
      return AF_INET6
    default:
      throw GatewayToolError.invalidArguments(
        "family must be any, all, ipv4, inet, ipv6, or inet6.")
    }
  }

  private func addressFamilyName(_ family: Int32) -> String {
    switch family {
    case AF_INET:
      return "ipv4"
    case AF_INET6:
      return "ipv6"
    case AF_UNSPEC:
      return "any"
    default:
      return "unknown"
    }
  }

  private func socketTypeName(_ socketType: Int32) -> String {
    switch socketType {
    case SOCK_STREAM:
      return "stream"
    case SOCK_DGRAM:
      return "datagram"
    case SOCK_RAW:
      return "raw"
    default:
      return "unknown"
    }
  }

  private func numericHostAddress(_ pointer: UnsafeMutablePointer<addrinfo>) -> String? {
    var host = [CChar](repeating: 0, count: Int(NI_MAXHOST))
    let status = host.withUnsafeMutableBufferPointer { buffer in
      getnameinfo(
        pointer.pointee.ai_addr,
        pointer.pointee.ai_addrlen,
        buffer.baseAddress,
        socklen_t(buffer.count),
        nil,
        0,
        NI_NUMERICHOST
      )
    }
    guard status == 0 else {
      return nil
    }
    return stringFromNullTerminatedCString(host)
  }

  private func validateExecutableLookupName(_ name: String) throws {
    try validateUTF8ByteLimit(name, name: "name", maxBytes: 128)
    guard !name.isEmpty else {
      throw GatewayToolError.invalidArguments("name must not be empty.")
    }
    guard !name.hasPrefix("-") else {
      throw GatewayToolError.invalidArguments("name must not start with an option marker.")
    }
    guard name != "." && name != ".." else {
      throw GatewayToolError.invalidArguments("name must be an executable basename.")
    }
    let allowed = CharacterSet(
      charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._+@-")
    guard name.unicodeScalars.allSatisfy({ allowed.contains($0) }) else {
      throw GatewayToolError.invalidArguments(
        "name must be an executable basename without slashes or whitespace.")
    }
  }

  private func validateSymbolicLinkDestination(_ destination: String) throws {
    try validateUTF8ByteLimit(destination, name: "destination", maxBytes: 4_096)
    guard !destination.isEmpty else {
      throw GatewayToolError.invalidArguments("destination must not be empty.")
    }
    guard !destination.contains("\0") else {
      throw GatewayToolError.invalidArguments("destination must not contain null bytes.")
    }
  }

  private func validateMetadataAttributeName(_ name: String) throws {
    try validateUTF8ByteLimit(name, name: "attribute", maxBytes: 128)
    guard !name.isEmpty else {
      throw GatewayToolError.invalidArguments("attributes must not contain empty strings.")
    }
    guard !name.hasPrefix("-") else {
      throw GatewayToolError.invalidArguments("attribute must not be an option.")
    }
    let allowed = CharacterSet(
      charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.$")
    guard name.unicodeScalars.allSatisfy({ allowed.contains($0) }) else {
      throw GatewayToolError.invalidArguments(
        "attribute may contain only letters, digits, underscore, dot, or dollar sign.")
    }
  }

  private func validateExtendedAttributeName(_ name: String) throws {
    try validateUTF8ByteLimit(name, name: "name", maxBytes: 255)
    guard !name.isEmpty else {
      throw GatewayToolError.invalidArguments("name must not be empty.")
    }
    guard !name.contains("\0") else {
      throw GatewayToolError.invalidArguments("name must not contain null bytes.")
    }
    guard
      name.unicodeScalars.allSatisfy({ scalar in
        scalar.value >= 0x20 && scalar.value != 0x7F
      })
    else {
      throw GatewayToolError.invalidArguments("name must not contain control characters.")
    }
  }

  private func passwdJSON(for uid: uid_t) -> JSONValue {
    guard let pointer = getpwuid(uid) else {
      return .null
    }
    let value = pointer.pointee
    return .object([
      "uid": .number(Double(value.pw_uid)),
      "gid": .number(Double(value.pw_gid)),
      "name": cStringJSON(value.pw_name),
      "home_directory": cStringJSON(value.pw_dir),
      "shell": cStringJSON(value.pw_shell),
    ])
  }

  private func groupJSON(for gid: gid_t) -> JSONValue {
    guard let pointer = getgrgid(gid) else {
      return .null
    }
    let value = pointer.pointee
    return .object([
      "gid": .number(Double(value.gr_gid)),
      "name": cStringJSON(value.gr_name),
    ])
  }

  private func cStringJSON(_ pointer: UnsafePointer<CChar>?) -> JSONValue {
    guard let pointer else {
      return .null
    }
    return .string(String(cString: pointer))
  }

  private func fixedCString<T>(_ value: T) -> String {
    withUnsafePointer(to: value) { pointer in
      pointer.withMemoryRebound(to: CChar.self, capacity: MemoryLayout<T>.size) { buffer in
        String(cString: buffer)
      }
    }
  }

  private func sysctlString(_ name: String) -> String? {
    var size = 0
    guard sysctlbyname(name, nil, &size, nil, 0) == 0, size > 0 else {
      return nil
    }

    var buffer = [CChar](repeating: 0, count: size)
    guard sysctlbyname(name, &buffer, &size, nil, 0) == 0 else {
      return nil
    }
    return stringFromNullTerminatedCString(buffer)
  }

  private func sysctlInteger(_ name: String) -> Int64? {
    var size = 0
    guard sysctlbyname(name, nil, &size, nil, 0) == 0 else {
      return nil
    }

    switch size {
    case MemoryLayout<Int32>.size:
      var value: Int32 = 0
      var valueSize = size
      guard sysctlbyname(name, &value, &valueSize, nil, 0) == 0 else {
        return nil
      }
      return Int64(value)

    case MemoryLayout<Int64>.size:
      var value: Int64 = 0
      var valueSize = size
      guard sysctlbyname(name, &value, &valueSize, nil, 0) == 0 else {
        return nil
      }
      return value

    default:
      return nil
    }
  }

  private func stringFromNullTerminatedCString(_ buffer: [CChar]) -> String {
    let endIndex = buffer.firstIndex(of: 0) ?? buffer.endIndex
    let bytes = buffer[..<endIndex].map { UInt8(bitPattern: $0) }
    return String(decoding: bytes, as: UTF8.self)
  }

  private func thermalStateName(_ state: ProcessInfo.ThermalState) -> String {
    switch state {
    case .nominal:
      return "nominal"
    case .fair:
      return "fair"
    case .serious:
      return "serious"
    case .critical:
      return "critical"
    @unknown default:
      return "unknown"
    }
  }

  private func thermalStateRank(_ state: ProcessInfo.ThermalState) -> Int {
    switch state {
    case .nominal:
      return 0
    case .fair:
      return 1
    case .serious:
      return 2
    case .critical:
      return 3
    @unknown default:
      return -1
    }
  }

  private func propertyListFormatName(_ format: PropertyListSerialization.PropertyListFormat)
    -> String
  {
    switch format {
    case .openStep:
      return "openstep"
    case .xml:
      return "xml"
    case .binary:
      return "binary"
    @unknown default:
      return "unknown"
    }
  }

  private func yamlJSONValue(
    _ value: Any,
    stats: inout YAMLConversionStats,
    depth: Int,
    maxDepth: Int
  ) throws -> JSONValue {
    guard depth <= maxDepth else {
      throw GatewayToolError.invalidArguments("YAML nesting exceeds max_depth.")
    }

    switch value {
    case _ as NSNull:
      return .null
    case let bool as Bool:
      return .bool(bool)
    case let string as String:
      return .string(string)
    case let int as Int:
      return .number(Double(int))
    case let int as Int64:
      return .number(Double(int))
    case let int as Int32:
      return .number(Double(int))
    case let int as Int16:
      return .number(Double(int))
    case let int as Int8:
      return .number(Double(int))
    case let uint as UInt:
      return .number(Double(uint))
    case let uint as UInt64:
      return .number(Double(uint))
    case let uint as UInt32:
      return .number(Double(uint))
    case let uint as UInt16:
      return .number(Double(uint))
    case let uint as UInt8:
      return .number(Double(uint))
    case let double as Double:
      return yamlJSONNumber(double, stats: &stats)
    case let float as Float:
      return yamlJSONNumber(Double(float), stats: &stats)
    case let number as NSNumber:
      return yamlJSONNumber(number.doubleValue, stats: &stats)
    case let date as Date:
      stats.dateCount += 1
      let formatter = ISO8601DateFormatter()
      formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
      return .object([
        "type": .string("date"),
        "iso8601": .string(formatter.string(from: date)),
      ])
    case let array as [Any]:
      return .array(
        try array.map {
          try yamlJSONValue($0, stats: &stats, depth: depth + 1, maxDepth: maxDepth)
        })
    case let dictionary as [String: Any]:
      var object: [String: JSONValue] = [:]
      for key in dictionary.keys.sorted() {
        if let entry = dictionary[key] {
          object[key] = try yamlJSONValue(
            entry,
            stats: &stats,
            depth: depth + 1,
            maxDepth: maxDepth
          )
        }
      }
      return .object(object)
    case let dictionary as [AnyHashable: Any]:
      var object: [String: JSONValue] = [:]
      let pairs = dictionary.map { key, value in (yamlKeyString(key), value, key is String) }
        .sorted { lhs, rhs in lhs.0.localizedStandardCompare(rhs.0) == .orderedAscending }
      for (key, entry, keyWasString) in pairs {
        if !keyWasString {
          stats.nonStringKeyCount += 1
        }
        if object[key] != nil {
          stats.keyCollisionCount += 1
        }
        object[key] = try yamlJSONValue(
          entry,
          stats: &stats,
          depth: depth + 1,
          maxDepth: maxDepth
        )
      }
      return .object(object)
    case let array as NSArray:
      return .array(
        try array.map {
          try yamlJSONValue($0, stats: &stats, depth: depth + 1, maxDepth: maxDepth)
        })
    case let dictionary as NSDictionary:
      var object: [String: JSONValue] = [:]
      let pairs = dictionary.map { key, value in
        (yamlKeyString(key), value, key is String)
      }
      .sorted { lhs, rhs in lhs.0.localizedStandardCompare(rhs.0) == .orderedAscending }
      for (key, entry, keyWasString) in pairs {
        if !keyWasString {
          stats.nonStringKeyCount += 1
        }
        if object[key] != nil {
          stats.keyCollisionCount += 1
        }
        object[key] = try yamlJSONValue(
          entry,
          stats: &stats,
          depth: depth + 1,
          maxDepth: maxDepth
        )
      }
      return .object(object)
    default:
      stats.unsupportedValueCount += 1
      return .object([
        "type": .string("unsupported_yaml_value"),
        "swift_type": .string(String(describing: type(of: value))),
        "description": .string(String(describing: value)),
      ])
    }
  }

  private func yamlJSONNumber(_ value: Double, stats: inout YAMLConversionStats) -> JSONValue {
    guard value.isFinite else {
      stats.nonFiniteNumberCount += 1
      let representation: String
      if value.isNaN {
        representation = "nan"
      } else if value > 0 {
        representation = "inf"
      } else {
        representation = "-inf"
      }
      return .object([
        "type": .string("non_finite_number"),
        "value": .string(representation),
      ])
    }
    return .number(value)
  }

  private func yamlKeyString(_ key: Any) -> String {
    if let string = key as? String {
      return string
    }
    if key is NSNull {
      return "null"
    }
    return String(describing: key)
  }

  private func propertyListJSONValue(_ value: Any, depth: Int = 0) throws -> JSONValue {
    guard depth <= 100 else {
      throw GatewayToolError.invalidArguments("Property list nesting exceeds 100 levels.")
    }

    switch value {
    case let string as String:
      return .string(string)
    case let bool as Bool:
      return .bool(bool)
    case let number as NSNumber:
      return .number(number.doubleValue)
    case let date as Date:
      let formatter = ISO8601DateFormatter()
      formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
      return .object([
        "type": .string("date"),
        "iso8601": .string(formatter.string(from: date)),
      ])
    case let data as Data:
      return .object([
        "type": .string("data"),
        "byte_count": .number(Double(data.count)),
        "base64": .string(data.base64EncodedString()),
      ])
    case let array as [Any]:
      return .array(try array.map { try propertyListJSONValue($0, depth: depth + 1) })
    case let dictionary as [String: Any]:
      var object: [String: JSONValue] = [:]
      for key in dictionary.keys.sorted() {
        if let entry = dictionary[key] {
          object[key] = try propertyListJSONValue(entry, depth: depth + 1)
        }
      }
      return .object(object)
    default:
      throw GatewayToolError.invalidArguments(
        "Unsupported property list value: \(String(describing: type(of: value)))")
    }
  }

  private func propertyListObject(from value: JSONValue, depth: Int = 0) throws -> Any {
    guard depth <= 100 else {
      throw GatewayToolError.invalidArguments("Property list nesting exceeds 100 levels.")
    }

    switch value {
    case .string(let string):
      return string
    case .bool(let bool):
      return bool
    case .number(let number):
      guard number.isFinite else {
        throw GatewayToolError.invalidArguments("Property list numbers must be finite.")
      }
      let rounded = number.rounded()
      if rounded == number && number >= Double(Int.min) && number <= Double(Int.max) {
        return Int(number)
      }
      return number
    case .array(let array):
      return try array.map { try propertyListObject(from: $0, depth: depth + 1) }
    case .object(let object):
      if let typed = try typedPropertyListObject(from: object) {
        return typed
      }
      var dictionary: [String: Any] = [:]
      for key in object.keys.sorted() {
        if let entry = object[key] {
          dictionary[key] = try propertyListObject(from: entry, depth: depth + 1)
        }
      }
      return dictionary
    case .null:
      throw GatewayToolError.invalidArguments("Property lists do not support null values.")
    }
  }

  private func typedPropertyListObject(from object: [String: JSONValue]) throws -> Any? {
    guard let type = object["type"]?.stringValue else {
      return nil
    }
    switch type {
    case "date":
      guard let iso8601 = object["iso8601"]?.stringValue else {
        return nil
      }
      guard let date = propertyListDate(from: iso8601) else {
        throw GatewayToolError.invalidArguments("Invalid property list date iso8601 value.")
      }
      return date
    case "data":
      guard let base64 = object["base64"]?.stringValue else {
        return nil
      }
      guard let data = Data(base64Encoded: base64) else {
        throw GatewayToolError.invalidArguments("Invalid property list data base64 value.")
      }
      return data
    default:
      return nil
    }
  }

  private func propertyListDate(from string: String) -> Date? {
    let fractional = ISO8601DateFormatter()
    fractional.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
    if let date = fractional.date(from: string) {
      return date
    }
    let standard = ISO8601DateFormatter()
    standard.formatOptions = [.withInternetDateTime]
    return standard.date(from: string)
  }

  private func propertyListPreview(
    data: Data,
    format: PropertyListSerialization.PropertyListFormat,
    maxBytes: Int
  ) -> JSONValue {
    let bounded = data.count > maxBytes ? Data(data.prefix(maxBytes)) : data
    let truncated = data.count > maxBytes
    if format == .xml, let text = String(data: bounded, encoding: .utf8) {
      return .object([
        "preview_max_bytes": .number(Double(maxBytes)),
        "encoding": .string("utf8"),
        "content": .string(text),
        "content_truncated": .bool(truncated),
      ])
    }
    return .object([
      "preview_max_bytes": .number(Double(maxBytes)),
      "encoding": .string("base64"),
      "content": .string(bounded.base64EncodedString()),
      "content_truncated": .bool(truncated),
    ])
  }

  private func tomlJSONValue(_ value: DecodedTOMLValue) -> JSONValue {
    switch value {
    case .string(let string):
      return .string(string)
    case .integer(let integer):
      return .number(Double(integer))
    case .float(let double):
      return .number(double)
    case .bool(let bool):
      return .bool(bool)
    case .offsetDateTime(let date):
      let formatter = ISO8601DateFormatter()
      formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
      return .object([
        "type": .string("offset_datetime"),
        "iso8601": .string(formatter.string(from: date)),
      ])
    case .localDateTime(let dateTime):
      return .object([
        "type": .string("local_datetime"),
        "value": .string(formatTOMLLocalDateTime(dateTime)),
      ])
    case .localDate(let date):
      return .object([
        "type": .string("local_date"),
        "value": .string(formatTOMLLocalDate(date)),
      ])
    case .localTime(let time):
      return .object([
        "type": .string("local_time"),
        "value": .string(formatTOMLLocalTime(time)),
      ])
    case .array(let array):
      return .array(array.map(tomlJSONValue))
    case .table(let table):
      var object: [String: JSONValue] = [:]
      for key in table.keys.sorted() {
        if let value = table[key] {
          object[key] = tomlJSONValue(value)
        }
      }
      return .object(object)
    }
  }

  private func readBoundedFileData(url: URL, path: String, maxBytes: Int) throws -> Data {
    let handle = try FileHandle(forReadingFrom: url)
    defer {
      try? handle.close()
    }
    let data = try handle.read(upToCount: maxBytes + 1) ?? Data()
    guard data.count <= maxBytes else {
      throw GatewayToolError.invalidArguments("File exceeds max_bytes: \(path)")
    }
    return data
  }

  private func structuredFormat(_ requestedFormat: String, path: String) throws -> String {
    let normalized = requestedFormat.lowercased()
    let allowed = ["auto", "json", "yaml", "toml", "plist"]
    guard allowed.contains(normalized) else {
      throw GatewayToolError.invalidArguments(
        "format must be one of: auto, json, yaml, toml, plist.")
    }
    guard normalized == "auto" else {
      return normalized
    }
    let extensionName = URL(fileURLWithPath: path).pathExtension.lowercased()
    switch extensionName {
    case "json":
      return "json"
    case "yaml", "yml":
      return "yaml"
    case "toml":
      return "toml"
    case "plist":
      return "plist"
    default:
      throw GatewayToolError.invalidArguments(
        "Unable to infer structured format from file extension; pass format explicitly.")
    }
  }

  private func parseStructuredValue(
    data: Data,
    format: String,
    path: String,
    maxBytes: Int,
    maxDocuments: Int,
    maxDepth: Int
  ) throws -> StructuredDocument {
    switch format {
    case "json":
      do {
        return StructuredDocument(
          value: try JSONDecoder().decode(JSONValue.self, from: data),
          metadata: .object(["kind": .string("json")])
        )
      } catch {
        throw GatewayToolError.invalidArguments(
          "Unable to parse JSON: \(error.localizedDescription)")
      }

    case "toml":
      let decoder = TOMLDecoder()
      decoder.limits = TOMLDecoder.DecodingLimits(
        maxInputSize: maxBytes,
        maxDepth: maxDepth,
        maxTableKeys: 10_000,
        maxArrayLength: 100_000,
        maxStringLength: min(maxBytes, 1_048_576)
      )
      do {
        let value = try decoder.decode(DecodedTOMLValue.self, from: data)
        return StructuredDocument(
          value: tomlJSONValue(value),
          metadata: .object(["kind": .string("toml")])
        )
      } catch {
        throw GatewayToolError.invalidArguments(
          "Unable to parse TOML: \(error.localizedDescription)")
      }

    case "yaml":
      guard let text = String(data: data, encoding: .utf8) else {
        throw GatewayToolError.invalidArguments("YAML file is not valid UTF-8: \(path)")
      }
      var sequence: YamlSequence<Any>
      do {
        sequence = try Yams.load_all(yaml: text)
      } catch {
        throw GatewayToolError.invalidArguments(
          "Unable to parse YAML: \(error.localizedDescription)")
      }
      var stats = YAMLConversionStats()
      var documents: [JSONValue] = []
      var parsedDocumentCount = 0
      while let document = sequence.next() {
        parsedDocumentCount += 1
        if documents.count < maxDocuments {
          documents.append(
            try yamlJSONValue(document, stats: &stats, depth: 0, maxDepth: maxDepth))
        }
      }
      if let error = sequence.error {
        throw GatewayToolError.invalidArguments(
          "Unable to parse YAML: \(error.localizedDescription)")
      }
      let value: JSONValue
      switch documents.count {
      case 0:
        value = .null
      case 1:
        value = documents[0]
      default:
        value = .array(documents)
      }
      return StructuredDocument(
        value: value,
        metadata: .object([
          "kind": .string("yaml"),
          "document_count": .number(Double(parsedDocumentCount)),
          "returned_document_count": .number(Double(documents.count)),
          "document_count_truncated": .bool(parsedDocumentCount > documents.count),
          "conversion": stats.json,
        ])
      )

    case "plist":
      var propertyListFormat = PropertyListSerialization.PropertyListFormat.xml
      let plist: Any
      do {
        plist = try PropertyListSerialization.propertyList(
          from: data,
          options: [],
          format: &propertyListFormat
        )
      } catch {
        throw GatewayToolError.invalidArguments(
          "Unable to parse property list: \(error.localizedDescription)")
      }
      return StructuredDocument(
        value: try propertyListJSONValue(plist),
        metadata: .object([
          "kind": .string("plist"),
          "property_list_format": .string(propertyListFormatName(propertyListFormat)),
        ])
      )

    default:
      throw GatewayToolError.invalidArguments("Unsupported structured format: \(format)")
    }
  }

  private func selectStructuredValue(_ root: JSONValue, path: [StructuredPathSegment])
    -> StructuredSelection
  {
    var current = root
    for (index, segment) in path.enumerated() {
      switch segment {
      case .key(let key):
        guard let object = current.objectValue else {
          return StructuredSelection(
            matched: false,
            value: .null,
            failure: StructuredSelectionFailure(
              index: index,
              segment: segment,
              reason: "not_object",
              actualKind: jsonValueKind(current)
            )
          )
        }
        guard let value = object[key] else {
          return StructuredSelection(
            matched: false,
            value: .null,
            failure: StructuredSelectionFailure(
              index: index,
              segment: segment,
              reason: "missing_key",
              actualKind: "object"
            )
          )
        }
        current = value

      case .index(let itemIndex):
        guard let array = current.arrayValue else {
          return StructuredSelection(
            matched: false,
            value: .null,
            failure: StructuredSelectionFailure(
              index: index,
              segment: segment,
              reason: "not_array",
              actualKind: jsonValueKind(current)
            )
          )
        }
        guard itemIndex < array.count else {
          return StructuredSelection(
            matched: false,
            value: .null,
            failure: StructuredSelectionFailure(
              index: index,
              segment: segment,
              reason: "index_out_of_range",
              actualKind: "array"
            )
          )
        }
        current = array[itemIndex]
      }
    }

    return StructuredSelection(matched: true, value: current, failure: nil)
  }

  private func structuredPointer(_ path: [StructuredPathSegment]) -> String {
    guard !path.isEmpty else {
      return ""
    }
    return path.map { segment in
      switch segment {
      case .key(let key):
        return "/"
          + key.replacingOccurrences(of: "~", with: "~0")
          .replacingOccurrences(of: "/", with: "~1")
      case .index(let index):
        return "/\(index)"
      }
    }.joined()
  }

  private func jsonValueKind(_ value: JSONValue) -> String {
    switch value {
    case .string:
      return "string"
    case .number:
      return "number"
    case .bool:
      return "bool"
    case .object:
      return "object"
    case .array:
      return "array"
    case .null:
      return "null"
    }
  }

  private func formatTOMLLocalDateTime(_ value: LocalDateTime) -> String {
    "\(formatTOMLLocalDate(LocalDate(year: value.year, month: value.month, day: value.day)))T\(formatTOMLLocalTime(LocalTime(hour: value.hour, minute: value.minute, second: value.second, nanosecond: value.nanosecond)))"
  }

  private func formatTOMLLocalDate(_ value: LocalDate) -> String {
    String(format: "%04d-%02d-%02d", value.year, value.month, value.day)
  }

  private func formatTOMLLocalTime(_ value: LocalTime) -> String {
    var time = String(format: "%02d:%02d:%02d", value.hour, value.minute, value.second)
    if value.nanosecond > 0 {
      var fractional = String(format: "%09d", value.nanosecond)
      while fractional.last == "0" {
        fractional.removeLast()
      }
      time += ".\(fractional)"
    }
    return time
  }

  private func systemProcess(line: String) -> JSONValue {
    let parts = line.split(separator: " ", maxSplits: 7, omittingEmptySubsequences: true)
      .map(String.init)
    guard parts.count == 8,
      let pid = Int(parts[0]),
      let parentPID = Int(parts[1]),
      let cpuPercent = Double(parts[4]),
      let memoryPercent = Double(parts[5])
    else {
      return .object([
        "parsed": .bool(false),
        "raw_line": .string(line),
      ])
    }

    return .object([
      "parsed": .bool(true),
      "pid": .number(Double(pid)),
      "parent_pid": .number(Double(parentPID)),
      "user": .string(parts[2]),
      "state": .string(parts[3]),
      "cpu_percent": .number(cpuPercent),
      "memory_percent": .number(memoryPercent),
      "elapsed": .string(parts[6]),
      "command": .string(parts[7]),
    ])
  }

  private func systemProcess(_ process: JSONValue, matches query: String?) -> Bool {
    guard let query, !query.isEmpty else {
      return true
    }
    guard let object = process.objectValue else {
      return false
    }
    let fields = [
      object["user"]?.stringValue,
      object["state"]?.stringValue,
      object["command"]?.stringValue,
      object["raw_line"]?.stringValue,
    ].compactMap { $0?.lowercased() }
    return fields.contains { $0.contains(query) }
  }

  private func macOSRunningApplicationInfo(
    _ application: NSRunningApplication
  ) -> MacOSRunningApplicationInfo {
    MacOSRunningApplicationInfo(
      name: application.localizedName,
      bundleIdentifier: application.bundleIdentifier,
      bundlePath: application.bundleURL?.standardizedFileURL.path,
      executablePath: application.executableURL?.standardizedFileURL.path,
      processIdentifier: Int(application.processIdentifier),
      activationPolicy: macOSActivationPolicyName(application.activationPolicy),
      isActive: application.isActive,
      isHidden: application.isHidden,
      isFinishedLaunching: application.isFinishedLaunching,
      launchDate: application.launchDate
    )
  }

  private func macOSRunningApplication(
    _ application: NSRunningApplication,
    matches query: String,
    mode: FileNameMatchMode,
    caseSensitive: Bool
  ) -> Bool {
    let candidates = [
      application.localizedName,
      application.bundleIdentifier,
      application.bundleURL?.path,
      application.executableURL?.path,
    ].compactMap { $0 }
    return candidates.contains {
      fileName($0, matches: query, mode: mode, caseSensitive: caseSensitive)
    }
  }

  private func macOSActivationPolicyName(
    _ policy: NSApplication.ActivationPolicy
  ) -> String {
    switch policy {
    case .regular:
      return "regular"
    case .accessory:
      return "accessory"
    case .prohibited:
      return "prohibited"
    @unknown default:
      return "unknown"
    }
  }

  private func validateUTF8ByteLimit(_ value: String, name: String, maxBytes: Int) throws {
    let bytes = Data(value.utf8).count
    guard bytes <= maxBytes else {
      throw GatewayToolError.invalidArguments("\(name) must be at most \(maxBytes) bytes.")
    }
  }

  private func fileInfo(url: URL) throws -> FileInfo {
    let attributes = try FileManager.default.attributesOfItem(atPath: url.path)
    let type = fileType(attributes[.type])
    let symlinkDestination = try? FileManager.default.destinationOfSymbolicLink(atPath: url.path)
    let relativePath =
      symlinkDestination == nil
      ? workspaceRelativePath(url) : workspaceRelativePathPreservingSymlinks(url)

    return FileInfo(
      path: url.path,
      workspaceRelativePath: relativePath,
      type: symlinkDestination == nil ? type : "symlink",
      size: (attributes[.size] as? NSNumber)?.int64Value,
      createdAt: attributes[.creationDate] as? Date,
      modifiedAt: attributes[.modificationDate] as? Date,
      isReadable: FileManager.default.isReadableFile(atPath: url.path),
      isWritable: FileManager.default.isWritableFile(atPath: url.path),
      isExecutable: FileManager.default.isExecutableFile(atPath: url.path),
      isSymlink: symlinkDestination != nil,
      symlinkDestination: symlinkDestination
    )
  }

  private func fileType(_ attribute: Any?) -> String {
    guard let type = attribute as? FileAttributeType else {
      return "unknown"
    }
    switch type {
    case .typeDirectory:
      return "directory"
    case .typeRegular:
      return "file"
    case .typeSymbolicLink:
      return "symlink"
    case .typeSocket:
      return "socket"
    case .typeCharacterSpecial:
      return "character_special"
    case .typeBlockSpecial:
      return "block_special"
    default:
      return "unknown"
    }
  }

  private func fileNameMatchMode(_ value: String) throws -> FileNameMatchMode {
    guard let mode = FileNameMatchMode(rawValue: value) else {
      throw GatewayToolError.invalidArguments(
        "match must be one of: contains, prefix, suffix, exact.")
    }
    return mode
  }

  private func fileTimelineSort(_ value: String) throws -> FileTimelineSort {
    guard let sort = FileTimelineSort(rawValue: value) else {
      throw GatewayToolError.invalidArguments(
        "sort must be one of: modified_desc, modified_asc, path.")
    }
    return sort
  }

  private func fileName(
    _ name: String,
    matches query: String,
    mode: FileNameMatchMode,
    caseSensitive: Bool
  ) -> Bool {
    let candidate = caseSensitive ? name : name.lowercased()
    let needle = caseSensitive ? query : query.lowercased()

    switch mode {
    case .contains:
      return candidate.contains(needle)
    case .prefix:
      return candidate.hasPrefix(needle)
    case .suffix:
      return candidate.hasSuffix(needle)
    case .exact:
      return candidate == needle
    }
  }

  private func countOccurrences(of needle: String, in haystack: String) -> Int {
    var count = 0
    var searchStart = haystack.startIndex
    while let range = haystack.range(of: needle, range: searchStart..<haystack.endIndex) {
      count += 1
      searchStart = range.upperBound
    }
    return count
  }

  private func fileInsertPosition(_ value: String) throws -> FileInsertPosition {
    guard let position = FileInsertPosition(rawValue: value) else {
      throw GatewayToolError.invalidArguments("position must be one of: before, after.")
    }
    return position
  }

  private func existingLineStarts(in content: String) -> [String.Index] {
    guard !content.isEmpty else {
      return []
    }
    var starts = [content.startIndex]
    var searchStart = content.startIndex
    while let newline = content[searchStart...].firstIndex(of: "\n") {
      let next = content.index(after: newline)
      if next < content.endIndex {
        starts.append(next)
      }
      searchStart = next
    }
    return starts
  }

  private func lineText(
    at line: Int,
    starts: [String.Index],
    in content: String
  ) -> String {
    let start = starts[line - 1]
    var end: String.Index
    if line < starts.count {
      let nextStart = starts[line]
      end = content.index(before: nextStart)
    } else {
      end = content.endIndex
      if end > start {
        let previous = content.index(before: end)
        if content[previous] == "\n" {
          end = previous
        }
      }
    }
    return String(content[start..<end])
  }

  private func utf8Preview(_ value: String, maxBytes: Int) -> (text: String, truncated: Bool) {
    let data = Data(value.utf8)
    guard data.count > maxBytes else {
      return (value, false)
    }

    var index = value.startIndex
    var byteCount = 0
    while index < value.endIndex {
      let next = value.index(after: index)
      let characterByteCount = value[index..<next].utf8.count
      guard byteCount + characterByteCount <= maxBytes else {
        break
      }
      byteCount += characterByteCount
      index = next
    }

    return (String(value[..<index]), true)
  }

  private func mcpToolFindField(_ value: String) throws -> MCPToolFindField {
    guard let field = MCPToolFindField(rawValue: value) else {
      throw GatewayToolError.invalidArguments("field must be one of: name, description, all.")
    }
    return field
  }

  private func mcpTool(
    _ tool: MCPTool,
    matches query: String,
    field: MCPToolFindField,
    mode: FileNameMatchMode,
    caseSensitive: Bool
  ) -> Bool {
    switch field {
    case .name:
      return fileName(tool.name, matches: query, mode: mode, caseSensitive: caseSensitive)
    case .description:
      return fileName(tool.description, matches: query, mode: mode, caseSensitive: caseSensitive)
    case .all:
      return fileName(tool.name, matches: query, mode: mode, caseSensitive: caseSensitive)
        || fileName(tool.description, matches: query, mode: mode, caseSensitive: caseSensitive)
    }
  }

  private func requireDirectory(_ url: URL, originalPath: String) throws {
    var isDirectory: ObjCBool = false
    guard FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory) else {
      throw GatewayToolError.invalidArguments("Directory does not exist: \(originalPath)")
    }
    guard isDirectory.boolValue else {
      throw GatewayToolError.invalidArguments("Path is not a directory: \(originalPath)")
    }
  }

