  private func environmentEntry(
    key: String,
    owner: String,
    purpose: String,
    valueOrigin: String,
    processEnvironment: [String: String],
    declaredKeys: inout Set<String>
  ) -> JSONValue {
    declaredKeys.insert(key)
    return .object([
      "key": .string(key),
      "owner": .string(owner),
      "purpose": .string(purpose),
      "value_origin": .string(valueOrigin),
      "process_environment_present": .bool(processEnvironment[key] != nil),
      "value_redacted": .bool(true),
    ])
  }

  private func prepareDestination(
    _ url: URL,
    originalPath: String,
    overwrite: Bool,
    createDirectories: Bool
  ) throws {
    if createDirectories {
      try FileManager.default.createDirectory(
        at: url.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
    }

    guard FileManager.default.fileExists(atPath: url.path) else {
      return
    }
    guard overwrite else {
      throw GatewayToolError.invalidArguments("Destination already exists: \(originalPath)")
    }
    try FileManager.default.removeItem(at: url)
  }

  private struct DestinationPreparation {
    let destinationExists: Bool
    let wouldCreateParentDirectories: Bool
  }

  private func inspectDestinationPreparation(
    _ url: URL,
    originalPath: String,
    overwrite: Bool,
    createDirectories: Bool,
    treatsBrokenSymlinkAsExisting: Bool = false
  ) throws -> DestinationPreparation {
    let parent = url.deletingLastPathComponent()
    var parentIsDirectory: ObjCBool = false
    let parentExists = FileManager.default.fileExists(
      atPath: parent.path,
      isDirectory: &parentIsDirectory
    )
    if parentExists {
      guard parentIsDirectory.boolValue else {
        throw GatewayToolError.invalidArguments("Parent path is not a directory: \(originalPath)")
      }
    } else {
      guard createDirectories else {
        throw GatewayToolError.invalidArguments(
          "Parent directory does not exist: \(originalPath)"
        )
      }
    }

    let destinationExists =
      FileManager.default.fileExists(atPath: url.path)
      || (treatsBrokenSymlinkAsExisting
        && (try? FileManager.default.destinationOfSymbolicLink(atPath: url.path)) != nil)
    if destinationExists && !overwrite {
      throw GatewayToolError.invalidArguments("Destination already exists: \(originalPath)")
    }

    return DestinationPreparation(
      destinationExists: destinationExists,
      wouldCreateParentDirectories: !parentExists
    )
  }

  private func prepareSymlinkDestination(
    _ url: URL,
    originalPath: String,
    overwrite: Bool,
    createDirectories: Bool
  ) throws {
    if createDirectories {
      try FileManager.default.createDirectory(
        at: url.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
    }

    let exists =
      FileManager.default.fileExists(atPath: url.path)
      || (try? FileManager.default.destinationOfSymbolicLink(atPath: url.path)) != nil
    guard exists else {
      return
    }
    guard overwrite else {
      throw GatewayToolError.invalidArguments("Destination already exists: \(originalPath)")
    }
    try FileManager.default.removeItem(at: url)
  }

  private func organizationResult(
    operation: String,
    source: URL,
    destination: URL,
    dryRun: Bool,
    overwritten: Bool,
    wouldOverwrite: Bool,
    wouldCreateParentDirectories: Bool,
    performedKey: String,
    wouldPerformKey: String
  ) throws -> JSONValue {
    var payload: [String: JSONValue] = [
      "operation": .string(operation),
      "source": .string(source.path),
      "source_workspace_relative_path": .string(workspaceRelativePath(source)),
      "destination": .string(destination.path),
      "destination_workspace_relative_path": .string(workspaceRelativePath(destination)),
      "dry_run": .bool(dryRun),
      "overwritten": .bool(overwritten),
      "would_overwrite": .bool(wouldOverwrite),
      "would_create_parent_directories": .bool(wouldCreateParentDirectories),
      performedKey: .bool(!dryRun),
      wouldPerformKey: .bool(true),
    ]
    if operation == "file.move" {
      payload["source_removed"] = .bool(!dryRun)
      payload["would_remove_source"] = .bool(true)
    }
    payload["result"] = dryRun ? .null : try fileInfo(url: destination).json
    return .object(payload)
  }

  private func validateNonNegative(_ value: Int, name: String) throws {
    guard value >= 0 else {
      throw GatewayToolError.invalidArguments("\(name) must be zero or greater.")
    }
  }

  private func validateBoundedNonNegative(_ value: Int, name: String, upperBound: Int) throws {
    try validateNonNegative(value, name: name)
    guard value <= upperBound else {
      throw GatewayToolError.invalidArguments(
        "\(name) must be less than or equal to \(upperBound).")
    }
  }

  private func validateBoundedPositive(_ value: Int, name: String, upperBound: Int) throws {
    guard value > 0 else {
      throw GatewayToolError.invalidArguments("\(name) must be greater than zero.")
    }
    guard value <= upperBound else {
      throw GatewayToolError.invalidArguments(
        "\(name) must be less than or equal to \(upperBound).")
    }
  }

  private func extendedAttributeNames(url: URL) throws -> [String] {
    let size = url.withUnsafeFileSystemRepresentation { pathPointer -> Int in
      guard let pathPointer else {
        errno = EINVAL
        return -1
      }
      return listxattr(pathPointer, nil, 0, 0)
    }
    guard size >= 0 else {
      throw extendedAttributeError("listxattr", url: url, errno: errno)
    }
    guard size > 0 else {
      return []
    }

    var buffer = [CChar](repeating: 0, count: size)
    let bytesRead = url.withUnsafeFileSystemRepresentation { pathPointer -> Int in
      guard let pathPointer else {
        errno = EINVAL
        return -1
      }
      return buffer.withUnsafeMutableBufferPointer { pointer in
        listxattr(pathPointer, pointer.baseAddress, pointer.count, 0)
      }
    }
    guard bytesRead >= 0 else {
      throw extendedAttributeError("listxattr", url: url, errno: errno)
    }

    var names: [String] = []
    var start = 0
    for index in 0..<bytesRead where buffer[index] == 0 {
      if index > start {
        names.append(
          String(
            decoding: buffer[start..<index].map { UInt8(bitPattern: $0) },
            as: UTF8.self
          ))
      }
      start = index + 1
    }
    return names
  }

  private func extendedAttributeSize(url: URL, name: String) throws -> Int {
    let size = url.withUnsafeFileSystemRepresentation { pathPointer -> Int in
      guard let pathPointer else {
        errno = EINVAL
        return -1
      }
      return name.withCString { namePointer in
        getxattr(pathPointer, namePointer, nil, 0, 0, 0)
      }
    }
    guard size >= 0 else {
      throw extendedAttributeError("getxattr", url: url, errno: errno)
    }
    return size
  }

  private func extendedAttributeValue(
    url: URL,
    name: String,
    size: Int,
    maxBytes: Int
  ) throws -> Data {
    let bytesToRead = min(size, maxBytes)
    guard bytesToRead > 0 else {
      return Data()
    }

    var data = Data(count: bytesToRead)
    let bytesRead = data.withUnsafeMutableBytes { rawBuffer -> Int in
      url.withUnsafeFileSystemRepresentation { pathPointer -> Int in
        guard let pathPointer else {
          errno = EINVAL
          return -1
        }
        return name.withCString { namePointer in
          getxattr(pathPointer, namePointer, rawBuffer.baseAddress, bytesToRead, 0, 0)
        }
      }
    }
    guard bytesRead >= 0 else {
      throw extendedAttributeError("getxattr", url: url, errno: errno)
    }
    if bytesRead < data.count {
      data.removeSubrange(bytesRead..<data.count)
    }
    return data
  }

  private func removeExtendedAttribute(url: URL, name: String) throws {
    let result = url.withUnsafeFileSystemRepresentation { pathPointer -> Int32 in
      guard let pathPointer else {
        errno = EINVAL
        return -1
      }
      return name.withCString { namePointer in
        removexattr(pathPointer, namePointer, 0)
      }
    }
    guard result == 0 else {
      throw extendedAttributeError("removexattr", url: url, errno: errno)
    }
  }

  private func extendedAttributeError(_ operation: String, url: URL, errno error: Int32)
    -> GatewayToolError
  {
    GatewayToolError.executionFailed(
      "\(operation) failed for \(url.path): \(String(cString: strerror(error)))"
    )
  }

  private func metadataPayload(from result: CommandResult) -> MetadataPayload {
    if result.timedOut {
      return MetadataPayload(
        metadata: .null,
        error: nil,
        omittedReason: "mdls timed out"
      )
    }
    if result.stdoutTruncated {
      return MetadataPayload(
        metadata: .null,
        error: nil,
        omittedReason: "stdout truncated"
      )
    }
    if result.exitCode != 0 {
      return MetadataPayload(
        metadata: .null,
        error: nil,
        omittedReason: "mdls exited nonzero"
      )
    }
    guard !result.stdout.isEmpty else {
      return MetadataPayload(
        metadata: .null,
        error: nil,
        omittedReason: "empty stdout"
      )
    }

    do {
      let plist = try PropertyListSerialization.propertyList(
        from: Data(result.stdout.utf8),
        options: [],
        format: nil
      )
      return MetadataPayload(
        metadata: propertyListJSON(plist),
        error: nil,
        omittedReason: nil
      )
    } catch {
      return MetadataPayload(
        metadata: .null,
        error: error.localizedDescription,
        omittedReason: "plist parse failed"
      )
    }
  }

  private func propertyListJSON(_ value: Any) -> JSONValue {
    if let dictionary = value as? NSDictionary {
      var object: [String: JSONValue] = [:]
      for key in dictionary.allKeys {
        guard let stringKey = key as? String else {
          continue
        }
        object[stringKey] = propertyListJSON(dictionary[stringKey] as Any)
      }
      return .object(object)
    }
    if let array = value as? NSArray {
      return .array(array.map { propertyListJSON($0) })
    }
    if let string = value as? String {
      return .string(string)
    }
    if let date = value as? Date {
      return .string(iso8601String(date))
    }
    if let data = value as? Data {
      return .string(data.base64EncodedString())
    }
    if let number = value as? NSNumber {
      let type = String(cString: number.objCType)
      if type == "c" || type == "B" {
        return .bool(number.boolValue)
      }
      return .number(number.doubleValue)
    }
    return .null
  }

  private func filteredMetadata(_ metadata: JSONValue, attributes: [String]) -> JSONValue {
    guard !attributes.isEmpty else {
      return metadata
    }
    guard let object = metadata.objectValue else {
      return metadata
    }

    var filtered: [String: JSONValue] = [:]
    for attribute in attributes {
      filtered[attribute] = object[attribute] ?? .null
    }
    return .object(filtered)
  }

  private func permissionSummary(_ mode: Int) -> JSONValue {
    func triplet(read: Int, write: Int, execute: Int) -> JSONValue {
      .object([
        "read": .bool((mode & read) != 0),
        "write": .bool((mode & write) != 0),
        "execute": .bool((mode & execute) != 0),
      ])
    }

    return .object([
      "user": triplet(read: 0o400, write: 0o200, execute: 0o100),
      "group": triplet(read: 0o040, write: 0o020, execute: 0o010),
      "other": triplet(read: 0o004, write: 0o002, execute: 0o001),
      "setuid": .bool((mode & 0o4000) != 0),
      "setgid": .bool((mode & 0o2000) != 0),
      "sticky": .bool((mode & 0o1000) != 0),
    ])
  }

  private func parsePOSIXMode(_ raw: String, name: String) throws -> Int {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    let digits: String
    if trimmed.hasPrefix("0o") {
      digits = String(trimmed.dropFirst(2))
    } else {
      digits = trimmed
    }

    guard digits.count == 3 || digits.count == 4, digits.allSatisfy({ $0 >= "0" && $0 <= "7" }),
      let mode = Int(digits, radix: 8), mode >= 0, mode <= 0o7777
    else {
      throw GatewayToolError.invalidArguments(
        "\(name) must be a 3- or 4-digit octal POSIX mode, for example 0644.")
    }
    return mode
  }

  private func archiveListCommand(for url: URL) throws -> ArchiveListCommand {
    let name = url.lastPathComponent.lowercased()
    if name.hasSuffix(".zip") || name.hasSuffix(".jar") || name.hasSuffix(".war")
      || name.hasSuffix(".ear")
    {
      return ArchiveListCommand(
        format: "zip",
        executable: "/usr/bin/zipinfo",
        arguments: ["-1", url.path]
      )
    }

    let tarSuffixes = [
      ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz", ".tbz2", ".tar.xz", ".txz",
    ]
    if tarSuffixes.contains(where: { name.hasSuffix($0) }) {
      return ArchiveListCommand(
        format: "tar",
        executable: "/usr/bin/tar",
        arguments: ["-tf", url.path]
      )
    }

    throw GatewayToolError.invalidArguments(
      "Unsupported archive format. Supported suffixes: .zip, .jar, .war, .ear, .tar, .tar.gz, .tgz, .tar.bz2, .tbz, .tbz2, .tar.xz, .txz."
    )
  }

  private func archiveVerboseListCommand(
    archive: ArchiveListCommand,
    archiveURL: URL
  ) throws -> ArchiveListCommand {
    switch archive.format {
    case "zip":
      return ArchiveListCommand(
        format: archive.format,
        executable: "/usr/bin/zipinfo",
        arguments: ["-l", archiveURL.path]
      )
    case "tar":
      return ArchiveListCommand(
        format: archive.format,
        executable: "/usr/bin/tar",
        arguments: ["-tvf", archiveURL.path]
      )
    default:
      throw GatewayToolError.invalidArguments("Unsupported archive format: \(archive.format)")
    }
  }

  private func archiveExtractCommand(
    archive: ArchiveListCommand,
    archiveURL: URL,
    destinationURL: URL,
    overwrite: Bool
  ) throws -> ArchiveListCommand {
    switch archive.format {
    case "zip":
      return ArchiveListCommand(
        format: archive.format,
        executable: "/usr/bin/unzip",
        arguments: ["-q", overwrite ? "-o" : "-n", archiveURL.path, "-d", destinationURL.path]
      )
    case "tar":
      let args =
        overwrite
        ? ["-xf", archiveURL.path, "-C", destinationURL.path]
        : ["-xkf", archiveURL.path, "-C", destinationURL.path]
      return ArchiveListCommand(
        format: archive.format,
        executable: "/usr/bin/tar",
        arguments: args
      )
    default:
      throw GatewayToolError.invalidArguments("Unsupported archive format: \(archive.format)")
    }
  }

  private func archiveReadFileCommand(
    archive: ArchiveListCommand,
    archiveURL: URL,
    entry: String
  ) throws -> ArchiveListCommand {
    switch archive.format {
    case "zip":
      return ArchiveListCommand(
        format: archive.format,
        executable: "/usr/bin/unzip",
        arguments: ["-p", archiveURL.path, entry]
      )
    case "tar":
      return ArchiveListCommand(
        format: archive.format,
        executable: "/usr/bin/tar",
        arguments: ["-xOf", archiveURL.path, entry]
      )
    default:
      throw GatewayToolError.invalidArguments("Unsupported archive format: \(archive.format)")
    }
  }

  private func archiveCreateCommand(
    for archiveURL: URL,
    requestedFormat: String?,
    sourcePaths: [String]
  ) throws -> ArchiveListCommand {
    let name = archiveURL.lastPathComponent.lowercased()
    let normalizedFormat = requestedFormat?.lowercased()
    if let normalizedFormat, normalizedFormat != "zip" && normalizedFormat != "tar" {
      throw GatewayToolError.invalidArguments("format must be one of: zip, tar.")
    }

    if name.hasSuffix(".zip") || name.hasSuffix(".jar") || name.hasSuffix(".war")
      || name.hasSuffix(".ear")
    {
      if normalizedFormat == "tar" {
        throw GatewayToolError.invalidArguments("format=tar does not match archive path suffix.")
      }
      return ArchiveListCommand(
        format: "zip",
        executable: "/usr/bin/zip",
        arguments: ["-qry", archiveURL.path] + sourcePaths
      )
    }

    let tarFlag: String?
    if name.hasSuffix(".tar") {
      tarFlag = "-cf"
    } else if name.hasSuffix(".tar.gz") || name.hasSuffix(".tgz") {
      tarFlag = "-czf"
    } else if name.hasSuffix(".tar.bz2") || name.hasSuffix(".tbz") || name.hasSuffix(".tbz2") {
      tarFlag = "-cjf"
    } else if name.hasSuffix(".tar.xz") || name.hasSuffix(".txz") {
      tarFlag = "-cJf"
    } else {
      tarFlag = nil
    }
    if let tarFlag {
      if normalizedFormat == "zip" {
        throw GatewayToolError.invalidArguments("format=zip does not match archive path suffix.")
      }
      return ArchiveListCommand(
        format: "tar",
        executable: "/usr/bin/tar",
        arguments: [tarFlag, archiveURL.path] + sourcePaths
      )
    }

    throw GatewayToolError.invalidArguments(
      "Unsupported archive format. Supported suffixes: .zip, .jar, .war, .ear, .tar, .tar.gz, .tgz, .tar.bz2, .tbz, .tbz2, .tar.xz, .txz."
    )
  }

  private func validateArchiveCreateSources(
    _ rawSourcePaths: [String],
    archiveURL: URL,
    maxEntries: Int,
    maxPreviewEntries: Int
  ) throws -> ArchiveCreateSourceSnapshot {
    let fileManager = FileManager.default
    let archivePath = archiveURL.standardizedFileURL.path
    var sources: [ArchiveCreateSource] = []
    var previewEntries: [ArchiveCreateEntry] = []
    var entryCount = 0
    var argvSourcePaths: [String] = []

    func appendEntry(url: URL, type: String) throws {
      entryCount += 1
      guard entryCount <= maxEntries else {
        throw GatewayToolError.invalidArguments(
          "sources contain more than max_entries entries; increase max_entries to validate archive creation."
        )
      }
      if previewEntries.count < maxPreviewEntries {
        previewEntries.append(
          ArchiveCreateEntry(
            workspaceRelativePath: workspaceRelativePathPreservingSymlinks(url),
            type: type
          ))
      }
    }

    for rawSourcePath in rawSourcePaths {
      let lexicalSourceURL = try lexicalWorkspaceURL(rawSourcePath)
      let resolvedSourceURL = try resolvedWorkspaceURL(rawSourcePath)
      let sourceInfo = try fileInfo(url: lexicalSourceURL)
      guard !sourceInfo.isSymlink else {
        throw GatewayToolError.invalidArguments(
          "archive.create refuses symbolic link sources: \(rawSourcePath)")
      }
      guard sourceInfo.type == "file" || sourceInfo.type == "directory" else {
        throw GatewayToolError.invalidArguments(
          "archive.create source must be a file or directory: \(rawSourcePath)")
      }

      let sourcePath = resolvedSourceURL.standardizedFileURL.path
      let sourcePrefix = sourcePath.hasSuffix("/") ? sourcePath : "\(sourcePath)/"
      guard archivePath != sourcePath && !archivePath.hasPrefix(sourcePrefix) else {
        throw GatewayToolError.invalidArguments(
          "Archive output must not be inside a source path: \(rawSourcePath)")
      }

      let sourceEntryStart = entryCount
      try appendEntry(url: lexicalSourceURL, type: sourceInfo.type)

      if sourceInfo.type == "directory" {
        var enumerationError: Error?
        guard
          let enumerator = fileManager.enumerator(
            at: lexicalSourceURL,
            includingPropertiesForKeys: [
              .isDirectoryKey,
              .isRegularFileKey,
              .isSymbolicLinkKey,
            ],
            options: [],
            errorHandler: { _, error in
              enumerationError = error
              return false
            }
          )
        else {
          throw GatewayToolError.invalidArguments(
            "Unable to enumerate source directory: \(rawSourcePath)")
        }

        for case let itemURL as URL in enumerator {
          let values = try itemURL.resourceValues(forKeys: [
            .isDirectoryKey,
            .isRegularFileKey,
            .isSymbolicLinkKey,
          ])
          if values.isSymbolicLink == true {
            throw GatewayToolError.invalidArguments(
              "archive.create refuses symbolic link entries: \(workspaceRelativePathPreservingSymlinks(itemURL))"
            )
          }
          let type =
            values.isDirectory == true
            ? "directory"
            : (values.isRegularFile == true ? "file" : "other")
          guard type == "file" || type == "directory" else {
            throw GatewayToolError.invalidArguments(
              "archive.create source contains unsupported file type: \(workspaceRelativePathPreservingSymlinks(itemURL))"
            )
          }
          try appendEntry(url: itemURL, type: type)
        }

        if let enumerationError {
          throw GatewayToolError.invalidArguments(
            "Unable to enumerate source directory \(rawSourcePath): \(enumerationError.localizedDescription)"
          )
        }
      }

      let sourceEntryCount = entryCount - sourceEntryStart
      let argvSourcePath = workspaceRelativePathPreservingSymlinks(lexicalSourceURL)
      argvSourcePaths.append(argvSourcePath)
      sources.append(
        ArchiveCreateSource(
          path: lexicalSourceURL.path,
          workspaceRelativePath: argvSourcePath,
          type: sourceInfo.type,
          entryCount: sourceEntryCount
        ))
    }

    return ArchiveCreateSourceSnapshot(
      sources: sources,
      argvSourcePaths: argvSourcePaths,
      entryCount: entryCount,
      previewEntries: previewEntries
    )
  }

  private func requireSuccessfulArchivePreflight(
    _ result: CommandResult,
    operation: String
  ) throws {
    guard !result.timedOut else {
      throw GatewayToolError.invalidArguments("\(operation) timed out.")
    }
    guard result.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "\(operation) failed with exit code \(result.exitCode.map(String.init) ?? "unknown").")
    }
    guard !result.stdoutTruncated else {
      throw GatewayToolError.invalidArguments(
        "\(operation) output was truncated; increase max_output_bytes to validate extraction.")
    }
  }

  private func requireSuccessfulArchiveRead(_ result: CommandDataResult) throws {
    guard !result.timedOut else {
      throw GatewayToolError.invalidArguments("archive.read_file timed out.")
    }
    guard result.exitCode == 0 else {
      throw GatewayToolError.invalidArguments(
        "archive.read_file failed with exit code \(result.exitCode.map(String.init) ?? "unknown").")
    }
  }

  private func archiveLinkEntries(
    archiveURL: URL,
    archive: ArchiveListCommand,
    timeout: Int,
    maxOutputBytes: Int
  ) throws -> [String] {
    let verboseCommand = try archiveVerboseListCommand(archive: archive, archiveURL: archiveURL)
    let result = try commandRunner.run(
      executable: verboseCommand.executable,
      arguments: verboseCommand.arguments,
      workingDirectory: configuration.workspaceDirectory,
      environment: [:],
      timeoutMilliseconds: timeout,
      maxOutputBytes: maxOutputBytes
    )
    try requireSuccessfulArchivePreflight(result, operation: "archive verbose list")
    return result.stdout.split(separator: "\n", omittingEmptySubsequences: true)
      .map(String.init)
      .filter { line in
        guard let first = line.first else {
          return false
        }
        return first == "l" || first == "h"
      }
  }

  private func validateArchiveEntries(
    _ rawEntries: [String],
    destination: URL,
    overwrite: Bool
  ) throws -> [ArchiveValidatedEntry] {
    let fileManager = FileManager.default
    let destinationBase = destination.standardizedFileURL.resolvingSymlinksInPath()
    let destinationBasePath = destinationBase.path
    let destinationBasePrefix =
      destinationBasePath.hasSuffix("/") ? destinationBasePath : "\(destinationBasePath)/"
    var entries: [ArchiveValidatedEntry] = []

    for rawEntry in rawEntries {
      let normalizedPath = try normalizedArchiveEntryPath(rawEntry)
      let isDirectory = rawEntry.hasSuffix("/") || normalizedPath == "."
      let targetURL = destination.appendingPathComponent(normalizedPath)
        .standardizedFileURL
        .resolvingSymlinksInPath()
      guard targetURL.path == destinationBasePath || targetURL.path.hasPrefix(destinationBasePrefix)
      else {
        throw GatewayToolError.invalidArguments(
          "archive entry escapes destination: \(rawEntry)")
      }

      let targetExists: Bool
      var targetIsDirectory = ObjCBool(false)
      if normalizedPath == "." {
        targetExists = true
        targetIsDirectory = true
      } else {
        targetExists = fileManager.fileExists(
          atPath: targetURL.path,
          isDirectory: &targetIsDirectory
        )
      }
      if targetExists {
        if isDirectory {
          guard targetIsDirectory.boolValue else {
            throw GatewayToolError.invalidArguments(
              "archive entry would replace a non-directory path: \(normalizedPath)")
          }
        } else if !overwrite {
          throw GatewayToolError.invalidArguments(
            "archive entry would overwrite existing path: \(normalizedPath)")
        }
      }

      let parent = targetURL.deletingLastPathComponent()
      var parentIsDirectory = ObjCBool(false)
      if fileManager.fileExists(atPath: parent.path, isDirectory: &parentIsDirectory) {
        guard parentIsDirectory.boolValue else {
          throw GatewayToolError.invalidArguments(
            "archive entry parent is not a directory: \(normalizedPath)")
        }
      }

      entries.append(
        ArchiveValidatedEntry(
          originalPath: rawEntry,
          normalizedPath: normalizedPath,
          isDirectory: isDirectory,
          destinationWorkspaceRelativePath: workspaceRelativePath(targetURL),
          wouldOverwrite: targetExists && !isDirectory
        ))
    }

    return entries
  }

  private func normalizedReadableArchiveEntryPath(_ entry: String) throws -> String {
    guard !entry.hasSuffix("/") else {
      throw GatewayToolError.invalidArguments(
        "archive.read_file entry must be a file, not a directory.")
    }
    let normalizedPath = try normalizedArchiveEntryPath(entry)
    guard normalizedPath != "." else {
      throw GatewayToolError.invalidArguments("archive.read_file entry must be a file path.")
    }
    guard !normalizedPath.hasPrefix("-") else {
      throw GatewayToolError.invalidArguments(
        "archive.read_file entry must not start with '-'.")
    }
    let wildcardCharacters = CharacterSet(charactersIn: "*?[]")
    guard normalizedPath.rangeOfCharacter(from: wildcardCharacters) == nil else {
      throw GatewayToolError.invalidArguments(
        "archive.read_file entry must not contain archive wildcard characters.")
    }
    return normalizedPath
  }

  private func normalizedArchiveEntryPath(_ entry: String) throws -> String {
    guard !entry.isEmpty else {
      throw GatewayToolError.invalidArguments("archive contains an empty entry path.")
    }
    guard !entry.hasPrefix("/") else {
      throw GatewayToolError.invalidArguments("archive contains an absolute entry path: \(entry)")
    }
    let parts = entry.split(separator: "/", omittingEmptySubsequences: false)
    var normalized: [String] = []
    for part in parts {
      if part.isEmpty || part == "." {
        continue
      }
      guard part != ".." else {
        throw GatewayToolError.invalidArguments("archive entry escapes destination: \(entry)")
      }
      normalized.append(String(part))
    }
    return normalized.isEmpty ? "." : normalized.joined(separator: "/")
  }

  private func gitResult(
    operation: String,
    arguments: [String],
    timeout: Int?,
    extra: [String: JSONValue] = [:]
  ) throws -> JSONValue {
    let command = try gitCLICommand()
    let result = try runRegisteredCLI(
      command: command,
      args: arguments,
      timeout: timeout,
      requireArbitraryArgs: false
    )
    var payload: [String: JSONValue] = [
      "operation": .string(operation),
      "provider": .string(command.id),
      "argv": .array(arguments.map { .string($0) }),
      "result": result.json,
    ]
    for (key, value) in extra {
      payload[key] = value
    }
    return .object(payload)
  }

  private func gitCommandMetadata(_ result: CommandResult) -> JSONValue {
    .object([
      "executable": .string(result.executable),
      "arguments": .array(result.arguments.map(JSONValue.string)),
      "exit_code": result.exitCode.map { .number(Double($0)) } ?? .null,
      "timed_out": .bool(result.timedOut),
      "stderr": .string(result.stderr),
      "stdout_bytes": .number(Double(result.stdout.utf8.count)),
      "stdout_truncated": .bool(result.stdoutTruncated),
      "stderr_truncated": .bool(result.stderrTruncated),
    ])
  }

  private func gitCLICommand() throws -> CLICommandConfig {
    guard let command = configuration.cli.commands.first(where: { $0.id == "git" }) else {
      throw GatewayToolError.disabled(
        "git.* tools require a registered CLI provider with id 'git'.")
    }
    return command
  }

  private func httpAuthMode() -> String {
    if configuration.server.http.accessTokenEnv != nil {
      return "bearer"
    }
    return "none"
  }

  private func cliExecutableStatus(_ command: CLICommandConfig) -> JSONValue {
    let resolved = resolveExecutable(command.executable, command: command)
    return .object([
      "id": .string(command.id),
      "executable": .string(command.executable),
      "exists": .bool(resolved.exists),
      "is_executable": .bool(resolved.isExecutable),
      "resolved_path": resolved.path.map(JSONValue.string) ?? .null,
      "resolution_source": .string(resolved.source),
      "resolution": executableResolutionJSON(resolved),
      "cwd": command.resolvedWorkingDirectory(base: configuration.workspaceDirectory)
        .map { .string($0.standardizedFileURL.path) } ?? .null,
      "risk": .string(command.risk ?? "unspecified"),
      "has_interface": .bool(command.interface != nil),
    ])
  }

  private func resolveExecutable(_ executable: String, command: CLICommandConfig)
    -> ExecutableResolution
  {
    resolveExecutable(
      executable,
      base: command.resolvedWorkingDirectory(base: configuration.workspaceDirectory),
      defaultBase: configuration.workspaceDirectory
    )
  }

  private func resolveExecutable(_ executable: String, base: URL?, defaultBase: URL)
    -> ExecutableResolution
  {
    if executable.contains("/") {
      let base = base ?? defaultBase
      let url =
        executable.hasPrefix("/")
        ? URL(fileURLWithPath: executable)
        : base.appendingPathComponent(executable)
      let path = url.standardizedFileURL.path
      return ExecutableResolution(
        path: path,
        source: executable.hasPrefix("/") ? "absolute_path" : "relative_path",
        exists: FileManager.default.fileExists(atPath: path),
        isExecutable: FileManager.default.isExecutableFile(atPath: path)
      )
    }

    guard let path = pathExecutable(executable) else {
      return ExecutableResolution(
        path: nil,
        source: "path",
        exists: false,
        isExecutable: false
      )
    }

    return ExecutableResolution(
      path: path,
      source: "path",
      exists: true,
      isExecutable: FileManager.default.isExecutableFile(atPath: path)
    )
  }

  private func executableResolutionJSON(_ resolution: ExecutableResolution) -> JSONValue {
    .object([
      "exists": .bool(resolution.exists),
      "is_executable": .bool(resolution.isExecutable),
      "resolved_path": resolution.path.map(JSONValue.string) ?? .null,
      "resolution_source": .string(resolution.source),
    ])
  }

  private func mcpWorkingDirectory(_ server: MCPServerConfig) -> URL? {
    guard let cwd = server.cwd, !cwd.isEmpty else {
      return configuration.workspaceDirectory
    }
    if cwd == "workspace" {
      return configuration.workspaceDirectory
    }
    if cwd.hasPrefix("/") {
      return URL(fileURLWithPath: cwd)
    }
    return configuration.workspaceDirectory.appendingPathComponent(cwd)
  }

  private func mcpEnvironmentEntries(_ server: MCPServerConfig) -> [JSONValue] {
    let processEnvironment = ProcessInfo.processInfo.environment
    var declaredKeys = Set<String>()
    return server.env.keys.sorted().map { key in
      environmentEntry(
        key: key,
        owner: "mcp.\(server.id)",
        purpose: "env",
        valueOrigin: "configured_provider_env",
        processEnvironment: processEnvironment,
        declaredKeys: &declaredKeys
      )
    }
  }

  private func httpURLStatus(_ value: String?) -> JSONValue {
    guard let value, let url = URL(string: value) else {
      return .object([
        "valid": .bool(false),
        "scheme": .null,
        "host": .null,
        "path": .null,
      ])
    }

    return .object([
      "valid": .bool(true),
      "scheme": url.scheme.map(JSONValue.string) ?? .null,
      "host": url.host.map(JSONValue.string) ?? .null,
      "path": .string(url.path.isEmpty ? "/" : url.path),
    ])
  }

  private func pathExecutable(_ executable: String) -> String? {
    pathExecutables(executable, allMatches: false).first
  }

  private func pathExecutables(_ executable: String, allMatches: Bool) -> [String] {
    var matches: [String] = []
    var seen = Set<String>()
    for directory in pathSearchDirectories() {
      let candidate = URL(fileURLWithPath: directory).appendingPathComponent(executable).path
      guard FileManager.default.isExecutableFile(atPath: candidate) else {
        continue
      }
      guard seen.insert(candidate).inserted else {
        continue
      }
      matches.append(candidate)
      if !allMatches {
        break
      }
    }
    return matches
  }

  private func pathSearchDirectories() -> [String] {
    let pathValue =
      environment["PATH"]
      ?? "/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin"
    return pathValue.split(separator: ":").map(String.init).filter { !$0.isEmpty }
  }

  private func reexportedTool(for name: String) -> (
    server: MCPServerConfig, downstreamName: String
  )? {
    for server in configuration.mcp.servers where server.exposure.includesReexport {
      guard let prefix = server.prefix else {
        continue
      }
      let marker = "\(prefix)."
      if name.hasPrefix(marker) {
        return (server, String(name.dropFirst(marker.count)))
      }
    }
    return nil
  }

  private func permittedDownstreamTools(server: MCPServerConfig) throws -> [MCPTool] {
    try mcpClient.listTools(server: server).filter { server.permitsTool($0.name) }
  }

  private func requireDownstreamToolAllowed(
    _ name: String,
    server: MCPServerConfig
  ) throws {
    guard server.permitsTool(name) else {
      throw GatewayToolError.invalidArguments(
        "[mcp.tool_not_approved] Downstream MCP tool '\(name)' is not approved for server '\(server.id)'. "
          + "Add it to allowed_tools or expose it as a pinned [[tools]] mapping."
      )
    }
  }

  private func mcpServer(_ id: String) throws -> MCPServerConfig {
    guard let server = configuration.mcp.servers.first(where: { $0.id == id }) else {
      throw GatewayToolError.unknownMCPServer(id)
    }
    return server
  }

  private func textResult(_ value: JSONValue) throws -> JSONValue {
    let data = try encoder.encode(value)
    return .object([
      "content": .array([
        .object([
          "type": .string("text"),
          "text": .string(String(decoding: data, as: UTF8.self)),
        ])
      ]),
      "structuredContent": .object(["result": value]),
      "isError": .bool(false),
    ])
  }

  private func requiredString(_ name: String, in object: [String: JSONValue]) throws -> String {
    guard let value = object[name]?.stringValue, !value.isEmpty else {
      throw GatewayToolError.invalidArguments("Missing required string argument: \(name)")
    }
    return value
  }

  private func requiredStringAllowingEmpty(
    _ name: String,
    in object: [String: JSONValue]
  ) throws -> String {
    guard object[name] != nil else {
      throw GatewayToolError.invalidArguments("Missing required string argument: \(name)")
    }
    guard let value = object[name]?.stringValue else {
      throw GatewayToolError.invalidArguments("\(name) must be a string.")
    }
    return value
  }

  private func optionalString(_ name: String, in object: [String: JSONValue]) throws -> String? {
    guard let value = object[name] else {
      return nil
    }
    guard let string = value.stringValue else {
      throw GatewayToolError.invalidArguments("\(name) must be a string.")
    }
    guard !string.isEmpty else {
      throw GatewayToolError.invalidArguments("\(name) must not be empty.")
    }
    return string
  }

  private func optionalStringAllowingEmpty(_ name: String, in object: [String: JSONValue]) throws
    -> String?
  {
    guard let value = object[name] else {
      return nil
    }
    guard let string = value.stringValue else {
      throw GatewayToolError.invalidArguments("\(name) must be a string.")
    }
    return string
  }

  private func optionalISO8601Date(_ name: String, in object: [String: JSONValue]) throws -> Date? {
    guard let value = try optionalString(name, in: object) else {
      return nil
    }
    let formatter = ISO8601DateFormatter()
    formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
    if let date = formatter.date(from: value) {
      return date
    }
    let fallbackFormatter = ISO8601DateFormatter()
    fallbackFormatter.formatOptions = [.withInternetDateTime]
    guard let date = fallbackFormatter.date(from: value) else {
      throw GatewayToolError.invalidArguments("\(name) must be an ISO8601 timestamp.")
    }
    return date
  }

  private func optionalStringArray(_ name: String, in object: [String: JSONValue]) throws
    -> [String]
  {
    guard let value = object[name] else {
      return []
    }
    guard let array = value.arrayValue else {
      throw GatewayToolError.invalidArguments("\(name) must be an array of strings.")
    }
    return try array.map { item in
      guard let string = item.stringValue else {
        throw GatewayToolError.invalidArguments("\(name) must be an array of strings.")
      }
      return string
    }
  }

  private func requiredStructuredPath(_ name: String, in object: [String: JSONValue]) throws
    -> [StructuredPathSegment]
  {
    guard let value = object[name] else {
      throw GatewayToolError.invalidArguments("Missing required array argument: \(name)")
    }
    guard let array = value.arrayValue else {
      throw GatewayToolError.invalidArguments("\(name) must be an array of strings or integers.")
    }
    guard array.count <= 256 else {
      throw GatewayToolError.invalidArguments("\(name) must contain 256 or fewer segments.")
    }
    return try array.enumerated().map { index, item in
      if let key = item.stringValue {
        return .key(key)
      }
      if let int = item.intValue {
        guard int >= 0 else {
          throw GatewayToolError.invalidArguments(
            "\(name)[\(index)] index must be zero or greater.")
        }
        return .index(int)
      }
      throw GatewayToolError.invalidArguments("\(name) must be an array of strings or integers.")
    }
  }

  private func requiredStringArray(_ name: String, in object: [String: JSONValue]) throws
    -> [String]
  {
    guard object[name] != nil else {
      throw GatewayToolError.invalidArguments("Missing required array argument: \(name)")
    }
    return try optionalStringArray(name, in: object)
  }

  private func requiredObjectArray(_ name: String, in object: [String: JSONValue]) throws
    -> [[String: JSONValue]]
  {
    guard let value = object[name] else {
      throw GatewayToolError.invalidArguments("Missing required array argument: \(name)")
    }
    guard let array = value.arrayValue else {
      throw GatewayToolError.invalidArguments("\(name) must be an array of objects.")
    }
    return try array.enumerated().map { index, item in
      guard let object = item.objectValue else {
        throw GatewayToolError.invalidArguments("\(name)[\(index)] must be an object.")
      }
      return object
    }
  }

  private func optionalInt(_ name: String, in object: [String: JSONValue]) -> Int? {
    object[name]?.intValue
  }

  private func optionalBool(_ name: String, in object: [String: JSONValue]) throws -> Bool? {
    guard let value = object[name] else {
      return nil
    }
    guard let bool = value.boolValue else {
      throw GatewayToolError.invalidArguments("\(name) must be a Boolean.")
    }
    return bool
  }

  private func optionalGitPaths(in object: [String: JSONValue]) throws -> [String] {
    let paths = try optionalStringArray("paths", in: object)
    for path in paths {
      guard !path.isEmpty else {
        throw GatewayToolError.invalidArguments("paths must not contain empty strings.")
      }
      guard !path.hasPrefix("/") else {
        throw GatewayToolError.invalidArguments("paths must be workspace-relative: \(path)")
      }
      guard !path.hasPrefix(":("), !path.hasPrefix(":/") else {
        throw GatewayToolError.invalidArguments("git pathspec magic is not supported: \(path)")
      }
      let components = path.split(separator: "/", omittingEmptySubsequences: false)
      guard !components.contains("..") else {
        throw GatewayToolError.invalidArguments("paths must not escape workspace: \(path)")
      }
    }
    return paths
  }

  private func validateTodoMarkers(_ markers: [String]) throws {
    guard !markers.isEmpty else {
      throw GatewayToolError.invalidArguments("markers must not be empty.")
    }
    guard markers.count <= 20 else {
      throw GatewayToolError.invalidArguments("markers must contain at most 20 values.")
    }

    for marker in markers {
      guard !marker.isEmpty else {
        throw GatewayToolError.invalidArguments("markers must not contain empty strings.")
      }
      guard marker.utf8.count <= 64 else {
        throw GatewayToolError.invalidArguments("markers must be 64 bytes or fewer.")
      }
      guard
        marker.unicodeScalars.allSatisfy({ scalar in
          !((scalar.value <= 0x1F) || (scalar.value >= 0x7F && scalar.value <= 0x9F))
        })
      else {
        throw GatewayToolError.invalidArguments("markers must not contain control characters.")
      }
    }
  }

  private func toolMeta() -> JSONValue? {
    if configuration.server.http.accessTokenEnv == nil {
      return .object(["securitySchemes": .array([.object(["type": .string("noauth")])])])
    }

    return nil
  }

