private struct GitTrackingStatusInfo {
  var branch: String?
  var upstream: String?
  var ahead: Int?
  var behind: Int?
  var flags: [String]
  var detached: Bool
  var unborn: Bool
  var rawBranchLine: String

  var hasUpstream: Bool {
    upstream != nil
  }

  var state: String {
    if detached {
      return "detached"
    }
    if unborn {
      return "unborn"
    }
    if flags.contains("gone") {
      return "gone"
    }
    guard hasUpstream else {
      return "no_upstream"
    }
    let aheadValue = ahead ?? 0
    let behindValue = behind ?? 0
    if aheadValue > 0 && behindValue > 0 {
      return "diverged"
    }
    if aheadValue > 0 {
      return "ahead"
    }
    if behindValue > 0 {
      return "behind"
    }
    return "up_to_date"
  }

  var json: JSONValue {
    .object([
      "branch": branch.map(JSONValue.string) ?? .null,
      "upstream": upstream.map(JSONValue.string) ?? .null,
      "has_upstream": .bool(hasUpstream),
      "ahead": ahead.map { .number(Double($0)) } ?? .null,
      "behind": behind.map { .number(Double($0)) } ?? .null,
      "flags": .array(flags.map(JSONValue.string)),
      "detached": .bool(detached),
      "unborn": .bool(unborn),
      "state": .string(state),
      "raw_branch_line": .string(rawBranchLine),
    ])
  }
}

