private struct SkillResourceSummary {
  var kind: String
  var path: String?
  var skill: SkillInfo
  var exists = false
  var fileCount = 0
  var directoryCount = 0
  var symlinkCount = 0
  var otherCount = 0
  var totalSizeBytes: Int64 = 0
  var isReadable = false
  var isDirectory = false
  var targetInsideSkill = false

  mutating func add(_ file: SkillFileInfo) {
    exists = true
    if file.path == path {
      isReadable = file.isReadable
      isDirectory = file.type == "directory"
      targetInsideSkill = file.targetInsideSkill
    }
    switch file.type {
    case "file":
      fileCount += 1
    case "directory":
      directoryCount += 1
    default:
      otherCount += 1
    }
    if file.isSymlink {
      symlinkCount += 1
    }
    if let sizeBytes = file.sizeBytes {
      totalSizeBytes += sizeBytes
    }
  }

  var json: JSONValue {
    let listContext: JSONValue
    if let path, exists, isDirectory, isReadable, targetInsideSkill {
      listContext = .object([
        "tool": .string("skills.files"),
        "arguments": .object([
          "name": .string(skill.name),
          "root_id": .string(skill.root.id),
          "path": .string(path),
        ]),
      ])
    } else {
      listContext = .null
    }

    return .object([
      "kind": .string(kind),
      "path": path.map(JSONValue.string) ?? .null,
      "exists": .bool(exists),
      "file_count": .number(Double(fileCount)),
      "directory_count": .number(Double(directoryCount)),
      "symlink_count": .number(Double(symlinkCount)),
      "other_count": .number(Double(otherCount)),
      "total_size_bytes": .number(Double(totalSizeBytes)),
      "list_context": listContext,
    ])
  }
}

